INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-1', 'toeic', 'Negotiate', '/nəˈɡoʊ.ʃi.eɪt/', 'Verb', 'B2', 'Đàm phán, thương lượng hợp đồng', 'To discuss something in order to reach an agreement.', 'The procurement team managed to negotiate a 15% discount with the supplier.', 'Đội ngũ thu mua đã đàm phán thành công mức giảm giá 15% với nhà cung cấp.', ARRAY['Bargain', 'Confer', 'Debate']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-2', 'toeic', 'Compliance', '/kəmˈplaɪ.əns/', 'Noun', 'B2', 'Sự tuân thủ các quy định và tiêu chuẩn', 'The act of obeying an order, rule, or request.', 'Our factory operates in full compliance with international safety regulations.', 'Nhà máy của chúng tôi vận hành hoàn toàn tuân thủ các quy chuẩn an toàn quốc tế.', ARRAY['Adherence', 'Conformity', 'Obedience']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-3', 'toeic', 'Reimbursement', '/ˌriː.ɪmˈbɝːs.mənt/', 'Noun', 'B2', 'Khoản hoàn tiền công tác phí, chi phí bồi hoàn', 'The act of paying back money to someone who spent it for official business.', 'Please submit all receipts to accounting to claim your travel reimbursement.', 'Vui lòng nộp lại tất cả hóa đơn cho bộ phận kế toán để nhận tiền bồi hoàn công tác.', ARRAY['Repayment', 'Compensation', 'Refund']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-4', 'toeic', 'Warranty', '/ˈwɔːr.ən.t̬i/', 'Noun', 'B1', 'Giấy bảo hành, cam kết bảo hành sản phẩm', 'A written promise by a company that it will repair or replace a product.', 'The electronic equipment comes with a comprehensive two-year warranty.', 'Thiết bị điện tử đi kèm gói bảo hành toàn diện trong 2 năm.', ARRAY['Guarantee', 'Contract', 'Assurance']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-5', 'toeic', 'Inventory', '/ˈɪn.vən.tɔːr.i/', 'Noun', 'B1', 'Hàng tồn kho, bản kiểm kê hàng hóa', 'A detailed list or total quantity of goods in stock.', 'The warehouse conducts an inventory audit at the end of every quarter.', 'Kho hàng tiến hành kiểm kê lượng hàng tồn vào cuối mỗi quý.', ARRAY['Stock', 'Supply', 'Reserve']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-6', 'toeic', 'Audit', '/ˈɑː.dɪt/', 'Noun', 'B2', 'Kiểm toán tài chính, thanh tra sổ sách', 'An official examination of the accounts or operational procedures of an organization.', 'The external audit confirmed that all financial statements were accurate.', 'Cuộc kiểm toán độc lập xác nhận rằng toàn bộ báo cáo tài chính đều chính xác.', ARRAY['Inspection', 'Examination', 'Review']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-7', 'toeic', 'Procurement', '/prəˈkjʊr.mənt/', 'Noun', 'C1', 'Quy trình thu mua vật tư và thiết bị', 'The process of getting supplies or services for business operations.', 'She was recently promoted to head of the global procurement department.', 'Cô ấy vừa được thăng chức lên vị trí trưởng phòng thu mua toàn cầu.', ARRAY['Purchasing', 'Acquisition', 'Sourcing']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-8', 'toeic', 'Specifications', '/ˌspes.ə.fəˈkeɪ.ʃənz/', 'Noun', 'B2', 'Thông số kỹ thuật chi tiết', 'A detailed description of how something should be designed, made, or done.', 'The new laptop model meets all the technical specifications requested by the client.', 'Mẫu máy tính xách tay mới đáp ứng toàn bộ các thông số kỹ thuật mà khách hàng yêu cầu.', ARRAY['Details', 'Requirements', 'Standards']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-9', 'toeic', 'Terminate', '/ˈtɝː.mə.neɪt/', 'Verb', 'B2', 'Chấm dứt hợp đồng, đình chỉ dịch vụ', 'To bring something to an end or to conclude officially.', 'Either party may terminate the lease agreement with a 30-day written notice.', 'Một trong hai bên có thể chấm dứt hợp đồng thuê với thông báo bằng văn bản trước 30 ngày.', ARRAY['End', 'Cancel', 'Conclude']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-10', 'toeic', 'Credential', '/krɪˈden.ʃəl/', 'Noun', 'B2', 'Chứng chỉ hành nghề, bằng cấp chuyên môn', 'A document or qualification proving someone''s authority or competence.', 'The applicant possesses impressive academic credentials and strong leadership experience.', 'Ứng viên sở hữu bằng cấp học thuật ấn tượng và kinh nghiệm lãnh đạo vững vàng.', ARRAY['Qualification', 'Certification', 'Accreditation']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-11', 'toeic', 'Merger', '/ˈmɝː.dʒɚ/', 'Noun', 'B2', 'Sự sáp nhập giữa hai công ty', 'The combining of two or more commercial companies into one.', 'The merger between the two airline giants will create the largest fleet in the region.', 'Vụ sáp nhập giữa hai tập đoàn hàng không lớn sẽ tạo nên đội bay lớn nhất khu vực.', ARRAY['Amalgamation', 'Union', 'Consolidation']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-12', 'toeic', 'Acquisition', '/ˌæk.wəˈzɪʃ.ən/', 'Noun', 'B2', 'Thương vụ thâu tóm, mua lại doanh nghiệp', 'The process of getting or buying something, especially a company or property.', 'The acquisition of the tech startup will help expand our cloud offerings.', 'Thương vụ thâu tóm công ty khởi nghiệp công nghệ sẽ giúp mở rộng các dịch vụ đám mây của chúng tôi.', ARRAY['Purchase', 'Takeover', 'Procurement']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-13', 'toeic', 'Vendor', '/ˈven.dɚ/', 'Noun', 'B1', 'Nhà cung cấp hàng hóa hoặc dịch vụ', 'A person or company offering something for sale.', 'We must select a reliable catering vendor for the upcoming annual gala dinner.', 'Chúng ta phải chọn một nhà cung cấp tiệc uy tín cho đêm tiệc gala thường niên sắp tới.', ARRAY['Supplier', 'Seller', 'Merchant']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-14', 'toeic', 'Feasible', '/ˈfiː.zə.bəl/', 'Adj', 'B2', 'Khả thi, có thể thực hiện được', 'Able to be made, done, or achieved easily or conveniently.', 'The board agreed that the marketing strategy was economically feasible.', 'Hội đồng quản trị đồng ý rằng chiến lược tiếp thị là hoàn toàn khả thi về mặt kinh tế.', ARRAY['Viable', 'Practicable', 'Workable']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-15', 'toeic', 'Subcontractor', '/ˈsʌbˌkɑːn.træk.tɚ/', 'Noun', 'B2', 'Nhà thầu phụ', 'A person or firm that undertakes a contract from a primary contractor.', 'Electrical wiring throughout the skyscraper was completed by an experienced subcontractor.', 'Hệ thống dây điện trên toàn bộ tòa nhà chọc trời được hoàn thành bởi một nhà thầu phụ giàu kinh nghiệm.', ARRAY['Secondary contractor', 'Specialist vendor']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-16', 'toeic', 'Invoice', '/ˈɪn.vɔɪs/', 'Noun', 'B1', 'Hóa đơn thanh toán tài chính', 'A list of goods sent or services provided, with a statement of the sum due.', 'The invoice must be settled within thirty days of the billing date.', 'Hóa đơn phải được thanh toán trong vòng 30 ngày kể từ ngày xuất hóa đơn.', ARRAY['Bill', 'Statement', 'Account']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-17', 'toeic', 'Delegate', '/ˈdel.ə.ɡeɪt/', 'Verb', 'B2', 'Giao phó công việc, ủy quyền cho cấp dưới', 'To entrust a task or responsibility to another person.', 'A great project manager knows how to delegate responsibilities effectively.', 'Một người quản lý dự án giỏi biết cách giao phó trách nhiệm một cách hiệu quả.', ARRAY['Assign', 'Entrust', 'Allocate']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-18', 'toeic', 'Appraisal', '/əˈpreɪ.zəl/', 'Noun', 'B2', 'Sự đánh giá năng lực nhân viên, thẩm định giá', 'An assessment or evaluation of someone''s performance or the value of property.', 'Annual performance appraisals will begin next week for all engineering staff.', 'Kỳ đánh giá hiệu suất công việc hàng năm sẽ bắt đầu vào tuần tới cho toàn bộ kỹ sư.', ARRAY['Evaluation', 'Assessment', 'Review']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-19', 'toeic', 'Compensation', '/ˌkɑːm.penˈseɪ.ʃən/', 'Noun', 'B2', 'Chế độ đãi ngộ, thù lao hoặc khoản đền bù', 'Money awarded or paid to someone in exchange for labor or as recompense for loss.', 'The company offers competitive compensation, including health insurance and annual stock options.', 'Công ty đưa ra mức thù lao cạnh tranh, bao gồm bảo hiểm y tế và quyền chọn mua cổ phiếu hàng năm.', ARRAY['Remuneration', 'Salary', 'Benefit package']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-20', 'toeic', 'Defective', '/dɪˈfek.tɪv/', 'Adj', 'B1', 'Bị lỗi, có khuyết tật sản xuất', 'Imperfect or faulty; not functioning properly.', 'Customers can immediately return any defective merchandise within 14 business days.', 'Khách hàng có thể đổi trả ngay lập tức bất kỳ sản phẩm nào bị lỗi trong vòng 14 ngày làm việc.', ARRAY['Faulty', 'Flawed', 'Damaged']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-21', 'toeic', 'Logistics', '/ləˈdʒɪs.tɪks/', 'Noun', 'B2', 'Hậu cần vận tải và chuỗi cung ứng', 'The detailed organization and implementation of a complex operation involving transport.', 'Our logistics network guarantees next-day delivery to major cities.', 'Mạng lưới hậu cần của chúng tôi cam kết giao hàng trong ngày hôm sau tới các thành phố lớn.', ARRAY['Supply chain', 'Transport management', 'Distribution']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-22', 'toeic', 'Discrepancy', '/dɪˈskrep.ən.si/', 'Noun', 'B2', 'Sự sai lệch, chênh lệch không khớp số liệu', 'A lack of compatibility or similarity between two or more facts or numbers.', 'There is a noticeable discrepancy between the warehouse count and the sales ledger.', 'Có sự sai lệch đáng chú ý giữa số lượng kiểm kho và sổ cái doanh số.', ARRAY['Inconsistency', 'Difference', 'Variance']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-23', 'toeic', 'Confidential', '/ˌkɑːn.fəˈden.ʃəl/', 'Adj', 'B2', 'Bảo mật, thông tin tuyệt mật', 'Intended to be kept secret or private.', 'All staff must sign a non-disclosure agreement to protect confidential company data.', 'Toàn bộ nhân viên phải ký cam kết bảo mật nhằm bảo vệ dữ liệu bí mật của công ty.', ARRAY['Private', 'Secret', 'Classified']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-24', 'toeic', 'Revenue', '/ˈrev.ə.nuː/', 'Noun', 'B1', 'Doanh thu của doanh nghiệp', 'Income, especially when of a company or organization of a substantial nature.', 'Third-quarter revenue exceeded Wall Street forecasts by approximately 12 percent.', 'Doanh thu quý ba đã vượt dự báo của Phố Wall khoảng 12%.', ARRAY['Income', 'Earnings', 'Proceeds']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-25', 'toeic', 'Turnover', '/ˈtɝːnˌoʊ.vɚ/', 'Noun', 'B2', 'Tỷ lệ luân chuyển nhân sự hoặc doanh thu quay vòng', 'The rate at which employees leave a workforce and are replaced, or sales volume.', 'Improving company culture helped decrease employee turnover by thirty percent.', 'Cải thiện văn hóa doanh nghiệp đã giúp giảm tỷ lệ luân chuyển nhân viên đi 30%.', ARRAY['Attrition rate', 'Replacement rate']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-26', 'toeic', 'Restructure', '/ˌriːˈstrʌk.tʃɚ/', 'Verb', 'B2', 'Tái cơ cấu bộ máy tổ chức hoặc tài chính', 'Organize differently in order to improve efficiency or profitability.', 'The corporation plans to restructure its European operations to cut overhead costs.', 'Tập đoàn có kế hoạch tái cơ cấu các chi nhánh tại châu Âu để cắt giảm chi phí vận hành.', ARRAY['Reorganize', 'Overhaul', 'Realine']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-27', 'toeic', 'Obligation', '/ˌɑː.bləˈɡeɪ.ʃən/', 'Noun', 'B2', 'Nghĩa vụ pháp lý hoặc hợp đồng', 'An act or course of action to which a person is morally or legally bound.', 'The contractor failed to fulfill its contractual obligations on schedule.', 'Nhà thầu đã không thể hoàn thành các nghĩa vụ trong hợp đồng đúng tiến độ.', ARRAY['Duty', 'Commitment', 'Responsibility']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-28', 'toeic', 'Expedite', '/ˈek.spə.daɪt/', 'Verb', 'C1', 'Đẩy nhanh tiến độ, xúc tiến nhanh chóng', 'Make an action or process happen sooner or be accomplished more quickly.', 'We paid an extra fee to expedite the shipping of emergency server replacement parts.', 'Chúng tôi đã trả thêm một khoản phí để xúc tiến vận chuyển nhanh phụ tùng máy chủ khẩn cấp.', ARRAY['Accelerate', 'Speed up', 'Hasten']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-29', 'toeic', 'Overdue', '/ˌoʊ.vɚˈduː/', 'Adj', 'B1', 'Quá hạn thanh toán hoặc trả nợ', 'Not having arrived, happened, or been done by the expected time.', 'Our accounts receivable department sent a stern reminder for the overdue invoice.', 'Bộ phận thu nợ của chúng tôi đã gửi thư nhắc nhở nghiêm khắc đối với hóa đơn quá hạn.', ARRAY['Late', 'Unpaid', 'Delayed']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-30', 'toeic', 'Quota', '/ˈkwoʊ.t̬ə/', 'Noun', 'B2', 'Hạn ngạch sản xuất hoặc chỉ tiêu bán hàng', 'A fixed minimum or maximum number of a particular group of people or things.', 'The sales team surpassed their monthly revenue quota ahead of schedule.', 'Đội ngũ kinh doanh đã vượt chỉ tiêu doanh số tháng trước thời hạn quy định.', ARRAY['Target', 'Allocation', 'Share']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-31', 'toeic', 'Consolidate', '/kənˈsɑː.lə.deɪt/', 'Verb', 'B2', 'Hợp nhất, củng cố vị thế', 'To combine several things into a single more effective whole.', 'The company plans to consolidate its regional offices into one headquarters.', 'Công ty dự kiến hợp nhất các văn phòng khu vực thành một trụ sở chính.', ARRAY['Combine', 'Merge', 'Unify']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-32', 'toeic', 'Subsidiary', '/səbˈsɪd.i.er.i/', 'Noun', 'B2', 'Công ty con trực thuộc', 'A company controlled by a holding or parent company.', 'The Japanese multinational operates subsidiaries in over twenty countries.', 'Tập đoàn đa quốc gia Nhật Bản sở hữu các công ty con tại hơn 20 quốc gia.', ARRAY['Branch', 'Affiliate', 'Offshoot']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-33', 'toeic', 'Deficit', '/ˈdef.ə.sɪt/', 'Noun', 'B2', 'Thâm hụt cán cân ngân sách', 'The amount by which something, especially a sum of money, is too small.', 'The proposed budget aims to cut the trade deficit by half within two years.', 'Bản dự thảo ngân sách hướng tới việc cắt giảm một nửa mức thâm hụt thương mại trong 2 năm.', ARRAY['Shortfall', 'Deficiency', 'Loss']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-34', 'toeic', 'Surplus', '/ˈsɝː.pləs/', 'Noun', 'B2', 'Thặng dư tài chính, phần dư thừa', 'An amount of something left over when requirements have been met.', 'The strong holiday sales resulted in a record financial surplus for the quarter.', 'Doanh thu kỳ nghỉ lễ vượt trội đã mang lại mức thặng dư tài chính kỷ lục cho quý này.', ARRAY['Excess', 'Overabundance', 'Surfeit']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-35', 'toeic', 'Solicit', '/səˈlɪs.ɪt/', 'Verb', 'C1', 'Kêu gọi đóng góp, mời thầu', 'To ask for or try to obtain something from someone.', 'The municipality released a tender to solicit bids from qualified contractors.', 'Chính quyền thành phố đã phát hành hồ sơ mời thầu từ các nhà thầu đủ điều kiện.', ARRAY['Request', 'Seek', 'Petition']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-36', 'toeic', 'Endorsement', '/ɪnˈdɔːrs.mənt/', 'Noun', 'B2', 'Sự bảo chứng thương hiệu, ủng hộ', 'An act of giving one''s public approval or support to someone or something.', 'The celebrity endorsement generated millions of pre-orders for the new smartphone.', 'Sự bảo chứng của người nổi tiếng đã đem lại hàng triệu đơn đặt trước cho mẫu điện thoại mới.', ARRAY['Backing', 'Approval', 'Sponsorship']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-37', 'toeic', 'Tenant', '/ˈten.ənt/', 'Noun', 'B1', 'Người thuê nhà, văn phòng', 'A person who occupies land or property rented from a landlord.', 'All tenants in the commercial building must adhere to fire drill procedures.', 'Tất cả khách thuê trong tòa nhà thương mại phải tuân thủ quy trình diễn tập phòng cháy.', ARRAY['Renter', 'Occupant', 'Lessee']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-38', 'toeic', 'Lease', '/liːs/', 'Noun', 'B1', 'Hợp đồng cho thuê tài sản dài hạn', 'A legal contract conveying land, property, or services to another for a specified time.', 'The enterprise signed a ten-year lease for three floors in the central business district.', 'Doanh nghiệp đã ký hợp đồng thuê 10 năm cho 3 tầng tại khu vực trung tâm thương mại.', ARRAY['Charter', 'Rental contract', 'Hire']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-39', 'toeic', 'Liaison', '/liˈeɪ.zɑːn/', 'Noun', 'C1', 'Người đầu mối liên lạc giữa các bộ phận', 'Communication or cooperation which facilitates a close working relationship.', 'She acted as the primary liaison between our software team and the client.', 'Cô ấy đóng vai trò là đầu mối liên lạc chính giữa đội ngũ phần mềm và khách hàng.', ARRAY['Intermediary', 'Go-between', 'Coordinator']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-40', 'toeic', 'Arbitration', '/ˌɑːr.bəˈtreɪ.ʃən/', 'Noun', 'C1', 'Sự phân xử thông qua trọng tài thương mại', 'The use of an arbitrator to settle a dispute.', 'The contractual disagreement was ultimately resolved through international arbitration.', 'Bất đồng hợp đồng cuối cùng đã được giải quyết thông qua trọng tài thương mại quốc tế.', ARRAY['Adjudication', 'Mediation', 'Settlement']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-41', 'toeic', 'Clause', '/klɑːz/', 'Noun', 'B2', 'Điều khoản trong văn bản pháp lý', 'A particular and separate article, stipulation, or proviso in a treaty or contract.', 'Pay close attention to the confidentiality clause before signing the employment contract.', 'Hãy chú ý kỹ đến điều khoản bảo mật trước khi ký hợp đồng lao động.', ARRAY['Provision', 'Stipulation', 'Section']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-42', 'toeic', 'Stipulate', '/ˈstɪp.jə.leɪt/', 'Verb', 'C1', 'Quy định rõ ràng thành văn', 'Demand or specify a requirement, typically as part of a bargain or agreement.', 'The agreement stipulates that all deliverables must be submitted by December 1st.', 'Thỏa thuận quy định rõ rằng mọi sản phẩm bàn giao phải được nộp trước ngày 1 tháng 12.', ARRAY['Specify', 'Prescribe', 'State']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-43', 'toeic', 'Default', '/dɪˈfɑːlt/', 'Verb', 'B2', 'Vỡ nợ, không trả được nợ đúng hạn', 'Fail to fulfill an obligation, especially to repay a loan.', 'Borrowers who default on their debt obligations face severe credit rating penalties.', 'Người vay vỡ nợ không trả được các nghĩa vụ tài chính sẽ đối mặt với việc bị hạ điểm tín dụng nghiêm trọng.', ARRAY['Fail to pay', 'Renege', 'Lapse']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-44', 'toeic', 'Incentive', '/ɪnˈsen.tɪv/', 'Noun', 'B2', 'Chính sách khuyến khích, tiền thưởng hiệu suất', 'A thing that motivates or encourages someone to do something.', 'Performance bonuses provide a powerful incentive for engineers to innovate rapidly.', 'Tiền thưởng theo hiệu suất mang lại động lực to lớn giúp các kỹ sư đổi mới sáng tạo nhanh chóng.', ARRAY['Inducement', 'Motivation', 'Stimulus']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-45', 'toeic', 'Fringe Benefit', '/ˈfrɪndʒ ˌben.ə.fɪt/', 'Noun', 'B2', 'Phúc lợi bổ sung ngoài lương', 'An extra benefit supplementing an employee''s salary, for example a company car.', 'Fringe benefits such as gym memberships and free meals boost employee morale.', 'Các phúc lợi ngoài lương như thẻ tập thể hình và bữa ăn miễn phí giúp nâng cao tinh thần nhân viên.', ARRAY['Perk', 'Extra privilege', 'Add-on']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-46', 'toeic', 'Apprentice', '/əˈpren.tɪs/', 'Noun', 'B1', 'Người học việc, tập sự', 'A person who is learning a trade from a skilled employer.', 'The senior technician is training two promising young apprentices.', 'Kỹ thuật viên cao cấp đang trực tiếp hướng dẫn hai bạn học việc trẻ đầy triển vọng.', ARRAY['Trainee', 'Intern', 'Learner']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-47', 'toeic', 'Roster', '/ˈrɑː.stɚ/', 'Noun', 'B2', 'Bảng phân công ca làm việc', 'A list or plan showing turns of duty or leave for individuals or groups in an organization.', 'The hospital manager updated the weekend duty roster for on-call nurses.', 'Quản lý bệnh viện đã cập nhật bảng phân công trực ban cuối tuần cho các điều dưỡng viên.', ARRAY['Schedule', 'Timetable', 'Duty list']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-48', 'toeic', 'Probation', '/proʊˈbeɪ.ʃən/', 'Noun', 'B2', 'Thời gian thử việc', 'A period of time during which someone''s ability or fitness is tested.', 'After successfully completing her three-month probation, she was granted a permanent contract.', 'Sau khi hoàn thành xuất sắc 3 tháng thử việc, cô ấy đã được ký hợp đồng chính thức.', ARRAY['Trial period', 'Test stage']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-49', 'toeic', 'Punctuality', '/ˌpʌŋk.tʃuˈæl.ə.t̬i/', 'Noun', 'B1', 'Tính đúng giờ giấc', 'The fact or quality of being on time.', 'Punctuality and reliability are essential attributes for any professional consultant.', 'Đúng giờ và đáng tin cậy là những phẩm chất cốt lõi của bất kỳ chuyên viên tư vấn chuyên nghiệp nào.', ARRAY['Promptness', 'Timeliness']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-50', 'toeic', 'Remittance', '/rɪˈmɪt.əns/', 'Noun', 'C1', 'Số tiền chuyển khoản thanh toán', 'A sum of money sent in payment or as a gift.', 'Please ensure that your remittance includes the corresponding invoice reference code.', 'Xin hãy đảm bảo rằng khoản tiền chuyển khoản của bạn ghi kèm mã tham chiếu hóa đơn tương ứng.', ARRAY['Payment', 'Transfer', 'Dispatch']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-51', 'toeic', 'Collateral', '/kəˈlæt̬.ɚ.əl/', 'Noun', 'B2', 'Tài sản thế chấp ngân hàng', 'Something pledged as security for repayment of a loan.', 'The bank accepted the commercial real estate property as collateral for the business loan.', 'Ngân hàng đã chấp thuận bất động sản thương mại làm tài sản thế chấp cho khoản vay doanh nghiệp.', ARRAY['Security', 'Guarantee', 'Pledge']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-52', 'toeic', 'Depreciation', '/dɪˌpriː.ʃiˈeɪ.ʃən/', 'Noun', 'B2', 'Khấu hao tài sản cố định qua thời gian', 'A reduction in the value of an asset with the passage of time.', 'Accelerated depreciation allows enterprises to write off machinery costs more rapidly.', 'Khấu hao nhanh cho phép doanh nghiệp trích chi phí máy móc một cách nhanh chóng hơn.', ARRAY['Devaluation', 'Wear and tear', 'Discount']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-53', 'toeic', 'Overhead', '/ˈoʊ.vɚ.hed/', 'Noun', 'B2', 'Chi phí vận hành cố định', 'The regular and necessary costs of running a business, such as rent, heating, and taxes.', 'Transitioning to a hybrid remote model helped cut our office overhead costs by 40%.', 'Chuyển sang mô hình làm việc kết hợp từ xa đã giúp giảm 40% chi phí vận hành văn phòng.', ARRAY['Operating expenses', 'Fixed costs', 'Running costs']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-54', 'toeic', 'Merchandising', '/ˈmɝː.tʃən.daɪ.zɪŋ/', 'Noun', 'B2', 'Hoạt động trưng bày và tiếp thị hàng hóa', 'The activity of promoting the sale of goods, especially by their presentation in stores.', 'Effective visual merchandising significantly increases in-store impulsive purchases.', 'Việc trưng bày hàng hóa trực quan hiệu quả giúp tăng đáng kể lượng mua sắm ngẫu hứng tại cửa hàng.', ARRAY['Marketing display', 'Retailing', 'Promotion']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-55', 'toeic', 'Consignment', '/kənˈsaɪn.mənt/', 'Noun', 'B2', 'Lô hàng ký gửi phân phối', 'A batch of goods destined for or delivered to someone.', 'A large consignment of medical equipment arrived at the port this morning.', 'Một lô hàng thiết bị y tế lớn đã cập cảng vào sáng nay.', ARRAY['Shipment', 'Batch', 'Cargo']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-56', 'toeic', 'Affiliation', '/əˌfɪl.iˈeɪ.ʃən/', 'Noun', 'B2', 'Sự liên kết, gia nhập tổ chức', 'The state or process of affiliating or being affiliated with an organization.', 'Our medical clinic has an academic affiliation with the national university hospital.', 'Phòng khám y khoa của chúng tôi có mối liên kết học thuật với bệnh viện đại học quốc gia.', ARRAY['Association', 'Alliance', 'Partnership']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-57', 'toeic', 'Unanimous', '/juːˈnæn.ə.məs/', 'Adj', 'B2', 'Nhất trí đồng lòng 100%', 'Fully in agreement; held or arrived at with everyone''s consent.', 'The shareholders passed a unanimous vote to appoint the new Chief Executive Officer.', 'Các cổ đông đã bỏ phiếu nhất trí tuyệt đối để bổ nhiệm Tổng giám đốc điều hành mới.', ARRAY['Undivided', 'Harmonious', 'In accord']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-58', 'toeic', 'Discretionary', '/dɪˈskreʃ.ən.er.i/', 'Adj', 'C1', 'Tùy ý sử dụng theo quyết định riêng', 'Available for use at the discretion of the user, not predetermined by law.', 'The management holds a discretionary fund to sponsor internal employee innovation projects.', 'Ban quản lý duy trì một quỹ tùy ý sử dụng để tài trợ cho các dự án đổi mới sáng tạo nội bộ.', ARRAY['Optional', 'Voluntary', 'Flexible']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-59', 'toeic', 'Indemnify', '/ɪnˈdem.nə.faɪ/', 'Verb', 'C1', 'Bồi thường tổn thất tài chính', 'Compensate someone for harm or loss, or secure against legal liability.', 'The insurance contract indemnifies the homeowner against flood and earthquake damage.', 'Hợp đồng bảo hiểm bồi thường cho chủ nhà trước mọi thiệt hại do lũ lụt và động đất.', ARRAY['Compensate', 'Reimburse', 'Insure']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-60', 'toeic', 'Severance', '/ˈsev.ɚ.əns/', 'Noun', 'B2', 'Khoản tiền trợ cấp thôi việc', 'The act of ending a connection or relationship, or money paid on leaving employment.', 'Employees affected by the corporate downsizing received generous severance packages.', 'Những nhân sự bị ảnh hưởng bởi việc thu hẹp quy mô công ty đã nhận được gói trợ cấp thôi việc hậu hĩnh.', ARRAY['Discharge compensation', 'Termination pay']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-61', 'toeic', 'Requisition', '/ˌrek.wəˈzɪʃ.ən/', 'Noun', 'B2', 'Phiếu yêu cầu cấp phát vật tư nội bộ', 'An official order laying claim to the use of property or supplies.', 'Please fill out a requisition slip if your department requires additional monitors.', 'Vui lòng điền vào phiếu yêu cầu cấp phát nếu phòng ban của bạn cần thêm màn hình làm việc.', ARRAY['Purchase order', 'Request form', 'Claim']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-62', 'toeic', 'Retain', '/rɪˈteɪn/', 'Verb', 'B2', 'Giữ chân nhân tài, lưu giữ hồ sơ', 'Continue to have or keep possession of something.', 'The firm adopted flexible working hours to attract and retain top software talent.', 'Công ty đã áp dụng thời gian làm việc linh hoạt để thu hút và giữ chân nhân tài phần mềm hàng đầu.', ARRAY['Keep', 'Hold', 'Preserve']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-63', 'toeic', 'Statutory', '/ˈstætʃ.ə.tɔːr.i/', 'Adj', 'C1', 'Theo luật định bắt buộc', 'Decided, controlled, or required by law.', 'Every employee is entitled to statutory maternity and sick leave benefits.', 'Mỗi người lao động đều được hưởng quyền lợi nghỉ thai sản và nghỉ ốm theo đúng luật định.', ARRAY['Mandatory', 'Legal', 'Obligatory']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-64', 'toeic', 'Subsidize', '/ˈsʌb.sə.daɪz/', 'Verb', 'B2', 'Trợ cấp ngân sách, hỗ trợ giá', 'Support an organization or activity financially.', 'The government agreed to subsidize public transport to reduce traffic congestion.', 'Chính phủ đã đồng ý trợ cấp chi phí giao thông công cộng nhằm giảm ùn tắc giao thông.', ARRAY['Fund', 'Underwrite', 'Finance']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-65', 'toeic', 'Yield', '/jiːld/', 'Noun', 'B2', 'Lợi suất đầu tư, sản lượng thu hoạch', 'The full amount of an agricultural or industrial product, or financial return.', 'High-dividend stocks provide an attractive annual yield for retirement investors.', 'Cổ phiếu cổ tức cao đem lại lợi suất hàng năm hấp dẫn cho các nhà đầu tư hưu trí.', ARRAY['Return', 'Profit', 'Output']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-66', 'toeic', 'Tenure', '/ˈten.jɚ/', 'Noun', 'C1', 'Nhiệm kỳ công tác, quyền biên chế trọn đời', 'The conditions or period under which land or buildings are held, or holding an office.', 'During his successful five-year tenure as director, company revenue doubled.', 'Trong suốt nhiệm kỳ 5 năm thành công với tư cách giám đốc, doanh thu công ty đã tăng gấp đôi.', ARRAY['Term of office', 'Incumbency', 'Period']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-67', 'toeic', 'Surveillance', '/sɚˈveɪ.ləns/', 'Noun', 'B2', 'Hệ thống giám sát an ninh', 'Close observation, especially of a suspected spy or criminal.', 'High-resolution surveillance cameras were installed at all warehouse exits.', 'Các camera giám sát độ nét cao đã được lắp đặt tại tất cả các cửa ra của nhà kho.', ARRAY['Monitoring', 'Observation', 'Watch']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-68', 'toeic', 'Stringent', '/ˈstrɪn.dʒənt/', 'Adj', 'C1', 'Nghiêm ngặt, chặt chẽ (tiêu chuẩn/quy định)', 'Strict, precise, and exacting rules or requirements.', 'Medical devices must satisfy stringent quality testing before receiving FDA approval.', 'Thiết bị y tế phải thỏa mãn các tiêu chuẩn kiểm nghiệm nghiêm ngặt trước khi được FDA cấp phép.', ARRAY['Rigorous', 'Demanding', 'Strict']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-69', 'toeic', 'Remuneration', '/rɪˌmjuː.nəˈreɪ.ʃən/', 'Noun', 'C1', 'Thù lao công lao động', 'Money paid for work or a service.', 'Executive remuneration packages are closely tied to long-term stock performance.', 'Các gói thù lao dành cho cấp điều hành gắn liền mật thiết với kết quả cổ phiếu dài hạn.', ARRAY['Compensation', 'Earnings', 'Pay']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-70', 'toeic', 'Quorum', '/ˈkwɔːr.əm/', 'Noun', 'C1', 'Số lượng đại biểu tối thiểu để biểu quyết hợp lệ', 'The minimum number of members of an assembly that must be present at any of its meetings.', 'The shareholder assembly cannot vote on the resolution without reaching a legal quorum.', 'Đại hội đồng cổ đông không thể bỏ phiếu thông qua nghị quyết nếu chưa đạt túc số pháp lý tối thiểu.', ARRAY['Sufficient attendance', 'Legal presence']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-71', 'toeic', 'Nullify', '/ˈnʌl.ə.faɪ/', 'Verb', 'C1', 'Làm mất hiệu lực pháp lý, hủy bỏ', 'Make legally null and void; invalidate.', 'The court ruled to nullify the merger agreement due to anti-monopoly violations.', 'Tòa án đã phán quyết hủy bỏ hiệu lực thỏa thuận sáp nhập do vi phạm luật chống độc quyền.', ARRAY['Invalidate', 'Annul', 'Void']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-72', 'toeic', 'Nonchalant', '/ˌnɑːn.ʃəˈlɑːnt/', 'Adj', 'C1', 'Thản nhiên, điềm tĩnh trước áp lực', 'Feeling or appearing casually calm and relaxed.', 'The spokesperson remained nonchalant despite aggressive questions from journalists.', 'Người phát ngôn vẫn giữ vẻ thản nhiên mặc cho những câu hỏi dồn dập từ các phóng viên.', ARRAY['Calm', 'Unruffled', 'Composed']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-73', 'toeic', 'Noticeable', '/ˈnoʊ.t̬ɪ.sə.bəl/', 'Adj', 'B1', 'Đáng chú ý, dễ nhận thấy', 'Easily seen or noticed; clear or apparent.', 'There has been a noticeable improvement in response times since the system update.', 'Đã có sự cải thiện rõ rệt trong thời gian phản hồi kể từ đợt nâng cấp hệ thống.', ARRAY['Conspicuous', 'Distinct', 'Apparent']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-74', 'toeic', 'Lucrative', '/ˈluː.krə.t̬ɪv/', 'Adj', 'B2', 'Béo bở, sinh lời rất cao', 'Producing a great deal of profit.', 'Securing the government cloud contract was a highly lucrative opportunity for the vendor.', 'Giành được hợp đồng đám mây của chính phủ là một cơ hội sinh lời rất lớn cho nhà cung cấp.', ARRAY['Profitable', 'Remunerative', 'Gainful']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-75', 'toeic', 'Liability', '/ˌlaɪ.əˈbɪl.ə.t̬i/', 'Noun', 'B2', 'Khoản nợ phải trả hoặc trách nhiệm pháp lý', 'A thing for which someone is responsible, especially a debt or financial obligation.', 'The financial audit revealed hidden liabilities that had not been recorded.', 'Cuộc kiểm toán tài chính phát hiện những khoản nợ tiềm ẩn chưa được hạch toán.', ARRAY['Debt', 'Financial obligation', 'Accountability']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-76', 'toeic', 'Jurisdiction', '/ˌdʒʊr.ɪsˈdɪk.ʃən/', 'Noun', 'C1', 'Quyền hạn tài phán, phạm vi pháp lý', 'The official power to make legal decisions and judgments.', 'Cross-border internet transactions often fall outside standard national jurisdiction.', 'Giao dịch qua mạng xuyên biên giới thường nằm ngoài phạm vi tài phán thông thường của quốc gia.', ARRAY['Authority', 'Territory', 'Control']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-77', 'toeic', 'Integrity', '/ɪnˈteɡ.rə.t̬i/', 'Noun', 'B2', 'Sự chính trực, tính toàn vẹn dữ liệu', 'The quality of being honest and having strong moral principles, or completeness.', 'Data integrity is critical when maintaining financial records for tax authorities.', 'Tính toàn vẹn của dữ liệu là điều tối quan trọng khi lưu trữ sổ sách tài chính phục vụ cơ quan thuế.', ARRAY['Honesty', 'Probity', 'Soundness']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-78', 'toeic', 'Incur', '/ɪnˈkɝː/', 'Verb', 'B2', 'Gánh chịu chi phí, chuốc lấy rủi ro', 'Become subject to something unwelcome or unpleasant as a result of one''s own behavior.', 'The firm will incur significant penalties if the delivery deadline is missed.', 'Công ty sẽ phải gánh chịu các khoản phạt nặng nề nếu để trễ hạn giao hàng.', ARRAY['Sustain', 'Experience', 'Bring upon']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-79', 'toeic', 'Flructure', '/ˈflaʊn.dɚ/', 'Verb', 'B2', 'Gặp trục trặc, lúng túng trong điều hành', 'Struggle or stagger helplessly or clumsily in water or mud, or financially.', 'Many small businesses floundered during the economic recession before recovering.', 'Nhiều doanh nghiệp nhỏ đã phải vật lộn chao đảo trong đợt suy thoái kinh tế trước khi phục hồi.', ARRAY['Struggle', 'Stumble', 'Falter']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-80', 'toeic', 'Fleet', '/fliːt/', 'Noun', 'B2', 'Đội tàu thuyền hoặc đội xe vận chuyển', 'A group of ships, vehicles, or aircraft operating together under the same ownership.', 'The delivery service expanded its electric van fleet to reduce greenhouse emissions.', 'Dịch vụ giao hàng đã mở rộng đội xe tải điện để giảm phát thải khí nhà kính.', ARRAY['Vehicle group', 'Conveyance pool']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-81', 'toeic', 'Fidelity', '/fɪˈdel.ə.t̬i/', 'Noun', 'C1', 'Lòng trung thành của đối tác, độ chân thực', 'Faithfulness to a person, cause, or belief, demonstrated by continuing loyalty.', 'High customer fidelity enabled the brand to endure intense competitive price wars.', 'Lòng trung thành lớn của khách hàng đã giúp thương hiệu đứng vững trước các cuộc chiến giảm giá khốc liệt.', ARRAY['Loyalty', 'Allegiance', 'Dedication']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-82', 'toeic', 'Fiscal', '/ˈfɪs.kəl/', 'Adj', 'B2', 'Thuộc về năm tài khóa, tài chính công', 'Relating to government revenue, especially taxes, or financial matters.', 'The corporation announced its results for fiscal year 2025 with record growth.', 'Tập đoàn đã công bố kết quả cho năm tài chính 2025 với mức tăng trưởng kỷ lục.', ARRAY['Financial', 'Monetary', 'Economic']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-83', 'toeic', 'Expenditure', '/ɪkˈspen.də.tʃɚ/', 'Noun', 'B2', 'Khoản chi tiêu ngân sách', 'An amount of money, time, or effort spent.', 'Capital expenditure on cutting-edge manufacturing robots will pay off over the next decade.', 'Khoản chi tiêu vốn cho robot sản xuất tiên tiến sẽ sinh lời trong suốt thập kỷ tới.', ARRAY['Spending', 'Outlay', 'Disbursement']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-84', 'toeic', 'Exempt', '/ɪɡˈzempt/', 'Adj', 'B2', 'Được miễn thuế hoặc miễn trừ nghĩa vụ', 'Free from an obligation or liability imposed on others.', 'Nonprofit educational institutions are largely exempt from local real estate taxes.', 'Các tổ chức giáo dục phi lợi nhuận phần lớn được miễn thuế bất động sản địa phương.', ARRAY['Free', 'Immune', 'Excused']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-85', 'toeic', 'Endeavor', '/enˈdev.ɚ/', 'Noun', 'B2', 'Sự nỗ lực, cố gắng thực hiện dự án', 'An attempt to achieve a goal; earnest and industrious effort.', 'Launching the global satellite communications system was a massive engineering endeavor.', 'Việc phóng hệ thống thông tin vệ tinh toàn cầu là một nỗ lực kỹ thuật to lớn.', ARRAY['Undertaking', 'Effort', 'Enterprise']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-86', 'toeic', 'Embargo', '/ɪmˈbɑːr.ɡoʊ/', 'Noun', 'C1', 'Lệnh cấm vận thương mại', 'An official ban on trade or other commercial activity with a particular country.', 'The international community imposed an oil embargo in response to the treaty violation.', 'Cộng đồng quốc tế đã áp đặt lệnh cấm vận dầu mỏ nhằm đáp trả hành vi vi phạm hiệp ước.', ARRAY['Trade ban', 'Sanction', 'Boycott']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-87', 'toeic', 'Eligibility', '/ˌel.ə.dʒəˈbɪl.ə.t̬i/', 'Noun', 'B2', 'Điều kiện hợp lệ, đủ tư cách tham gia', 'The state of having the right for something through meeting the required qualifications.', 'Candidates can review their eligibility criteria online prior to submitting application forms.', 'Các ứng viên có thể xem xét điều kiện hợp lệ trực tuyến trước khi nộp đơn xin việc.', ARRAY['Qualification', 'Fitness', 'Entitlement']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-88', 'toeic', 'Earmark', '/ˈɪr.mɑːrk/', 'Verb', 'C1', 'Dành riêng ngân sách cho mục đích cụ thể', 'Designate funds or resources for a specific purpose.', 'Five million dollars were earmarked for upgrading corporate cybersecurity infrastructure.', 'Năm triệu đô la đã được chỉ định dành riêng để nâng cấp hạ tầng an ninh mạng doanh nghiệp.', ARRAY['Designate', 'Allocate', 'Reserve']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-89', 'toeic', 'Dividend', '/ˈdɪv.ə.dend/', 'Noun', 'B2', 'Cổ tức chia cho cổ đông', 'A sum of money paid regularly by a company to its shareholders out of its profits.', 'The board declared an increase in quarterly dividend payouts following record profits.', 'Hội đồng quản trị tuyên bố tăng mức chi trả cổ tức hàng quý sau khi ghi nhận lợi nhuận kỷ lục.', ARRAY['Share of profits', 'Payout', 'Return']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-90', 'toeic', 'Discretion', '/dɪˈskreʃ.ən/', 'Noun', 'B2', 'Sự thận trọng, quyền tự quyết', 'The freedom to decide what should be done in a particular situation, or secrecy.', 'The hiring committee exercised strict discretion throughout the interview process.', 'Hội đồng tuyển dụng đã thể hiện sự thận trọng và bảo mật nghiêm ngặt trong suốt quá trình phỏng vấn.', ARRAY['Prudence', 'Judgment', 'Carefulness']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-91', 'toeic', 'Dilute', '/daɪˈluːt/', 'Verb', 'B2', 'Làm loãng cổ phiếu hoặc quyền biểu quyết', 'Make something thinner or weaker in value or quality.', 'Issuing additional common shares will dilute the equity ownership of current investors.', 'Việc phát hành thêm cổ phiếu phổ thông sẽ làm loãng tỷ lệ sở hữu vốn của các nhà đầu tư hiện tại.', ARRAY['Weaken', 'Water down', 'Diminish']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-92', 'toeic', 'Deregulation', '/ˌdiːˌreɡ.jəˈleɪ.ʃən/', 'Noun', 'C1', 'Sự bãi bỏ quy định gò bó thị trường', 'The reduction or elimination of government power in a particular industry.', 'Market deregulation in the energy sector fostered fierce price competition.', 'Việc bãi bỏ các quy định trong ngành năng lượng đã thúc đẩy cạnh tranh giá cả quyết liệt.', ARRAY['Liberalization', 'Free market reform']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-93', 'toeic', 'Deplete', '/dɪˈpliːt/', 'Verb', 'B2', 'Làm cạn kiệt nguồn lực dự trữ', 'Use up the supply or resources of something.', 'Unexpected logistical supply delays threatened to deplete our backup warehouse inventory.', 'Những sự chậm trễ hậu cần bất ngờ đe dọa làm cạn kiệt lượng hàng dự trữ trong kho của chúng tôi.', ARRAY['Exhaust', 'Drain', 'Empty']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-94', 'toeic', 'Demurrage', '/dɪˈmɝː.ɪdʒ/', 'Noun', 'C1', 'Phí phạt lưu bãi, lưu container trễ hạn', 'A charge payable to the owner of a chartered ship in respect of failure to load within time.', 'Importers paid steep demurrage fees due to severe congestion at the container terminal.', 'Các nhà nhập khẩu đã phải trả khoản phí lưu bãi rất cao do tình trạng ùn tắc nghiêm trọng tại cảng container.', ARRAY['Detention charge', 'Overdue holding fee']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-95', 'toeic', 'Delinquent', '/dɪˈlɪŋ.kwənt/', 'Adj', 'C1', 'Chậm trả nợ quá hạn nghiêm trọng', 'Failing to pay an outstanding debt or accomplish an official duty.', 'The automated billing system sends daily warnings to delinquent enterprise accounts.', 'Hệ thống thanh toán tự động gửi cảnh báo hàng ngày tới các tài khoản doanh nghiệp chậm nợ quá hạn.', ARRAY['Past due', 'Overdue', 'Defaulter']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-96', 'toeic', 'Defamation', '/ˌdef.əˈmeɪ.ʃən/', 'Noun', 'C1', 'Hành vi vu khống, bôi nhọ thanh danh', 'The action of damaging the good reputation of someone; slander or libel.', 'The corporate legal counsel initiated a lawsuit alleging commercial defamation.', 'Cố vấn pháp lý doanh nghiệp đã khởi kiện với cáo buộc bôi nhọ thanh danh thương mại.', ARRAY['Libel', 'Slander', 'Character assassination']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-97', 'toeic', 'Decree', '/dɪˈkriː/', 'Noun', 'C1', 'Sắc lệnh, nghị định pháp quy', 'An official order issued by a legal authority.', 'A ministerial decree was issued requiring all export firms to transition to paperless customs.', 'Nghị định của bộ đã được ban hành yêu cầu tất cả các doanh nghiệp xuất khẩu chuyển đổi sang thủ tục hải quan không dùng giấy tờ.', ARRAY['Edict', 'Ordinance', 'Mandate']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-98', 'toeic', 'Customs Broker', '/ˈkʌs.təmz ˌbroʊ.kɚ/', 'Noun', 'B2', 'Đại lý thông quan hải quan', 'A licensed professional that assists businesses in clearing goods through customs barriers.', 'Employing an authorized customs broker prevents costly cargo delays at international border ports.', 'Thuê đại lý thông quan hải quan giúp ngăn chặn tình trạng hàng hóa bị chậm trễ gây tốn kém tại các cửa khẩu quốc tế.', ARRAY['Import-export agent', 'Clearance agent']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-99', 'toeic', 'Curtail', '/kɚˈteɪl/', 'Verb', 'C1', 'Cắt giảm, hạn chế bớt chi tiêu', 'Reduce in extent or quantity; impose a restriction on.', 'The board instructed managers to curtail unnecessary international travel expenses.', 'Hội đồng quản trị đã chỉ đạo các nhà quản lý cắt giảm những khoản chi phí đi công tác nước ngoài không thực sự cần thiết.', ARRAY['Reduce', 'Cut back', 'Restrict']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-100', 'toeic', 'Covenant', '/ˈkʌv.ə.nənt/', 'Noun', 'C1', 'Cam kết giao ước pháp lý ràng buộc', 'An agreement or stipulation within a lease, deed, or contract.', 'The credit agreement contains strict covenants concerning minimum cash reserves.', 'Thỏa thuận tín dụng chứa các cam kết giao ước nghiêm ngặt liên quan đến mức dự trữ tiền mặt tối thiểu.', ARRAY['Pledge', 'Binding agreement', 'Promise']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('toeic-101', 'toeic', 'Contingency', '/kənˈtɪn.dʒən.si/', 'Noun', 'B2', 'Kế hoạch dự phòng rủi ro phát sinh', 'A future event or circumstance which is possible but cannot be predicted with certainty.', 'Every engineering project proposal must include a contingency budget for unforeseen delays.', 'Mọi đề xuất dự án kỹ thuật đều phải bao gồm khoản ngân sách dự phòng cho các sự cố chậm trễ không lường trước.', ARRAY['Backup plan', 'Emergency provision', 'Safeguard']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-1', 'ielts-academic', 'Substantiate', '/səbˈstæn.ʃi.eɪt/', 'Verb', 'C1', 'Chứng minh, đưa ra bằng chứng xác thực', 'Provide evidence to support or prove the truth of something.', 'The researcher failed to substantiate his controversial claims with empirical data.', 'Nhà nghiên cứu đã không thể chứng minh các tuyên bố gây tranh cãi của mình bằng dữ liệu thực nghiệm.', ARRAY['Corroborate', 'Validate', 'Verify']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-2', 'ielts-academic', 'Ubiquitous', '/juːˈbɪk.wə.t̬əs/', 'Adj', 'C1', 'Phổ biến khắp nơi, đâu đâu cũng thấy', 'Present, appearing, or found everywhere.', 'Smartphones have become ubiquitous across modern urban societies.', 'Điện thoại thông minh đã trở nên phổ biến khắp mọi nơi trong các xã hội đô thị hiện đại.', ARRAY['Omnipresent', 'Pervasive', 'Universal']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-3', 'ielts-academic', 'Paradigm', '/ˈper.ə.daɪm/', 'Noun', 'C1', 'Mô hình tư duy, khuôn mẫu chuẩn mực', 'A typical example or pattern of something; a model or worldview.', 'Quantum mechanics introduced a radical shift in the scientific paradigm.', 'Cơ học lượng tử đã tạo ra một bước chuyển mang tính cách mạng trong mô hình tư duy khoa học.', ARRAY['Framework', 'Model', 'Archetype']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-4', 'ielts-academic', 'Mitigate', '/ˈmɪt̬.ə.ɡeɪt/', 'Verb', 'B2', 'Làm giảm nhẹ, xoa dịu tác hại', 'Make something bad less severe, serious, or painful.', 'Governments must invest in seawalls to mitigate the destructive impact of storm surges.', 'Các chính phủ phải đầu tư vào đê chắn sóng để giảm nhẹ tác động tàn phá của triều cường.', ARRAY['Alleviate', 'Attenuate', 'Diminish']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-5', 'ielts-academic', 'Exacerbate', '/ɪɡˈzæs.ɚ.beɪt/', 'Verb', 'C1', 'Làm trầm trọng thêm tình hình', 'Make a problem, bad situation, or negative feeling worse.', 'Prolonged droughts will exacerbate the ongoing food crisis in arid regions.', 'Hạn hán kéo dài sẽ làm trầm trọng thêm cuộc khủng hoảng lương thực tại các vùng khô hạn.', ARRAY['Worsen', 'Aggravate', 'Intensify']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-6', 'ielts-academic', 'Empirical', '/emˈpɪr.ɪ.kəl/', 'Adj', 'C1', 'Dựa trên thực nghiệm và quan sát thực tế', 'Based on, concerned with, or verifiable by observation or experience rather than theory.', 'Scientific conclusions must be founded upon rigorous empirical research.', 'Các kết luận khoa học phải dựa trên những nghiên cứu thực nghiệm nghiêm ngặt.', ARRAY['Observational', 'Experimental', 'Evidence-based']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-7', 'ielts-academic', 'Delineate', '/dɪˈlɪn.i.eɪt/', 'Verb', 'C1', 'Phác họa, mô tả chi tiết ranh giới hoặc đặc điểm', 'Describe or portray something precisely; indicate the exact position of a border.', 'The treaty clearly delineates the maritime boundaries between the two neighboring states.', 'Hiệp ước vạch rõ ranh giới hàng hải giữa hai quốc gia láng giềng.', ARRAY['Outline', 'Depict', 'Demarcate']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-8', 'ielts-academic', 'Juxtapose', '/ˌdʒʌk.stəˈpoʊz/', 'Verb', 'C1', 'Đặt cạnh nhau để so sánh đối chiếu', 'Place or deal with close together for contrasting effect.', 'The exhibition juxtaposes contemporary sculptures with classical oil paintings.', 'Triển lãm đặt các tác phẩm điêu khắc đương đại cạnh các bức tranh sơn dầu cổ điển để đối chiếu.', ARRAY['Compare', 'Contrast', 'Collocate']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-9', 'ielts-academic', 'Anomalous', '/əˈnɑː.mə.ləs/', 'Adj', 'C1', 'Bất thường, dị thường khác với quy luật', 'Deviating from what is standard, normal, or expected.', 'Scientists observed anomalous temperature spikes near the volcanic ridge.', 'Các nhà khoa học đã quan sát thấy những đợt tăng nhiệt độ bất thường gần sườn núi lửa.', ARRAY['Atypical', 'Aberrant', 'Irregular']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-10', 'ielts-academic', 'Equivocal', '/ɪˈkwɪv.ə.kəl/', 'Adj', 'C1', 'Mơ hồ, nước đôi, khó giải nghĩa chính xác', 'Open to more than one interpretation; ambiguous.', 'The politician gave an equivocal response when asked about increasing carbon taxes.', 'Chính trị gia đã đưa ra câu trả lời nước đôi khi được hỏi về việc tăng thuế carbon.', ARRAY['Ambiguous', 'Evasive', 'Vague']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-11', 'ielts-academic', 'Prevalent', '/ˈprev.əl.ənt/', 'Adj', 'B2', 'Thịnh hành, phổ biến rộng rãi', 'Widespread in a particular area or at a particular time.', 'Obesity is increasingly prevalent among children living in urban environments.', 'Tình trạng béo phì ngày càng phổ biến trong số trẻ em sống ở khu vực thành thị.', ARRAY['Widespread', 'Common', 'Rife']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-12', 'ielts-academic', 'Disseminate', '/dɪˈsem.ə.neɪt/', 'Verb', 'C1', 'Truyền bá kiến thức, lan tỏa thông tin', 'Spread or disperse something, especially information, widely.', 'Public health authorities use social media to disseminate disease prevention guidelines.', 'Cơ quan y tế công cộng dùng mạng xã hội để phổ biến hướng dẫn phòng chống bệnh tật.', ARRAY['Circulate', 'Broadcast', 'Disperse']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-13', 'ielts-academic', 'Catalyst', '/ˈkæt̬.əl.ɪst/', 'Noun', 'C1', 'Chất xúc tác thúc đẩy sự thay đổi', 'A person or thing that precipitates an event or accelerates change.', 'The invention of the steam engine acted as a catalyst for the Industrial Revolution.', 'Phát minh ra động cơ hơi nước đóng vai trò như chất xúc tác cho Cách mạng Công nghiệp.', ARRAY['Trigger', 'Stimulus', 'Impetus']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-14', 'ielts-academic', 'Proponent', '/prəˈpoʊ.nənt/', 'Noun', 'B2', 'Người đề xướng, người ủng hộ quan điểm', 'A person who advocates a theory, proposal, or project.', 'Proponents of renewable energy argue that wind and solar power lower long-term costs.', 'Những người ủng hộ năng lượng tái tạo lập luận rằng năng lượng gió và mặt trời giúp hạ giá thành dài hạn.', ARRAY['Advocate', 'Champion', 'Supporter']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-15', 'ielts-academic', 'Detriment', '/ˈdet.rə.mənt/', 'Noun', 'C1', 'Sự tổn hại, thiệt hại cho điều gì đó', 'The state of being harmed or damaged.', 'Excessive focus on academic testing operates to the detriment of students'' creative thinking.', 'Việc quá chú trọng vào các kỳ thi học thuật gây tổn hại đến tư duy sáng tạo của học sinh.', ARRAY['Harm', 'Damage', 'Disadvantage']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-16', 'ielts-academic', 'Tenet', '/ˈten.ɪt/', 'Noun', 'C1', 'Nguyên lý cốt lõi, giáo lý căn bản', 'A principle or belief, especially one of the main principles of a religion or philosophy.', 'Freedom of speech is a fundamental tenet of modern democratic societies.', 'Tự do ngôn luận là nguyên lý cốt lõi của các xã hội dân chủ hiện đại.', ARRAY['Principle', 'Creed', 'Doctrine']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-17', 'ielts-academic', 'Cognitive', '/ˈkɑːɡ.nə.t̬ɪv/', 'Adj', 'B2', 'Thuộc về nhận thức và tư duy não bộ', 'Relating to the mental action or process of acquiring knowledge and understanding.', 'Bilingual children often exhibit superior cognitive flexibility compared to monolinguals.', 'Trẻ em song ngữ thường thể hiện sự linh hoạt nhận thức vượt trội so với trẻ đơn ngữ.', ARRAY['Intellectual', 'Mental', 'Perceptual']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-18', 'ielts-academic', 'Disparity', '/dɪˈspær.ə.t̬i/', 'Noun', 'C1', 'Sự chênh lệch lớn, bất bình đẳng sâu sắc', 'A great difference or inequality.', 'The economic disparity between rural and metropolitan areas continues to widen.', 'Sự chênh lệch kinh tế giữa vùng nông thôn và các đại đô thị tiếp tục nới rộng.', ARRAY['Imbalance', 'Inequality', 'Divergence']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-19', 'ielts-academic', 'Conglomerate', '/kənˈɡlɑː.mɚ.ət/', 'Noun', 'C1', 'Tập đoàn đa ngành khổng lồ', 'A number of different things or parts that are put or grouped together to form a whole.', 'The multinational media conglomerate owns television networks, publishers, and film studios.', 'Tập đoàn truyền thông đa ngành sở hữu mạng lưới truyền hình, nhà xuất bản và hãng phim.', ARRAY['Multinational group', 'Consortium']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-20', 'ielts-academic', 'Inherent', '/ɪnˈhɪr.ənt/', 'Adj', 'B2', 'Vốn có, gắn liền bản chất cố hữu', 'Existing in something as a permanent, essential, or characteristic attribute.', 'Every investment in emerging tech carries an inherent risk of financial volatility.', 'Mọi khoản đầu tư vào công nghệ mới nổi đều mang rủi ro biến động tài chính cố hữu.', ARRAY['Intrinsic', 'Innate', 'Inborn']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-21', 'ielts-academic', 'Proliferate', '/prəˈlɪf.ə.reɪt/', 'Verb', 'C1', 'Sinh sôi nảy nở, gia tăng nhanh chóng', 'Increase rapidly in numbers; multiply.', 'Digital payment apps have proliferated across developing economies in recent years.', 'Các ứng dụng thanh toán kỹ thuật số đã gia tăng đột biến tại các nền kinh tế đang phát triển gần đây.', ARRAY['Multiply', 'Burgeon', 'Mushroom']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-22', 'ielts-academic', 'Efficacy', '/ˈef.ə.kə.si/', 'Noun', 'C1', 'Hiệu lực, tính hiệu quả của phương pháp/thuốc', 'The ability to produce a desired or intended result.', 'Clinical trials confirmed the strong efficacy of the novel antiviral treatment.', 'Các thử nghiệm lâm sàng đã khẳng định hiệu lực vượt trội của liệu pháp kháng virus mới.', ARRAY['Effectiveness', 'Potency', 'Success']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-23', 'ielts-academic', 'Corroborate', '/kəˈrɑː.bə.reɪt/', 'Verb', 'C1', 'Củng cố tính xác thực, kiểm chứng độc lập', 'Confirm or give support to a statement, theory, or finding.', 'Independent lab tests corroborated the presence of microscopic plastic particles in the river.', 'Các kiểm nghiệm phòng thí nghiệm độc lập đã kiểm chứng sự hiện diện của hạt vi nhựa trên sông.', ARRAY['Confirm', 'Authenticate', 'Back up']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-24', 'ielts-academic', 'Pervasive', '/pɚˈveɪ.sɪv/', 'Adj', 'C1', 'Lan tỏa sâu rộng, tràn ngập mọi khía cạnh', 'Spreading widely throughout an area or a group of people.', 'Social media exercises a pervasive influence on teenage cultural values.', 'Mạng xã hội tạo nên ảnh hưởng sâu rộng lên các giá trị văn hóa của giới trẻ.', ARRAY['Prevalent', 'Permeating', 'Ubiquitous']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-25', 'ielts-academic', 'Pragmatic', '/præɡˈmæt̬.ɪk/', 'Adj', 'B2', 'Thực tế, thực dụng, trọng tính khả thi', 'Dealing with things sensibly and realistically in a way that is based on practical considerations.', 'A pragmatic approach to urban housing is needed to accommodate rising population demands.', 'Cần có một cách tiếp cận thực tế đối với nhà ở đô thị để đáp ứng nhu cầu dân số gia tăng.', ARRAY['Practical', 'Sensible', 'Realistic']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-26', 'ielts-academic', 'Ambiguity', '/ˌæm.bəˈɡjuː.ə.t̬i/', 'Noun', 'B2', 'Sự mơ hồ, nước đôi không rõ ràng', 'The quality of being open to more than one interpretation; inexactness.', 'Vague contractual language can lead to severe legal ambiguity and costly disputes.', 'Ngôn từ hợp đồng mơ hồ có thể dẫn tới sự không rõ ràng về mặt pháp lý và các tranh chấp tốn kém.', ARRAY['Uncertainty', 'Vagueness', 'Obscurity']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-27', 'ielts-academic', 'Heterogeneous', '/ˌhet̬.ɚ.oʊˈdʒiː.ni.əs/', 'Adj', 'C1', 'Không đồng nhất, đa dạng hỗn hợp', 'Diverse in character or content.', 'Modern international universities comprise a highly heterogeneous student population.', 'Các trường đại học quốc tế hiện đại sở hữu một cộng đồng sinh viên vô cùng đa dạng.', ARRAY['Diverse', 'Varied', 'Assorted']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-28', 'ielts-academic', 'Homogeneous', '/ˌhoʊ.moʊˈdʒiː.ni.əs/', 'Adj', 'C1', 'Đồng nhất, cùng một bản chất', 'Of the same kind; alike.', 'Isolated island communities often exhibit a relatively homogeneous genetic heritage.', 'Các cộng đồng đảo biệt lập thường thể hiện một di sản di truyền tương đối đồng nhất.', ARRAY['Uniform', 'Consistent', 'Identical']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-29', 'ielts-academic', 'Epitome', '/ɪˈpɪt.ə.mi/', 'Noun', 'C1', 'Hình mẫu thu nhỏ lý tưởng, tấm gương điển hình', 'A person or thing that is a perfect example of a particular quality or type.', 'The historic cathedral stands as the epitome of Gothic architectural grandeur.', 'Nhà thờ lịch sử sừng sững như một hình mẫu lý tưởng của vẻ tráng lệ kiến trúc Gothic.', ARRAY['Embodiment', 'Quintessence', 'Paragon']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-30', 'ielts-academic', 'Conducive', '/kənˈduː.sɪv/', 'Adj', 'C1', 'Tạo điều kiện thuận lợi, có lợi cho', 'Making a certain situation or outcome likely or possible.', 'A tranquil and well-lit library is highly conducive to deep academic focus.', 'Một thư viện yên tĩnh và đủ ánh sáng vô cùng thuận lợi cho sự tập trung học thuật chuyên sâu.', ARRAY['Beneficial', 'Favorable', 'Promotive']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-31', 'ielts-academic', 'Repercussion', '/ˌriː.pɚˈkʌʃ.ən/', 'Noun', 'C1', 'Hậu quả khôn lường, tác động dây chuyền tiêu cực', 'An unintended consequence occurring some time after an event or action, especially an unwelcome one.', 'Unchecked carbon emissions will have devastating repercussions for future coastal ecosystems.', 'Lượng phát thải carbon không được kiểm soát sẽ để lại những hậu quả nặng nề cho hệ sinh thái ven biển trong tương lai.', ARRAY['Aftermath', 'Consequence', 'Backlash']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-32', 'ielts-academic', 'Nuance', '/ˈnuː.ɑːns/', 'Noun', 'C1', 'Sắc thái tinh tế trong ngữ nghĩa/cảm xúc', 'A subtle difference in or shade of meaning, expression, or sound.', 'Mastering academic English requires appreciating the delicate nuances of formal vocabulary.', 'Để thành thạo tiếng Anh học thuật đòi hỏi phải cảm thụ được các sắc thái tinh tế của từ vựng trang trọng.', ARRAY['Subtlety', 'Shade', 'Refinement']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-33', 'ielts-academic', 'Salient', '/ˈseɪ.li.ənt/', 'Adj', 'C1', 'Nổi bật, cốt lõi, dễ nhận thấy nhất', 'Most noticeable or important.', 'The summary highlights the salient findings of the five-year climate investigation.', 'Bản tóm tắt nêu bật những phát hiện cốt lõi từ cuộc điều tra khí hậu kéo dài 5 năm.', ARRAY['Prominent', 'Conspicuous', 'Key']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-34', 'ielts-academic', 'Surmount', '/sɚˈmaʊnt/', 'Verb', 'C1', 'Vượt qua chướng ngại vật khó khăn', 'Overcome a difficulty or obstacle.', 'Through resilient perseverance, the engineering team surmounted every technical hurdle.', 'Nhờ lòng kiên trì bền bỉ, đội ngũ kỹ thuật đã vượt qua mọi rào cản công nghệ.', ARRAY['Overcome', 'Conquer', 'Master']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-35', 'ielts-academic', 'Diminish', '/dɪˈmɪn.ɪʃ/', 'Verb', 'B2', 'Giảm bớt, suy giảm dần', 'Make or become less.', 'Heavy deforestation significantly diminishes the natural water retention capacity of soil.', 'Nạn phá rừng nặng nề làm suy giảm đáng kể khả năng giữ nước tự nhiên của đất trồng.', ARRAY['Decrease', 'Lessen', 'Dwindle']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-36', 'ielts-academic', 'Comprehensive', '/ˌkɑːm.prəˈhen.sɪv/', 'Adj', 'B2', 'Toàn diện, bao quát mọi mặt', 'Complete and including everything that is necessary.', 'The Ministry of Education published a comprehensive guide to reformed curriculum standards.', 'Bộ Giáo dục đã xuất bản một bản hướng dẫn toàn diện về các tiêu chuẩn chương trình cải cách.', ARRAY['Exhaustive', 'Thorough', 'All-inclusive']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-37', 'ielts-academic', 'Synthesize', '/ˈsɪn.θə.saɪz/', 'Verb', 'C1', 'Tổng hợp và đúc kết thông tin', 'Combine a number of things into a coherent whole.', 'The thesis synthesizes findings from over one hundred international sociological papers.', 'Luận án tổng hợp các phát hiện từ hơn 100 bài báo xã hội học quốc tế.', ARRAY['Integrate', 'Amalgamate', 'Blend']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-38', 'ielts-academic', 'Paradox', '/ˈper.ə.dɑːks/', 'Noun', 'B2', 'Nghịch lý tưởng chừng mâu thuẫn', 'A seemingly absurd or self-contradictory statement that may prove to be well founded.', 'It is a cruel paradox that modern food production has never been higher yet hunger persists.', 'Thật là một nghịch lý trớ trêu khi sản lượng lương thực hiện đại cao chưa từng có nhưng nạn đói vẫn dai dẳng.', ARRAY['Contradiction', 'Inconsistency', 'Enigma']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-39', 'ielts-academic', 'Manifest', '/ˈmæn.ə.fest/', 'Verb', 'C1', 'Biểu hiện rõ ràng ra ngoài', 'Display or show a quality or feeling by one''s acts or appearance; demonstrate.', 'Chronic emotional stress can manifest as persistent physical ailments and fatigue.', 'Căng thẳng cảm xúc mãn tính có thể biểu hiện ra thành các bệnh lý thể chất kéo dài và sự mệt mỏi.', ARRAY['Exhibit', 'Demonstrate', 'Reveal']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-40', 'ielts-academic', 'Subordinate', '/səˈbɔːr.dən.ət/', 'Adj', 'C1', 'Phụ thuộc, có vị thế thứ yếu', 'Lower in rank or position.', 'Short-term financial convenience should remain subordinate to long-term environmental protection.', 'Lợi ích tài chính ngắn hạn phải xếp sau mục tiêu bảo vệ môi trường dài hạn.', ARRAY['Secondary', 'Lesser', 'Inferior']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-41', 'ielts-academic', 'Precipitate', '/priːˈsɪp.ə.teɪt/', 'Verb', 'C1', 'Gây ra biến cố dồn dập, đẩy nhanh sự cố', 'Cause an event or situation, typically one that is bad or undesirable, to happen suddenly.', 'The sudden collapse of the major investment bank precipitated a global market panic.', 'Sự sụp đổ đột ngột của ngân hàng đầu tư lớn đã châm ngòi cho một làn sóng hoảng loạn thị trường toàn cầu.', ARRAY['Trigger', 'Accelerate', 'Instigate']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-42', 'ielts-academic', 'Omnipotent', '/ɑːmˈnɪp.ə.tənt/', 'Adj', 'C1', 'Có toàn quyền, quyền năng vô hạn', 'Having unlimited power; able to do anything.', 'No national government is omnipotent in the face of cross-border environmental emergencies.', 'Không một chính phủ quốc gia nào có toàn quyền sức mạnh trước các tình trạng khẩn cấp môi trường xuyên biên giới.', ARRAY['All-powerful', 'Almighty', 'Supreme']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-43', 'ielts-academic', 'Obsolete', '/ˌɑːb.səˈliːt/', 'Adj', 'B2', 'Lỗi thời, không còn giá trị sử dụng', 'No longer produced or used; out of date.', 'Advancements in microprocessors rendered mechanical cash registers entirely obsolete.', 'Những tiến bộ trong bộ vi xử lý đã khiến các máy tính tiền cơ học trở nên hoàn toàn lỗi thời.', ARRAY['Outmoded', 'Antiquated', 'Defunct']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-44', 'ielts-academic', 'Null', '/nʌl/', 'Adj', 'B2', 'Vô hiệu, không có giá trị', 'Having no legal or binding force; invalid.', 'The contract was declared null and void after fraudulent misrepresentations were discovered.', 'Hợp đồng đã bị tuyên bố vô hiệu sau khi những hành vi gian dối bị phát hiện.', ARRAY['Invalid', 'Void', 'Inoperative']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-45', 'ielts-academic', 'Mandate', '/ˈmæn.deɪt/', 'Noun', 'B2', 'Thẩm quyền được ủy thác, lệnh bắt buộc', 'An official order or commission to do something.', 'The newly elected mayor received a clear public mandate to revitalize inner-city transit.', 'Thị trưởng mới đắc cử đã nhận được sự ủy thác rõ ràng từ cử tri để phục hưng hệ thống giao thông nội đô.', ARRAY['Authorization', 'Directive', 'Command']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-46', 'ielts-academic', 'Lucid', '/ˈluː.sɪd/', 'Adj', 'C1', 'Sáng sủa, mạch lạc, dễ hiểu', 'Expressed clearly; easy to understand.', 'The professor offered a remarkably lucid explanation of complex astrophysical models.', 'Giáo sư đã đưa ra lời giải thích sáng sủa và dễ hiểu một cách đáng kinh ngạc về các mô hình vật lý thiên văn phức tạp.', ARRAY['Clear', 'Coherent', 'Articulate']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-47', 'ielts-academic', 'Intrinsically', '/ɪnˈtrɪn.zɪ.kəl.i/', 'Adv', 'C1', 'Về bản chất cố hữu, tự thân', 'In an essential or natural way.', 'Human language is intrinsically creative and continually evolves across generations.', 'Ngôn ngữ loài người tự bản chất vốn có tính sáng tạo và liên tục tiến hóa qua các thế hệ.', ARRAY['Inherently', 'Fundamentally', 'Essentially']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-48', 'ielts-academic', 'Incurable', '/ɪnˈkjʊr.ə.bəl/', 'Adj', 'B2', 'Nan y, không thể chữa khỏi', 'Not able to be cured of a disease or medical condition.', 'Certain degenerative neuro conditions remain incurable despite decades of intense study.', 'Một số bệnh lý thoái hóa thần kinh vẫn chưa thể chữa khỏi dù trải qua nhiều thập kỷ nghiên cứu sâu.', ARRAY['Untreatable', 'Fatal', 'Terminal']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-49', 'ielts-academic', 'Implausible', '/ɪmˈplɑː.zə.bəl/', 'Adj', 'C1', 'Khó tin, không hợp lý', 'Not seeming reasonable or probable; failing to convince.', 'The defendant provided an implausible alibi that contradicted multiple security camera timestamps.', 'Bị cáo đã đưa ra chứng cứ ngoại phạm khó tin, mâu thuẫn với nhiều mốc thời gian camera an ninh.', ARRAY['Unlikely', 'Dubious', 'Far-fetched']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-50', 'ielts-academic', 'Imperative', '/ɪmˈper.ə.t̬ɪv/', 'Adj', 'B2', 'Cực kỳ cấp bách, mệnh lệnh bắt buộc', 'Of vital importance; crucial.', 'It is absolutely imperative that medical aid reaches isolated earthquake victims swiftly.', 'Điều tối khẩn cấp là hàng viện trợ y tế phải đến tay các nạn nhân động đất vùng cô lập một cách nhanh chóng.', ARRAY['Vital', 'Essential', 'Urgent']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-51', 'ielts-academic', 'Harness', '/ˈhɑːr.nəs/', 'Verb', 'B2', 'Khai thác triệt để nguồn năng lượng', 'Control and make use of natural resources, especially to produce energy.', 'Engineers are devising novel wave turbines to harness the power of ocean tidal currents.', 'Các kỹ sư đang thiết kế tua-bin sóng mới để khai thác sức mạnh của các dòng hải lưu thủy triều.', ARRAY['Utilize', 'Exploit', 'Channel']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-52', 'ielts-academic', 'Grave', '/ɡreɪv/', 'Adj', 'B2', 'Nghiêm trọng, trầm trọng', 'Giving cause for great alarm or concern; serious.', 'Depleting underground aquifers presents a grave threat to sustainable agriculture.', 'Sự cạn kiệt nguồn nước ngầm gây ra mối đe dọa nghiêm trọng đối với nền nông nghiệp bền vững.', ARRAY['Severe', 'Critical', 'Dire']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-53', 'ielts-academic', 'Formidable', '/fɔːrˈmɪd.ə.bəl/', 'Adj', 'C1', 'Đáng gờm, ghê gớm, thách thức lớn', 'Inspiring fear or respect through being impressively large, powerful, or capable.', 'Transitioning to carbon neutrality poses a formidable challenge for heavy industrial nations.', 'Chuyển đổi sang mức phát thải ròng bằng không đặt ra thách thức đáng gờm cho các quốc gia công nghiệp nặng.', ARRAY['Daunting', 'Formidable', 'Imposing']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-54', 'ielts-academic', 'Fluctuate', '/ˈflʌk.tʃu.eɪt/', 'Verb', 'B2', 'Dao động lên xuống thất thường', 'Rise and fall irregularly in number or amount.', 'Commodity prices fluctuate widely depending on global geopolitical tensions.', 'Giá cả hàng hóa dao động thất thường tùy thuộc vào căng thẳng địa chính trị toàn cầu.', ARRAY['Vary', 'Waver', 'Oscillate']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-55', 'ielts-academic', 'Feat', '/fiːt/', 'Noun', 'B2', 'Kỳ tích, chiến công phi thường', 'An achievement that requires great courage, skill, or strength.', 'Constructing the deep subsea tunnel under the stormy strait was a stunning engineering feat.', 'Việc xây dựng đường hầm ngầm dưới eo biển giông bão là một kỳ tích kỹ thuật đáng kinh ngạc.', ARRAY['Achievement', 'Triumph', 'Accomplishment']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-56', 'ielts-academic', 'Fabricate', '/ˈfæb.rə.keɪt/', 'Verb', 'C1', 'Bịa đặt thông tin, chế tạo lắp ráp', 'Invent or concoct something, typically with deceitful intent.', 'Unethical researchers fabricated experimental data to secure lucrative federal grant funds.', 'Những nhà nghiên cứu thiếu đạo đức đã ngụy tạo dữ liệu thực nghiệm để chiếm đoạt tiền tài trợ từ chính phủ.', ARRAY['Concoct', 'Forge', 'Invent']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-57', 'ielts-academic', 'Exemplify', '/ɪɡˈzem.plə.faɪ/', 'Verb', 'C1', 'Minh họa điển hình, làm ví dụ sáng tỏ', 'Be a typical example of.', 'Recent extreme heatwaves exemplify the accelerating severity of anthropogenic global warming.', 'Những đợt sóng nhiệt cực đoan gần đây là minh họa điển hình cho mức độ gia tăng nghiêm trọng của hiện tượng ấm lên toàn cầu do con người gây ra.', ARRAY['Illustrate', 'Typify', 'Embody']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-58', 'ielts-academic', 'Endorse', '/ɪnˈdɔːrs/', 'Verb', 'B2', 'Tán thành công khai, ký duyệt', 'Declare one''s public approval or support of.', 'International scientific academies unanimously endorse strict limits on atmospheric pollution.', 'Các viện hàn lâm khoa học quốc tế đều công khai tán thành việc giới hạn nghiêm ngặt ô nhiễm khí quyển.', ARRAY['Support', 'Back', 'Sanction']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-59', 'ielts-academic', 'Eloquent', '/ˈel.ə.kwənt/', 'Adj', 'C1', 'Hùng hồn, truyền cảm, lưu loát', 'Fluent or persuasive in speaking or writing.', 'The activist delivered an eloquent defense of human rights before the United Nations assembly.', 'Nhà hoạt động đã có bài phát biểu hùng hồn bảo vệ nhân quyền trước Đại hội đồng Liên Hợp Quốc.', ARRAY['Articulate', 'Persuasive', 'Expressive']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-60', 'ielts-academic', 'Elicit', '/iˈlɪs.ɪt/', 'Verb', 'C1', 'Gợi ra, khơi gợi phản hồi', 'Evoke or draw out a response, answer, or fact from someone.', 'The documentary succeeded in eliciting profound public empathy for climate refugees.', 'Bộ phim tài liệu đã thành công trong việc khơi gợi lòng trắc ẩn sâu sắc của công chúng đối với những người tị nạn khí hậu.', ARRAY['Evoke', 'Extract', 'Draw forth']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-61', 'ielts-academic', 'Dubious', '/ˈduː.bi.əs/', 'Adj', 'C1', 'Đáng ngờ, hồ nghi về độ tin cậy', 'Hesitating or doubting; not to be relied upon.', 'Economists cast dubious glances at the government''s overly optimistic growth projections.', 'Các nhà kinh tế học tỏ ra hoài nghi trước những dự báo tăng trưởng quá lạc quan của chính phủ.', ARRAY['Doubtful', 'Questionable', 'Skeptical']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-62', 'ielts-academic', 'Divergence', '/daɪˈvɝː.dʒəns/', 'Noun', 'C1', 'Sự phân kỳ, rẽ hướng khác biệt', 'The process of moving or extending in different directions from a common point.', 'There was a sharp divergence of opinions regarding monetary policy among council members.', 'Đã có sự phân kỳ ý kiến sâu sắc liên quan đến chính sách tiền tệ giữa các thành viên hội đồng.', ARRAY['Difference', 'Deviation', 'Separation']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-63', 'ielts-academic', 'Discontent', '/ˌdɪs.kənˈtent/', 'Noun', 'B2', 'Sự bất mãn, không hài lòng trong dân chúng', 'Dissatisfaction with one''s circumstances.', 'Rising inflation and frozen real wages sparked widespread public discontent across the nation.', 'Lạm phát tăng cao và tiền lương thực tế đình trệ đã làm bùng phát làn sóng bất mãn rộng khắp trong cả nước.', ARRAY['Dissatisfaction', 'Disaffection', 'Grievance']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-64', 'ielts-academic', 'Diminutive', '/dɪˈmɪn.jə.t̬ɪv/', 'Adj', 'C1', 'Nhỏ bé, tí hon', 'Extremely or unusually small.', 'Despite its diminutive size, the microcontroller computes complex sensor telemetry instantly.', 'Dù kích thước tí hon, vi điều khiển vẫn xử lý dữ liệu đo xa phức tạp từ cảm biến chỉ trong tích tắc.', ARRAY['Tiny', 'Minute', 'Miniature']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-65', 'ielts-academic', 'Diligent', '/ˈdɪl.ə.dʒənt/', 'Adj', 'B2', 'Cần cù, tận tụy, siêng năng', 'Having or showing care and conscientiousness in one''s work or duties.', 'Thanks to diligent archival research, historians identified the forgotten medieval treaty.', 'Nhờ nghiên cứu lưu trữ tài liệu tận tụy, các nhà sử học đã xác định được hiệp ước thời trung cổ từng bị lãng quên.', ARRAY['Conscientious', 'Assiduous', 'Meticulous']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-66', 'ielts-academic', 'Devise', '/dɪˈvaɪz/', 'Verb', 'B2', 'Nghĩ ra, sáng chế, đặt ra phương án', 'Plan or invent a complex procedure or system by careful thought.', 'Engineers devised a closed-loop irrigation system that conserves ninety percent of freshwater.', 'Các kỹ sư đã sáng chế ra hệ thống tưới tuần hoàn khép kín giúp tiết kiệm đến 90% nước ngọt.', ARRAY['Conceive', 'Formulate', 'Invent']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-67', 'ielts-academic', 'Deteriorate', '/dɪˈtɪr.i.ə.reɪt/', 'Verb', 'B2', 'Xuống cấp, suy thoái theo thời gian', 'Become progressively worse.', 'Air quality in mega-cities deteriorates significantly during winter inversion episodes.', 'Chất lượng không khí tại các siêu đô thị xuống cấp nghiêm trọng trong những đợt nghịch nhiệt mùa đông.', ARRAY['Worsen', 'Degrade', 'Decline']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-68', 'ielts-academic', 'Denounce', '/dɪˈnaʊns/', 'Verb', 'C1', 'Lên án kịch liệt, tố cáo công khai', 'Publicly declare to be wrong or evil.', 'The human rights committee convened to denounce unprovoked military aggression.', 'Ủy ban nhân quyền đã họp để lên án kịch liệt hành vi xâm lược vũ trang vô cớ.', ARRAY['Condemn', 'Censure', 'Criticize']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-69', 'ielts-academic', 'Deem', '/diːm/', 'Verb', 'C1', 'Nhận định, coi như là, phán xét', 'Regard or consider in a specified way.', 'The regional inspector deemed the old suspension bridge structurally unsound for traffic.', 'Thanh tra khu vực đã nhận định cây cầu treo cũ không còn an toàn về mặt kết cấu để lưu thông.', ARRAY['Consider', 'Judge', 'Hold']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-70', 'ielts-academic', 'Debilitate', '/dɪˈbɪl.ə.teɪt/', 'Verb', 'C1', 'Làm suy nhược, kiệt quệ sức lực', 'Make someone very weak and infirm.', 'Chronic joint inflammation can severely debilitate elderly patients if left unmanaged.', 'Viêm khớp mãn tính có thể làm suy kiệt trầm trọng các bệnh nhân cao tuổi nếu không được điều trị.', ARRAY['Weaken', 'Incapacitate', 'Enfeeble']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-71', 'ielts-academic', 'Cumbersome', '/ˈkʌm.bɚ.səm/', 'Adj', 'B2', 'Cồng kềnh, nặng nề, phức tạp khó dùng', 'Large or heavy and therefore difficult to carry or use; unwieldy.', 'Bureaucratic loan application forms are often too cumbersome for humble rural entrepreneurs.', 'Thủ tục xin vay vốn hành chính quan liêu thường quá cồng kềnh đối với các chủ doanh nghiệp nông thôn nhỏ.', ARRAY['Unwieldy', 'Ponderous', 'Clunky']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-72', 'ielts-academic', 'Crucial', '/ˈkruː.ʃəl/', 'Adj', 'B2', 'Then chốt, quyết định thành bại', 'Decisive or critical, especially in the success or failure of something.', 'Early language immersion plays a crucial role in bilingual cognitive development.', 'Việc tiếp xúc ngôn ngữ sớm đóng vai trò then chốt trong sự phát triển nhận thức của trẻ song ngữ.', ARRAY['Pivotal', 'Vital', 'Essential']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-73', 'ielts-academic', 'Converge', '/kənˈvɝːdʒ/', 'Verb', 'C1', 'Hội tụ về một điểm, đồng quy', 'Tend to meet at a point or gradually become similar.', 'Advanced computing and biotechnology are rapidly converging to revolutionize medicine.', 'Điện toán tiên tiến và công nghệ sinh học đang hội tụ nhanh chóng để tạo ra cuộc cách mạng y học.', ARRAY['Meet', 'Merge', 'Intersect']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-74', 'ielts-academic', 'Contemplate', '/ˈkɑːn.t̬əm.pleɪt/', 'Verb', 'B2', 'Trầm ngâm suy ngẫm, dự tính thấu đáo', 'Look thoughtfully for a long time at, or think deeply about.', 'Philosophers have long contemplated the profound existential mysteries of human consciousness.', 'Các triết gia từ lâu đã trầm ngâm suy ngẫm về những bí ẩn hiện sinh sâu sắc của ý thức loài người.', ARRAY['Reflect on', 'Meditate', 'Ponder']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-75', 'ielts-academic', 'Constrain', '/kənˈstreɪn/', 'Verb', 'C1', 'Gò bó, trói buộc, hạn chế quyền lực', 'Severely restrict the scope, extent, or activity of.', 'Budgetary limitations heavily constrain our ability to hire seasoned clinical psychologists.', 'Những hạn chế về ngân sách trói buộc nghiêm ngặt khả năng tuyển dụng chuyên gia tâm lý lâm sàng dày dặn kinh nghiệm.', ARRAY['Restrict', 'Inhibit', 'Limit']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-76', 'ielts-academic', 'Concur', '/kənˈkɝː/', 'Verb', 'C1', 'Đồng tình, nhất trí quan điểm', 'Be of the same opinion; agree.', 'All participating climatologists concurred that global average temperatures are rising.', 'Tất cả các nhà khí hậu học tham gia đều nhất trí quan điểm rằng nhiệt độ trung bình toàn cầu đang gia tăng.', ARRAY['Agree', 'Accord', 'Coincide']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-77', 'ielts-academic', 'Cohort', '/ˈkoʊ.hɔːrt/', 'Noun', 'C1', 'Nhóm đối tượng nghiên cứu đồng trang lứa', 'A group of people banded together or treated as a group in an epidemiological study.', 'The longitudinal medical study followed a cohort of 5,000 infants over two decades.', 'Nghiên cứu y học dọc đã theo dõi một nhóm 5.000 trẻ sơ sinh trong suốt hai thập kỷ.', ARRAY['Sample group', 'Demographic', 'Category']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-78', 'ielts-academic', 'Circumvent', '/ˌsɝː.kəmˈvent/', 'Verb', 'C1', 'Lách luật, tránh né rào cản khéo léo', 'Find a way around an obstacle or rule cleverly or dishonestly.', 'Multinational corporations often set up offshore subsidiaries to circumvent domestic tax laws.', 'Các tập đoàn đa quốc gia thường lập công ty con ở nước ngoài để lách luật thuế nội địa.', ARRAY['Bypass', 'Evade', 'Sidestep']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-79', 'ielts-academic', 'Cater', '/ˈkeɪ.t̬ɚ/', 'Verb', 'B2', 'Phục vụ đáp ứng nhu cầu chuyên biệt', 'Provide food and drink or provide what is needed or desired by someone.', 'The educational platform was engineered to cater specifically to visually impaired students.', 'Nền tảng giáo dục được thiết kế để phục vụ chuyên biệt cho các học sinh khiếm thị.', ARRAY['Serve', 'Accommodate', 'Provide for']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-80', 'ielts-academic', 'Bolster', '/ˈboʊl.stɚ/', 'Verb', 'B2', 'Củng cố vững chắc, tăng cường sức mạnh', 'Support or strengthen; prop up.', 'The central bank injected emergency liquidity into commercial lenders to bolster market confidence.', 'Ngân hàng trung ương đã bơm thanh khoản khẩn cấp cho các ngân hàng thương mại để củng cố niềm tin thị trường.', ARRAY['Strengthen', 'Reinforce', 'Fortify']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-81', 'ielts-academic', 'Axiomatic', '/ˌæk.si.əˈmæt̬.ɪk/', 'Adj', 'C1', 'Hiển nhiên, chân lý không cần bàn cãi', 'Self-evident or unquestionable.', 'It is an axiomatic principle of justice that an accused person is innocent until proven guilty.', 'Đó là một nguyên tắc công lý hiển nhiên rằng một người bị cáo buộc là vô tội cho đến khi chứng minh được có tội.', ARRAY['Self-evident', 'Indisputable', 'Given']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-82', 'ielts-academic', 'Augment', '/ɑːɡˈment/', 'Verb', 'C1', 'Gia tăng, tăng cường quy mô', 'Make something greater by adding to it; increase.', 'Many modern surgeons use augmented reality visors to augment spatial precision in the operating room.', 'Nhiều bác sĩ phẫu thuật hiện đại dùng kính thực tế tăng cường để tăng độ chuẩn xác về không gian trong phòng mổ.', ARRAY['Increase', 'Enhance', 'Amplify']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-83', 'ielts-academic', 'Ascribe', '/əˈskraɪb/', 'Verb', 'C1', 'Quy cho, gán cho nguyên nhân bởi', 'Attribute something to a cause, person, or origin.', 'Historians ascribe the decline of the empire to rampant administrative corruption and civil conflict.', 'Các nhà sử học quy sự suy tàn của đế chế cho nạn tham nhũng hành chính tràn lan và các cuộc xung đột nội bộ.', ARRAY['Attribute', 'Assign', 'Impute']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-84', 'ielts-academic', 'Articulate', '/ɑːrˈtɪk.jə.lət/', 'Verb', 'B2', 'Diễn đạt rành mạch, trình bày trôi chảy', 'Express an idea or feeling fluently and coherently.', 'She was able to articulate the technical complexities of the software architecture with effortless clarity.', 'Cô ấy có thể diễn đạt các mức độ phức tạp kỹ thuật của kiến trúc phần mềm với sự sáng rõ dễ dàng.', ARRAY['Express', 'Vocalize', 'Formulate']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-85', 'ielts-academic', 'Arbitrary', '/ˈɑːr.bə.trer.i/', 'Adj', 'C1', 'Tùy tiện, độc đoán không theo quy chuẩn', 'Based on random choice or personal whim, rather than any reason or system.', 'Critics argued that setting the tax exemption threshold at that arbitrary number was unfair.', 'Các nhà phê bình lập luận rằng việc đặt ngưỡng miễn thuế ở con số tùy tiện đó là không công bằng.', ARRAY['Random', 'Capricious', 'Subjective']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-86', 'ielts-academic', 'Apex', '/ˈeɪ.peks/', 'Noun', 'C1', 'Đỉnh cao tột bậc, điểm cực thịnh', 'The top or highest part of something, especially one forming a point.', 'Winning the Nobel Prize in Physics represented the absolute apex of her distinguished career.', 'Đoạt giải Nobel Vật lý đại diện cho đỉnh cao tột bậc trong sự nghiệp lẫy lừng của bà.', ARRAY['Pinnacle', 'Zenith', 'Peak']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-87', 'ielts-academic', 'Affluent', '/ˈæf.lu.ənt/', 'Adj', 'B2', 'Giàu có, khá giả, dồi dào tài nguyên', 'Having a great deal of money; wealthy.', 'Investment in private tutoring is disproportionately concentrated in affluent suburban neighborhoods.', 'Đầu tư vào việc học thêm tư nhân tập trung phần lớn ở các khu ngoại ô giàu có.', ARRAY['Wealthy', 'Prosperous', 'Well-off']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-88', 'ielts-academic', 'Adverse', '/ædˈvɝːs/', 'Adj', 'B2', 'Bất lợi, gây hại, tiêu cực', 'Preventing success or development; harmful; unfavorable.', 'The vaccine was thoroughly tested to ensure it causes no adverse immunological reactions.', 'Vắc-xin đã được thử nghiệm kỹ lưỡng để đảm bảo không gây ra các phản ứng miễn dịch bất lợi nào.', ARRAY['Unfavorable', 'Disadvantageous', 'Detrimental']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-89', 'ielts-academic', 'Adjacent', '/əˈdʒeɪ.sənt/', 'Adj', 'B2', 'Kế bên, liền kề, giáp ranh', 'Next to or adjoining something else.', 'The medical research laboratory is situated immediately adjacent to the university hospital.', 'Phòng thí nghiệm nghiên cứu y học tọa lạc ngay liền kề bệnh viện đại học.', ARRAY['Neighboring', 'Contiguous', 'Adjoining']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-90', 'ielts-academic', 'Acquiesce', '/ˌæk.wiˈes/', 'Verb', 'C1', 'Bằng lòng miễn cưỡng, ưng thuận ngầm', 'Accept something reluctantly but without protest.', 'Management ultimately had to acquiesce to the labor union''s demands for safer work conditions.', 'Ban quản lý cuối cùng đã phải chấp thuận các yêu sách của công đoàn về điều kiện làm việc an toàn hơn.', ARRAY['Comply', 'Consent', 'Concede']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-91', 'ielts-academic', 'Accentuate', '/ækˈsen.tʃu.eɪt/', 'Verb', 'B2', 'Làm nổi bật, nhấn mạnh thêm', 'Make more noticeable or prominent.', 'The dramatic spotlights accentuate the intricate details of the historical marble monument.', 'Những ngọn đèn chiếu điểm kịch tính làm nổi bật các chi tiết chạm khắc tinh xảo của tượng đài cẩm thạch lịch sử.', ARRAY['Highlight', 'Emphasize', 'Underscore']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-92', 'ielts-academic', 'Abstain', '/æbˈsteɪn/', 'Verb', 'B2', 'Kiêng khem, bỏ phiếu trắng', 'Restrain oneself from doing or enjoying something, or formally decline to vote.', 'Several non-aligned delegations decided to abstain during the contentious diplomatic vote.', 'Một vài phái đoàn không liên kết đã quyết định bỏ phiếu trắng trong cuộc bỏ phiếu ngoại giao gây tranh cãi.', ARRAY['Refrain', 'Withhold', 'Desist']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-93', 'ielts-academic', 'Vindicate', '/ˈvɪn.də.keɪt/', 'Verb', 'C1', 'Minh oan, chứng minh sự đúng đắn sau hoài nghi', 'Clear someone of blame or suspicion; show or prove to be right, reasonable, or justified.', 'Recent archaeological excavations vindicated his long-doubted theory about Bronze Age maritime trade.', 'Các cuộc khai quật khảo cổ gần đây đã chứng minh sự đúng đắn của giả thuyết về thương mại hàng hải thời Đồ Đồng từng bị hoài nghi từ lâu của ông.', ARRAY['Exonerate', 'Justify', 'Validate']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-94', 'ielts-academic', 'Vacillate', '/ˈvæs.əl.eɪt/', 'Verb', 'C1', 'Do dự, dao động thiếu quyết đoán', 'Waver between different opinions or actions; be indecisive.', 'The prime minister continued to vacillate over whether to impose strict nationwide energy rationing.', 'Thủ tướng tiếp tục do dự không biết có nên áp đặt việc phân bổ hạn ngạch năng lượng nghiêm ngặt trên toàn quốc hay không.', ARRAY['Hesitate', 'Fluctuate', 'Waver']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-95', 'ielts-academic', 'Utilitarian', '/juːˌtɪl.əˈter.i.ən/', 'Adj', 'C1', 'Mang tính thực dụng, chú trọng công năng', 'Designed to be useful or practical rather than attractive.', 'Post-war architectural housing projects were predominantly utilitarian and austere in appearance.', 'Các dự án nhà ở thời hậu chiến chủ yếu mang tính thực dụng và có vẻ ngoài mộc mạc đơn giản.', ARRAY['Functional', 'Practical', 'Pragmatic']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-96', 'ielts-academic', 'Ubiquity', '/juːˈbɪk.wə.t̬i/', 'Noun', 'C1', 'Tính phổ biến tràn ngập khắp nơi', 'The fact of appearing everywhere or of being very common.', 'The ubiquity of automated algorithmic recommendations shapes the listening habits of billions.', 'Sự phổ biến ở khắp nơi của thuật toán đề xuất tự động định hình thói quen nghe nhạc của hàng tỷ người.', ARRAY['Omnipresence', 'Pervasiveness']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-97', 'ielts-academic', 'Tenable', '/ˈten.ə.bəl/', 'Adj', 'C1', 'Có thể bảo vệ, đứng vững trước lý lẽ phản bác', 'Able to be maintained or defended against attack or objection.', 'In light of recent climate findings, the assertion that sea levels are stable is no longer tenable.', 'Trước những phát hiện khí hậu gần đây, khẳng định rằng mực nước biển ổn định không còn có thể đứng vững được nữa.', ARRAY['Defensible', 'Justifiable', 'Sound']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-98', 'ielts-academic', 'Temporal', '/ˈtem.pɚ.əl/', 'Adj', 'C1', 'Thuộc về thời gian, thế tục', 'Relating to worldly as opposed to spiritual affairs; relating to time.', 'The philosophical inquiry explores how humans construct their internal temporal awareness.', 'Cuộc khảo cứu triết học khám phá cách con người hình thành nhận thức về thời gian bên trong tâm trí mình.', ARRAY['Chronological', 'Secular', 'Time-related']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-99', 'ielts-academic', 'Tangible', '/ˈtæn.dʒə.bəl/', 'Adj', 'B2', 'Hữu hình, có thể sờ mó hoặc cảm nhận rõ', 'Perceptible by touch; clear and definite; real.', 'The vocational education initiative produced tangible economic improvements for rural youths.', 'Sáng kiến đào tạo nghề đã mang lại những cải thiện kinh tế rõ ràng hữu hình cho thanh niên nông thôn.', ARRAY['Palpable', 'Concrete', 'Real']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-100', 'ielts-academic', 'Tacit', '/ˈtæs.ɪt/', 'Adj', 'C1', 'Ngầm hiểu, không cần nói ra', 'Understood or implied without being stated directly.', 'There was a tacit agreement among the researchers that all raw data would be shared openly.', 'Có một sự đồng thuận ngầm giữa các nhà nghiên cứu rằng toàn bộ dữ liệu thô sẽ được chia sẻ cởi mở.', ARRAY['Implicit', 'Unspoken', 'Implied']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-101', 'ielts-academic', 'Susceptible', '/səˈsep.tə.bəl/', 'Adj', 'B2', 'Dễ bị tổn thương, nhạy cảm trước tác động', 'Likely or liable to be influenced or harmed by a particular thing.', 'Premature infants are exceptionally susceptible to airborne respiratory viral infections.', 'Trẻ sinh non đặc biệt dễ bị tổn thương trước các bệnh nhiễm trùng đường hô hấp do virus lây qua không khí.', ARRAY['Vulnerable', 'Prone', 'Receptive']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-102', 'ielts-academic', 'Stratify', '/ˈstræt̬.ə.faɪ/', 'Verb', 'C1', 'Phân tầng giai cấp hoặc lớp địa chất', 'Arrange or classify into different social or physical strata.', 'Industrial capitalism can inadvertently stratify society into rigid wealth tiers.', 'Chủ nghĩa tư bản công nghiệp có thể vô tình phân tầng xã hội thành các nấc thang của cải cứng nhắc.', ARRAY['Classify', 'Grade', 'Layer']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-103', 'ielts-academic', 'Spurious', '/ˈspjʊr.i.əs/', 'Adj', 'C1', 'Ngụy tạo, giả mạo, lập luận sai lầm', 'Not being what it purports to be; false or fake.', 'The statistical correlation between ice cream sales and shark attacks is entirely spurious.', 'Mối tương quan thống kê giữa doanh số bán kem và các vụ cá mập tấn công là hoàn toàn ngụy tạo.', ARRAY['Bogus', 'Fraudulent', 'False']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-104', 'ielts-academic', 'Relegate', '/ˈrel.ə.ɡeɪt/', 'Verb', 'C1', 'Đẩy xuống vị trí thứ yếu, hạ cấp', 'Consign or dismiss to an inferior rank or position.', 'Women scientists in that historical epoch were unjustifiably relegated to administrative tasks.', 'Các nhà khoa học nữ trong thời kỳ lịch sử đó từng bị giáng xuống làm các công việc hành chính một cách bất công.', ARRAY['Demote', 'Downgrade', 'Lower']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-105', 'ielts-academic', 'Reciprocal', '/rɪˈsɪp.rə.kəl/', 'Adj', 'C1', 'Có đi có lại, tương hỗ qua lại', 'Given, felt, or done in return; mutually corresponding.', 'The bilateral agreement guarantees reciprocal visa exemptions for business travelers.', 'Thỏa thuận song phương đảm bảo miễn thị thực có đi có lại cho các doanh nhân đi công tác.', ARRAY['Mutual', 'Complementary', 'Shared']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-106', 'ielts-academic', 'Quasi', '/ˈkweɪ.zaɪ/', 'Adj', 'C1', 'Tương tự như, bán phần, gần như', 'Apparently but not really; seemingly.', 'The quasi-independent regulatory commission oversees compliance across digital payment systems.', 'Ủy ban quản lý bán độc lập giám sát việc tuân thủ quy định trên các hệ thống thanh toán kỹ thuật số.', ARRAY['Semi', 'Pseudo', 'Apparent']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-107', 'ielts-academic', 'Plausible', '/ˈplɑː.zə.bəl/', 'Adj', 'B2', 'Hợp lý, có vẻ đáng tin', 'Seeming reasonable or probable.', 'Astrobiologists put forward a plausible explanation for the presence of methane in the atmosphere.', 'Các nhà sinh học vũ trụ đã đưa ra một lời giải thích hợp lý cho sự xuất hiện của khí metan trong khí quyển.', ARRAY['Credible', 'Believable', 'Feasible']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-108', 'ielts-academic', 'Permeate', '/ˈpɝː.mi.eɪt/', 'Verb', 'C1', 'Thấm nhuần, lan tỏa khắp ngóc ngách', 'Spread throughout something; pervade.', 'The scent of wild pine needles permeated the cool morning mountain air.', 'Mùi thơm của lá thông rừng thấm đẫm vào bầu không khí miền núi ban mai mát lạnh.', ARRAY['Pervade', 'Infiltrate', 'Saturate']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-109', 'ielts-academic', 'Pedagogical', '/ˌped.əˈɡɑː.dʒɪ.kəl/', 'Adj', 'C1', 'Thuộc về phương pháp sư phạm giảng dạy', 'Relating to teaching methods and academic instruction.', 'The newly introduced interactive tablets represent a major pedagogical evolution in the classroom.', 'Những chiếc máy tính bảng tương tác mới được giới thiệu đại diện cho một bước tiến sư phạm lớn trong lớp học.', ARRAY['Instructional', 'Educational', 'Academic']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-110', 'ielts-academic', 'Omniscient', '/ɑːmˈnɪʃ.ənt/', 'Adj', 'C1', 'Biết tuốt, toàn tri thấu hiểu mọi sự', 'Knowing everything.', 'Classical third-person novels often employ an omniscient narrator who sees into every character''s mind.', 'Các tiểu thuyết ngôi thứ ba cổ điển thường sử dụng một người kể chuyện toàn tri thấu suốt tâm can mọi nhân vật.', ARRAY['All-knowing', 'Pansophical']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-111', 'ielts-academic', 'Juxtaposition', '/ˌdʒʌk.stə.pəˈzɪʃ.ən/', 'Noun', 'C1', 'Sự đặt cạnh nhau để làm nổi bật tương phản', 'The fact of two things being seen or placed close together with contrasting effect.', 'The striking juxtaposition of sleek modern skyscrapers alongside ancient shrines defines the city skyline.', 'Sự đặt cạnh nhau đầy ấn tượng giữa những tòa nhà chọc trời hiện đại bóng bẩy và các ngôi đền cổ xưa định hình nên đường chân trời của thành phố.', ARRAY['Contrast', 'Comparison', 'Proximity']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-112', 'ielts-academic', 'Incongruous', '/ɪnˈkɑːŋ.ɡru.əs/', 'Adj', 'C1', 'Lạc lõng, không ăn nhập, không phù hợp hoàn cảnh', 'Not in harmony or keeping with the surroundings or other aspects of something.', 'The modern glass elevator looked entirely incongruous inside the 12th-century stone castle.', 'Chiếc thang máy kính hiện đại trông hoàn toàn không ăn nhập bên trong lâu đài đá thế kỷ 12.', ARRAY['Out of place', 'Incompatible', 'Jarring']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-113', 'ielts-academic', 'Holistic', '/hoʊˈlɪs.tɪk/', 'Adj', 'B2', 'Toàn diện, tổng thể không tách rời', 'Characterized by the treatment of the whole person, taking into account mental and social factors.', 'Holistic health approaches integrate proper balanced nutrition, physical exercise, and mental well-being.', 'Các cách tiếp cận sức khỏe tổng thể kết hợp dinh dưỡng cân bằng hợp lý, rèn luyện thể chất và an lạc tinh thần.', ARRAY['Comprehensive', 'Integrated', 'All-encompassing']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-114', 'ielts-academic', 'Feasible', '/ˈfiː.zə.bəl/', 'Adj', 'B2', 'Khả thi, thực tiễn có thể làm được', 'Possible to do easily or conveniently.', 'It is technically feasible to produce zero-emission hydrogen fuel cells at commercial scale.', 'Việc sản xuất pin nhiên liệu hydro không phát thải ở quy mô thương mại là hoàn toàn khả thi về mặt kỹ thuật.', ARRAY['Viable', 'Achievable', 'Practical']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-115', 'ielts-academic', 'Ephemeral', '/ɪˈfem.ɚ.əl/', 'Adj', 'C1', 'Phù du, chóng tàn, tồn tại trong chốc lát', 'Lasting for a very short time.', 'The dazzling colors of cherry blossoms are famously beautiful yet ephemeral.', 'Sắc màu rực rỡ của hoa anh đào nổi tiếng là tuyệt đẹp nhưng lại sớm nở tối tàn.', ARRAY['Transitory', 'Transient', 'Fleeting']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-116', 'ielts-academic', 'Disparity', '/dɪˈspær.ə.t̬i/', 'Noun', 'C1', 'Sự cách biệt sâu sắc về trình độ/của cải', 'A great difference, especially an unjust inequality.', 'International organizations strive to diminish the wide educational disparity between urban and rural girls.', 'Các tổ chức quốc tế nỗ lực thu hẹp khoảng cách giáo dục sâu sắc giữa các bé gái thành thị và nông thôn.', ARRAY['Inequality', 'Imbalance', 'Divergence']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-117', 'ielts-academic', 'Cognizant', '/ˈkɑːɡ.nɪ.zənt/', 'Adj', 'C1', 'Có nhận thức rõ ràng, ý thức thấu đáo', 'Having knowledge or being aware of.', 'Urban planners must remain fully cognizant of ecological preservation during infrastructure expansion.', 'Các nhà quy hoạch đô thị phải luôn ý thức thấu đáo về việc bảo tồn sinh thái trong quá trình mở rộng hạ tầng.', ARRAY['Aware', 'Conscious', 'Mindful']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-118', 'ielts-academic', 'Banal', '/bəˈnɑːl/', 'Adj', 'C1', 'Tầm thường, sáo rỗng, nhàm chán', 'So lacking in originality as to be obvious and boring.', 'The candidate''s acceptance speech was widely criticized for relying on banal clichés rather than concrete policy.', 'Bài phát biểu nhận chức của ứng viên bị chỉ trích rộng rãi vì dựa dẫm vào các khẩu hiệu sáo rỗng thay vì chính sách cụ thể.', ARRAY['Clichéd', 'Trite', 'Hackneyed']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-119', 'ielts-academic', 'Anomaly', '/əˈnɑː.mə.li/', 'Noun', 'C1', 'Hiện tượng bất thường, dị thường', 'Something that deviates from what is standard, normal, or expected.', 'A sudden drop in ocean salinity near the glacier was an alarming environmental anomaly.', 'Sự sụt giảm đột ngột độ mặn nước biển gần sông băng là một hiện tượng dị thường về môi trường đáng báo động.', ARRAY['Irregularity', 'Abnormality', 'Deviation']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('ielts-120', 'ielts-academic', 'Alleviate', '/əˈliː.vi.eɪt/', 'Verb', 'B2', 'Làm dịu bớt nỗi đau, xoa dịu áp lực', 'Make suffering, deficiency, or a problem less severe.', 'The municipal council introduced emergency bus rapid lanes to alleviate severe rush hour traffic.', 'Hội đồng thành phố đã đưa vào sử dụng các làn xe buýt nhanh khẩn cấp để giảm bớt tình trạng ùn tắc giờ cao điểm nghiêm trọng.', ARRAY['Relieve', 'Ease', 'Mitigate']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-1', 'business', 'Consensus', '/kənˈsen.səs/', 'Noun', 'C1', 'Sự đồng thuận chung của ban điều hành', 'A generally accepted opinion or decision among a group of people.', 'The board reached a unanimous consensus to enter the Southeast Asian market.', 'Hội đồng quản trị đã đạt được sự đồng thuận nhất trí để tiến vào thị trường Đông Nam Á.', ARRAY['Agreement', 'Harmony', 'Concurrence']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-2', 'business', 'Feasibility', '/ˌfiː.zəˈbɪl.ə.t̬i/', 'Noun', 'B2', 'Tính khả thi của đề án kinh doanh', 'The state or degree of being easily or conveniently done.', 'We conducted a comprehensive study to evaluate the feasibility of opening twenty new retail stores.', 'Chúng tôi đã thực hiện một nghiên cứu toàn diện nhằm đánh giá tính khả thi của việc mở 20 cửa hàng bán lẻ mới.', ARRAY['Viability', 'Practicability', 'Workability']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-3', 'business', 'Stakeholder', '/ˈsteɪkˌhoʊl.dɚ/', 'Noun', 'B2', 'Bên liên quan (nhà đầu tư, khách hàng, nhân sự)', 'A person with an interest or concern in something, especially a business.', 'Transparent communication with internal and external stakeholders is crucial for brand trust.', 'Giao tiếp minh bạch với các bên liên quan nội bộ và bên ngoài là điều cốt tử để xây dựng lòng tin thương hiệu.', ARRAY['Shareholder', 'Partner', 'Collaborator']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-4', 'business', 'Leverage', '/ˈlev.ɚ.ɪdʒ/', 'Verb', 'C1', 'Tận dụng đòn bẩy nguồn lực tối đa', 'Use something to maximum advantage.', 'Startups often leverage viral influencer marketing to gain initial customer traction.', 'Các công ty khởi nghiệp thường tận dụng đòn bẩy tiếp thị người ảnh hưởng để thu hút khách hàng ban đầu.', ARRAY['Capitalize on', 'Exploit positively', 'Utilize']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-5', 'business', 'Benchmark', '/ˈbentʃ.mɑːrk/', 'Noun', 'B2', 'Chuẩn mực đối sánh chất lượng', 'A standard or point of reference against which things may be compared.', 'Our customer retention rates set the new gold benchmark for the enterprise SaaS industry.', 'Tỷ lệ giữ chân khách hàng của chúng tôi đã thiết lập chuẩn mực vàng mới cho toàn ngành SaaS doanh nghiệp.', ARRAY['Standard', 'Criterion', 'Yardstick']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-6', 'business', 'Milestone', '/ˈmaɪl.stoʊn/', 'Noun', 'B1', 'Cột mốc tăng trưởng quan trọng', 'A significant stage or event in the development of something.', 'Surpassing one million active daily users was an unforgettable corporate milestone.', 'Vượt qua một triệu người dùng hoạt động mỗi ngày là một cột mốc công ty không thể nào quên.', ARRAY['Landmark', 'Turning point', 'Breakthrough']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-7', 'business', 'Synergy', '/ˈsɪn.ɚ.dʒi/', 'Noun', 'B2', 'Hiệu ứng cộng hưởng sức mạnh', 'The interaction or cooperation of two or more organizations to produce a combined effect greater than the sum of their separate parts.', 'The strategic merger created powerful synergies across logistics, marketing, and R&D operations.', 'Vụ sáp nhập chiến lược đã tạo ra hiệu ứng cộng hưởng mạnh mẽ trên các mảng hậu cần, tiếp thị và nghiên cứu phát triển.', ARRAY['Collaboration', 'Combined effort', 'Symbiosis']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-8', 'business', 'Streamline', '/ˈstriːm.laɪn/', 'Verb', 'B2', 'Tinh giản quy trình, tối ưu hóa bộ máy', 'Make an organization or system more efficient and effective by employing faster or simpler working methods.', 'Automating invoice processing allowed us to streamline accounting operations significantly.', 'Việc tự động hóa xử lý hóa đơn đã cho phép chúng tôi tinh giản các quy trình kế toán một cách đáng kể.', ARRAY['Optimize', 'Simplify', 'Modernize']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-9', 'business', 'Scalability', '/ˌskeɪ.ləˈbɪl.ə.t̬i/', 'Noun', 'B2', 'Khả năng mở rộng quy mô linh hoạt', 'The capacity to be changed in size or scale.', 'Cloud infrastructure offers unmatched scalability as transaction volumes spike during flash sales.', 'Hạ tầng đám mây mang lại khả năng mở rộng quy mô vô song khi khối lượng giao dịch tăng vọt trong đợt giảm giá chớp nhoáng.', ARRAY['Expandability', 'Adaptability', 'Flexibility']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-10', 'business', 'Downsizing', '/ˈdaʊnˌsaɪ.zɪŋ/', 'Noun', 'B2', 'Sự thu hẹp quy mô nhân sự', 'The act of reducing the number of employees on a company''s payroll.', 'Economic headwinds forced the conglomerate into painful downsizing across non-core divisions.', 'Những cơn gió ngược kinh tế đã buộc tập đoàn phải thu hẹp quy mô đau đớn trên khắp các phòng ban phi cốt lõi.', ARRAY['Workforce reduction', 'Staff cuts', 'Right-sizing']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-11', 'business', 'Outsourcing', '/ˈaʊtˌsɔːr.sɪŋ/', 'Noun', 'B1', 'Gia công ngoài, thuê ngoài dịch vụ', 'Obtaining goods or services from an outside or foreign supplier.', 'Outsourcing customer service to specialized centers reduced operational expenses by 35 percent.', 'Việc thuê ngoài dịch vụ chăm sóc khách hàng tới các trung tâm chuyên nghiệp đã giảm 35% chi phí vận hành.', ARRAY['External contracting', 'Contracting out']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-12', 'business', 'Turnaround', '/ˈtɝːn.ə.raʊnd/', 'Noun', 'B2', 'Sự đảo ngược tình thế, phục hồi ngoạn mục', 'An abrupt or unexpected change, especially one that results in a more favorable outcome.', 'The new CEO orchestrated a miraculous turnaround that saved the airline from imminent bankruptcy.', 'Tổng giám đốc mới đã kiến tạo một cú lội ngược dòng kỳ diệu cứu hãng hàng không khỏi nguy cơ phá sản cận kề.', ARRAY['Recovery', 'Rebound', 'Reversal']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-13', 'business', 'Brand Equity', '/brænd ˈek.wə.t̬i/', 'Noun', 'B2', 'Giá trị tài sản thương hiệu trong lòng khách hàng', 'The commercial value that derives from consumer perception of the brand name of a particular product.', 'Apple commands enormous brand equity, allowing it to maintain premium price margins.', 'Apple nắm giữ giá trị tài sản thương hiệu khổng lồ, cho phép hãng duy trì mức biên lợi nhuận cao cấp.', ARRAY['Brand worth', 'Reputational capital']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-14', 'business', 'Market Penetration', '/ˈmɑːr.kɪt ˌpen.əˈtreɪ.ʃən/', 'Noun', 'B2', 'Độ thâm nhập thị trường', 'The extent to which a product is recognized and bought by customers in a particular market.', 'Aggressive introductory pricing drove rapid market penetration in tier-two cities.', 'Mức giá giới thiệu cạnh tranh quyết liệt đã thúc đẩy mức thâm nhập thị trường thần tốc tại các đô thị loại hai.', ARRAY['Market share expansion', 'Market reach']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-15', 'business', 'Overhaul', '/ˈoʊ.vɚ.hɑːl/', 'Verb', 'B2', 'Đại tu toàn diện hệ thống', 'Take apart a piece of machinery or equipment in order to examine and repair it; thoroughly reform.', 'The engineering director decided to overhaul the entire legacy codebase using modern microservices.', 'Giám đốc kỹ thuật quyết định đại tu toàn bộ cơ sở mã cũ kỹ bằng kiến trúc vi dịch vụ hiện đại.', ARRAY['Revamp', 'Rebuild', 'Refurbish']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-16', 'business', 'Pivot', '/ˈpɪv.ət/', 'Verb', 'B2', 'Chuyển hướng mô hình kinh doanh nhanh', 'Change direction or business strategy substantially.', 'When hardware sales plummeted, the startup decided to pivot into enterprise cloud software.', 'Khi doanh số phần cứng sụt giảm mạnh, công ty khởi nghiệp quyết định chuyển hướng sang phần mềm đám mây doanh nghiệp.', ARRAY['Shift', 'Reorient', 'Change course']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-17', 'business', 'Due Diligence', '/ˌduː ˈdɪl.ə.dʒəns/', 'Noun', 'C1', 'Thẩm định chi tiết trước khi đầu tư/mua lại', 'Comprehensive appraisal of a business undertaken by a prospective buyer.', 'Our legal and financial advisors spent three months conducting thorough due diligence.', 'Các cố vấn pháp lý và tài chính của chúng tôi đã dành 3 tháng để tiến hành thẩm định chi tiết toàn diện.', ARRAY['Vetting', 'Investigation', 'Audit']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-18', 'business', 'Venture Capital', '/ˈven.tʃɚ ˌkæp.ə.t̬əl/', 'Noun', 'B2', 'Quỹ đầu tư mạo hiểm mạo hiểm công nghệ', 'Capital invested in a project in which there is a substantial element of risk, typically for a new business.', 'Silicon Valley venture capital firms poured billions of dollars into generative AI startups.', 'Các quỹ đầu tư mạo hiểm Thung lũng Silicon đã rót hàng tỷ USD vào các công ty khởi nghiệp AI tạo sinh.', ARRAY['Risk capital', 'Startup funding']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-19', 'business', 'Incubator', '/ˈɪŋ.kjə.beɪ.t̬ɚ/', 'Noun', 'B2', 'Vườn ươm khởi nghiệp', 'An organization or place that helps developing businesses and startups to grow.', 'The university established a tech incubator to support student-led biotechnology ventures.', 'Trường đại học đã thành lập một vườn ươm công nghệ để hỗ trợ các dự án công nghệ sinh học do sinh viên dẫn dắt.', ARRAY['Accelerator', 'Startup hub']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-20', 'business', 'Disruption', '/dɪsˈrʌp.ʃən/', 'Noun', 'B2', 'Sự đột phá làm đảo lộn trật tự thị trường cũ', 'Radical change in an industry or business strategy, especially involving technology.', 'Ride-hailing apps caused major disruption to traditional taxi monopolies globally.', 'Các ứng dụng gọi xe công nghệ đã tạo nên cú đột phá đảo lộn thế độc quyền của taxi truyền thống trên toàn cầu.', ARRAY['Upheaval', 'Revolution', 'Innovation']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-21', 'business', 'Monopoly', '/məˈnɑː.pəl.i/', 'Noun', 'B2', 'Thế độc quyền thương mại', 'The exclusive possession or control of the supply of or trade in a commodity or service.', 'Antitrust regulators filed charges to dismantle the company''s regional monopoly over broadband fiber.', 'Các cơ quan chống độc quyền đã đệ đơn kiện nhằm phá bỏ thế độc quyền của công ty về cáp quang băng rộng tại khu vực.', ARRAY['Exclusivity', 'Cartel', 'Dominance']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-22', 'business', 'Oligopoly', '/ˌɑː.lɪˈɡɑː.pəl.i/', 'Noun', 'C1', 'Thị trường thiểu số độc quyền (vài ông lớn)', 'A state of limited competition, in which a market is shared by a small number of producers.', 'The civil aviation manufacturing market is essentially an oligopoly dominated by Boeing and Airbus.', 'Thị trường sản xuất máy bay dân dụng về cơ bản là một thị trường thiểu quyền bị thống trị bởi Boeing và Airbus.', ARRAY['Dominated market', 'Exclusive consortium']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-23', 'business', 'Underwrite', '/ˈʌn.dɚ.raɪt/', 'Verb', 'C1', 'Bảo lãnh phát hành cổ phiếu hoặc bảo hiểm rủi ro', 'Sign and accept liability under an insurance policy, thus guaranteeing payment in case of loss; financial backing.', 'Top global investment banks agreed to underwrite the tech giant''s multi-billion-dollar initial public offering.', 'Các ngân hàng đầu tư hàng đầu thế giới đã đồng ý bảo lãnh phát hành đợt chào bán cổ phiếu lần đầu ra công chúng trị giá hàng tỷ USD của gã khổng lồ công nghệ.', ARRAY['Guarantee', 'Insure', 'Back financially']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-24', 'business', 'Liquidation', '/ˌlɪk.wəˈdeɪ.ʃən/', 'Noun', 'B2', 'Thanh lý tài sản giải thể công ty', 'The process of closing a business and selling its assets to pay off debts.', 'The bankrupt department store chain entered mandatory court liquidation last Monday.', 'Chuỗi trung tâm thương mại phá sản đã bước vào giai đoạn thanh lý tài sản bắt buộc theo lệnh của tòa vào thứ Hai tuần trước.', ARRAY['Winding up', 'Dissolution', 'Sell-off']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-25', 'business', 'Insolvency', '/ɪnˈsɑːl.vən.si/', 'Noun', 'C1', 'Tình trạng mất khả năng thanh toán nợ nần', 'The state of being unable to pay one''s debts.', 'Skyrocketing interest rates pushed several commercial real estate developers into deep insolvency.', 'Lãi suất tăng chóng mặt đã đẩy nhiều nhà phát triển bất động sản thương mại vào tình trạng mất khả năng thanh toán sâu sắc.', ARRAY['Bankruptcy', 'Default', 'Financial ruin']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-26', 'business', 'Headcount', '/ˈhed.kaʊnt/', 'Noun', 'B1', 'Tổng số lượng nhân sự trong biên chế', 'The total number of people employed by a particular organization.', 'Management instituted a strict hiring freeze to maintain the current engineering headcount.', 'Ban quản lý đã thiết lập lệnh đóng băng tuyển dụng nghiêm ngặt để duy trì số lượng nhân sự kỹ thuật hiện tại.', ARRAY['Staff size', 'Personnel count', 'Workforce']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-27', 'business', 'Attrition', '/əˈtrɪʃ.ən/', 'Noun', 'C1', 'Sự hao mòn nhân sự tự nhiên (nghỉ hưu, thôi việc)', 'The reduction in staff numbers through retirement, resignation, or death.', 'The corporation reduced its workforce through natural attrition rather than forced layoffs.', 'Tập đoàn đã cắt giảm quy mô nhân lực thông qua sự hao mòn tự nhiên thay vì sa thải hàng loạt ép buộc.', ARRAY['Staff erosion', 'Natural reduction']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-28', 'business', 'Onboarding', '/ˈɑːnˌbɔːr.dɪŋ/', 'Noun', 'B1', 'Quy trình hội nhập nhân sự mới', 'The action or process of integrating a new employee into an organization.', 'A structured onboarding program improves first-year employee retention by over fifty percent.', 'Một quy trình hội nhập bài bản giúp tăng tỷ lệ giữ chân nhân viên năm đầu lên hơn 50%.', ARRAY['Orientation', 'Induction', 'Integration']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-29', 'business', 'KPI', '/ˌkeɪ.piːˈaɪ/', 'Noun', 'B1', 'Chỉ số đánh giá hiệu quả công việc', 'Key Performance Indicator: a quantifiable measure used to evaluate success in reaching targets.', 'Meeting quarterly customer satisfaction scores is a mandatory KPI for support agents.', 'Đạt điểm hài lòng của khách hàng hàng quý là một chỉ số KPI bắt buộc đối với nhân viên hỗ trợ.', ARRAY['Metric', 'Target', 'Performance measure']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-30', 'business', 'OKR', '/ˌoʊ.keɪˈɑːr/', 'Noun', 'B2', 'Mục tiêu và kết quả then chốt', 'Objectives and Key Results: a goal-setting framework used by individuals and teams.', 'Google popularized the OKR system to align enterprise goals across tens of thousands of workers.', 'Google đã phổ biến hệ thống OKR nhằm đồng bộ hóa các mục tiêu doanh nghiệp trên hàng vạn nhân sự.', ARRAY['Goal framework', 'Target framework']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-31', 'business', 'Bottleneck', '/ˈbɑː.t̬əl.nek/', 'Noun', 'B2', 'Nút thắt cổ chai làm chậm trễ tiến độ', 'A point of congestion or blockage in a system or process.', 'A shortage of microchips created a crippling bottleneck in vehicle assembly plants.', 'Tình trạng thiếu hụt chip vi xử lý đã tạo ra nút thắt cổ chai làm đình trệ các nhà máy lắp ráp ô tô.', ARRAY['Choke point', 'Impediment', 'Obstacle']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-32', 'business', 'Deliverable', '/dɪˈlɪv.ɚ.ə.bəl/', 'Noun', 'B2', 'Sản phẩm bàn giao theo hợp đồng', 'A thing able to be provided, especially as a product of a development process.', 'The final contract deliverable is an end-to-end encrypted mobile payment application.', 'Sản phẩm bàn giao cuối cùng theo hợp đồng là ứng dụng thanh toán di động được mã hóa đầu cuối.', ARRAY['Handover product', 'End product', 'Output']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-33', 'business', 'Core Competency', '/kɔːr ˈkɑːm.pə.tən.si/', 'Noun', 'C1', 'Năng lực cạnh tranh cốt lõi', 'A harmonized combination of multiple resources and skills that distinguish a firm in the marketplace.', 'Ultra-low latency database optimization is our startup''s primary core competency.', 'Tối ưu hóa cơ sở dữ liệu với độ trễ siêu thấp là năng lực cốt lõi hàng đầu của công ty khởi nghiệp chúng tôi.', ARRAY['Key capability', 'Competitive advantage']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-34', 'business', 'Competitive Advantage', '/kəmˈpet̬.ə.t̬ɪv ədˈvæn.t̬ɪdʒ/', 'Noun', 'B2', 'Lợi thế cạnh tranh vượt trội', 'A condition or circumstance that puts a company in a favorable or superior business position.', 'Patented proprietary manufacturing algorithms provide a durable competitive advantage.', 'Các thuật toán sản xuất độc quyền đã được cấp bằng sáng chế mang lại lợi thế cạnh tranh bền vững.', ARRAY['Edge', 'Upper hand', 'Strategic strength']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-35', 'business', 'Value Proposition', '/ˈvæl.juː ˌprɑː.pəˈzɪʃ.ən/', 'Noun', 'B2', 'Tuyên bố giá trị khác biệt cho khách hàng', 'An innovation, service, or feature intended to make a company or product attractive to customers.', 'The product''s clear value proposition is cutting manual data entry time by eighty percent.', 'Tuyên ngôn giá trị rõ ràng của sản phẩm là cắt giảm 80% thời gian nhập liệu thủ công.', ARRAY['Unique selling point', 'USP', 'Benefit statement']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-36', 'business', 'Return on Investment', '/rɪˈtɝːn ɑːn ɪnˈvest.mənt/', 'Noun', 'B1', 'Tỷ suất hoàn vốn đầu tư (ROI)', 'A performance measure used to evaluate the efficiency of an investment.', 'Automating warehouse packaging yielded a swift return on investment within eight months.', 'Tự động hóa đóng gói nhà kho đã mang lại tỷ suất hoàn vốn đầu tư nhanh chóng chỉ trong vòng 8 tháng.', ARRAY['ROI', 'Yield', 'Profit margin']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-37', 'business', 'Breakeven', '/ˈbreɪkˌiː.vən/', 'Noun', 'B2', 'Điểm hòa vốn không lỗ không lãi', 'The point at which cost and revenue of a commercial enterprise are equal.', 'The coffee shop chain projects reaching monthly breakeven within six months of opening.', 'Chuỗi quán cà phê dự kiến sẽ đạt điểm hòa vốn hàng tháng trong vòng 6 tháng kể từ khi khai trương.', ARRAY['Parity point', 'Zero-profit point']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-38', 'business', 'Runway', '/ˈrʌn.weɪ/', 'Noun', 'B2', 'Thời gian còn sống sót theo quỹ tiền mặt của startup', 'The amount of time a business has left until it runs out of money, assuming revenue and expenses stay constant.', 'Securing seed funding gave the software team an eighteen-month runway to build the MVP.', 'Nhận được vòng vốn hạt giống đã mang lại cho đội ngũ phần mềm 18 tháng tồn tại để xây dựng bản sản phẩm khả dụng tối thiểu.', ARRAY['Cash runway', 'Survival period']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-39', 'business', 'Burn Rate', '/ˈbɝːn ˌreɪt/', 'Noun', 'B2', 'Tốc độ tiêu thụ tiền mặt mỗi tháng của công ty', 'The rate at which a new company is spending its venture capital to finance overhead operations before generating positive cash flow.', 'The founders took steps to trim marketing expenses and decrease their monthly burn rate.', 'Các nhà sáng lập đã thực hiện các bước cắt giảm chi phí tiếp thị nhằm hạ thấp tốc độ đốt tiền hàng tháng.', ARRAY['Cash expenditure speed', 'Spending rate']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-40', 'business', 'Bootstrapping', '/ˈbuːtˌstræp.ɪŋ/', 'Noun', 'B2', 'Tự lực cánh sinh xây dựng doanh nghiệp không gọi vốn', 'Building a business from the ground up without relying on external equity financing or venture capital.', 'Bootstrapping taught the early founders to maintain ruthless fiscal discipline and obsess over profitability.', 'Tự lực cánh sinh phát triển công ty đã rèn luyện cho những nhà sáng lập ban đầu tính kỷ luật tài chính nghiêm ngặt và luôn chú trọng lợi nhuận.', ARRAY['Self-funding', 'Organic growth']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-41', 'business', 'White Collar', '/ˌwaɪt ˈkɑː.lɚ/', 'Adj', 'B1', 'Lao động trí óc, nhân viên văn phòng', 'Relating to the work done by people who work in an office or other professional environment.', 'Automation is increasingly impacting white-collar professions like financial analysis and law.', 'Tự động hóa đang ngày càng tác động sâu sắc đến các ngành nghề văn phòng như phân tích tài chính và luật pháp.', ARRAY['Professional', 'Office worker']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-42', 'business', 'Blue Collar', '/ˌbluː ˈkɑː.lɚ/', 'Adj', 'B1', 'Lao động chân tay, công nhân nhà xưởng', 'Relating to manual work or workers, particularly in industry.', 'Demand for skilled blue-collar workers in precision manufacturing continues to rise.', 'Nhu cầu về lực lượng lao động tay nghề cao trong ngành sản xuất chính xác tiếp tục tăng trưởng.', ARRAY['Manual laborer', 'Industrial worker']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-43', 'business', 'Micromanage', '/ˈmaɪ.kroʊˌmæn.ɪdʒ/', 'Verb', 'B2', 'Soi mói quản lý tiểu tiết gây ức chế', 'Control every part of a business or system, even small details, in a way that is not helpful.', 'Managers who micromanage stifle employee creativity and induce unnecessary stress.', 'Những người quản lý có thói quen soi mói tiểu tiết sẽ bóp nghẹt tính sáng tạo của nhân viên và gây căng thẳng không đáng có.', ARRAY['Over-supervise', 'Interfere']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-44', 'business', 'Workplace Culture', '/ˈwɝːk.pleɪs ˌkʌl.tʃɚ/', 'Noun', 'B1', 'Văn hóa môi trường làm việc', 'The environment that you create for your employees, including values, beliefs, and behaviors.', 'A transparent workplace culture fosters psychological safety and cross-team collaboration.', 'Văn hóa môi trường làm việc minh bạch sẽ nuôi dưỡng sự an tâm tâm lý và sự hợp tác giữa các phòng ban.', ARRAY['Company climate', 'Organizational culture']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-45', 'business', 'Whistleblower', '/ˈwɪs.əlˌbloʊ.ɚ/', 'Noun', 'C1', 'Người dũng cảm tố giác sai phạm nội bộ', 'A person who informs on a person or organization regarded as engaging in an unlawful or immoral activity.', 'The corporate whistleblower alerted regulatory authorities to widespread accounting irregularities.', 'Người tố giác nội bộ đã cảnh báo các cơ quan quản lý về những hành vi bất thường kế toán tràn lan trong tập đoàn.', ARRAY['Informant', 'Tipster', 'Exposer']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-46', 'business', 'Severance Pay', '/ˈsev.ɚ.əns ˌpeɪ/', 'Noun', 'B2', 'Tiền trợ cấp khi chấm dứt hợp đồng lao động', 'Money paid by an employer to an employee whose job the employer has had to bring to an end.', 'Discharged senior executives were granted six months of base severance pay.', 'Những giám đốc điều hành cấp cao bị miễn nhiệm đã được chi trả 6 tháng lương cơ bản trợ cấp thôi việc.', ARRAY['Redundancy pay', 'Termination payout']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-47', 'business', 'Golden Parachute', '/ˌɡoʊl.dən ˈper.ə.ʃuːt/', 'Noun', 'C1', 'Khoản bồi thường kếch xù cho sếp lớn khi rời công ty', 'A large payment or other financial compensation guaranteed to a company executive if they should be dismissed.', 'The outgoing chief executive walked away with a fifty-million-dollar golden parachute.', 'Tổng giám đốc điều hành mãn nhiệm đã rời ghế với khoản bồi thường kếch xù lên đến 50 triệu USD.', ARRAY['Executive exit bonus', 'Severance package']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-48', 'business', 'Hostile Takeover', '/ˌhɑː.stəl ˈteɪkˌoʊ.vɚ/', 'Noun', 'C1', 'Thương vụ thâu tóm thù địch chống lại ý muốn ban lãnh đạo', 'The acquisition of one company by another that is accomplished by going directly to the company''s shareholders.', 'The board launched a poison pill defense strategy to fend off the hostile takeover bid.', 'Hội đồng quản trị đã triển khai chiến thuật phòng thủ thuốc độc để đẩy lùi nỗ lực thâu tóm thù địch.', ARRAY['Aggressive buyout', 'Unsolicited acquisition']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-49', 'business', 'Non-Disclosure Agreement', '/ˌnɑːn.dɪˈskloʊ.ʒɚ əˈɡriː.mənt/', 'Noun', 'B2', 'Thỏa thuận bảo mật thông tin (NDA)', 'A contract by which one or more parties agree not to disclose confidential information.', 'Engineers must sign an NDA before getting access to the unreleased product prototypes.', 'Các kỹ sư phải ký thỏa thuận bảo mật trước khi được tiếp cận các mẫu sản phẩm nguyên mẫu chưa ra mắt.', ARRAY['NDA', 'Confidentiality pact', 'Secrecy contract']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-50', 'business', 'Intellectual Property', '/ˌɪn.t̬əlˈek.tʃu.əl ˈprɑː.pɚ.t̬i/', 'Noun', 'B2', 'Tài sản sở hữu trí tuệ', 'Intangible property that is the result of creativity, such as patents, copyrights, and trademarks.', 'Safeguarding corporate intellectual property is critical in high-tech manufacturing.', 'Bảo vệ tài sản sở hữu trí tuệ của doanh nghiệp là điều sống còn trong lĩnh vực sản xuất công nghệ cao.', ARRAY['IP', 'Patents and copyrights']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-51', 'business', 'Patent', '/ˈpæt.ənt/', 'Noun', 'B2', 'Bằng sáng chế độc quyền bảo hộ công nghệ', 'A government authority or license conferring a right or title for a set period, especially the sole right to exclude others from making or selling an invention.', 'The biotech firm was granted a patent for its revolutionary gene-editing technique.', 'Công ty công nghệ sinh học đã được cấp bằng sáng chế cho kỹ thuật chỉnh sửa gen mang tính cách mạng của mình.', ARRAY['Copyright', 'License', 'Exclusive right']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-52', 'business', 'Trademark', '/ˈtreɪd.mɑːrk/', 'Noun', 'B1', 'Nhãn hiệu hàng hóa được đăng ký bảo hộ', 'A symbol, word, or words legally registered or established by use as representing a company or product.', 'Counterfeit manufacturers were penalized for infringing upon the registered global trademark.', 'Những kẻ sản xuất hàng giả đã bị xử phạt nghiêm khắc vì vi phạm nhãn hiệu đã được đăng ký bảo hộ toàn cầu.', ARRAY['Brand name', 'Logo', 'Emblem']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-53', 'business', 'Infringement', '/ɪnˈfrɪndʒ.mənt/', 'Noun', 'B2', 'Hành vi xâm phạm quyền pháp lý/sở hữu', 'The action of breaking the terms of a law, agreement, etc.; violation.', 'The software giant settled an intellectual property infringement lawsuit out of court.', 'Gã khổng lồ phần mềm đã dàn xếp êm đẹp vụ kiện xâm phạm quyền sở hữu trí tuệ ngoài tòa án.', ARRAY['Violation', 'Breach', 'Contravention']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-54', 'business', 'Restructuring', '/ˌriːˈstrʌk.tʃɚ.ɪŋ/', 'Noun', 'B2', 'Tái cấu trúc bộ máy và tài chính', 'Reorganizing the operational, legal, ownership, or other structures of a company.', 'The comprehensive corporate restructuring helped the legacy retailer remain solvent.', 'Cuộc tái cấu trúc doanh nghiệp toàn diện đã giúp nhà bán lẻ truyền thống duy trì khả năng thanh toán.', ARRAY['Reorganization', 'Overhaul', 'Realignment']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-55', 'business', 'Divestment', '/daɪˈvest.mənt/', 'Noun', 'C1', 'Thoái vốn đầu tư khỏi tài sản phụ', 'The reduction of some kind of asset for financial, ethical, or political objectives.', 'The oil corporation announced the divestment of its aging coal extraction assets.', 'Tập đoàn dầu mỏ đã tuyên bố thoái vốn khỏi các tài sản khai thác than đá già cỗi.', ARRAY['Divestiture', 'Disinvestment', 'Asset sale']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-56', 'business', 'Conglomerate', '/kənˈɡlɑː.mɚ.ət/', 'Noun', 'C1', 'Tập đoàn quy mô lớn đa lĩnh vực', 'A multi-industry company consisting of several distinct and unrelated business entities.', 'The Korean conglomerate operates shipyards, insurance firms, and electronics factories.', 'Tập đoàn đa ngành Hàn Quốc vận hành các xưởng đóng tàu, công ty bảo hiểm và nhà máy điện tử.', ARRAY['Corporate group', 'Holding empire']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-57', 'business', 'Spin-off', '/ˈspɪn.ɑːf/', 'Noun', 'B2', 'Tách công ty con thành công ty đại chúng độc lập', 'A byproduct or incidental result of a larger project, or a new independent company formed from an existing firm.', 'The automaker announced a public spin-off of its dedicated electric vehicle division.', 'Hãng xe hơi đã công bố việc tách độc lập bộ phận xe điện chuyên biệt thành công ty đại chúng.', ARRAY['Offshoot', 'Branch company', 'Subsidiary IPO']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-58', 'business', 'Seed Capital', '/ˈsiːd ˌkæp.ə.t̬əl/', 'Noun', 'B2', 'Vốn hạt giống giai đoạn phôi thai', 'The initial funding used to establish and begin developing a business concept.', 'Angel investors provided two hundred thousand dollars in seed capital for the fintech app.', 'Các nhà đầu tư thiên thần đã cung cấp 200.000 USD vốn hạt giống cho ứng dụng công nghệ tài chính.', ARRAY['Initial funding', 'Angel funding']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-59', 'business', 'Angel Investor', '/ˈeɪn.dʒəl ɪnˌves.tɚ/', 'Noun', 'B2', 'Nhà đầu tư thiên thần cá nhân', 'An individual who provides capital for a business startup, usually in exchange for convertible debt or ownership equity.', 'An early angel investor took a ten percent stake in the nascent video streaming platform.', 'Một nhà đầu tư thiên thần thuở ban đầu đã nắm giữ 10% cổ phần tại nền tảng phát video trực tuyến non trẻ.', ARRAY['Seed investor', 'Private backer']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-60', 'business', 'Term Sheet', '/ˈtɝːm ˌʃiːt/', 'Noun', 'C1', 'Bản điều khoản cam kết đầu tư sơ bộ', 'A non-binding agreement showing the basic terms and conditions under which an investment will be made.', 'After reviewing the venture term sheet, the founders negotiated for a higher company valuation.', 'Sau khi xem xét kỹ bản điều khoản đầu tư, các nhà sáng lập đã đàm phán để nâng mức định giá công ty lên cao hơn.', ARRAY['Investment terms', 'Preliminary deal sheet']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-61', 'business', 'Valuation', '/ˌvæl.juˈeɪ.ʃən/', 'Noun', 'B2', 'Mức định giá tổng tài sản doanh nghiệp', 'An estimation of the worth of something, especially one carried out by a professional.', 'The generative AI startup attained a staggering ten-billion-dollar market valuation.', 'Công ty khởi nghiệp AI tạo sinh đã đạt được mức định giá thị trường gây sửng sốt lên tới 10 tỷ USD.', ARRAY['Appraisal', 'Assessment', 'Worth estimate']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-62', 'business', 'Unicorn', '/ˈjuː.nə.kɔːrn/', 'Noun', 'B1', 'Kỳ lân công nghệ (startup định giá trên 1 tỷ USD)', 'A privately held startup company with a value of over $1 billion.', 'Achieving unicorn status within three years made the payment provider an international sensation.', 'Đạt được danh hiệu kỳ lân chỉ trong vòng 3 năm đã biến nhà cung cấp dịch vụ thanh toán trở thành hiện tượng quốc tế.', ARRAY['Billion-dollar startup']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-63', 'business', 'Decacorn', '/ˈdek.ə.kɔːrn/', 'Noun', 'C1', 'Siêu kỳ lân (startup định giá trên 10 tỷ USD)', 'A privately held startup company with a valuation exceeding $10 billion.', 'Only an elite tier of tech firms transition from unicorn to decacorn status prior to going public.', 'Chỉ có tầng lớp công ty công nghệ tinh hoa mới có thể chuyển mình từ kỳ lân lên siêu kỳ lân trước khi lên sàn đại chúng.', ARRAY['Mega startup', 'Ten-billion unicorn']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-64', 'business', 'Sweat Equity', '/ˈswet ˌek.wə.t̬i/', 'Noun', 'B2', 'Cổ phần đóng góp bằng công sức thay vì tiền', 'An interest or increased value in a property or business earned from labor toward its creation or improvement.', 'The lead engineer accepted a lower base salary in exchange for valuable sweat equity shares.', 'Kỹ sư trưởng đã chấp nhận mức lương cơ bản thấp hơn để đổi lấy số cổ phần công sức đóng góp giá trị.', ARRAY['Labor equity', 'Contribution share']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-65', 'business', 'Vesting Period', '/ˈves.tɪŋ ˌpɪr.i.əd/', 'Noun', 'C1', 'Thời gian giữ chân để cổ phần chính thức có hiệu lực', 'The period of time before shares given to an employee unconditionally belong to them.', 'Employee stock grants typically follow a four-year vesting period with a one-year cliff.', 'Các khoản cấp cổ phiếu cho nhân viên thường tuân theo thời hạn nhận dần 4 năm với mốc một năm đầu tiên.', ARRAY['Vesting schedule', 'Accrual period']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-66', 'business', 'Cliff', '/klɪf/', 'Noun', 'C1', 'Mốc thời gian tối thiểu để nhận phần cổ phần đầu tiên', 'A period of time during which an employee must stay at a company to receive any stock options.', 'Leaving the software startup before the one-year cliff means forfeiting all unvested equity options.', 'Rời khỏi công ty khởi nghiệp phần mềm trước mốc thời gian một năm đồng nghĩa với việc mất toàn bộ quyền chọn cổ phiếu chưa phát hành.', ARRAY['Threshold date', 'Waiting threshold']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-67', 'business', 'Golden Handcuffs', '/ˌɡoʊl.dən ˈhænd.kʌfs/', 'Noun', 'C1', 'Xiềng xích vàng (phúc lợi khủng để giữ chân nhân sự cốt cán)', 'Financial incentives used to prevent a valuable employee from leaving a company.', 'Substantial delayed stock bonuses act as effective golden handcuffs for key artificial intelligence researchers.', 'Những khoản thưởng cổ phiếu trì hoãn giá trị lớn đóng vai trò như xiềng xích vàng hiệu quả để giữ chân các nhà nghiên cứu trí tuệ nhân tạo trọng yếu.', ARRAY['Retention incentives', 'Lock-in rewards']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-68', 'business', 'Glass Ceiling', '/ˌɡlæs ˈsiː.lɪŋ/', 'Noun', 'B2', 'Rào cản vô hình ngăn thăng tiến (phụ nữ, thiểu số)', 'An unacknowledged barrier to advancement in a profession, especially affecting women and members of minorities.', 'Promoting female executives to the boardroom shattered the traditional corporate glass ceiling.', 'Việc thăng chức cho các nữ giám đốc điều hành vào hội đồng quản trị đã phá vỡ rào cản vô hình truyền thống của doanh nghiệp.', ARRAY['Invisible barrier', 'Promotion ceiling']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-69', 'business', 'Brain Drain', '/ˈbreɪn ˌdreɪn/', 'Noun', 'B2', 'Chảy máu chất xám ra nước ngoài hoặc đối thủ', 'The emigration of highly trained or intelligent people from a particular country or firm.', 'Competitive overseas salaries are accelerating the brain drain of local top software talent.', 'Mức lương hấp dẫn ở nước ngoài đang đẩy nhanh tình trạng chảy máu chất xám của các nhân tài phần mềm hàng đầu trong nước.', ARRAY['Human capital flight', 'Talent exodus']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-70', 'business', 'Moonlighting', '/ˈmuːnˌlaɪ.t̬ɪŋ/', 'Noun', 'B2', 'Làm thêm nghề thứ hai ngoài giờ làm chính', 'Working at an additional job, especially without the knowledge of the main employer.', 'Strict employment contracts strictly prohibit moonlighting for competing technology enterprises.', 'Hợp đồng lao động nghiêm ngặt nghiêm cấm việc làm thêm cho các doanh nghiệp công nghệ đối thủ ngoài giờ làm chính.', ARRAY['Side job', 'Secondary employment']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-71', 'business', 'Wholesale', '/ˈhoʊl.seɪl/', 'Noun', 'B1', 'Bán buôn, bán sỉ khối lượng lớn', 'The selling of goods in large quantities to be retailed by others.', 'Purchasing industrial chemicals at wholesale rates saved the manufacturing facility forty percent.', 'Mua hóa chất công nghiệp theo giá bán sỉ đã giúp cơ sở sản xuất tiết kiệm được 40%.', ARRAY['Bulk selling', 'Trade distribution']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-72', 'business', 'Retail', '/ˈriː.teɪl/', 'Noun', 'B1', 'Bán lẻ tới tay người tiêu dùng cuối', 'The sale of goods to the public in relatively small quantities for use or consumption rather than for resale.', 'E-commerce continues to swallow market share from traditional brick-and-mortar retail outlets.', 'Thương mại điện tử tiếp tục thâu tóm thị phần từ các điểm bán lẻ truyền thống mặt phố.', ARRAY['Direct selling', 'Consumer sales']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-73', 'business', 'Supply Chain', '/səˈplaɪ ˌtʃeɪn/', 'Noun', 'B1', 'Chuỗi cung ứng từ nguyên liệu đến thành phẩm', 'The sequence of processes involved in the production and distribution of a commodity.', 'Geopolitical disruptions severely crippled the maritime electronic supply chain.', 'Những biến động địa chính trị đã làm tê liệt trầm trọng chuỗi cung ứng hàng hải điện tử.', ARRAY['Logistics chain', 'Distribution network']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-74', 'business', 'Procurement Officer', '/prəˈkjʊr.mənt ˌɑː.fɪ.sɚ/', 'Noun', 'B2', 'Chuyên viên quản lý thu mua vật tư', 'A corporate specialist responsible for purchasing goods and services for business operations.', 'The procurement officer secured a favorable long-term volume discount from steel suppliers.', 'Chuyên viên thu mua đã thương lượng được mức chiết khấu số lượng lớn dài hạn có lợi từ các nhà cung cấp thép.', ARRAY['Purchasing agent', 'Buyer']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-75', 'business', 'Fulfillment Center', '/fʊlˈfɪl.mənt ˌsen.t̬ɚ/', 'Noun', 'B1', 'Trung tâm xử lý và hoàn tất đơn hàng', 'A warehouse where incoming orders from customers are received, processed, and packed for shipment.', 'The e-commerce conglomerate operates automated fulfillment centers staffed by thousands of sorting robots.', 'Tập đoàn thương mại điện tử vận hành các trung tâm hoàn tất đơn hàng tự động với sự hỗ trợ của hàng ngàn robot phân loại.', ARRAY['Distribution warehouse', 'Pack facility']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-76', 'business', 'Freight Forwarder', '/ˈfreɪt ˌfɔːr.wɚ.dɚ/', 'Noun', 'B2', 'Đơn vị giao nhận vận tải quốc tế', 'A person or company that organizes shipments for individuals or corporations to get goods from the manufacturer or producer to a market, customer or final point of distribution.', 'We engaged a reputable freight forwarder to handle international customs clearance and ocean container transport.', 'Chúng tôi đã thuê một công ty giao nhận vận tải uy tín để xử lý thủ tục thông quan quốc tế và vận tải container đường biển.', ARRAY['Cargo agent', 'Shipping agent']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-77', 'business', 'Bill of Lading', '/ˌbɪl əv ˈleɪ.dɪŋ/', 'Noun', 'C1', 'Vận đơn đường biển xác nhận nhận hàng', 'A detailed list of a shipment of goods in the form of a receipt given by the carrier to the person consigning the goods.', 'The shipping line releases cargo containers only upon receipt of the original signed bill of lading.', 'Hãng tàu chỉ giải phóng các container hàng hóa sau khi nhận được vận đơn gốc có chữ ký hợp lệ.', ARRAY['B/L', 'Cargo manifest', 'Consignment note']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-78', 'business', 'Tariff', '/ˈter.ɪf/', 'Noun', 'B2', 'Thuế quan đánh lên hàng hóa xuất nhập khẩu', 'A tax or duty to be paid on a particular class of imports or exports.', 'Imposing punitive tariffs on foreign steel triggered reciprocal trade countermeasures.', 'Việc áp đặt mức thuế quan trừng phạt đối với thép nhập khẩu đã kích hoạt các biện pháp đáp trả thương mại tương hỗ.', ARRAY['Customs duty', 'Import tax', 'Levy']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-79', 'business', 'Embargo', '/ɪmˈbɑːr.ɡoʊ/', 'Noun', 'C1', 'Lệnh phong tỏa cấm vận kinh tế', 'An official ban on trade or other commercial activity with a particular country.', 'Sanctioned banks were cut off from SWIFT due to the comprehensive financial embargo.', 'Các ngân hàng bị áp lệnh trừng phạt đã bị ngắt kết nối khỏi hệ thống SWIFT do lệnh cấm vận tài chính toàn diện.', ARRAY['Sanction', 'Trade ban', 'Blockade']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-80', 'business', 'Arbitrage', '/ˈɑːr.bə.trɑːʒ/', 'Noun', 'C1', 'Kinh doanh chênh lệch giá giữa các thị trường', 'The simultaneous buying and selling of securities, currency, or commodities in different markets or in derivative forms in order to take advantage of differing prices for the same asset.', 'High-frequency trading hedge funds exploit microscopic price arbitrage across global exchanges.', 'Các quỹ phòng hộ giao dịch tần suất cao khai thác triệt để những chênh lệch giá siêu nhỏ giữa các sàn giao dịch toàn cầu.', ARRAY['Spread trading', 'Price exploitation']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-81', 'business', 'Hedge Fund', '/ˈhedʒ ˌfʌnd/', 'Noun', 'B2', 'Quỹ đầu tư phòng hộ rủi ro cao', 'A limited partnership of investors that uses high risk methods, such as investing with borrowed money, in hopes of realizing large capital gains.', 'The aggressive hedge fund generated a forty percent net return during market turbulence.', 'Quỹ phòng hộ với chiến lược quyết liệt đã mang lại tỷ suất lợi nhuận ròng 40% giữa cơn biến động thị trường.', ARRAY['Alternative investment fund']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-82', 'business', 'Private Equity', '/ˌpraɪ.vət ˈek.wə.t̬i/', 'Noun', 'B2', 'Quỹ đầu tư vốn cổ phần tư nhân', 'Capital investment made into companies that are not publicly traded on a stock exchange.', 'The private equity consortium acquired the struggling retail chain and took it private.', 'Liên minh quỹ đầu tư vốn cổ phần tư nhân đã mua lại chuỗi bán lẻ gặp khó khăn và chuyển nó về sở hữu tư nhân.', ARRAY['PE', 'Direct equity']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-83', 'business', 'LBO', '/ˌel.biːˈoʊ/', 'Noun', 'C1', 'Mua lại doanh nghiệp bằng vốn vay đòn bẩy', 'Leveraged Buyout: the acquisition of another company using a significant amount of borrowed money to meet the cost of acquisition.', 'The massive LBO burdened the newly acquired enterprise with billions in debt service payments.', 'Vụ mua lại bằng vốn vay đòn bẩy khổng lồ đã tạo gánh nặng nợ nần lên tới hàng tỷ USD chi phí trả lãi cho doanh nghiệp vừa thâu tóm.', ARRAY['Leveraged buyout', 'Debt-financed takeover']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-84', 'business', 'Joint Venture', '/ˌdʒɔɪnt ˈven.tʃɚ/', 'Noun', 'B2', 'Liên doanh hợp tác giữa hai công ty độc lập', 'A commercial enterprise undertaken jointly by two or more parties which otherwise retain their distinct identities.', 'The two automobile manufacturers formed a joint venture to build next-generation solid-state batteries.', 'Hai hãng sản xuất ô tô đã thành lập một liên doanh để sản xuất pin thể rắn thế hệ tiếp theo.', ARRAY['JV', 'Consortium', 'Partnership']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-85', 'business', 'Memorandum of Understanding', '/ˌmem.əˈræn.dəm əv ˌʌn.dɚˈstæn.dɪŋ/', 'Noun', 'C1', 'Biên bản ghi nhớ hợp tác sơ bộ (MOU)', 'A nonbinding agreement between two or more parties outlining the terms and details of an understanding, including each parties'' requirements and responsibilities.', 'The ministries signed an MOU to foster cross-border semiconductor talent exchanges.', 'Các bộ đã ký kết một biên bản ghi nhớ nhằm thúc đẩy trao đổi nhân tài bán dẫn xuyên biên giới.', ARRAY['MOU', 'Preliminary pact', 'Letter of intent']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-86', 'business', 'Letter of Intent', '/ˌlet̬.ɚ əv ɪnˈtent/', 'Noun', 'B2', 'Thư bày tỏ ý định hợp tác giao dịch (LOI)', 'A document outlining the general terms of an agreement with its parties prior to the agreement being finalized.', 'The prospective buyer submitted an official LOI proposing an all-cash buyout.', 'Bên mua tiềm năng đã đệ trình một bức thư bày tỏ ý định chính thức đề xuất mua lại toàn bộ bằng tiền mặt.', ARRAY['LOI', 'Intent document']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-87', 'business', 'Force Majeure', '/ˌfɔːrs məˈʒɝː/', 'Noun', 'C1', 'Điều khoản bất khả kháng trong hợp đồng', 'Unforeseeable circumstances that prevent someone from fulfilling a contract.', 'A massive volcanic eruption was recognized as a legitimate force majeure event that excused delayed shipments.', 'Một đợt phun trào núi lửa dữ dội đã được công nhận là sự kiện bất khả kháng chính đáng cho phép miễn trừ việc chậm giao hàng.', ARRAY['Act of God', 'Unavoidable catastrophe']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-88', 'business', 'Liquidated Damages', '/ˈlɪk.wə.deɪ.t̬ɪd ˈdæm.ɪ.dʒɪz/', 'Noun', 'C1', 'Mức bồi thường thiệt hại được ấn định trước', 'An amount of money agreed upon by both parties to a contract which one will pay to the other in the event of breach.', 'The construction contract specifies liquidated damages of five thousand dollars per day of construction delay.', 'Hợp đồng xây dựng quy định mức bồi thường thiệt hại ấn định trước là 5.000 USD cho mỗi ngày thi công chậm trễ.', ARRAY['Pre-agreed penalty', 'Contractual damages']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-89', 'business', 'Indemnity Clause', '/ɪnˈdem.nə.t̬i ˌklɑːz/', 'Noun', 'C1', 'Điều khoản cam kết bồi thường miễn trừ thiệt hại', 'A contractual agreement by which one party agrees to compensate another for certain damages or liabilities.', 'The supplier accepted a comprehensive indemnity clause covering any third-party patent infringements.', 'Nhà cung cấp đã chấp thuận một điều khoản bồi hoàn toàn diện bao gồm mọi vi phạm bằng sáng chế của bên thứ ba.', ARRAY['Hold-harmless clause', 'Protection clause']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-90', 'business', 'Non-Compete Clause', '/ˌnɑːn.kəmˈpiːt ˌklɑːz/', 'Noun', 'B2', 'Điều khoản không cạnh tranh sau khi nghỉ việc', 'A clause under which one party agrees not to enter into or start a similar profession or trade in competition against another party.', 'The court struck down the non-compete clause as excessively restrictive on the engineer''s livelihood.', 'Tòa án đã bác bỏ điều khoản không cạnh tranh vì quá hạn chế sinh kế làm việc của kỹ sư.', ARRAY['Covenant not to compete', 'Restraint of trade']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-91', 'business', 'Right of First Refusal', '/ˌraɪt əv ˌfɝːst rɪˈfjuː.zəl/', 'Noun', 'C1', 'Quyền ưu tiên mua trước', 'A contractual right that gives its holder the option to enter a business transaction with the owner of something, before the owner can enter into that transaction with a third party.', 'Early investors retained the legal right of first refusal on any new issuance of preferred stock.', 'Các nhà đầu tư ban đầu nắm giữ quyền ưu tiên mua trước theo luật định đối với bất kỳ đợt phát hành cổ phiếu ưu đãi mới nào.', ARRAY['ROFR', 'Preemptive right']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-92', 'business', 'Subsidize', '/ˈsʌb.sə.daɪz/', 'Verb', 'B2', 'Trợ cấp ngân sách nhà nước', 'Support an organization or activity financially.', 'The government decided to heavily subsidize rooftop solar panel installations for commercial warehouses.', 'Chính phủ quyết định trợ cấp mạnh tay cho việc lắp đặt các tấm pin năng lượng mặt trời áp mái tại các nhà kho thương mại.', ARRAY['Fund', 'Underwrite', 'Back']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-93', 'business', 'Depreciation', '/dɪˌpriː.ʃiˈeɪ.ʃən/', 'Noun', 'B2', 'Khấu hao tài sản hữu hình', 'A reduction in the value of an asset with the passage of time, due in particular to wear and tear.', 'Linear depreciation charges reduce net taxable income on balance sheets.', 'Các khoản trích khấu hao tài sản tuyến tính giúp giảm thu nhập chịu thuế ròng trên bảng cân đối kế toán.', ARRAY['Wear and tear', 'Devaluation', 'Amortization']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-94', 'business', 'Amortization', '/ˌæm.ɚ.t̬əˈzeɪ.ʃən/', 'Noun', 'C1', 'Khấu hao tài sản vô hình / trả dần nợ gốc lãi', 'The action or process of gradually writing off the initial cost of an asset or paying off a debt.', 'Intangible software acquisition costs are amortized over a realistic five-year operational lifespan.', 'Chi phí mua lại phần mềm vô hình được phân bổ khấu hao dần trong suốt vòng đời vận hành thực tế 5 năm.', ARRAY['Write-off', 'Installment repayment']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-95', 'business', 'Goodwill', '/ˌɡʊdˈwɪl/', 'Noun', 'B2', 'Lợi thế thương mại ghi nhận trên bảng kế toán', 'The established reputation of a business regarded as a quantifiable asset and calculated as part of its value when it is sold.', 'The acquiring firm recorded two billion dollars in accounting goodwill after the merger.', 'Công ty mua lại đã ghi nhận 2 tỷ USD vào tài sản lợi thế thương mại trên sổ sách sau vụ sáp nhập.', ARRAY['Reputational asset', 'Intangible asset']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-96', 'business', 'Accounts Payable', '/əˌkaʊnts ˈpeɪ.ə.bəl/', 'Noun', 'B1', 'Khoản nợ phải trả cho nhà cung cấp (AP)', 'Money owed by a company to its creditors.', 'The finance team optimized accounts payable cycles to preserve positive working cash flow.', 'Đội ngũ tài chính đã tối ưu hóa các chu kỳ nợ phải trả nhằm bảo toàn dòng tiền mặt hoạt động tích cực.', ARRAY['AP', 'Creditor balance', 'Bills owed']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-97', 'business', 'Accounts Receivable', '/əˌkaʊnts rɪˈsiː.və.bəl/', 'Noun', 'B1', 'Khoản tiền phải thu từ khách hàng (AR)', 'Money owed to a company by its debtors.', 'Tightening payment collection terms reduced outstanding accounts receivable balances significantly.', 'Thắt chặt các điều khoản thu hồi nợ đã làm giảm đáng kể số dư nợ phải thu chưa thanh toán.', ARRAY['AR', 'Debtor balance', 'Owed funds']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-98', 'business', 'Working Capital', '/ˌwɝː.kɪŋ ˈkæp.ə.t̬əl/', 'Noun', 'B2', 'Vốn lưu động vận hành ngắn hạn', 'The capital of a business which is used in its day-to-day trading operations, calculated as the current assets minus the current liabilities.', 'Managing inventory levels efficiently frees up millions in vital working capital.', 'Quản lý lượng hàng tồn kho hiệu quả giúp giải phóng hàng triệu USD vốn lưu động thiết yếu.', ARRAY['Operating capital', 'Net current assets']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-99', 'business', 'EBITDA', '/iːˈbɪt.dɑː/', 'Noun', 'C1', 'Lợi nhuận trước lãi vay, thuế và khấu hao', 'Earnings Before Interest, Taxes, Depreciation, and Amortization.', 'Institutional investors evaluate corporate buyout candidates based on their EBITDA multiple.', 'Các nhà đầu tư tổ chức đánh giá những mục tiêu mua lại doanh nghiệp dựa trên bội số EBITDA của họ.', ARRAY['Operating cash profit', 'Cash earnings']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('biz-100', 'business', 'Net Profit Margin', '/ˌnet ˈprɑː.fɪt ˌmɑːr.dʒɪn/', 'Noun', 'B2', 'Biên lợi nhuận ròng sau thuế', 'The percentage of revenue left after all expenses have been deducted from sales.', 'The software company boasts an astonishing net profit margin of thirty-five percent.', 'Công ty phần mềm tự hào có mức biên lợi nhuận ròng đáng kinh ngạc lên đến 35%.', ARRAY['Bottom line margin', 'Net earnings margin']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-1', 'technology', 'Algorithm', '/ˈæl.ɡə.rɪ.ðəm/', 'Noun', 'B2', 'Thuật toán xử lý tuần tự', 'A process or set of rules to be followed in calculations or problem-solving operations by a computer.', 'Search engines utilize sophisticated algorithms to rank web pages by relevance and authority.', 'Các công cụ tìm kiếm sử dụng những thuật toán tinh vi để xếp hạng các trang web theo mức độ phù hợp và độ tin cậy.', ARRAY['Procedure', 'Computation rule', 'Program formula']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-2', 'technology', 'Artificial Intelligence', '/ˌɑːr.t̬əˈfɪʃ.əl ɪnˈtel.ə.dʒəns/', 'Noun', 'B1', 'Trí tuệ nhân tạo (AI)', 'The simulation of human intelligence in machines that are programmed to think and learn.', 'Artificial intelligence is accelerating breakthroughs in genomic drug discovery.', 'Trí tuệ nhân tạo đang đẩy nhanh các bước đột phá trong việc phát hiện thuốc hệ gen.', ARRAY['AI', 'Machine intelligence']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-3', 'technology', 'Machine Learning', '/məˈʃiːn ˌlɝː.nɪŋ/', 'Noun', 'B2', 'Học máy dựa trên dữ liệu', 'The use and development of computer systems that are able to learn and adapt without following explicit instructions.', 'Predictive maintenance models rely on machine learning to forecast equipment failure.', 'Các mô hình bảo trì dự đoán dựa vào học máy để dự báo sự cố thiết bị.', ARRAY['ML', 'Data-driven learning']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-4', 'technology', 'Neural Network', '/ˈnʊr.əl ˌnet.wɝːk/', 'Noun', 'C1', 'Mạng nơ-ron nhân tạo mô phỏng não bộ', 'A computer system modeled on the human brain and nervous system.', 'Deep neural networks power autonomous vehicle visual recognition systems.', 'Mạng nơ-ron sâu vận hành các hệ thống nhận diện thị giác của xe tự hành.', ARRAY['Deep learning network', 'ANN']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-5', 'technology', 'Large Language Model', '/ˌlɑːrdʒ ˈlæŋ.ɡwɪdʒ ˌmɑː.dəl/', 'Noun', 'B2', 'Mô hình ngôn ngữ lớn (LLM)', 'An advanced AI model trained on vast amounts of text data to understand and generate human-like language.', 'State-of-the-art large language models can draft legal briefs and synthesize medical research in seconds.', 'Các mô hình ngôn ngữ lớn tối tân có thể soạn thảo tóm tắt pháp lý và tổng hợp nghiên cứu y khoa chỉ trong vài giây.', ARRAY['LLM', 'Foundation model']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-6', 'technology', 'Cloud Computing', '/klaʊd kəmˈpjuː.t̬ɪŋ/', 'Noun', 'B1', 'Điện toán đám mây phân tán', 'The practice of using a network of remote servers hosted on the Internet to store, manage, and process data.', 'Migrating to cloud computing eliminated the need for on-premises server maintenance.', 'Chuyển đổi sang điện toán đám mây đã loại bỏ nhu cầu bảo trì máy chủ tại chỗ.', ARRAY['Distributed cloud', 'Serverless hosting']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-7', 'technology', 'Latency', '/ˈleɪ.tən.si/', 'Noun', 'B2', 'Độ trễ truyền tải tín hiệu mạng', 'The delay before a transfer of data begins following an instruction for its transfer.', 'High network latency ruins the user experience in competitive online gaming.', 'Độ trễ mạng cao làm hỏng trải nghiệm người dùng trong các trò chơi trực tuyến đối kháng.', ARRAY['Delay', 'Lag', 'Response time']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-8', 'technology', 'Throughput', '/ˈθruː.pʊt/', 'Noun', 'B2', 'Băng thông thông lượng xử lý dữ liệu', 'The amount of material or items passing through a system or process.', 'Upgrading our database cluster doubled the write throughput to 50,000 transactions per second.', 'Nâng cấp cụm cơ sở dữ liệu đã tăng gấp đôi thông lượng ghi lên 50.000 giao dịch mỗi giây.', ARRAY['Processing capacity', 'Data rate']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-9', 'technology', 'Cryptography', '/krɪpˈtɑː.ɡrə.fi/', 'Noun', 'C1', 'Mật mã học bảo mật thông tin', 'The art of writing or solving codes, especially for secure communications.', 'Asymmetric cryptography forms the foundation of secure HTTPS web connections.', 'Mật mã học bất đối xứng tạo nên nền tảng của các kết nối web HTTPS bảo mật.', ARRAY['Encryption science', 'Cipher science']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-10', 'technology', 'Decryption', '/diːˈkrɪp.ʃən/', 'Noun', 'B2', 'Giải mã thông điệp mã hóa', 'The process of converting information or data that has been encrypted back into an unencrypted form.', 'Without the private key, mathematical decryption of the encrypted vault is practically impossible.', 'Nếu không có khóa riêng, việc giải mã toán học kho lưu trữ đã mã hóa về mặt thực tế là bất khả thi.', ARRAY['Decoding', 'Deciphering']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-11', 'technology', 'Microservices', '/ˈmaɪ.kroʊˌsɝː.vɪ.sɪz/', 'Noun', 'B2', 'Kiến trúc vi dịch vụ độc lập', 'A software architecture design wherein an application is composed of small, independent services.', 'Decomposing the monolith into microservices allowed teams to deploy independently.', 'Việc chia nhỏ khối mã liền khối thành các vi dịch vụ cho phép các đội ngũ triển khai độc lập.', ARRAY['Distributed services', 'Decoupled architecture']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-12', 'technology', 'Monolith', '/ˈmɑː.nə.lɪθ/', 'Noun', 'B2', 'Khối kiến trúc phần mềm liền khối', 'A software system where the user interface, business logic, and data access code are all combined into a single program.', 'Refactoring a ten-year-old legacy monolith requires meticulous automated test coverage.', 'Việc tái cấu trúc một khối phần mềm liền khối 10 năm tuổi đòi hỏi độ bao phủ kiểm thử tự động tỉ mỉ.', ARRAY['Single-tier app', 'Integrated architecture']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-13', 'technology', 'Orchestration', '/ˌɔːr.kəˈstreɪ.ʃən/', 'Noun', 'C1', 'Sự điều phối tự động container/hệ thống', 'The automated configuration, coordination, and management of computer systems and software.', 'Kubernetes handles container orchestration across thousands of cloud compute nodes.', 'Kubernetes đảm nhiệm việc điều phối container trên hàng ngàn nút điện toán đám mây.', ARRAY['Automated coordination', 'Cluster management']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-14', 'technology', 'Virtualization', '/ˌvɝː.tʃu.ə.laɪˈzeɪ.ʃən/', 'Noun', 'B2', 'Ảo hóa tài nguyên phần cứng', 'The creation of a virtual rather than actual version of something, such as an operating system or server.', 'Hardware virtualization enables multiple isolated operating systems to share physical processors.', 'Ảo hóa phần cứng cho phép nhiều hệ điều hành cô lập cùng chia sẻ các bộ vi xử lý vật lý.', ARRAY['Hardware abstraction', 'Virtual machine hosting']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-15', 'technology', 'Repository', '/rɪˈpɑː.zə.tɔːr.i/', 'Noun', 'B1', 'Kho lưu trữ mã nguồn (Repo Git)', 'A central place in which data is stored and managed, specifically source code.', 'All developers clone the remote Git repository to begin local feature development.', 'Tất cả các lập trình viên đều sao chép kho mã nguồn Git từ xa để bắt đầu phát triển tính năng cục bộ.', ARRAY['Repo', 'Codebase', 'Storage']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-16', 'technology', 'Refactoring', '/riːˈfæk.tɚ.ɪŋ/', 'Noun', 'B2', 'Tái cấu trúc mã nguồn tối ưu mà không đổi tính năng', 'The process of restructuring existing computer code without changing its external behavior.', 'Continuous code refactoring prevents technical debt from crippling product velocity.', 'Việc tái cấu trúc mã nguồn liên tục giúp ngăn nợ kỹ thuật làm tê liệt tốc độ ra mắt sản phẩm.', ARRAY['Code restructuring', 'Code clean-up']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-17', 'technology', 'Technical Debt', '/ˌtek.nɪ.kəl ˈdet/', 'Noun', 'B2', 'Nợ kỹ thuật do viết mã ẩu vội vàng', 'The implied cost of additional rework caused by choosing an easy limited solution now instead of a better approach that would take longer.', 'Accumulating too much technical debt eventually slows sprint progress to a crawl.', 'Tích tụ quá nhiều nợ kỹ thuật cuối cùng sẽ làm chậm tiến độ các chu kỳ phát triển xuống mức rùa bò.', ARRAY['Code debt', 'Engineering deficit']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-18', 'technology', 'Telemetry', '/təˈlem.ə.tri/', 'Noun', 'C1', 'Dữ liệu đo xa tự động gửi về', 'The automatic measurement and wireless transmission of data from remote sources.', 'Production telemetry alerts our on-call engineers when API error rates breach one percent.', 'Dữ liệu đo xa môi trường thực tế sẽ cảnh báo các kỹ sư trực ban khi tỷ lệ lỗi API vượt ngưỡng 1%.', ARRAY['Remote monitoring data', 'System metrics']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-19', 'technology', 'Continuous Integration', '/kənˌtɪn.ju.əs ˌɪn.t̬əˈɡreɪ.ʃən/', 'Noun', 'B2', 'Tích hợp liên tục (CI)', 'The practice of automating the integration of code changes from multiple contributors into a single software project.', 'Our CI pipeline runs automated linting and unit tests on every pull request.', 'Quy trình CI của chúng tôi tự động chạy rà soát cú pháp và kiểm thử đơn vị trên mỗi yêu cầu hợp nhất mã.', ARRAY['CI', 'Automated build pipeline']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-20', 'technology', 'Continuous Deployment', '/kənˌtɪn.ju.əs dɪˈplɔɪ.mənt/', 'Noun', 'B2', 'Triển khai liên tục (CD)', 'A software engineering approach in which software functionalities are delivered frequently through automated deployments.', 'Continuous deployment enables our engineering team to ship updates to end users twenty times a day.', 'Triển khai liên tục cho phép đội ngũ kỹ thuật của chúng tôi xuất bản các bản cập nhật tới người dùng cuối 20 lần mỗi ngày.', ARRAY['CD', 'Automated release pipeline']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-21', 'technology', 'Concurrency', '/kənˈkɝː.ən.si/', 'Noun', 'C1', 'Tính đồng thời trong xử lý đa luồng', 'The ability of different parts or units of a program, algorithm, or problem to be executed out-of-order or in partial order, without affecting the outcome.', 'Go and Rust provide robust primitives for managing safe concurrency without data races.', 'Go và Rust cung cấp các nguyên mẫu mạnh mẽ để quản lý tính đồng thời an toàn mà không xảy ra xung đột dữ liệu.', ARRAY['Parallelism', 'Simultaneous execution', 'Multithreading']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-22', 'technology', 'Multithreading', '/ˌmʌl.tiˈθred.ɪŋ/', 'Noun', 'B2', 'Xử lý đa luồng trên CPU', 'A technique by which a single set of code can be used by several processors at different stages of execution.', 'Video rendering applications utilize multithreading to speed up frame processing across all CPU cores.', 'Các ứng dụng kết xuất video tận dụng xử lý đa luồng để đẩy nhanh tiến độ khung hình trên mọi nhân CPU.', ARRAY['Parallel threading', 'Concurrent tasks']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-23', 'technology', 'Asynchronous', '/eɪˈsɪŋ.krə.nəs/', 'Adj', 'B2', 'Bất đồng bộ không chặn luồng chính', 'Not occurring at the same time; computing processes that execute independently of the main program flow.', 'Asynchronous JavaScript requests fetch API data in the background without freezing the UI.', 'Các lệnh yêu cầu JavaScript bất đồng bộ lấy dữ liệu API ngầm mà không làm đơ giao diện người dùng.', ARRAY['Async', 'Non-blocking', 'Concurrent']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-24', 'technology', 'Synchronous', '/ˈsɪŋ.krə.nəs/', 'Adj', 'B2', 'Đồng bộ, chờ xử lý tuần tự', 'Existing or occurring at the same time; executing step-by-step where each step waits for the previous one to finish.', 'Synchronous disk writes guarantee immediate data persistence at the cost of higher latency.', 'Ghi đĩa đồng bộ đảm bảo tính bền vững dữ liệu ngay tức thì nhưng phải trả giá bằng độ trễ cao hơn.', ARRAY['Blocking', 'Sequential', 'Sequential execution']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-25', 'technology', 'Idempotency', '/ˌaɪ.dəmˈpoʊ.tən.si/', 'Noun', 'C1', 'Tính lũy kế bất biến khi gọi lại nhiều lần', 'The property of certain operations in mathematics and computer science whereby they can be applied multiple times without changing the result beyond the initial application.', 'Payment endpoints must enforce idempotency to prevent customers from being charged twice upon retries.', 'Các cổng thanh toán phải áp dụng tính lũy kế bất biến để ngăn khách hàng bị trừ tiền 2 lần khi thử lại giao dịch.', ARRAY['Repeat safety', 'Result invariance']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-26', 'technology', 'Sharding', '/ˈʃɑːr.dɪŋ/', 'Noun', 'C1', 'Phân mảnh cơ sở dữ liệu theo chiều ngang', 'A type of database partitioning that separates large databases into smaller, faster, more easily managed parts called data shards.', 'Database sharding allows social media networks to distribute billions of posts across hundreds of servers.', 'Phân mảnh cơ sở dữ liệu cho phép các mạng xã hội phân tán hàng tỷ bài đăng trên hàng trăm máy chủ.', ARRAY['Horizontal partitioning', 'Data splitting']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-27', 'technology', 'Replication', '/ˌrep.lɪˈkeɪ.ʃən/', 'Noun', 'B2', 'Nhân bản dữ liệu dự phòng', 'The process of sharing information so as to ensure consistency between redundant resources.', 'Multi-region database replication ensures high availability in case of a regional datacenter outage.', 'Nhân bản cơ sở dữ liệu đa khu vực đảm bảo tính sẵn sàng cao trong trường hợp xảy ra sự cố trung tâm dữ liệu khu vực.', ARRAY['Duplication', 'Redundancy mirroring', 'Cloning']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-28', 'technology', 'Failover', '/ˈfeɪlˌoʊ.vɚ/', 'Noun', 'B2', 'Chuyển đổi dự phòng tự động khi máy chủ gặp sự cố', 'An automated backup operational mode in which the functions of a system component are assumed by secondary system components when the primary fails.', 'Automated DNS failover rerouted incoming web traffic to our secondary cluster within three seconds.', 'Chuyển đổi dự phòng DNS tự động đã chuyển hướng lưu lượng web đến cụm thứ cấp chỉ trong 3 giây.', ARRAY['Backup switch', 'Redundancy transfer']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-29', 'technology', 'Immutable', '/ɪˈmjuː.t̬ə.bəl/', 'Adj', 'C1', 'Bất biến không thể chỉnh sửa sau khi tạo', 'Unchanging over time or unable to be changed.', 'Blockchain transaction blocks are mathematically immutable once appended to the distributed ledger.', 'Các khối giao dịch chuỗi khối về mặt toán học là bất biến một khi đã được gắn vào sổ cái phân tán.', ARRAY['Unchangeable', 'Fixed', 'Permanent']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-30', 'technology', 'Polymorphism', '/ˌpɑː.liˈmɔːr.fɪ.zəm/', 'Noun', 'C1', 'Tính đa hình trong lập trình hướng đối tượng', 'The condition of occurring in several different forms; in OOP, providing a single interface to entities of different types.', 'Object-oriented polymorphism allows our graphics engine to render shapes without knowing their concrete classes.', 'Tính đa hình hướng đối tượng cho phép công cụ đồ họa kết xuất các hình khối mà không cần biết lớp cụ thể của chúng.', ARRAY['Multiformity', 'Interface flexibility']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-31', 'technology', 'Encapsulation', '/ɪnˌkæp.səˈleɪ.ʃən/', 'Noun', 'B2', 'Tính đóng gói bảo vệ dữ liệu nội tại', 'The action of enclosing something in or as if in a capsule; in OOP, restricting direct access to object components.', 'Encapsulation safeguards internal class state by exposing only validated setter methods.', 'Tính đóng gói bảo vệ trạng thái nội tại của lớp bằng cách chỉ công khai các phương thức gán giá trị đã được xác thực.', ARRAY['Information hiding', 'Data protection']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-32', 'technology', 'Inheritance', '/ɪnˈher.ɪ.təns/', 'Noun', 'B1', 'Tính kế thừa thuộc tính và phương thức', 'The derivation of characteristics by a child class from its parent class in OOP.', 'Composition is frequently preferred over deep class inheritance to prevent brittle software hierarchies.', 'Ghép nối thành phần thường được ưa chuộng hơn là kế thừa lớp sâu để tránh hệ thống phân cấp phần mềm dễ gãy.', ARRAY['Derivation', 'Ancestry']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-33', 'technology', 'Serialization', '/ˌsɪr.i.ə.ləˈzeɪ.ʃən/', 'Noun', 'B2', 'Tuần tự hóa dữ liệu thành chuỗi byte', 'The process of translating a data structure or object state into a format that can be stored or transmitted.', 'JSON serialization converts runtime objects into text strings suitable for HTTP transmission.', 'Tuần tự hóa JSON chuyển đổi các đối tượng đang chạy thành các chuỗi văn bản phù hợp để truyền qua HTTP.', ARRAY['Marshalling', 'Byte encoding']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-34', 'technology', 'Deserialization', '/diːˌsɪr.i.ə.ləˈzeɪ.ʃən/', 'Noun', 'B2', 'Giải tuần tự hóa chuỗi byte thành đối tượng', 'The reverse process of reconstructing an object from a serialized byte stream.', 'Careless deserialization of untrusted payloads can introduce severe remote code execution vulnerabilities.', 'Giải tuần tự hóa bất cẩn dữ liệu không đáng tin cậy có thể dẫn đến những lỗ hổng thực thi mã từ xa nguy hiểm.', ARRAY['Unmarshalling', 'Decoding']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-35', 'technology', 'Endpoint', '/ˈend.pɔɪnt/', 'Noun', 'B1', 'Điểm cuối API tiếp nhận yêu cầu', 'A specific URL where a web service can be accessed by a client application.', 'The REST API endpoint for user authentication requires an email and password in the JSON body.', 'Điểm cuối API REST phục vụ xác thực người dùng yêu cầu email và mật khẩu trong phần thân JSON.', ARRAY['API route', 'Access point', 'URL path']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-36', 'technology', 'Payload', '/ˈpeɪ.loʊd/', 'Noun', 'B2', 'Dữ liệu thực tế mang theo trong gói tin', 'The actual data transported in a packet, transmission, or API request, excluding header overhead.', 'Compressing the HTTP response payload reduced mobile mobile network bandwidth consumption.', 'Nén gói dữ liệu phản hồi HTTP đã làm giảm mức tiêu thụ băng thông mạng di động.', ARRAY['Data body', 'Content cargo']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-37', 'technology', 'Rate Limiting', '/ˈreɪt ˌlɪm.ɪ.tɪŋ/', 'Noun', 'B2', 'Giới hạn tần suất gọi yêu cầu để chống nghẽn', 'A strategy for limiting network traffic by capping how often a user can repeat an action within a specified time.', 'The API implements rate limiting to thwart denial-of-service brute-force attacks.', 'API triển khai giới hạn tần suất gọi nhằm cản trở các cuộc tấn công từ chối dịch vụ vét cạn.', ARRAY['Throttling', 'Traffic capping']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-38', 'technology', 'Denial of Service', '/dɪˌnaɪ.əl əv ˈsɝː.vɪs/', 'Noun', 'B2', 'Tấn công từ chối dịch vụ làm sập hệ thống (DoS)', 'An interruption in an authorized user''s access to a computer network, typically one caused with malicious intent.', 'A distributed denial of service attack overwhelmed our front-facing load balancers with bogus traffic.', 'Một cuộc tấn công từ chối dịch vụ phân tán đã làm tê liệt các bộ cân bằng tải mặt trước bằng lưu lượng giả mạo.', ARRAY['DoS', 'DDoS', 'Service flood']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-39', 'technology', 'Firewall', '/ˈfaɪr.wɑːl/', 'Noun', 'B1', 'Tường lửa ngăn chặn xâm nhập mạng', 'A part of a computer system or network designed to block unauthorized access while permitting outward communication.', 'Corporate network firewalls prevent unauthorized incoming connections from reaching internal databases.', 'Tường lửa mạng doanh nghiệp ngăn các kết nối bên ngoài trái phép tiếp cận các cơ sở dữ liệu nội bộ.', ARRAY['Network barrier', 'Security shield']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-40', 'technology', 'Vulnerability', '/ˌvʌl.nɚ.əˈbɪl.ə.t̬i/', 'Noun', 'B2', 'Lỗ hổng bảo mật có thể bị khai thác', 'A weakness in a system or its design that can be exploited by a threat actor.', 'Security researchers uncovered a critical zero-day vulnerability in the open-source library.', 'Các nhà nghiên cứu an ninh mạng đã phát hiện ra lỗ hổng ngày số không nguy cấp trong thư viện mã nguồn mở.', ARRAY['Flaw', 'Security loophole', 'Weakness']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-41', 'technology', 'Zero-Day', '/ˌzɪr.oʊ ˈdeɪ/', 'Noun', 'C1', 'Lỗ hổng ngày số không chưa có bản vá', 'A vulnerability that is discovered before the software creator is aware of it or has released a security patch.', 'Nation-state hackers weaponized a zero-day exploit targeting popular smartphone operating systems.', 'Tin tặc cấp quốc gia đã vũ khí hóa mã khai thác ngày số không nhắm vào các hệ điều hành điện thoại phổ biến.', ARRAY['Unpatched flaw', 'Unknown exploit']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-42', 'technology', 'Patch', '/pætʃ/', 'Noun', 'B1', 'Bản vá lỗi phần mềm khẩn cấp', 'A piece of software designed to update a computer program or its supporting data, to fix or improve it.', 'Sysadmins installed the emergency security patch across all production servers before midnight.', 'Quản trị viên hệ thống đã cài đặt bản vá bảo mật khẩn cấp trên toàn bộ máy chủ thực tế trước nửa đêm.', ARRAY['Update', 'Hotfix', 'Fix']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-43', 'technology', 'Sandbox', '/ˈsænd.bɑːks/', 'Noun', 'B2', 'Môi trường hộp cát cách ly an toàn', 'An isolated testing environment that enables users to run programs or execute files without affecting the application, system or platform on which they run.', 'Modern web browsers run third-party plugins in a secure sandbox to isolate untrusted code.', 'Trình duyệt web hiện đại chạy các plugin của bên thứ ba trong hộp cát bảo mật để cô lập mã không tin cậy.', ARRAY['Isolated environment', 'Safe container']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-44', 'technology', 'Containerization', '/kənˌteɪ.nɚ.əˈzeɪ.ʃən/', 'Noun', 'C1', 'Đóng gói ứng dụng vào thùng chứa container', 'The packaging of software code with just the operating system libraries and dependencies required to run the code.', 'Docker popularized containerization, enabling identical runtime behaviors across local and cloud servers.', 'Docker đã phổ biến phương thức container hóa, mang lại hành vi chạy mã đồng nhất trên máy cục bộ và máy chủ đám mây.', ARRAY['Container deployment', 'Dockerization']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-45', 'technology', 'Hypervisor', '/ˈhaɪ.pɚ.vaɪ.zɚ/', 'Noun', 'C1', 'Phần mềm giám sát quản lý máy ảo', 'Software, firmware, or hardware that creates and runs virtual machines.', 'The hypervisor dynamically allocates CPU cores and physical RAM among thirty virtual machines.', 'Trình giám sát máy ảo phân bổ linh hoạt nhân CPU và RAM vật lý giữa 30 máy ảo khác nhau.', ARRAY['VMM', 'Virtual machine monitor']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-46', 'technology', 'State Machine', '/ˈsteɪt məˌʃiːn/', 'Noun', 'C1', 'Máy trạng thái hữu hạn kiểm soát logic', 'A mathematical model of computation that can be in exactly one of a finite number of states at any given time.', 'We implemented a deterministic state machine to govern the checkout and payment transaction flow.', 'Chúng tôi đã triển khai một máy trạng thái hữu hạn tiền định để kiểm soát quy trình thanh toán đơn hàng.', ARRAY['FSM', 'Finite state automaton']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-47', 'technology', 'Deterministic', '/dɪˌtɝː.mɪˈnɪs.tɪk/', 'Adj', 'C1', 'Tiền định, đầu vào như nhau cho ra kết quả như nhau', 'Relating to the philosophical doctrine that all events, including human action, are ultimately determined by causes external to the will; computing without randomness.', 'Unit tests should be strictly deterministic, yielding the exact same assertion outcomes every run.', 'Kiểm thử đơn vị phải tuyệt đối mang tính tiền định, luôn trả về cùng kết quả khẳng định ở mỗi lần chạy.', ARRAY['Predictable', 'Non-random', 'Repeatable']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-48', 'technology', 'Stochastic', '/stəˈkæs.tɪk/', 'Adj', 'C1', 'Ngẫu nhiên, có tính xác suất thống kê', 'Having a random probability distribution or pattern that may be analyzed statistically but may not be predicted precisely.', 'Stochastic gradient descent is an essential optimization algorithm used in training deep neural nets.', 'Hạ độ dốc ngẫu nhiên là một thuật toán tối ưu hóa thiết yếu được dùng trong huấn luyện mạng nơ-ron sâu.', ARRAY['Probabilistic', 'Random', 'Statistical']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-49', 'technology', 'Gradient Descent', '/ˌɡreɪ.di.ənt dɪˈsent/', 'Noun', 'C1', 'Thuật toán hạ độ dốc tối ưu hàm mất mát', 'A first-order iterative optimization algorithm for finding a local minimum of a differentiable function.', 'Adjusting the learning rate prevents gradient descent from overshooting the optimal loss minimum.', 'Điều chỉnh tốc độ học giúp ngăn thuật toán hạ độ dốc nhảy vượt qua điểm cực tiểu mất mát tối ưu.', ARRAY['Optimization algorithm', 'Loss minimization']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-50', 'technology', 'Hyperparameter', '/ˌhaɪ.pɚ.pəˈræm.ə.t̬ɚ/', 'Noun', 'C1', 'Siêu tham số cấu hình mô hình học máy', 'A parameter whose value is set before the learning process begins, controlling the training algorithm.', 'Tuning hyperparameters such as batch size and dropout rate is crucial for high model accuracy.', 'Tinh chỉnh các siêu tham số như kích thước lô và tỷ lệ loại bỏ là điều cốt tử để đạt độ chính xác cao cho mô hình.', ARRAY['Configuration parameter', 'External variable']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-51', 'technology', 'Overfitting', '/ˌoʊ.vɚˈfɪt.ɪŋ/', 'Noun', 'B2', 'Hiện tượng học vẹt quá khớp dữ liệu huấn luyện', 'The production of an analysis that corresponds too closely or exclusively to a particular set of data, failing to predict future observations reliably.', 'Applying regularization techniques helps prevent deep learning models from overfitting.', 'Áp dụng các kỹ thuật chính quy hóa giúp ngăn các mô hình học sâu khỏi hiện tượng học vẹt quá khớp dữ liệu.', ARRAY['Over-specialization', 'Data memorization']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-52', 'technology', 'Underfitting', '/ˌʌn.dɚˈfɪt.ɪŋ/', 'Noun', 'B2', 'Hiện tượng chưa khớp dữ liệu do mô hình quá đơn giản', 'A situation where a machine learning model cannot capture the underlying trend of the training data.', 'Using a linear model for complex non-linear image recognition resulted in severe underfitting.', 'Sử dụng mô hình tuyến tính cho việc nhận diện hình ảnh phi tuyến tính phức tạp đã dẫn đến hiện tượng chưa khớp nghiêm trọng.', ARRAY['Under-specialization', 'Insufficient complexity']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-53', 'technology', 'Ground Truth', '/ˌɡraʊnd ˈtruːθ/', 'Noun', 'C1', 'Dữ liệu thực tế chuẩn xác tuyệt đối để đối chiếu', 'Information that is known to be real or true, provided by direct observation and measurement.', 'Radiologists provided the expert ground truth labels used to evaluate the chest X-ray AI model.', 'Các bác sĩ chẩn đoán hình ảnh đã cung cấp nhãn dữ liệu thực tế chuẩn xác được dùng để đánh giá mô hình AI X-quang phổi.', ARRAY['Gold standard', 'Empirical baseline']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-54', 'technology', 'Inference', '/ˈɪn.fɚ.əns/', 'Noun', 'B2', 'Quá trình suy luận chạy mô hình AI thực tế', 'The process of using a trained machine learning model to make predictions on unseen data.', 'Edge AI chips allow real-time image inference directly on wearable glasses without internet latency.', 'Chip AI biên cho phép suy luận hình ảnh theo thời gian thực trực tiếp trên kính đeo mà không bị trễ mạng.', ARRAY['Model prediction', 'Execution step']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-55', 'technology', 'Tokenization', '/ˌtoʊ.kən.əˈzeɪ.ʃən/', 'Noun', 'B2', 'Phân mảnh văn bản thành các token đơn vị', 'The process of breaking down a stream of text into words, phrases, symbols, or other meaningful elements called tokens.', 'Byte-pair encoding tokenization breaks unusual technical words into familiar sub-word chunks.', 'Phân mảnh văn bản mã hóa cặp byte chia các từ ngữ kỹ thuật lạ lẫm thành các mẩu từ con quen thuộc.', ARRAY['Word segmentation', 'Text parsing']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-56', 'technology', 'Embedding', '/ɪmˈbed.ɪŋ/', 'Noun', 'C1', 'Véc-tơ biểu diễn ngữ nghĩa không gian', 'A relatively low-dimensional space into which high-dimensional vectors can be translated, capturing semantic meaning.', 'Vector embeddings allow similarity search algorithms to find related articles conceptually.', 'Véc-tơ nhúng ngữ nghĩa cho phép các thuật toán tìm kiếm tương đồng tìm ra các bài viết liên quan về mặt khái niệm.', ARRAY['Vector representation', 'Semantic encoding']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-57', 'technology', 'Vector Database', '/ˈvek.tɚ ˌdeɪ.t̬ə.beɪs/', 'Noun', 'B2', 'Cơ sở dữ liệu véc-tơ phục vụ tìm kiếm ngữ nghĩa', 'A database designed to store, manage, and index high-dimensional vector representations efficiently.', 'Retrieval-Augmented Generation workflows query a vector database to fetch relevant enterprise knowledge.', 'Quy trình Tạo sinh tăng cường truy xuất dữ liệu truy vấn cơ sở dữ liệu véc-tơ để lấy kiến thức doanh nghiệp liên quan.', ARRAY['Embedding store', 'Semantic database']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-58', 'technology', 'Fine-Tuning', '/ˌfaɪnˈtuː.nɪŋ/', 'Noun', 'B2', 'Tinh chỉnh chuyên sâu mô hình nền tảng bằng dữ liệu riêng', 'The process of taking a pre-trained model and adapting it to a specific task by further training it on specialized data.', 'Fine-tuning the language model on clinical oncology records dramatically improved diagnostic accuracy.', 'Tinh chỉnh mô hình ngôn ngữ trên các bệnh án ung thư lâm sàng đã cải thiện đáng kể độ chính xác chẩn đoán.', ARRAY['Model adaptation', 'Specialized training']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-59', 'technology', 'Hallucination', '/həˌluː.səˈneɪ.ʃən/', 'Noun', 'B2', 'Hiện tượng AI bịa đặt thông tin sai lệch', 'A phenomenon where a large language model generates incorrect, nonsensical, or unfaithful statements with high confidence.', 'Grounding AI outputs with cited reference documents mitigates the dangerous risk of hallucination.', 'Cung cấp tài liệu tham khảo có trích dẫn cho kết quả AI giúp giảm thiểu nguy cơ ảo tưởng bịa đặt nguy hiểm.', ARRAY['Fabrication', 'False generation', 'Model delusion']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-60', 'technology', 'Prompt Engineering', '/ˌprɑːmpt ˌen.dʒəˈnɪr.ɪŋ/', 'Noun', 'B2', 'Kỹ thuật tối ưu câu lệnh điều khiển AI', 'The practice of crafting input prompts to guide generative AI models toward desired, accurate outputs.', 'Mastering prompt engineering techniques like chain-of-thought dramatically improves mathematical reasoning.', 'Thành thạo các kỹ thuật tối ưu câu lệnh như chuỗi tư duy sẽ cải thiện đáng kể khả năng lập luận toán học của AI.', ARRAY['Prompt design', 'Instruction tuning']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-61', 'technology', 'Zero-Shot Learning', '/ˌzɪr.oʊ ˈʃɑːt ˌlɝː.nɪŋ/', 'Noun', 'C1', 'Học không cần mẫu ví dụ', 'A machine learning scenario where a model recognizes classes or tasks without having seen explicit labeled examples during training.', 'The vision-language model displayed impressive zero-shot learning on identifying exotic deep-sea marine species.', 'Mô hình thị giác - ngôn ngữ đã thể hiện khả năng học không cần mẫu ấn tượng trong việc nhận diện các loài sinh vật biển sâu kỳ lạ.', ARRAY['Transfer learning', 'Shot-free learning']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-62', 'technology', 'Few-Shot Learning', '/ˌfjuː ˈʃɑːt ˌlɝː.nɪŋ/', 'Noun', 'C1', 'Học với vài mẫu ví dụ minh họa', 'A machine learning task where a model is presented with a tiny number of training examples to generalize a new concept.', 'Supplying three good code examples enabled the AI assistant to perform accurate few-shot classification.', 'Cung cấp 3 ví dụ mã mẫu chuẩn đã giúp trợ lý AI thực hiện phân loại chính xác theo phương thức học vài mẫu.', ARRAY['Context learning', 'In-context learning']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-63', 'technology', 'Explainability', '/ɪkˌspleɪ.nəˈbɪl.ə.t̬i/', 'Noun', 'C1', 'Khả năng giải thích được lý do đằng sau quyết định của AI', 'The extent to which the internal mechanics of a machine learning model can be understood by humans.', 'In healthcare and criminal sentencing, algorithmic explainability is legally mandated.', 'Trong chăm sóc sức khỏe và tuyên án hình sự, khả năng giải thích của thuật toán là yêu cầu bắt buộc theo luật định.', ARRAY['Interpretability', 'Transparency', 'Accountability']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-64', 'technology', 'Bias', '/ˈbaɪ.əs/', 'Noun', 'B2', 'Định kiến thiên lệch dữ liệu', 'Prejudice in favor of or against one thing, person, or group compared with another, usually in a way considered unfair.', 'Training on uncurated historical hiring logs introduced severe gender bias into the screening algorithm.', 'Huấn luyện trên nhật ký tuyển dụng lịch sử chưa qua chọn lọc đã mang định kiến giới tính nặng nề vào thuật toán sàng lọc.', ARRAY['Prejudice', 'Skew', 'Partiality']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-65', 'technology', 'Alignment', '/əˈlaɪn.mənt/', 'Noun', 'C1', 'Sự đồng bộ hóa mục tiêu AI theo chuẩn đạo đức con người', 'The subfield of artificial intelligence aimed at steering AI systems toward human goals, preferences, or ethical principles.', 'AI safety researchers prioritize alignment to ensure advanced superintelligence acts benevolently.', 'Các nhà nghiên cứu an toàn AI ưu tiên tính tương thích nhằm đảm bảo siêu trí tuệ nhân tạo hành động vì mục đích tốt đẹp cho con người.', ARRAY['Ethical tuning', 'Goal concordance']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-66', 'technology', 'Supervised Learning', '/ˈsuː.pɚ.vaɪzd ˌlɝː.nɪŋ/', 'Noun', 'B2', 'Học có giám sát bằng dữ liệu gắn nhãn', 'A machine learning paradigm where the computer is trained on input data that has been paired with the correct output labels.', 'Supervised learning algorithms excel at spam email detection when trained on hundreds of thousands of marked emails.', 'Các thuật toán học có giám sát rất xuất sắc trong việc phát hiện thư rác khi được huấn luyện trên hàng trăm nghìn email đã gắn nhãn.', ARRAY['Labeled learning', 'Guided training']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-67', 'technology', 'Unsupervised Learning', '/ˌʌnˈsuː.pɚ.vaɪzd ˌlɝː.nɪŋ/', 'Noun', 'B2', 'Học không giám sát tự tìm quy luật ẩn', 'A type of machine learning that looks for previously undetected patterns in a data set with no pre-existing labels.', 'Clustering customer purchasing behaviors into distinct marketing personas is an application of unsupervised learning.', 'Phân nhóm hành vi mua sắm của khách hàng thành các chân dung tiếp thị riêng biệt là ứng dụng của học không giám sát.', ARRAY['Pattern discovery', 'Clustering analysis']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-68', 'technology', 'Reinforcement Learning', '/ˌriː.ɪnˈfɔːrs.mənt ˌlɝː.nɪŋ/', 'Noun', 'C1', 'Học tăng cường dựa trên thưởng phạt', 'An area of machine learning concerned with how software agents ought to take actions in an environment to maximize some notion of cumulative reward.', 'Reinforcement learning enabled computers to defeat grandmasters in complex strategy games like Go.', 'Học tăng cường đã cho phép máy tính đánh bại các đại kiện tướng trong những trò chơi chiến thuật phức tạp như Cờ vây.', ARRAY['RL', 'Reward-based learning']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-69', 'technology', 'Heuristic', '/hjʊˈrɪs.tɪk/', 'Noun', 'C1', 'Phương pháp giải toán gần đúng theo kinh nghiệm', 'Any approach to problem solving or self-discovery that employs a practical method that is not guaranteed to be optimal or perfect, but sufficient for immediate goals.', 'Pathfinding algorithms in video games employ distance heuristics to discover navigations rapidly.', 'Thuật toán tìm đường trong trò chơi điện tử sử dụng các hàm gần đúng khoảng cách để tìm đường đi nhanh chóng.', ARRAY['Rule of thumb', 'Approximation method']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-70', 'technology', 'Idempotent', '/ˌaɪ.dəmˈpoʊ.tənt/', 'Adj', 'C1', 'Có tính bất biến khi thực hiện lặp lại', 'Denoting an element or operation which can be applied multiple times without changing the result.', 'HTTP GET and DELETE requests are designed by specification to be strictly idempotent.', 'Các yêu cầu HTTP GET và DELETE được thiết kế theo quy chuẩn kỹ thuật là phải có tính bất biến tuyệt đối.', ARRAY['Repeat-invariant', 'Side-effect free']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-71', 'technology', 'Compiler', '/kəmˈpaɪ.lɚ/', 'Noun', 'B2', 'Trình biên dịch mã nguồn sang mã máy', 'A program that translates source code into machine language.', 'The C++ compiler optimizes machine instructions for maximum hardware speed.', 'Trình biên dịch C++ tối ưu hóa các lệnh mã máy để đạt tốc độ phần cứng tối đa.', ARRAY['Translator', 'Code builder']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-72', 'technology', 'Interpreter', '/ɪnˈtɝː.prə.t̬ɚ/', 'Noun', 'B2', 'Trình thông dịch chạy mã trực tiếp từng dòng', 'A computer program that directly executes instructions written in a programming or scripting language, without requiring them previously to have been compiled into a machine language program.', 'The Python interpreter evaluates code line by line at runtime.', 'Trình thông dịch Python thực thi mã nguồn từng dòng một trong thời gian chạy.', ARRAY['Runtime executor', 'Script parser']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-73', 'technology', 'Garbage Collection', '/ˈɡɑːr.bɪdʒ kəˌlek.ʃən/', 'Noun', 'B2', 'Cơ chế tự động thu gom dọn dẹp bộ nhớ rác', 'The automatic recovery of heap memory for the program by reclaiming objects that are no longer referenced.', 'Automatic garbage collection in C# prevents common fatal memory leaks.', 'Thu gom bộ nhớ rác tự động trong C# ngăn ngừa các lỗi rò rỉ bộ nhớ chết người phổ biến.', ARRAY['Memory reclamation', 'Heap cleanup']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-74', 'technology', 'Memory Leak', '/ˈmem.ɚ.i ˌliːk/', 'Noun', 'B2', 'Hiện tượng rò rỉ bộ nhớ RAM do không giải phóng', 'A failure in a program to release discarded memory, causing impaired performance or failure.', 'Unclosed database connections caused an insidious memory leak that crashed the server after two days.', 'Các kết nối cơ sở dữ liệu không đóng đã gây ra hiện tượng rò rỉ bộ nhớ âm thầm làm sập máy chủ sau 2 ngày.', ARRAY['Memory bleed', 'Resource exhaustion']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-75', 'technology', 'Deadlock', '/ˈded.lɑːk/', 'Noun', 'C1', 'Tình trạng bế tắc nghẽn tài nguyên giữa các luồng', 'A situation, typically one involving opposing parties, in which no progress can be made; in computing, when two processes each hold a resource the other needs.', 'Improper lock acquisition order resulted in a critical database transaction deadlock.', 'Thứ tự chiếm dụng khóa không chuẩn xác đã dẫn tới tình trạng bế tắc giao dịch cơ sở dữ liệu nghiêm trọng.', ARRAY['Impasse', 'Stalemate', 'Lockout']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-76', 'technology', 'Race Condition', '/ˈreɪs kənˌdɪʃ.ən/', 'Noun', 'C1', 'Xung đột tương tranh luồng khi cùng sửa tài nguyên', 'An undesirable situation that occurs when a device or system attempts to perform two or more operations at the same time, but because of the nature of the device or system, the operations must be done in the proper sequence to be done correctly.', 'Lack of mutex synchronization created a subtle race condition in bank balance updates.', 'Thiếu đồng bộ khóa loại trừ đã tạo ra xung đột tương tranh tinh vi trong việc cập nhật số dư ngân hàng.', ARRAY['Data race', 'Timing hazard']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-77', 'technology', 'Mutex', '/ˈmjuː.teks/', 'Noun', 'C1', 'Khóa loại trừ tương hỗ bảo vệ vùng nhớ chung', 'A program object that allows multiple program threads to share the same resource, such as file access, but not simultaneously.', 'Acquiring a mutex lock ensures exclusive access to the shared counter variable.', 'Chiếm dụng khóa loại trừ tương hỗ đảm bảo quyền truy cập độc quyền vào biến đếm dùng chung.', ARRAY['Mutual exclusion lock', 'Binary semaphore']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-78', 'technology', 'Semaphore', '/ˈsem.ə.fɔːr/', 'Noun', 'C1', 'Cơ chế đèn hiệu điều phối số lượng luồng truy cập', 'A variable or abstract data type used to control access to a common resource by multiple threads.', 'A counting semaphore limits simultaneous database connections to a maximum of twenty.', 'Đèn hiệu đếm giới hạn số lượng kết nối cơ sở dữ liệu đồng thời ở mức tối đa 20.', ARRAY['Signaling mechanism', 'Concurrency regulator']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-79', 'technology', 'Load Balancer', '/ˈloʊd ˌbæl.ən.sɚ/', 'Noun', 'B2', 'Bộ cân bằng tải phân phối lưu lượng truy cập', 'A device that acts as a reverse proxy and distributes network or application traffic across a number of servers.', 'The load balancer distributes incoming user requests evenly across ten web application instances.', 'Bộ cân bằng tải phân phối đều đặn các yêu cầu của người dùng tới 10 phiên bản ứng dụng web.', ARRAY['Traffic distributor', 'Reverse proxy']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-80', 'technology', 'Reverse Proxy', '/rɪˌvɝːs ˈprɑːk.si/', 'Noun', 'B2', 'Máy chủ ủy quyền ngược đứng trước bảo vệ backend', 'A type of proxy server that retrieves resources on behalf of a client from one or more servers.', 'Nginx is frequently deployed as a reverse proxy to handle SSL termination and static asset caching.', 'Nginx thường được triển khai làm máy chủ ủy quyền ngược để xử lý chứng chỉ SSL và bộ nhớ đệm tài nguyên tĩnh.', ARRAY['Front gateway', 'Edge proxy']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-81', 'technology', 'CDN', '/ˌsiː.diːˈen/', 'Noun', 'B2', 'Mạng phân phối nội dung đặt gần người dùng', 'Content Delivery Network: a geographically distributed network of proxy servers and their data centers.', 'Serving media assets via a global CDN drastically cuts webpage load times worldwide.', 'Phân phối hình ảnh và video qua mạng CDN toàn cầu giúp giảm đáng kể thời gian tải trang web trên khắp thế giới.', ARRAY['Edge network', 'Distributed cache']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-82', 'technology', 'Caching', '/ˈkæʃ.ɪŋ/', 'Noun', 'B2', 'Bộ nhớ đệm lưu tạm dữ liệu thường dùng', 'The process of storing copies of data in a cache memory location so that they can be accessed more quickly.', 'Redis in-memory caching stores hot session states for sub-millisecond retrieval.', 'Bộ nhớ đệm trong RAM Redis lưu trữ các phiên đăng nhập thường dùng để truy xuất dưới 1 mili-giây.', ARRAY['Temporary storage', 'Buffer storage']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-83', 'technology', 'Indexing', '/ˈɪn.dek.sɪŋ/', 'Noun', 'B2', 'Đánh chỉ mục tăng tốc độ tìm kiếm cơ sở dữ liệu', 'A data structure technique to quickly locate and access data in a database.', 'Adding a composite index on user email and status reduced lookup times from two seconds to three milliseconds.', 'Thêm chỉ mục tổng hợp trên email người dùng và trạng thái đã giảm thời gian tìm kiếm từ 2 giây xuống còn 3 mili-giây.', ARRAY['Index creation', 'Lookup cataloging']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-84', 'technology', 'Normalization', '/ˌnɔːr.mə.ləˈzeɪ.ʃən/', 'Noun', 'B2', 'Chuẩn hóa cơ sở dữ liệu để loại bỏ trùng lặp', 'The process of organizing data in a database to reduce data redundancy and improve data integrity.', 'Database normalization up to third normal form eliminates redundant customer address entries.', 'Chuẩn hóa cơ sở dữ liệu đến dạng chuẩn 3 loại bỏ các mục địa chỉ khách hàng bị trùng lặp.', ARRAY['Data structuring', 'Redundancy elimination']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-85', 'technology', 'Denormalization', '/diːˌnɔːr.mə.ləˈzeɪ.ʃən/', 'Noun', 'B2', 'Phi chuẩn hóa cơ sở dữ liệu để tăng tốc truy vấn đọc', 'The process of adding precomputed redundant data to an otherwise normalized relational database to improve read performance.', 'We used denormalization on the analytics dashboard tables to avoid massive thirty-table joins.', 'Chúng tôi đã sử dụng phi chuẩn hóa trên các bảng biểu đồ phân tích để tránh việc ghép 30 bảng khổng lồ.', ARRAY['Read optimization', 'Data duplication']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-86', 'technology', 'ACID', '/ˈæs.ɪd/', 'Noun', 'C1', 'Bốn tính chất bảo toàn giao dịch dữ liệu chuẩn', 'Atomicity, Consistency, Isolation, Durability: properties that guarantee database transactions are processed reliably.', 'PostgreSQL strictly adheres to ACID principles, making it ideal for financial transactions.', 'PostgreSQL tuân thủ nghiêm ngặt các nguyên tắc ACID, biến nó thành lựa chọn lý tưởng cho giao dịch tài chính.', ARRAY['Transaction guarantees', 'Database reliability']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-87', 'technology', 'Eventual Consistency', '/ɪˌven.tʃu.əl kənˈsɪs.tən.si/', 'Noun', 'C1', 'Tính nhất quán dữ liệu dần dần theo thời gian', 'A consistency model used in distributed computing to achieve high availability that guarantees, if no new updates are made to a given data item, eventually all accesses to that item will return the last updated value.', 'Distributed NoSQL databases trade immediate consistency for eventual consistency and massive scale.', 'Các cơ sở dữ liệu NoSQL phân tán đánh đổi tính nhất quán tức thì lấy tính nhất quán dần dần và quy mô khổng lồ.', ARRAY['Asynchronous consistency', 'Delayed synchronization']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-88', 'technology', 'CAP Theorem', '/ˌsiː.eɪˈpiː ˈθɪr.əm/', 'Noun', 'C1', 'Định lý CAP về giới hạn hệ thống phân tán', 'A theorem stating that a distributed data store can only provide two of the following three guarantees: Consistency, Availability, and Partition tolerance.', 'Under network partitioning, system designers must choose between data consistency or continuous availability.', 'Khi xảy ra chia cắt mạng, các nhà thiết kế hệ thống phải lựa chọn giữa tính nhất quán dữ liệu hoặc tính sẵn sàng liên tục.', ARRAY['Brewer''s theorem']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-89', 'technology', 'Websocket', '/ˈwebˌsɑː.kɪt/', 'Noun', 'B2', 'Giao thức truyền thông hai chiều thời gian thực', 'A computer communications protocol, providing full-duplex communication channels over a single TCP connection.', 'Real-time collaborative text editing relies on WebSockets for instant cursor synchronization.', 'Chỉnh sửa văn bản cộng tác thời gian thực dựa vào WebSocket để đồng bộ hóa con trỏ chuột tức thì.', ARRAY['Bidirectional socket', 'Real-time stream']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-90', 'technology', 'GraphQL', '/ˌɡræf.kjuːˈel/', 'Noun', 'B2', 'Ngôn ngữ truy vấn dữ liệu linh hoạt theo yêu cầu', 'An open-source data query and manipulation language for APIs, allowing clients to define the structure of data required.', 'GraphQL allows mobile applications to request exactly the fields they need, reducing over-fetching.', 'GraphQL cho phép các ứng dụng di động chỉ yêu cầu đúng các trường dữ liệu cần thiết, giảm lãng phí băng thông.', ARRAY['Query language', 'Flexible API']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-91', 'technology', 'Dependency Injection', '/dɪˌpen.dən.si ɪnˈdʒek.ʃən/', 'Noun', 'B2', 'Kỹ thuật tiêm phụ thuộc giúp mã lỏng lẻo dễ test', 'A software design pattern in which an object or function receives other objects or functions that it depends on.', 'ASP.NET Core provides built-in dependency injection for seamless database context resolution.', 'ASP.NET Core tích hợp sẵn kỹ thuật tiêm phụ thuộc giúp phân giải ngữ cảnh cơ sở dữ liệu một cách mượt mà.', ARRAY['DI', 'IoC pattern']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-92', 'technology', 'Inversion of Control', '/ɪnˌvɝː.ʒən əv kənˈtroʊl/', 'Noun', 'C1', 'Nguyên lý đảo ngược quyền điều khiển luồng chương trình', 'A design principle in which computer programs pass control of execution over to a container or framework.', 'The Spring framework uses inversion of control to manage enterprise Java application lifecycles.', 'Khung làm việc Spring áp dụng nguyên lý đảo ngược điều khiển để quản lý vòng đời ứng dụng Java doanh nghiệp.', ARRAY['IoC', 'Hollywood Principle']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-93', 'technology', 'Design Pattern', '/dɪˈzaɪn ˌpæt̬.ɚn/', 'Noun', 'B2', 'Mẫu thiết kế phần mềm chuẩn mực đã được kiểm nghiệm', 'A general repeatable solution to a commonly occurring problem in software design.', 'The Factory pattern is a popular creational design pattern for instantiating complex objects.', 'Mẫu Factory là một mẫu thiết kế khởi tạo phổ biến để khởi tạo các đối tượng phức tạp.', ARRAY['Software template', 'Architectural pattern']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-94', 'technology', 'Singleton', '/ˈsɪŋ.ɡəl.tən/', 'Noun', 'B2', 'Mẫu thiết kế chỉ tạo duy nhất một thực thể', 'A software design pattern that restricts the instantiation of a class to one single instance.', 'The logging service was implemented as a singleton to centralize log output across the application.', 'Dịch vụ ghi nhật ký được triển khai theo mẫu Singleton để tập trung hóa đầu ra nhật ký trên toàn ứng dụng.', ARRAY['Single instance', 'Global instance']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-95', 'technology', 'Observer Pattern', '/əbˈzɝː.vɚ ˌpæt̬.ɚn/', 'Noun', 'B2', 'Mẫu thiết kế quan sát và thông báo sự kiện', 'A software design pattern in which an object maintains a list of dependents and notifies them automatically of any state changes.', 'Event-driven UI frameworks use the observer pattern to update reactive view components.', 'Các khung làm việc giao diện hướng sự kiện sử dụng mẫu quan sát để cập nhật các thành phần hiển thị phản ứng.', ARRAY['Pub-sub pattern', 'Event listener pattern']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-96', 'technology', 'Middleware', '/ˈmɪd.əl.wer/', 'Noun', 'B2', 'Phần mềm trung gian xử lý yêu cầu trước khi vào ứng dụng', 'Software that provides common services and capabilities to applications outside of what''s offered by the operating system.', 'Authentication middleware validates JWT tokens before forwarding the request to the controller.', 'Phần mềm trung gian xác thực kiểm tra mã định danh JWT trước khi chuyển tiếp yêu cầu đến bộ điều khiển.', ARRAY['Intermediary software', 'Pipeline handler']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-97', 'technology', 'Cross-Origin', '/ˌkrɑːs ˈɔːr.ə.dʒɪn/', 'Noun', 'B2', 'Yêu cầu chia sẻ tài nguyên giữa các tên miền khác nhau (CORS)', 'The ability to request resources from a domain different from the domain that served the first resource.', 'Configure CORS policies carefully to allow trusted frontend applications to call your APIs.', 'Cấu hình chính sách CORS cẩn thận để cho phép các ứng dụng giao diện đáng tin cậy gọi các API của bạn.', ARRAY['CORS', 'Inter-domain sharing']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-98', 'technology', 'Sanitization', '/ˌsæn.ə.t̬əˈzeɪ.ʃən/', 'Noun', 'B2', 'Làm sạch dữ liệu đầu vào để chống tấn công', 'The process of cleaning data to prevent malicious input from compromising software security.', 'Input sanitization prevents SQL injection and cross-site scripting vulnerabilities.', 'Làm sạch dữ liệu đầu vào ngăn chặn các lỗ hổng tiêm mã SQL và tấn công kịch bản liên trang web.', ARRAY['Input cleaning', 'Data purification']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-99', 'technology', 'SQL Injection', '/ˌes.kjuːˈel ɪnˈdʒek.ʃən/', 'Noun', 'B2', 'Tấn công tiêm câu lệnh SQL độc hại vào cơ sở dữ liệu', 'A code injection technique used to attack data-driven applications by inserting malicious SQL statements.', 'Parameterized queries effectively eradicate SQL injection attack vectors.', 'Các truy vấn tham số hóa loại bỏ triệt để các véc-tơ tấn công tiêm mã SQL.', ARRAY['SQLi', 'Query tampering']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('tech-100', 'technology', 'Cross-Site Scripting', '/ˌkrɑːs saɪt ˈskrɪp.tɪŋ/', 'Noun', 'B2', 'Tấn công chèn mã JavaScript độc hại vào trang web (XSS)', 'A type of security vulnerability typically found in web applications that enables attackers to inject client-side scripts.', 'Escaping dynamic HTML output shields your users from stored cross-site scripting exploits.', 'Mã hóa ký tự thoát đầu ra HTML động bảo vệ người dùng của bạn khỏi các mã khai thác XSS lưu trữ.', ARRAY['XSS', 'Script injection']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('travel-1', 'travel', 'Itinerary', '/aɪˈtɪn.ə.rer.i/', 'Noun', 'B2', 'Lịch trình chuyến đi chi tiết theo từng ngày', 'A planned route or journey with scheduled dates and times.', 'Review the travel itinerary carefully to ensure you don''t miss the connecting flight.', 'Hãy xem lại lịch trình chuyến đi cẩn thận để đảm bảo bạn không lỡ chuyến bay nối chuyến.', ARRAY['Schedule', 'Travel plan', 'Route map']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('travel-2', 'travel', 'Embark', '/ɪmˈbɑːrk/', 'Verb', 'C1', 'Lên tàu, máy bay hoặc bắt đầu hành trình mới', 'Go on board a ship, aircraft, or other vehicle; begin a course of action.', 'Passengers for flight VN-302 may now embark through gate seven.', 'Hành khách trên chuyến bay VN-302 hiện có thể lên máy bay qua cửa số bảy.', ARRAY['Board', 'Set out', 'Commence']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('travel-3', 'travel', 'Accommodation', '/əˌkɑː.məˈdeɪ.ʃən/', 'Noun', 'B1', 'Phòng nghỉ lưu trú, chỗ ở khách sạn', 'A room, group of rooms, or building in which someone may live or stay.', 'The seaside boutique hotel provides luxurious accommodation with panoramic sea views.', 'Khách sạn phong cách bên bờ biển cung cấp chỗ nghỉ dưỡng sang trọng với tầm nhìn toàn cảnh ra biển.', ARRAY['Lodging', 'Housing', 'Rooms']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('travel-4', 'travel', 'Customs', '/ˈkʌs.təmz/', 'Noun', 'B1', 'Cơ quan hải quan kiểm soát biên giới', 'The official department that administers and collects the duties levied by a government on imported goods.', 'Declare all foreign agricultural produce upon arriving at international customs.', 'Hãy khai báo tất cả nông sản nước ngoài khi làm thủ tục tại hải quan quốc tế.', ARRAY['Border control', 'Port authority', 'Immigration']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('travel-5', 'travel', 'Breathtaking', '/ˈbreθˌteɪ.kɪŋ/', 'Adj', 'B2', 'Đẹp ngỡ ngàng, ngoạn mục choáng ngợp', 'Astonishing or awe-inspiring in quality, beauty, or grandeur.', 'Watching the golden sunrise over Ha Long Bay is a breathtaking experience.', 'Ngắm bình minh vàng rực trên Vịnh Hạ Long là một trải nghiệm đẹp đến ngỡ ngàng.', ARRAY['Spectacular', 'Awe-inspiring', 'Magnificent']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('travel-6', 'travel', 'Hospitality', '/ˌhɑː.spɪˈtæl.ə.t̬i/', 'Noun', 'B2', 'Lòng hiếu khách nồng hậu', 'The friendly and generous reception and entertainment of guests, visitors, or strangers.', 'The warm hospitality of the local homestay family made us feel right at home.', 'Lòng hiếu khách ấm áp của gia đình chủ nhà homestay địa phương khiến chúng tôi cảm thấy như ở nhà.', ARRAY['Warmth', 'Friendliness', 'Welcoming attitude']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('travel-7', 'travel', 'Excursion', '/ɪkˈskɝː.ʒən/', 'Noun', 'B2', 'Chuyến dã ngoại tham quan ngắn ngày', 'A short journey or trip, especially one engaged in as a leisure activity.', 'The resort organizes a daily scuba diving excursion to nearby coral reefs.', 'Khu nghỉ dưỡng tổ chức một chuyến tham quan lặn biển hàng ngày tới các rạn san hô gần đó.', ARRAY['Outing', 'Jaunt', 'Day trip']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('travel-8', 'travel', 'Layover', '/ˈleɪˌoʊ.vɚ/', 'Noun', 'B1', 'Khoảng thời gian quá cảnh chờ chuyến bay tiếp theo', 'A period of rest or waiting before a further stage in a journey.', 'We had a comfortable six-hour layover in Singapore Changi Airport.', 'Chúng tôi đã có 6 tiếng quá cảnh dễ chịu tại Sân bay Changi Singapore.', ARRAY['Stopover', 'Transit break', 'Pause']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('travel-9', 'travel', 'Souvenir', '/ˌsuː.vəˈnɪr/', 'Noun', 'A2', 'Món quà lưu niệm kỷ niệm chuyến đi', 'A thing that is kept as a reminder of a person, place, or event.', 'She purchased handmade ceramic tea cups as souvenirs from the pottery village.', 'Cô ấy đã mua những chiếc chén trà gốm thủ công làm quà lưu niệm từ làng gốm.', ARRAY['Keepsake', 'Memento', 'Token']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('travel-10', 'travel', 'Picturesque', '/ˌpɪk.tʃəˈresk/', 'Adj', 'B2', 'Đẹp như tranh vẽ, thơ mộng', 'Visually attractive, especially in a quaint or pretty style.', 'The ancient town of Hoi An is famous for its picturesque lantern-lit streets.', 'Phố cổ Hội An nổi tiếng với những con phố thắp đèn lồng đẹp như tranh vẽ.', ARRAY['Scenic', 'Charming', 'Quaint']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('travel-11', 'travel', 'Jet Lag', '/ˈdʒet ˌlæɡ/', 'Noun', 'B1', 'Sự mệt mỏi do lệch múi giờ sau chuyến bay dài', 'Extreme tiredness and other physical effects felt by a person after a long flight across different time zones.', 'Drinking plenty of water and getting sunlight helps overcome jet lag faster.', 'Uống nhiều nước và tắm nắng giúp nhanh chóng vượt qua cảm giác mệt mỏi do lệch múi giờ.', ARRAY['Time zone fatigue', 'Circadian desynchrony']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('travel-12', 'travel', 'Expedition', '/ˌek.spəˈdɪʃ.ən/', 'Noun', 'B2', 'Chuyến thám hiểm khoa học hoặc khám phá', 'A journey undertaken by a group of people with a particular purpose, especially that of exploration, scientific research, or war.', 'The team launched an ambitious climbing expedition to conquer the Himalayan peak.', 'Đội ngũ đã khởi động một chuyến leo núi thám hiểm đầy tham vọng nhằm chinh phục đỉnh Himalaya.', ARRAY['Exploration', 'Voyage', 'Trek']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('travel-13', 'travel', 'Wanderlust', '/ˈwɑːn.dɚ.lʌst/', 'Noun', 'C1', 'Niềm đam mê xê dịch, khao khát đi du lịch khắp chốn', 'A strong desire to travel.', 'Her insatiable wanderlust drove her to backpack through forty different nations in three years.', 'Niềm đam mê xê dịch không ngừng thôi thúc cô ấy vác ba lô đi qua 40 quốc gia khác nhau trong 3 năm.', ARRAY['Passion for travel', 'Restlessness']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('travel-14', 'travel', 'Boarding Pass', '/ˈbɔːr.dɪŋ ˌpæs/', 'Noun', 'A2', 'Thẻ lên máy bay qua cổng an ninh', 'A pass for boarding an aircraft, given to passengers when checking in.', 'Keep your boarding pass and national passport handy at the departure gate.', 'Hãy luôn cầm sẵn thẻ lên máy bay và hộ chiếu quốc gia tại cửa khởi hành.', ARRAY['Flight ticket', 'Boarding card']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('travel-15', 'travel', 'Luggage Allowance', '/ˈlʌɡ.ɪdʒ əˌlaʊ.əns/', 'Noun', 'B1', 'Hạn mức hành lý ký gửi cho phép', 'The maximum amount of baggage a passenger is allowed to carry without paying extra.', 'The budget airline offers a standard checked luggage allowance of twenty kilograms.', 'Hãng hàng không giá rẻ cung cấp hạn mức hành lý ký gửi tiêu chuẩn là 20 kg.', ARRAY['Baggage limit', 'Weight allowance']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('travel-16', 'travel', 'Transit', '/ˈtræn.zɪt/', 'Noun', 'B1', 'Sự quá cảnh chuyển tiếp qua một quốc gia', 'The action of passing through or across a place on the way to somewhere else.', 'Passengers traveling in transit through Tokyo do not require a tourist entry visa.', 'Hành khách quá cảnh qua Tokyo không cần phải xin thị thực du lịch nhập cảnh.', ARRAY['Passage', 'Transfer', 'Crossing']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('travel-17', 'travel', 'Immigration', '/ˌɪm.əˈɡreɪ.ʃən/', 'Noun', 'B1', 'Cửa khẩu nhập cảnh, kiểm tra hộ chiếu', 'The place at an airport or border where travelers'' passports and visas are checked.', 'Queue patiently in the non-resident lane when proceeding through passport immigration.', 'Hãy kiên nhẫn xếp hàng tại làn dành cho người không cư trú khi làm thủ tục nhập cảnh.', ARRAY['Passport control', 'Border inspection']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('travel-18', 'travel', 'Pristine', '/ˈprɪs.tiːn/', 'Adj', 'C1', 'Nguyên sơ, thuần khiết chưa bị con người tàn phá', 'In its original condition; unspoiled.', 'The tropical island is renowned for its pristine white sand beaches and crystal waters.', 'Hòn đảo nhiệt đới nổi tiếng với những bãi cát trắng nguyên sơ và làn nước trong vắt.', ARRAY['Unspoiled', 'Pure', 'Untouched']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('travel-19', 'travel', 'Sightseeing', '/ˈsaɪtˌsiː.ɪŋ/', 'Noun', 'A2', 'Hoạt động ngắm cảnh tham quan các danh thắng', 'The activity of visiting places of interest in a particular location by tourists.', 'We took a double-decker open-top bus for an afternoon of historical sightseeing.', 'Chúng tôi đã đi xe buýt hai tầng mui trần cho một buổi chiều tham quan các di tích lịch sử.', ARRAY['Touring', 'Excursions', 'Exploration']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('travel-20', 'travel', 'Ecotourism', '/ˈiː.koʊˌtʊr.ɪ.zəm/', 'Noun', 'B2', 'Du lịch sinh thái bảo vệ môi trường', 'Tourism directed toward exotic, often threatened, natural environments, intended to support conservation efforts.', 'Ecotourism generates vital funds to preserve natural national parks and endangered flora.', 'Du lịch sinh thái tạo ra nguồn kinh phí thiết yếu để bảo tồn các vườn quốc gia và thảm thực vật quý hiếm.', ARRAY['Green travel', 'Sustainable tourism']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('travel-21', 'travel', 'Scenic', '/ˈsiː.nɪk/', 'Adj', 'B1', 'Cảnh quan thiên nhiên tươi đẹp ngoạn mục', 'Providing or relating to views of impressive or beautiful natural scenery.', 'The train ride from Da Nang to Hue offers spectacular scenic views of Lang Co Bay.', 'Chuyến tàu từ Đà Nẵng ra Huế mang lại những khung cảnh thiên nhiên ngoạn mục nhìn ra vịnh Lăng Cô.', ARRAY['Picturesque', 'Panoramic', 'Breathtaking']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('travel-22', 'travel', 'Local Cuisine', '/ˈloʊ.kəl kwɪˈziːn/', 'Noun', 'B1', 'Ẩm thực địa phương đặc sản vùng miền', 'The style or method of cooking characteristic of a particular locality.', 'Tasting authentic local cuisine is an indispensable part of visiting Hanoi''s Old Quarter.', 'Thưởng thức ẩm thực địa phương đích thực là phần không thể thiếu khi ghé thăm Phố cổ Hà Nội.', ARRAY['Regional food', 'Traditional culinary']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('travel-23', 'travel', 'Heritage', '/ˈher.ɪ.t̬ɪdʒ/', 'Noun', 'B2', 'Di sản văn hóa hoặc thiên nhiên thế giới', 'Property that is or may be inherited; an inheritance; valued objects and qualities such as historic buildings.', 'The imperial citadel was recognized by UNESCO as a World Cultural Heritage site.', 'Hoàng thành đã được UNESCO công nhận là di sản văn hóa thế giới.', ARRAY['Legacy', 'Inheritance', 'Tradition']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('travel-24', 'travel', 'Backpacker', '/ˈbækˌpæk.ɚ/', 'Noun', 'B1', 'Khách du lịch bụi, đi phượt', 'A person who travels or hikes carrying their belongings in a rucksack.', 'The hostel provides cheap dormitory bunk beds favored by international backpackers.', 'Ký túc xá cung cấp giường tầng giá rẻ được giới du lịch bụi quốc tế ưa chuộng.', ARRAY['Trekker', 'Hiker', 'Budget traveler']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('travel-25', 'travel', 'Resort', '/rɪˈzɔːrt/', 'Noun', 'A2', 'Khu nghỉ dưỡng phức hợp cao cấp', 'A place that is a popular destination for vacations or recreation.', 'The five-star beach resort features three infinity swimming pools and private beachfront villas.', 'Khu nghỉ dưỡng 5 sao ven biển sở hữu 3 hồ bơi vô cực và các biệt thự riêng trước biển.', ARRAY['Holiday retreat', 'Spa hotel', 'Vacation complex']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('travel-26', 'travel', 'Concierge', '/koʊn.siˈerʒ/', 'Noun', 'B2', 'Nhân viên hỗ trợ hướng dẫn thông tin khách sạn', 'A hotel employee whose job is to assist guests by booking tours, making reservations, etc.', 'The concierge kindly booked our opera tickets and arranged private chauffeur transport.', 'Nhân viên hướng dẫn khách sạn đã nhiệt tình đặt vé xem nhạc kịch và sắp xếp xe riêng đưa đón.', ARRAY['Guest assistant', 'Hotel host']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('travel-27', 'travel', 'Charter Flight', '/ˈtʃɑːr.t̬ɚ ˌflaɪt/', 'Noun', 'B2', 'Chuyến bay thuê bao nguyên chuyến', 'A flight by an aircraft chartered for a specific journey, not part of an airline''s regular schedule.', 'Tour operators organized charter flights to transport football fans directly to the final match.', 'Các công ty lữ hành đã tổ chức những chuyến bay thuê bao đưa người hâm mộ bóng đá tới xem trận chung kết.', ARRAY['Private flight', 'Special flight']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('travel-28', 'travel', 'Baggage Claim', '/ˈbæɡ.ɪdʒ ˌkleɪm/', 'Noun', 'A2', 'Khu vực băng chuyền nhận lại hành lý', 'The area in an airport where arriving passengers collect luggage that has been carried in the hold.', 'Proceed straight to baggage claim carousels after passing health inspection.', 'Hãy đi thẳng tới khu vực băng chuyền hành lý sau khi hoàn tất kiểm tra y tế.', ARRAY['Luggage collection', 'Baggage hall']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('travel-29', 'travel', 'Check-In', '/ˈtʃek.ɪn/', 'Noun', 'A2', 'Thủ tục nhận phòng hoặc đăng ký chuyến bay', 'The act of reporting one''s arrival at an airport or hotel.', 'Online check-in opens twenty-four hours before scheduled aircraft departure.', 'Thủ tục nhận chỗ trực tuyến mở trước 24 giờ so với giờ khởi hành dự kiến của máy bay.', ARRAY['Registration', 'Arrival sign-in']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('travel-30', 'travel', 'Check-Out', '/ˈtʃek.aʊt/', 'Noun', 'A2', 'Thủ tục trả phòng khách sạn thanh toán', 'The act of leaving and paying for one''s stay at a hotel.', 'Hotel check-out time is strictly twelve noon unless a late departure is confirmed.', 'Giờ trả phòng khách sạn là 12 giờ trưa trừ khi đã được xác nhận trả phòng muộn.', ARRAY['Departure settlement', 'Room handover']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('travel-31', 'travel', 'Destination', '/ˌdes.təˈneɪ.ʃən/', 'Noun', 'A2', 'Điểm đến của chuyến đi', 'The place to which someone or something is going or being sent.', 'Da Nang is consistently voted the most attractive coastal destination in central Vietnam.', 'Đà Nẵng liên tục được bình chọn là điểm đến ven biển hấp dẫn nhất miền Trung Việt Nam.', ARRAY['Target location', 'Terminus']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('travel-32', 'travel', 'Voyage', '/ˈvɔɪ.ɪdʒ/', 'Noun', 'B2', 'Chuyến hải trình dài ngày vượt đại dương', 'A long journey involving travel by sea or in space.', 'The historical oceanic voyage took four months across stormy Pacific waters.', 'Chuyến hải trình lịch sử mất 4 tháng vượt qua những vùng biển Thái Bình Dương giông bão.', ARRAY['Cruise', 'Journey', 'Sea trek']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('travel-33', 'travel', 'Landmark', '/ˈlænd.mɑːrk/', 'Noun', 'B1', 'Địa danh danh lam nổi tiếng nhận diện vùng đất', 'An object or feature of a landscape or town that is easily seen and recognized from a distance.', 'The Eiffel Tower is the most iconic architectural landmark in Paris.', 'Tháp Eiffel là địa danh kiến trúc mang tính biểu tượng nhất tại Paris.', ARRAY['Monuments', 'Iconic site', 'Beacon']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('travel-34', 'travel', 'Commute', '/kəˈmjuːt/', 'Verb', 'B1', 'Di chuyển đi làm hàng ngày giữa nhà và cơ quan', 'Travel some distance between one''s home and place of work on a regular basis.', 'Thousands of professionals commute into central London by underground train every day.', 'Hàng ngàn nhân viên văn phòng đi lại vào trung tâm London bằng tàu điện ngầm mỗi ngày.', ARRAY['Travel to work', 'Daily journey']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('travel-35', 'travel', 'Cruise', '/kruːz/', 'Noun', 'B1', 'Kỳ nghỉ trên du thuyền xa hoa', 'A voyage on a ship or boat taken for pleasure, typically calling in at several places.', 'They booked a luxury Mediterranean cruise for their twentieth wedding anniversary.', 'Họ đã đặt một chuyến du thuyền Địa Trung Hải xa hoa cho kỷ niệm 20 năm ngày cưới.', ARRAY['Luxury voyage', 'Sea tour']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('travel-36', 'travel', 'Overbook', '/ˌoʊ.vɚˈbʊk/', 'Verb', 'B2', 'Bán vé quá số lượng chỗ thực tế', 'Accept more reservations than there is room for.', 'Airlines routinely overbook flights anticipating that some ticket holders will cancel.', 'Các hãng hàng không thường xuyên bán quá số ghế vì dự trù một số hành khách sẽ hủy vé.', ARRAY['Sell surplus seats', 'Excess booking']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('travel-37', 'travel', 'Terminal', '/ˈtɝː.mə.nəl/', 'Noun', 'B1', 'Nhà ga sân bay hoặc bến cảng', 'A building at an airport where passengers transfer between ground transportation and the aircraft.', 'International departures leave exclusively from Terminal 2 of the airport.', 'Các chuyến bay quốc tế khởi hành độc quyền từ Nhà ga số 2 của sân bay.', ARRAY['Airport building', 'Concourse']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('travel-38', 'travel', 'Carry-on', '/ˈker.i.ɑːn/', 'Noun', 'B1', 'Hành lý xách tay mang lên khoang máy bay', 'A piece of baggage suitable for being taken aboard an aircraft by a passenger.', 'Make sure your carry-on bag fits into the overhead luggage bin dimensions.', 'Hãy đảm bảo túi hành lý xách tay của bạn vừa vặn với kích thước ngăn để đồ trên đầu.', ARRAY['Hand luggage', 'Cabin baggage']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('travel-39', 'travel', 'Turbulence', '/ˈtɝː.bjə.ləns/', 'Noun', 'B2', 'Sự rung lắc bất ngờ do luồng không khí', 'Violent or unsteady movement of air or water, or of some other fluid.', 'Passengers were instructed to fasten their seatbelts due to sudden atmospheric turbulence.', 'Hành khách được yêu cầu thắt dây an toàn do luồng không khí bất ngờ gây rung lắc mạnh.', ARRAY['Rough air', 'Buffeting', 'Shaking']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('travel-40', 'travel', 'Runway', '/ˈrʌn.weɪ/', 'Noun', 'B1', 'Đường băng cất hạ cánh của sân bay', 'A leveled strip of smooth ground along which aircraft take off and land.', 'The heavy cargo plane touched down smoothly on the damp airport runway.', 'Chiếc máy bay chở hàng hạng nặng đã hạ cánh êm ái trên đường băng ẩm ướt của sân bay.', ARRAY['Airstrip', 'Landing strip']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('travel-41', 'travel', 'Delayed', '/dɪˈleɪd/', 'Adj', 'A2', 'Bị hoãn chuyến, trễ giờ bay', 'Late; slow; postponed.', 'Our flight was unfortunately delayed by two hours due to dense coastal fog.', 'Chuyến bay của chúng tôi không may bị hoãn hai tiếng do sương mù ven biển dày đặc.', ARRAY['Postponed', 'Late', 'Held up']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('travel-42', 'travel', 'Cancelled', '/ˈkæn.səld/', 'Adj', 'A2', 'Bị hủy chuyến hoàn toàn', 'Decided that an organized event will not happen.', 'All morning flights were cancelled following the tropical typhoon warning.', 'Toàn bộ các chuyến bay buổi sáng đã bị hủy bỏ sau lời cảnh báo bão nhiệt đới.', ARRAY['Called off', 'Aborted']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('travel-43', 'travel', 'Visa', '/ˈviː.zə/', 'Noun', 'A2', 'Thị thực nhập cảnh hợp pháp', 'An endorsement on a passport indicating that the holder is allowed to enter, leave, or stay for a specified period of time in a country.', 'Ensure you apply for an electronic tourist visa at least two weeks before your departure date.', 'Hãy nhớ nộp đơn xin thị thực du lịch điện tử ít nhất hai tuần trước ngày khởi hành của bạn.', ARRAY['Entry permit', 'Travel authorization']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('travel-44', 'travel', 'Passport', '/ˈpæs.pɔːrt/', 'Noun', 'A2', 'Hộ chiếu xuất nhập cảnh quốc tế', 'An official document issued by a government, certifying the holder''s identity and citizenship and entitling them to travel under its protection to and from foreign countries.', 'A valid passport with at least six months of validity is required for international travel.', 'Hộ chiếu hợp lệ còn hạn ít nhất sáu tháng là yêu cầu bắt buộc khi đi du lịch quốc tế.', ARRAY['Travel document', 'Identification passport']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('travel-45', 'travel', 'Boarding', '/ˈbɔːr.dɪŋ/', 'Noun', 'A2', 'Thời điểm lên máy bay chuẩn bị khởi hành', 'The action of getting on or into a ship, aircraft, train, or other vehicle.', 'Final boarding for Singapore Airlines flight SQ-180 will commence in five minutes.', 'Lượt lên máy bay cuối cùng của chuyến bay Singapore Airlines SQ-180 sẽ bắt đầu trong 5 phút nữa.', ARRAY['Embarkation', 'Gate loading']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('travel-46', 'travel', 'Upgrade', '/ʌpˈɡreɪd/', 'Verb', 'B1', 'Nâng hạng vé hoặc phòng cao cấp hơn', 'Raise something to a higher standard, in particular improve by adding or replacing components.', 'Loyal frequent flyers were pleasantly surprised with a complimentary upgrade to business class.', 'Những hành khách bay thường xuyên trung thành đã ngạc nhiên vui mừng khi được nâng hạng miễn phí lên vé thương gia.', ARRAY['Promote', 'Elevate', 'Improve']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('travel-47', 'travel', 'Downgrade', '/ˈdaʊn.ɡreɪd/', 'Verb', 'B2', 'Hạ cấp vé hoặc phòng do thiếu chỗ', 'Reduce to a lower grade, rank, or level of importance.', 'Due to aircraft re-routing, a few passengers were reluctantly downgraded to economy seating.', 'Do việc thay đổi lịch trình máy bay, một số hành khách đã phải miễn cưỡng bị hạ hạng ghế xuống phổ thông.', ARRAY['Demote', 'Reduce class']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('travel-48', 'travel', 'Duty-Free', '/ˌduː.t̬iˈfriː/', 'Adj', 'B1', 'Cửa hàng miễn thuế sân bay', 'Goods exempt from payment of certain local or national taxes and duties.', 'Travelers frequently purchase perfumes and chocolates at airport duty-free shops.', 'Du khách thường mua nước hoa và sô-cô-la tại các cửa hàng miễn thuế ở sân bay.', ARRAY['Tax-free', 'Excise-exempt']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('travel-49', 'travel', 'Exchange Rate', '/ɪksˈtʃeɪndʒ ˌreɪt/', 'Noun', 'B1', 'Tỷ giá hối đoái đổi ngoại tệ', 'The value of one currency for the purpose of conversion to another.', 'Compare foreign exchange rates at local city banks before converting large sums of cash.', 'Hãy so sánh tỷ giá hối đoái tại các ngân hàng trong thành phố trước khi đổi số tiền mặt lớn.', ARRAY['Conversion rate', 'Forex rate']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('travel-50', 'travel', 'Currency', '/ˈkɝː.ən.si/', 'Noun', 'B1', 'Đơn vị tiền tệ của một quốc gia', 'A system of money in common use, especially for people in a nation.', 'The official national currency of Vietnam is the Dong, symbolized as VND.', 'Đơn vị tiền tệ chính thức của Việt Nam là Đồng, ký hiệu là VND.', ARRAY['Money', 'Legal tender', 'Coinage']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('travel-51', 'travel', 'Guidebook', '/ˈɡaɪd.bʊk/', 'Noun', 'A2', 'Sách cẩm nang du lịch chỉ dẫn', 'A book of information about a place designed for the use of visitors or tourists.', 'The Lonely Planet guidebook contains excellent recommendations for off-the-beaten-path eateries.', 'Cuốn sách hướng dẫn Lonely Planet chứa đựng nhiều gợi ý tuyệt vời cho các quán ăn độc lạ ngoài các cung đường quen thuộc.', ARRAY['Travel manual', 'Tour guide']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('travel-52', 'travel', 'Local', '/ˈloʊ.kəl/', 'Noun', 'A2', 'Người dân bản địa sinh sống tại địa phương', 'An inhabitant of a particular area or neighborhood.', 'Ask a friendly local for directions if you find yourself wandering through confusing alleys.', 'Hãy hỏi một người dân địa phương thân thiện chỉ đường nếu bạn thấy mình đang lạc giữa những con hẻm rắc rối.', ARRAY['Native', 'Resident', 'Inhabitant']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('travel-53', 'travel', 'Bilingual', '/baɪˈlɪŋ.ɡwəl/', 'Adj', 'B1', 'Sử dụng song ngữ thành thạo', 'Speaking two languages fluently.', 'The historic museum provides bilingual audio headsets in both Vietnamese and English.', 'Bảo tàng lịch sử cung cấp tai nghe thuyết minh song ngữ bằng cả tiếng Việt và tiếng Anh.', ARRAY['Dual-language', 'Two-tongued']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('travel-54', 'travel', 'Souvenir Shop', '/ˌsuː.vəˈnɪr ˌʃɑːp/', 'Noun', 'A2', 'Cửa hàng bán đồ lưu niệm', 'A shop selling souvenirs and small memorabilia to travelers.', 'The souvenir shop on the corner sells colorful handmade silk lanterns.', 'Cửa hàng lưu niệm ở góc phố bày bán những chiếc đèn lồng lụa thủ công rực rỡ sắc màu.', ARRAY['Gift shop', 'Curio shop']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('travel-55', 'travel', 'High Season', '/ˈhaɪ ˌsiː.zən/', 'Noun', 'B1', 'Mùa du lịch cao điểm đông đúc', 'The time of year when travel and tourism is at its peak and prices are highest.', 'Hotel room rates surge substantially during the sunny summer high season.', 'Giá phòng khách sạn tăng vọt đáng kể trong suốt mùa hè cao điểm ngập tràn ánh nắng.', ARRAY['Peak season', 'Busy period']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('travel-56', 'travel', 'Off-Peak', '/ˌɑːfˈpiːk/', 'Adj', 'B1', 'Mùa thấp điểm vắng khách giá rẻ', 'At a time other than that when business or traffic is at its highest.', 'Traveling during off-peak autumn months saves money and avoids overwhelming tourist crowds.', 'Đi du lịch vào những tháng mùa thu thấp điểm vừa tiết kiệm tiền vừa tránh được đám đông du khách quá tải.', ARRAY['Low season', 'Quiet period']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('travel-57', 'travel', 'Hospitality Industry', '/ˌhɑː.spɪˈtæl.ə.t̬i ˌɪn.dəs.tri/', 'Noun', 'B2', 'Ngành công nghiệp khách sạn và dịch vụ lưu trú', 'A broad category of fields within the service industry that includes lodging, food and drink service, event planning, and theme parks.', 'The booming hospitality industry creates millions of flexible jobs in coastal resort towns.', 'Ngành dịch vụ khách sạn bùng nổ tạo ra hàng triệu việc làm linh hoạt tại các thành phố nghỉ dưỡng ven biển.', ARRAY['Tourism sector', 'Hotel industry']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('travel-58', 'travel', 'Room Service', '/ˈruːm ˌsɝː.vɪs/', 'Noun', 'A2', 'Dịch vụ phục vụ bữa ăn tận phòng khách sạn', 'A service provided in a hotel allowing guests to order food and drink to their rooms.', 'After a grueling 14-hour flight, we simply ordered late-night room service.', 'Sau chuyến bay dài 14 tiếng kiệt sức, chúng tôi chỉ đơn giản gọi dịch vụ ăn uống tận phòng đêm muộn.', ARRAY['In-room dining', 'Hotel catering']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('travel-59', 'travel', 'Complimentary', '/ˌkɑːm.pləˈmen.t̬ɚ.i/', 'Adj', 'B2', 'Miễn phí đính kèm dịch vụ', 'Given or supplied free of charge.', 'The hotel provides a complimentary hot breakfast buffet and fresh bottled water daily.', 'Khách sạn cung cấp tiệc buffet sáng nóng sốt và nước đóng chai tươi mới miễn phí mỗi ngày.', ARRAY['Free', 'Gratis', 'Courtesy']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('travel-60', 'travel', 'Suite', '/swiːt/', 'Noun', 'B1', 'Phòng khách sạn cao cấp hạng sang', 'A set of rooms designated for one person''s or family''s use or for a particular purpose.', 'The newlyweds celebrated their honeymoon in the presidential sea-view suite.', 'Cặp đôi mới cưới đã kỷ niệm tuần trăng mật trong căn phòng tổng thống hạng sang nhìn ra biển.', ARRAY['Luxury apartment', 'Deluxe quarters']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('travel-61', 'travel', 'Hostel', '/ˈhɑː.stəl/', 'Noun', 'A2', 'Nhà nghỉ tập thể giá rẻ cho giới trẻ', 'An establishment which provides inexpensive food and lodging for a specific group of people, such as students or workers.', 'The youth hostel has a communal kitchen where travelers can cook together.', 'Nhà nghỉ thanh niên có một nhà bếp chung nơi du khách có thể cùng nhau nấu ăn.', ARRAY['Dormitory', 'Bunkhouse']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('travel-62', 'travel', 'Homestay', '/ˈhoʊm.steɪ/', 'Noun', 'A2', 'Dịch vụ lưu trú tại nhà người dân địa phương', 'A holiday or other period spent staying in the home of a local family.', 'Booking a rural homestay in Sapa offers an intimate glimpse into ethnic traditions.', 'Đặt phòng homestay tại làng quê Sa Pa mang lại cái nhìn sâu sắc và gần gũi về truyền thống dân tộc.', ARRAY['Family stay', 'Village lodging']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('travel-63', 'travel', 'Infinity Pool', '/ɪnˈfɪn.ə.t̬i ˌpuːl/', 'Noun', 'B1', 'Hồ bơi vô cực nhìn ra chân trời', 'A swimming pool whose water flows over one or more edges, producing a visual effect of water with no boundary.', 'The rooftop infinity pool looks out across the gleaming city skyline.', 'Hồ bơi vô cực trên tầng thượng nhìn ra toàn cảnh đường chân trời rực rỡ của thành phố.', ARRAY['Edge pool', 'Horizon pool']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('travel-64', 'travel', 'Panoramic', '/ˌpæn.əˈræm.ɪk/', 'Adj', 'B2', 'Có tầm nhìn bao quát toàn cảnh rộng lớn', 'With a view of an extensive area in all directions.', 'The observation deck on the 81st floor offers panoramic views across the winding river.', 'Đài quan sát tại tầng 81 mang đến tầm nhìn toàn cảnh bao quát dòng sông uốn lượn.', ARRAY['Sweeping', 'All-encompassing', 'Expansive']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('travel-65', 'travel', 'Scenic Route', '/ˌsiː.nɪk ˈruːt/', 'Noun', 'B1', 'Tuyến đường ngắm cảnh thiên nhiên tươi đẹp', 'A road or path that goes through beautiful landscape, even if it is not the fastest way.', 'We chose the slower scenic route along the coastal cliffs rather than the highway.', 'Chúng tôi chọn tuyến đường ven vách đá tuyệt đẹp thay vì đi đường cao tốc.', ARRAY['Tourist road', 'Landscape path']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('travel-66', 'travel', 'Metropolis', '/məˈtrɑː.pəl.ɪs/', 'Noun', 'B2', 'Đại đô thị sầm uất triệu dân', 'A very large and densely populated city, particularly the capital or a major city of a country or region.', 'Tokyo is a bustling technological metropolis that never truly sleeps.', 'Tokyo là một đại đô thị công nghệ sầm uất chưa bao giờ thực sự ngủ.', ARRAY['Mega-city', 'Cosmopolitan center']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('travel-67', 'travel', 'Cosmopolitan', '/ˌkɑːz.məˈpɑː.lɪ.tən/', 'Adj', 'C1', 'Đa văn hóa mang tầm vóc quốc tế', 'Familiar with and at ease in many different countries and cultures; including people from many different countries.', 'London is a truly cosmopolitan city where hundreds of languages are spoken daily.', 'London là một thành phố đa văn hóa thực sự nơi hàng trăm ngôn ngữ được giao tiếp mỗi ngày.', ARRAY['Global', 'International', 'Multicultural']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('travel-68', 'travel', 'Exotic', '/ɪɡˈzɑː.t̬ɪk/', 'Adj', 'B2', 'Kỳ lạ, mới lạ từ xứ sở xa xôi', 'Originating in or characteristic of a distant foreign country.', 'The tropical botanical garden houses thousands of exotic orchids and colorful birds.', 'Vườn thực vật nhiệt đới là nơi sinh sống của hàng ngàn loài lan kỳ lạ và chim chóc rực rỡ sắc màu.', ARRAY['Unusual', 'Foreign', 'Alien']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('travel-69', 'travel', 'Baggage Drop', '/ˈbæɡ.ɪdʒ ˌdrɑːp/', 'Noun', 'A2', 'Quầy gửi hành lý ký gửi nhanh', 'A designated desk at an airport where passengers who have checked in online can hand in their bags.', 'After printing tags at the kiosk, head straight to the automated baggage drop counter.', 'Sau khi in thẻ tại ki-ốt, hãy đi thẳng tới quầy gửi hành lý tự động.', ARRAY['Luggage drop', 'Bag drop']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('travel-70', 'travel', 'Overweight Baggage', '/ˌoʊ.vɚˈweɪt ˌbæɡ.ɪdʒ/', 'Noun', 'B1', 'Hành lý quá tải trọng quy định', 'Luggage exceeding the allowable airline weight limit, subject to penalty fees.', 'Passengers with overweight baggage must pay a steep extra fee per kilogram.', 'Hành khách mang hành lý quá cân nặng quy định phải trả khoản phí phạt đắt đỏ theo từng kg.', ARRAY['Excess baggage', 'Heavy luggage']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('travel-71', 'travel', 'First Class', '/ˌfɝːst ˈklæs/', 'Noun', 'A2', 'Khoang ghế hạng nhất cao cấp nhất', 'The most luxurious and expensive accommodation on an aircraft or train.', 'First class airline passengers enjoy private suites with lie-flat beds and gourmet dining.', 'Hành khách khoang hạng nhất tận hưởng phòng riêng biệt lập với giường nằm phẳng và ẩm thực cao cấp.', ARRAY['Luxury cabin', 'Top tier']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('travel-72', 'travel', 'Business Class', '/ˈbɪz.nɪs ˌklæs/', 'Noun', 'A2', 'Khoang ghế thương gia dành cho doanh nhân', 'A tier of travel on commercial aircraft offering amenities superior to economy class.', 'Traveling business class allows corporate travelers to sleep comfortably during long overnight flights.', 'Bay khoang thương gia cho phép các doanh nhân ngủ thoải mái trong các chuyến bay dài qua đêm.', ARRAY['Executive class', 'Club class']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('travel-73', 'travel', 'Economy Class', '/ɪˈkɑː.nə.mi ˌklæs/', 'Noun', 'A2', 'Khoang ghế phổ thông tiêu chuẩn', 'The cheapest and least luxurious seating class in airline travel.', 'Most leisure holiday travelers book economy class tickets to save money.', 'Đa số khách du lịch nghỉ dưỡng đều đặt vé khoang phổ thông để tiết kiệm chi phí.', ARRAY['Coach class', 'Standard class']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('travel-74', 'travel', 'Cockpit', '/ˈkɑːk.pɪt/', 'Noun', 'B1', 'Khoang lái của phi công trên máy bay', 'A compartment for the pilot, and sometimes also the crew, in an aircraft or spacecraft.', 'Modern jet cockpits are equipped with digital touchscreen flight navigation systems.', 'Khoang lái máy bay phản lực hiện đại được trang bị hệ thống dẫn đường bay màn hình cảm ứng kỹ thuật số.', ARRAY['Flight deck', 'Pilot cabin']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('travel-75', 'travel', 'Cabin Crew', '/ˈkæb.ɪn ˌkruː/', 'Noun', 'B1', 'Đội ngũ tiếp viên hàng không trên chuyến bay', 'The members of an aircraft crew who attend to passengers'' comfort and safety.', 'The cabin crew performed the routine safety demonstration before take-off.', 'Đội ngũ tiếp viên đã thực hiện phần hướng dẫn an toàn tiêu chuẩn trước khi máy bay cất cánh.', ARRAY['Flight attendants', 'Air stewards']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('travel-76', 'travel', 'Flight Attendant', '/ˈflaɪt əˌten.dənt/', 'Noun', 'A2', 'Tiếp viên hàng không', 'A person whose job is to serve and take care of passengers on an aircraft.', 'The flight attendant handed out warm blankets and noise-cancelling headphones.', 'Tiếp viên hàng không đã phát chăn ấm và tai nghe chống ồn cho hành khách.', ARRAY['Air host', 'Steward']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('travel-77', 'travel', 'Co-Pilot', '/ˈkoʊˌpaɪ.lət/', 'Noun', 'B1', 'Cơ phó điều khiển máy bay', 'A pilot who is second in command of an aircraft.', 'The co-pilot monitored air traffic control communications during the stormy approach.', 'Cơ phó đã giám sát các liên lạc kiểm soát không lưu trong suốt quá trình tiếp cận hạ cánh giông bão.', ARRAY['First officer', 'Second pilot']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('travel-78', 'travel', 'Ground Staff', '/ˈɡraʊnd ˌstæf/', 'Noun', 'B1', 'Nhân viên mặt đất tại sân bay', 'The people who work on the ground at an airport, such as check-in workers and baggage handlers.', 'Helpful ground staff escorted elderly passengers to their gates in golf carts.', 'Nhân viên mặt đất nhiệt tình đã đưa các hành khách cao tuổi ra tận cửa lên máy bay bằng xe điện.', ARRAY['Airport crew', 'Terminal staff']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('travel-79', 'travel', 'Air Traffic Control', '/ˌer ˈtræf.ɪk kənˌtroʊl/', 'Noun', 'B2', 'Bộ phận kiểm soát không lưu điều phối bay', 'The service provided by ground-based controllers who direct aircraft on the ground and through a given section of controlled airspace.', 'Air traffic control cleared the wide-body aircraft for immediate takeoff.', 'Kiểm soát không lưu đã cấp phép cho máy bay thân rộng cất cánh ngay lập tức.', ARRAY['ATC', 'Flight controllers']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('travel-80', 'travel', 'Taxicab', '/ˈtæk.si.kæb/', 'Noun', 'A2', 'Xe taxi truyền thống', 'A car licensed to transport passengers in return for payment of a fare.', 'Hail a registered taxicab outside the main arrival hall rather than accepting private offers.', 'Hãy vẫy một chiếc xe taxi đăng kiểm bên ngoài sảnh đến chính thay vì đi xe dù tư nhân.', ARRAY['Cab', 'Taxi']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('travel-81', 'travel', 'Shuttle Bus', '/ˈʃʌt̬.əl ˌbʌs/', 'Noun', 'A2', 'Xe buýt đưa đón chặng ngắn miễn phí', 'A bus that travels regularly between two places, such as an airport and a city center or hotel.', 'The resort operates a complimentary shuttle bus into downtown every thirty minutes.', 'Khu nghỉ dưỡng vận hành xe buýt đưa đón miễn phí vào trung tâm thành phố cứ 30 phút một chuyến.', ARRAY['Transfer bus', 'Airport shuttle']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('travel-82', 'travel', 'Subway', '/ˈsʌb.weɪ/', 'Noun', 'A2', 'Hệ thống tàu điện ngầm đô thị', 'An underground electric railroad, also called metro or underground.', 'Riding the modern subway is the fastest way to avoid heavy downtown traffic jams.', 'Đi tàu điện ngầm hiện đại là cách nhanh nhất để tránh cảnh tắc đường nặng nề ở trung tâm.', ARRAY['Metro', 'Underground', 'Tube']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('travel-83', 'travel', 'Fare', '/fer/', 'Noun', 'A2', 'Giá vé cước phí di chuyển phương tiện', 'The money a passenger on public transportation has to pay.', 'Bus fares can be tapped conveniently using contactless smart travel cards.', 'Tiền vé xe buýt có thể chạm thanh toán tiện lợi bằng thẻ du lịch thông minh không tiếp xúc.', ARRAY['Ticket price', 'Transit fee', 'Cost of ride']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('travel-84', 'travel', 'Toll', '/toʊl/', 'Noun', 'B1', 'Phí qua trạm cầu đường cao tốc', 'A charge payable for permission to use a particular road or bridge.', 'Vehicles equipped with automated transponders pass through the toll gate without stopping.', 'Xe gắn thiết bị định danh tự động có thể đi qua trạm thu phí mà không cần dừng lại.', ARRAY['Road charge', 'Highway fee']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('travel-85', 'travel', 'Pass', '/pæs/', 'Noun', 'A2', 'Thẻ vé trọn gói dùng trong ngày/tuần', 'A ticket or card permitting the holder to enter, travel, or use facilities for a period.', 'Purchasing a three-day rail pass saved us considerable money on regional train rides.', 'Mua thẻ đi tàu 3 ngày đã giúp chúng tôi tiết kiệm khoản tiền đáng kể cho các chuyến tàu khu vực.', ARRAY['Travel ticket', 'Transit pass']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('travel-86', 'travel', 'Turnstile', '/ˈtɝːn.staɪl/', 'Noun', 'B1', 'Cửa quay soát vé tại ga tàu', 'A mechanical gate consisting of revolving horizontal arms that allow only one person at a time to pass through.', 'Tap your QR code at the automated turnstile to enter the metro platform.', 'Chạm mã QR của bạn tại cửa quay soát vé tự động để vào sân ga tàu điện ngầm.', ARRAY['Baffle gate', 'Ticket barrier']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('travel-87', 'travel', 'Platform', '/ˈplæt.fɔːrm/', 'Noun', 'A2', 'Sân ga đón tàu hỏa hoặc tàu điện', 'A raised level surface on which people or things can stand, specifically beside railway tracks.', 'Passengers waiting for the express train should wait behind the yellow platform line.', 'Hành khách chờ tàu tốc hành nên đứng chờ phía sau vạch vàng an toàn của sân ga.', ARRAY['Train dock', 'Track deck']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('travel-88', 'travel', 'Compartment', '/kəmˈpɑːrt.mənt/', 'Noun', 'B1', 'Khoang riêng trên tàu hỏa', 'A separate section or sectioned-off space in a railway carriage.', 'We booked a four-berth sleeper compartment for our overnight train ride to Da Nang.', 'Chúng tôi đã đặt một khoang nằm 4 giường cho chuyến tàu qua đêm đến Đà Nẵng.', ARRAY['Cabin', 'Berth room']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('travel-89', 'travel', 'Scenic Vista', '/ˌsiː.nɪk ˈvɪs.tə/', 'Noun', 'B2', 'Quang cảnh thiên nhiên mở rộng kỳ vĩ', 'A pleasing view, especially one seen through a long, narrow opening like a pass.', 'The mountain pass viewpoint offers an unforgettable scenic vista of cloud-covered valleys.', 'Điểm ngắm trên đèo mang lại một quang cảnh thiên nhiên kỳ vĩ khó quên nhìn xuống các thung lũng mây phủ.', ARRAY['Panoramic overlook', 'Grand view']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('travel-90', 'travel', 'Hospitality Management', '/ˌhɑː.spɪˈtæl.ə.t̬i ˈmæn.ədʒ.mənt/', 'Noun', 'B2', 'Ngành quản trị du lịch và khách sạn', 'The academic and professional study of managing businesses within the tourism and leisure sector.', 'She holds a master''s degree in international hospitality management from Switzerland.', 'Cô ấy sở hữu tấm bằng thạc sĩ về quản trị du lịch khách sạn quốc tế tại Thụy Sĩ.', ARRAY['Hotel administration', 'Tourism management']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('fin-1', 'finance', 'Dividend', '/ˈdɪv.ə.dend/', 'Noun', 'B2', 'Cổ tức tiền mặt hoặc cổ phiếu trả cho cổ đông', 'A sum of money paid regularly by a company to its shareholders out of its profits.', 'Blue-chip corporations provide reliable quarterly dividend payments to long-term investors.', 'Các tập đoàn vốn hóa lớn chi trả cổ tức hàng quý đáng tin cậy cho các nhà đầu tư dài hạn.', ARRAY['Payout', 'Shareholder yield', 'Return']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('fin-2', 'finance', 'Inflation', '/ɪnˈfleɪ.ʃən/', 'Noun', 'B1', 'Lạm phát, sự trượt giá của đồng tiền', 'A general increase in prices and fall in the purchasing value of money.', 'Central banks raise interest rates to tame runaway consumer price inflation.', 'Các ngân hàng trung ương tăng lãi suất nhằm kìm hãm mức lạm phát giá tiêu dùng tăng phi mã.', ARRAY['Price hike', 'Devaluation', 'Currency erosion']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('fin-3', 'finance', 'Deflation', '/dɪˈfleɪ.ʃən/', 'Noun', 'B2', 'Giảm phát, giá cả sụt giảm kìm hãm chi tiêu', 'Reduction of the general level of prices in an economy.', 'Prolonged economic deflation discourages consumer spending as buyers anticipate further price drops.', 'Giảm phát kinh tế kéo dài làm giảm chi tiêu của người tiêu dùng do người mua dự đoán giá sẽ còn giảm tiếp.', ARRAY['Price slump', 'Economic contraction']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('fin-4', 'finance', 'Liquidity', '/lɪˈkwɪd.ə.t̬i/', 'Noun', 'B2', 'Tính thanh khoản, khả năng chuyển thành tiền mặt', 'The availability of liquid assets to a market or company; the ease with which an asset can be converted into cash.', 'High market liquidity allows traders to buy and sell equities without causing wild price swings.', 'Tính thanh khoản thị trường cao cho phép các nhà giao dịch mua bán cổ phiếu mà không gây biến động giá dữ dội.', ARRAY['Cash availability', 'Convertibility', 'Fluidity']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('fin-5', 'finance', 'Portfolio', '/ˌpɔːrtˈfoʊ.li.oʊ/', 'Noun', 'B1', 'Danh mục đầu tư tài chính', 'A range of investments held by a person or organization.', 'A prudent investor maintains a balanced portfolio combining stocks, government bonds, and precious metals.', 'Một nhà đầu tư thận trọng luôn duy trì một danh mục cân bằng kết hợp cổ phiếu, trái phiếu chính phủ và kim loại quý.', ARRAY['Investment basket', 'Asset collection']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('fin-6', 'finance', 'Diversification', '/daɪˌvɝː.sə.fəˈkeɪ.ʃən/', 'Noun', 'B2', 'Đa dạng hóa danh mục để phân tán rủi ro', 'The action of diversifying something or the practice of varying one''s range of products or field of operation.', 'Asset diversification is the most reliable defense against sudden industry downturns.', 'Đa dạng hóa tài sản là lá chắn tin cậy nhất chống lại những đợt suy thoái bất ngờ của một ngành nghề.', ARRAY['Asset spreading', 'Risk dispersion']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('fin-7', 'finance', 'Equity', '/ˈek.wə.t̬i/', 'Noun', 'B2', 'Vốn chủ sở hữu, cổ phần trong doanh nghiệp', 'The value of the shares issued by a company; the value of property after deducting mortgage or other liabilities.', 'Founders surrendered twenty percent of their company equity in exchange for five million dollars in venture capital.', 'Các nhà sáng lập đã nhượng lại 20% vốn chủ sở hữu công ty để đổi lấy 5 triệu USD vốn đầu tư mạo hiểm.', ARRAY['Ownership shares', 'Capital stock']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('fin-8', 'finance', 'Bonds', '/bɑːndz/', 'Noun', 'B1', 'Trái phiếu nợ chính phủ hoặc doanh nghiệp', 'A debt security under which the issuer owes the holders a debt and is obliged to pay interest.', 'Treasury bonds are traditionally considered safe-haven investments during turbulent market times.', 'Trái phiếu kho bạc theo truyền thống được xem là kênh trú ẩn đầu tư an toàn trong thời kỳ thị trường biến động.', ARRAY['Debentures', 'Debt securities']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('fin-9', 'finance', 'Commodity', '/kəˈmɑː.də.t̬i/', 'Noun', 'B2', 'Hàng hóa thô thương phẩm (dầu, vàng, lúa mì)', 'A raw material or primary agricultural product that can be bought and sold, such as copper or coffee.', 'Crude oil and gold remain the most heavily traded commodity assets on international mercantile exchanges.', 'Dầu thô và vàng vẫn là những mặt hàng thô được giao dịch sôi động nhất trên các sàn giao dịch thương phẩm quốc tế.', ARRAY['Raw goods', 'Primary merchandise']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('fin-10', 'finance', 'Fiscal Policy', '/ˌfɪs.kəl ˈpɑː.lə.si/', 'Noun', 'B2', 'Chính sách tài khóa của chính phủ về thuế và chi tiêu', 'The means by which a government adjusts its spending levels and tax rates to monitor and influence a nation''s economy.', 'Expansionary fiscal policy involves increasing public infrastructure expenditure to stimulate employment.', 'Chính sách tài khóa mở rộng bao gồm việc gia tăng chi tiêu cho hạ tầng công cộng để kích thích việc làm.', ARRAY['Government spending', 'Budget policy']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('fin-11', 'finance', 'Monetary Policy', '/ˈmɑː.nə.ter.i ˌpɑː.lə.si/', 'Noun', 'B2', 'Chính sách tiền tệ kiểm soát cung tiền và lãi suất', 'The policy laid down by the central bank which involves management of money supply and interest rate.', 'The Federal Reserve adjusted monetary policy to cool down an overheating national economy.', 'Cục Dự trữ Liên bang đã điều chỉnh chính sách tiền tệ để hạ nhiệt một nền kinh tế đang phát triển quá nóng.', ARRAY['Central bank policy', 'Credit regulation']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('fin-12', 'finance', 'Bull Market', '/ˈbʊl ˌmɑːr.kɪt/', 'Noun', 'B1', 'Thị trường bò tót tăng trưởng bùng nổ', 'A market in which share prices are rising, encouraging buying.', 'Optimistic earnings reports sustained a historic bull market for technology equities.', 'Các báo cáo lợi nhuận lạc quan đã duy trì một thị trường bò tót tăng điểm lịch sử cho nhóm cổ phiếu công nghệ.', ARRAY['Rallying market', 'Boom market']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('fin-13', 'finance', 'Bear Market', '/ˈber ˌmɑːr.kɪt/', 'Noun', 'B1', 'Thị trường gấu suy giảm ảm đạm', 'A market in which prices are falling, encouraging selling.', 'A prolonged bear market tests the psychological resilience of individual retail traders.', 'Một thị trường giá xuống kéo dài thử thách khả năng chịu đựng tâm lý của các nhà đầu tư cá nhân nhỏ lẻ.', ARRAY['Slumping market', 'Downturn']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('fin-14', 'finance', 'Volatility', '/ˌvɑː.ləˈtɪl.ə.t̬i/', 'Noun', 'B2', 'Mức độ biến động trồi sụt của giá cả', 'Liability to change rapidly and unpredictably, especially for the worse.', 'Cryptocurrency markets are notorious for extreme intraday volatility.', 'Thị trường tiền mã hóa vốn nổi tiếng vì mức độ biến động giá trong ngày vô cùng dữ dội.', ARRAY['Fluctuation', 'Instability', 'Turbulence']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('fin-15', 'finance', 'Capital Gain', '/ˌkæp.ə.t̬əl ˈɡeɪn/', 'Noun', 'B2', 'Lợi nhuận từ chênh lệch giá vốn khi bán tài sản', 'A profit from the sale of property or an investment.', 'Investors holding assets for over one year benefit from lower long-term capital gain tax brackets.', 'Nhà đầu tư nắm giữ tài sản trên một năm sẽ được hưởng các mức thuế thu nhập chênh lệch vốn dài hạn thấp hơn.', ARRAY['Investment profit', 'Capital return']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('fin-16', 'finance', 'Depreciation', '/dɪˌpriː.ʃiˈeɪ.ʃən/', 'Noun', 'B2', 'Khấu hao tài sản hoặc sụt giảm giá trị tiền tệ', 'A reduction in the value of an asset over time, or the decrease in the value of a currency.', 'Automobiles experience steep financial depreciation within the very first year of ownership.', 'Xe ô tô bị khấu hao giá trị tài chính rất nhanh chóng chỉ ngay trong năm đầu tiên sở hữu.', ARRAY['Devaluation', 'Wear and tear']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('fin-17', 'finance', 'Appreciation', '/əˌpriː.ʃiˈeɪ.ʃən/', 'Noun', 'B2', 'Sự gia tăng giá trị tài sản qua thời gian', 'An increase in the value of an asset over time.', 'Prime beachfront land in Da Nang has witnessed phenomenal financial appreciation over the past decade.', 'Đất ven biển vị trí đắc địa tại Đà Nẵng đã chứng kiến mức gia tăng giá trị ngoạn mục trong thập kỷ qua.', ARRAY['Value increase', 'Growth in worth']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('fin-18', 'finance', 'Leverage', '/ˈlev.ɚ.ɪdʒ/', 'Noun', 'B2', 'Đòn bẩy tài chính dùng vốn vay để khuếch đại lợi nhuận', 'The use of borrowed capital for an investment, expecting the profits made to be greater than the interest payable.', 'Excessive financial leverage can magnify losses disastrously when market trades go awry.', 'Sử dụng đòn bẩy tài chính quá mức có thể khuếch đại các khoản thua lỗ thảm khốc khi các giao dịch diễn biến xấu.', ARRAY['Borrowed funds', 'Gearing']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('fin-19', 'finance', 'Yield Curve', '/ˈjiːld ˌkɝːv/', 'Noun', 'C1', 'Đường cong lợi suất trái phiếu theo kỳ hạn', 'A line that plots yields, often of bonds with equal credit quality but differing maturity dates.', 'An inverted yield curve has historically been a reliable harbinger of impending economic recessions.', 'Đường cong lợi suất đảo ngược trong lịch sử luôn là điềm báo đáng tin cậy cho các cuộc suy thoái kinh tế cận kề.', ARRAY['Interest rate curve', 'Maturity chart']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('fin-20', 'finance', 'Securitization', '/səˌkjʊr.ə.t̬əˈzeɪ.ʃən/', 'Noun', 'C1', 'Chứng khoán hóa các khoản nợ để bán ra thị trường', 'The process of taking an illiquid asset, or group of assets, and through financial engineering, transforming them into a security.', 'Mortgage securitization transformed thousands of individual home loans into tradable bond instruments.', 'Chứng khoán hóa thế chấp đã biến hàng ngàn khoản vay mua nhà cá nhân thành các công cụ trái phiếu có thể giao dịch.', ARRAY['Debt packaging', 'Asset-backed security']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('fin-21', 'finance', 'Derivative', '/dɪˈrɪv.ə.t̬ɪv/', 'Noun', 'C1', 'Công cụ tài chính phái sinh (hợp đồng tương lai, quyền chọn)', 'An arrangement or product whose value derives from and is dependent on the value of an underlying asset.', 'Multinational corporations use currency derivatives to hedge against sudden foreign exchange swings.', 'Các tập đoàn đa quốc gia sử dụng các sản phẩm phái sinh tiền tệ để phòng ngừa trước những biến động tỷ giá bất ngờ.', ARRAY['Hedge instrument', 'Futures contract']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('fin-22', 'finance', 'Hedging', '/ˈhedʒ.ɪŋ/', 'Noun', 'B2', 'Nghiệp vụ phòng ngừa rủi ro tài chính', 'An investment to reduce the risk of adverse price movements in an asset.', 'Airlines engage in fuel hedging contracts to lock in kerosene prices years ahead.', 'Các hãng hàng không tham gia vào các hợp đồng phòng ngừa rủi ro nhiên liệu để chốt giá dầu nhiều năm trước.', ARRAY['Risk mitigation', 'Financial protection']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('fin-23', 'finance', 'Collateral', '/kəˈlæt̬.ɚ.əl/', 'Noun', 'B2', 'Tài sản thế chấp để đảm bảo khoản vay', 'Something pledged as security for repayment of a loan, to be forfeited in the event of a default.', 'The commercial bank required a residential title deed as collateral for the business loan.', 'Ngân hàng thương mại yêu cầu sổ hồng nhà ở làm tài sản thế chấp cho khoản vay kinh doanh.', ARRAY['Pledge', 'Security deposit', 'Guarantee']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('fin-24', 'finance', 'Bankruptcy', '/ˈbæŋ.krəpt.si/', 'Noun', 'B1', 'Tình trạng phá sản hợp pháp của doanh nghiệp', 'The state of being bankrupt, unable to settle outstanding debts.', 'The real estate developer filed for bankruptcy protection after missing bond coupon payments.', 'Nhà phát triển bất động sản đã nộp đơn xin bảo hộ phá sản sau khi lỡ hạn thanh toán lãi coupon trái phiếu.', ARRAY['Insolvency', 'Liquidation', 'Ruin']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('fin-25', 'finance', 'Solvency', '/ˈsɑːl.vən.si/', 'Noun', 'B2', 'Khả năng thanh toán nợ dài hạn', 'The possession of assets in excess of liabilities; ability to pay one''s debts.', 'Rigorous stress tests proved the financial solvency of the banking sector under harsh conditions.', 'Các bài kiểm tra sức chịu đựng nghiêm ngặt đã chứng minh khả năng thanh toán tài chính của ngành ngân hàng trong những điều kiện khắc nghiệt.', ARRAY['Financial stability', 'Creditworthiness']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('fin-26', 'finance', 'Remittance', '/rɪˈmɪt.əns/', 'Noun', 'B2', 'Kiều hối, kiều bào gửi tiền về quê hương', 'A sum of money sent, especially by a person working abroad to someone in their home country.', 'Foreign remittances contribute billions of dollars annually to the developing economy.', 'Nguồn kiều hối từ nước ngoài đóng góp hàng tỷ USD mỗi năm cho nền kinh tế đang phát triển.', ARRAY['Overseas transfer', 'Money wire']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('fin-27', 'finance', 'Microfinance', '/ˈmaɪ.kroʊˌfaɪ.næns/', 'Noun', 'B2', 'Tài chính vi mô hỗ trợ hộ nghèo khởi nghiệp', 'A type of banking service provided to unemployed or low-income individuals or groups who otherwise would have no other access to financial services.', 'Microfinance loans empowered rural women to launch independent weaving cooperatives.', 'Các khoản vay tài chính vi mô đã trao quyền cho phụ nữ nông thôn thành lập các hợp tác xã dệt độc lập.', ARRAY['Small-scale credit', 'Grassroots banking']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('fin-28', 'finance', 'Annuity', '/əˈnuː.ə.t̬i/', 'Noun', 'C1', 'Hợp đồng niên kim chi trả định kỳ khi về hưu', 'A fixed sum of money paid to someone each year, typically for the rest of their life.', 'Investing in a guaranteed lifetime annuity provides predictable monthly cash flow in retirement.', 'Đầu tư vào một hợp đồng niên kim trọn đời có bảo đảm mang lại dòng tiền mặt hàng tháng dự đoán được khi về hưu.', ARRAY['Annual payout', 'Pension stream']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('fin-29', 'finance', 'Underwriting', '/ˈʌn.dɚˌraɪ.tɪŋ/', 'Noun', 'C1', 'Nghiệp vụ thẩm định rủi ro và bảo lãnh tài chính', 'The process by which an investment bank assesses risk and guarantees public share issuance.', 'The lead underwriter determined an initial IPO offer price of twenty-four dollars per share.', 'Đơn vị bảo lãnh phát hành chính đã xác định mức giá chào bán IPO ban đầu là 24 USD cho mỗi cổ phần.', ARRAY['Risk assessment', 'Financial backing']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('fin-30', 'finance', 'Custody', '/ˈkʌs.tə.di/', 'Noun', 'B2', 'Lưu ký tài sản và chứng khoán an toàn', 'The protective care or guardianship of assets, securities, or financial instruments.', 'Institutional custodians safeguard trillions of dollars in equities on behalf of sovereign wealth funds.', 'Các tổ chức lưu ký bảo quản hàng nghìn tỷ USD cổ phiếu thay mặt cho các quỹ đầu tư quốc gia.', ARRAY['Safekeeping', 'Asset guardianship']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('fin-31', 'finance', 'Amortization', '/ˌæm.ɚ.t̬əˈzeɪ.ʃən/', 'Noun', 'C1', 'Khấu hao tài sản vô hình / trả góp nợ định kỳ', 'The reduction of a loan or debt balance over time through scheduled payments.', 'The fixed mortgage amortization schedule shows the portion applied to principal versus interest.', 'Lịch trình trả góp thế chấp cố định thể hiện phần tiền được trả cho tiền gốc so với tiền lãi.', ARRAY['Installment schedule', 'Debt reduction']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('fin-32', 'finance', 'Arrears', '/əˈrɪrz/', 'Noun', 'C1', 'Khoản nợ đọng quá hạn chưa thanh toán', 'Money that is owed and should have been paid earlier.', 'Tenants who fall three months into rent arrears face immediate eviction proceedings.', 'Những khách thuê nợ đọng tiền nhà tới ba tháng sẽ đối mặt với thủ tục đuổi nhà ngay lập tức.', ARRAY['Overdue debt', 'Back payments']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('fin-33', 'finance', 'Asset Class', '/ˈæs.et ˌklæs/', 'Noun', 'B2', 'Nhóm lớp tài sản đầu tư tương đồng', 'A group of financial instruments that have similar financial characteristics and behave similarly in the marketplace.', 'Equities, real estate, and fixed-income bonds represent distinct investment asset classes.', 'Cổ phiếu, bất động sản và trái phiếu thu nhập cố định đại diện cho các lớp tài sản đầu tư khác biệt.', ARRAY['Investment category', 'Asset category']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('fin-34', 'finance', 'Balance Sheet', '/ˈbæl.əns ˌʃiːt/', 'Noun', 'B1', 'Bảng cân đối kế toán tài sản và nợ', 'A statement of the assets, liabilities, and capital of a business at a particular point in time.', 'Reviewing the balance sheet helps investors assess a corporation''s short-term financial strength.', 'Xem xét bảng cân đối kế toán giúp các nhà đầu tư đánh giá sức mạnh tài chính ngắn hạn của doanh nghiệp.', ARRAY['Financial statement', 'Asset summary']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('fin-35', 'finance', 'Cash Flow', '/ˈkæʃ ˌfloʊ/', 'Noun', 'B1', 'Dòng tiền mặt vào ra của doanh nghiệp', 'The total amount of money being transferred into and out of a business, especially as affecting liquidity.', 'Positive operating cash flow indicates that the core software business generates abundant cash.', 'Dòng tiền hoạt động dương chứng tỏ hoạt động kinh doanh phần mềm cốt lõi tạo ra nguồn tiền dồi dào.', ARRAY['Cash generation', 'Liquidity flow']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('fin-36', 'finance', 'Credit Rating', '/ˈkred.ɪt ˌreɪ.tɪŋ/', 'Noun', 'B2', 'Hạng mức tín nhiệm tín dụng quốc gia/doanh nghiệp', 'An estimate of the ability of a person or organization to fulfill their financial commitments, based on previous dealings.', 'Standard & Poor''s upgraded the sovereign credit rating from stable to positive.', 'Tổ chức Standard & Poor''s đã nâng hạng mức tín nhiệm quốc gia từ ổn định lên mức tích cực.', ARRAY['Credit score', 'Creditworthiness']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('fin-37', 'finance', 'Debenture', '/dɪˈben.tʃɚ/', 'Noun', 'C1', 'Trái phiếu doanh nghiệp không cần bảo đảm bằng tài sản', 'An unsecured loan certificate issued by a company, backed by general credit rather than by specified assets.', 'The energy conglomerate issued five-hundred million dollars in ten-year convertible debentures.', 'Tập đoàn năng lượng đã phát hành 500 triệu USD trái phiếu chuyển đổi kỳ hạn 10 năm không cần thế chấp.', ARRAY['Unsecured bond', 'Corporate note']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('fin-38', 'finance', 'Default', '/dɪˈfɑːlt/', 'Noun', 'B2', 'Sự vỡ nợ không trả được gốc hoặc lãi', 'Failure to fulfill an obligation, especially to repay a loan or appear in a court of law.', 'Sovereign debt default triggers immediate trade embargoes and freezes international credit lines.', 'Vỡ nợ quốc gia sẽ kích hoạt ngay lệnh cấm vận thương mại và đóng băng các hạn mức tín dụng quốc tế.', ARRAY['Non-payment', 'Loan breach']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('fin-39', 'finance', 'Depository', '/dɪˈpɑː.zə.tɔːr.i/', 'Noun', 'B2', 'Trung tâm lưu ký chứng khoán quốc gia', 'A facility where things can be deposited for storage or safekeeping, especially financial instruments.', 'The national securities depository manages electronic book-entry transfers of all public shares.', 'Trung tâm lưu ký chứng khoán quốc gia quản lý việc chuyển nhượng ghi sổ điện tử của tất cả cổ phiếu đại chúng.', ARRAY['Repository', 'Securities vault']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('fin-40', 'finance', 'Discount Rate', '/ˈdɪs.kaʊnt ˌreɪt/', 'Noun', 'B2', 'Lãi suất chiết khấu của ngân hàng trung ương', 'The minimum interest rate set by the central bank for lending to other banks, or rate used in DCF modeling.', 'Raising the central discount rate cools corporate borrowing and slows runaway business expansion.', 'Tăng lãi suất chiết khấu trung ương giúp hạ nhiệt hoạt động vay vốn doanh nghiệp và làm chậm đà mở rộng ồ ạt.', ARRAY['Base lending rate', 'Discount factor']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('fin-41', 'finance', 'Due Date', '/ˈduː ˌdeɪt/', 'Noun', 'A2', 'Hạn chót thanh toán nghĩa vụ nợ', 'The date on which something falls due, especially the payment of a bill or debt.', 'Always settle your credit card statement balance in full before the official due date.', 'Hãy luôn thanh toán toàn bộ số dư sao kê thẻ tín dụng trước ngày đến hạn chính thức.', ARRAY['Payment deadline', 'Maturity date']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('fin-42', 'finance', 'Equities', '/ˈek.wə.t̬iz/', 'Noun', 'B2', 'Cổ phiếu thị trường vốn', 'Stocks and shares in a company, representing ownership stakes.', 'Long-term historical returns from equities outpace those from fixed-interest bank deposits.', 'Lợi suất lịch sử dài hạn từ cổ phiếu luôn vượt trội so với các khoản tiền gửi tiết kiệm lãi suất cố định.', ARRAY['Stocks', 'Shares']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('fin-43', 'finance', 'Escrow', '/ˈes.kroʊ/', 'Noun', 'B2', 'Tài khoản ký quỹ bên thứ ba giữ tiền trung gian', 'A contractual arrangement in which a third party receives and disburses money or property for primary parties.', 'Funds for the property purchase remain held securely in escrow until all deeds are verified.', 'Tiền mua bất động sản được giữ an toàn trong tài khoản ký quỹ cho đến khi toàn bộ giấy tờ được xác thực.', ARRAY['Third-party holding', 'Trust account']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('fin-44', 'finance', 'Foreclosure', '/fɔːrˈkloʊ.ʒɚ/', 'Noun', 'C1', 'Thủ tục tịch thu nhà đất thế chấp để xiết nợ', 'The action of taking possession of a mortgaged property when the mortgagor fails to keep up their mortgage payments.', 'The bank initiated foreclosure proceedings after the homeowner missed eight consecutive mortgage payments.', 'Ngân hàng đã tiến hành thủ tục tịch thu tài sản sau khi chủ nhà lỡ 8 kỳ thanh toán tiền mua nhà liên tiếp.', ARRAY['Repossession', 'Seizure']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('fin-45', 'finance', 'Forex', '/ˈfɔːr.eks/', 'Noun', 'B1', 'Thị trường ngoại hối quốc tế (FX)', 'Foreign Exchange: the global marketplace for exchanging national currencies against one another.', 'Forex traders execute trillions of dollars in daily transactions across London, New York, and Tokyo.', 'Các nhà giao dịch ngoại hối thực hiện hàng nghìn tỷ USD giao dịch mỗi ngày tại London, New York và Tokyo.', ARRAY['Foreign exchange', 'Currency market']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('fin-46', 'finance', 'Gearing', '/ˈɡɪr.ɪŋ/', 'Noun', 'C1', 'Tỷ lệ đòn bẩy nợ trên vốn chủ sở hữu', 'The proportion of a company''s capital which is financed by debt as opposed to equity shares.', 'High financial gearing makes an enterprise exceptionally vulnerable during periods of rising interest rates.', 'Tỷ lệ đòn bẩy nợ cao khiến doanh nghiệp đặc biệt dễ tổn thương trong thời kỳ lãi suất gia tăng.', ARRAY['Debt-to-equity ratio', 'Financial leverage']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('fin-47', 'finance', 'Guarantor', '/ˌɡær.ənˈtɔːr/', 'Noun', 'B2', 'Người đứng ra bảo lãnh khoản vay nợ', 'A person or organization that provides a guarantee in support of another.', 'His father acted as legal guarantor so the young entrepreneur could secure a startup commercial loan.', 'Cha anh ấy đã đứng ra làm người bảo lãnh hợp pháp để doanh nhân trẻ có thể vay vốn khởi nghiệp.', ARRAY['Sponsor', 'Surety', 'Backer']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('fin-48', 'finance', 'Initial Public Offering', '/ɪˌnɪʃ.əl ˈpʌb.lɪk ˌɑː.fɚ.ɪŋ/', 'Noun', 'B2', 'Chào bán cổ phiếu lần đầu ra công chúng (IPO)', 'The first sale of stock by a private company to the public.', 'The tech unicorn filed documentation for an upcoming ten-billion-dollar initial public offering on NASDAQ.', 'Kỳ lân công nghệ đã nộp hồ sơ cho đợt chào bán cổ phiếu lần đầu trị giá 10 tỷ USD sắp tới trên sàn NASDAQ.', ARRAY['IPO', 'Public listing', 'Stock flotation']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('fin-49', 'finance', 'Insider Trading', '/ˌɪn.saɪ.dɚ ˈtreɪ.dɪŋ/', 'Noun', 'B2', 'Giao dịch nội gián trái phép dựa trên tin mật', 'The illegal practice of trading on the stock exchange to one''s own advantage through having access to confidential information.', 'The former corporate vice president was convicted of insider trading and handed a hefty prison term.', 'Cựu phó chủ tịch tập đoàn đã bị kết tội giao dịch nội gián trái phép và phải nhận mức án tù thích đáng.', ARRAY['Confidential dealing', 'Securities fraud']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('fin-50', 'finance', 'Interest Rate', '/ˈɪn.trɪst ˌreɪt/', 'Noun', 'B1', 'Lãi suất tiền gửi hoặc lãi vay', 'The proportion of a loan that is charged as interest to the borrower, typically expressed as an annual percentage.', 'Commercial banks raised mortgage interest rates following the central bank''s policy tightening.', 'Các ngân hàng thương mại đã tăng lãi suất thế chấp sau khi ngân hàng trung ương thắt chặt chính sách.', ARRAY['Borrowing rate', 'Yield percentage']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('fin-51', 'finance', 'Maturity', '/məˈtʊr.ə.t̬i/', 'Noun', 'B2', 'Ngày đáo hạn hợp đồng trái phiếu hoặc tiền gửi', 'The time when an insurance policy, security, etc. matures and is due for payment.', 'Hold the ten-year government bond until final maturity to receive the full face value principal.', 'Hãy nắm giữ trái phiếu chính phủ 10 năm cho tới ngày đáo hạn cuối cùng để nhận đủ toàn bộ mệnh giá tiền gốc.', ARRAY['Expiration date', 'Due date']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('fin-52', 'finance', 'Mutual Fund', '/ˈmjuː.tʃu.əl ˌfʌnd/', 'Noun', 'B1', 'Quỹ đầu tư tương hỗ đại chúng', 'An investment program funded by shareholders that trades in diversified holdings and is professionally managed.', 'Novice investors often start by placing monthly savings into low-cost index mutual funds.', 'Các nhà đầu tư mới bắt đầu thường gửi tiết kiệm hàng tháng vào các quỹ đầu tư tương hỗ chỉ số chi phí thấp.', ARRAY['Open-end fund', 'Collective investment']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('fin-53', 'finance', 'Overdrawn', '/ˌoʊ.vɚˈdrɑːn/', 'Adj', 'B1', 'Thấu chi tài khoản, tiêu vượt số dư hiện có', 'Having an account with a bank or other financial institution in deficit.', 'Her checking account went overdrawn after an unexpected automatic annual subscription charge.', 'Tài khoản thanh toán của cô ấy bị thấu chi sau một khoản trừ tiền đăng ký dịch vụ thường niên tự động bất ngờ.', ARRAY['In the red', 'Deficit']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('fin-54', 'finance', 'Overdraft', '/ˈoʊ.vɚ.dræft/', 'Noun', 'B1', 'Hạn mức thấu chi được ngân hàng cấp trước', 'A deficit in a bank account caused by drawing more money than the account holds.', 'The bank granted a flexible five-thousand-dollar business overdraft facility to manage payroll gaps.', 'Ngân hàng đã cấp hạn mức thấu chi kinh doanh linh hoạt 5.000 USD để xử lý khoảng trống tiền mặt trả lương.', ARRAY['Credit buffer', 'Deficit allowance']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('fin-55', 'finance', 'Par Value', '/ˈpɑːr ˌvæl.juː/', 'Noun', 'C1', 'Mệnh giá danh nghĩa ghi trên mặt trái phiếu', 'The nominal or face value of a share, bond, or coupon as stated on a certificate or chart.', 'Corporate bonds are issued with a standard par value of one thousand dollars per note.', 'Trái phiếu doanh nghiệp được phát hành với mệnh giá tiêu chuẩn là 1.000 USD cho mỗi phiếu ghi nhận nợ.', ARRAY['Face value', 'Nominal value']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('fin-56', 'finance', 'Payoff', '/ˈpeɪ.ɑːf/', 'Noun', 'B1', 'Phần thưởng lợi nhuận hoặc thanh toán dứt điểm', 'A payment made to someone, especially as a bribe or reward, or the return on an investment.', 'Patience in equity investing often yields an enormous financial payoff over a twenty-year horizon.', 'Sự kiên nhẫn trong đầu tư cổ phiếu thường mang lại mức lợi nhuận đền đáp to lớn trong chân trời 20 năm.', ARRAY['Return', 'Reward', 'Dividend']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('fin-57', 'finance', 'Principal', '/ˈprɪn.sə.pəl/', 'Noun', 'B2', 'Tiền gốc của một khoản nợ hoặc đầu tư', 'A sum of money lent or invested, on which interest is paid.', 'Monthly loan repayments cover both accrued interest and a portion of the original loan principal.', 'Các khoản trả nợ hàng tháng bao gồm cả phần tiền lãi phát sinh và một phần tiền gốc ban đầu.', ARRAY['Capital sum', 'Loan base', 'Face amount']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('fin-58', 'finance', 'Prospectus', '/prəˈspek.təs/', 'Noun', 'C1', 'Bản cáo bạch thông tin tài chính trước khi IPO', 'A formal legal document that is required by and filed with regulatory authorities providing details about an investment offering.', 'Prospective investors should carefully study the company''s financial prospectus before purchasing shares.', 'Các nhà đầu tư tiềm năng nên nghiên cứu kỹ bản cáo bạch tài chính của công ty trước khi mua cổ phiếu.', ARRAY['Offering document', 'Investment brochure']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('fin-59', 'finance', 'Recession', '/rɪˈseʃ.ən/', 'Noun', 'B2', 'Suy thoái kinh tế (tăng trưởng âm hai quý liên tiếp)', 'A period of temporary economic decline during which trade and industrial activity are reduced.', 'The government rolled out emergency stimulus packages to mitigate the severity of the global recession.', 'Chính phủ đã tung ra các gói kích thích khẩn cấp để giảm thiểu mức độ nghiêm trọng của cuộc suy thoái toàn cầu.', ARRAY['Downturn', 'Economic slump', 'Stagnation']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('fin-60', 'finance', 'Solvent', '/ˈsɑːl.vənt/', 'Adj', 'B2', 'Có khả năng thanh toán nợ đầy đủ', 'Having assets that exceed one''s liabilities, able to pay one''s debts.', 'Despite reduced factory output, the manufacturer remains completely solvent with solid cash reserves.', 'Mặc dù sản lượng nhà máy sụt giảm, nhà sản xuất vẫn hoàn toàn có khả năng thanh toán nhờ dự trữ tiền mặt vững chắc.', ARRAY['Financially sound', 'Liquid', 'In credit']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('fin-61', 'finance', 'Speculation', '/ˌspek.jəˈleɪ.ʃən/', 'Noun', 'B2', 'Hoạt động đầu cơ kiếm lời ngắn hạn rủi ro cao', 'Investment in stocks, property, or other ventures in the hope of gain but with the risk of loss.', 'Unchecked land speculation fueled an unsustainable real estate price bubble.', 'Hoạt động đầu cơ đất đai không kiểm soát đã thổi bùng bong bóng giá bất động sản khó bền vững.', ARRAY['Risk trading', 'Gambling on price']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('fin-62', 'finance', 'Spread', '/spred/', 'Noun', 'B2', 'Khoảng chênh lệch giữa giá mua và giá bán', 'The difference between the bid and the ask price of a security or asset.', 'Liquid currency pairs like EUR/USD maintain an extremely tight bid-ask spread.', 'Các cặp tiền tệ có tính thanh khoản cao như EUR/USD duy trì mức chênh lệch giá mua bán vô cùng hẹp.', ARRAY['Price gap', 'Margin difference']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('fin-63', 'finance', 'Stamp Duty', '/ˈstæmp ˌduː.t̬i/', 'Noun', 'B2', 'Thuế trước bạ khi mua bán nhà đất', 'A tax levied on single property purchases or documents, typically in real estate transfers.', 'Homebuyers must factor in local government stamp duty charges when budgeting for an apartment.', 'Người mua nhà phải tính toán đến khoản thuế trước bạ nộp cho chính quyền khi lên ngân sách mua căn hộ.', ARRAY['Transfer tax', 'Property levy']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('fin-64', 'finance', 'Stockbroker', '/ˈstɑːkˌbroʊ.kɚ/', 'Noun', 'B1', 'Môi giới chứng khoán hỗ trợ lệnh đặt', 'A broker who buys and sells securities on a stock exchange on behalf of clients.', 'Her licensed stockbroker advised her against panic-selling during the sudden morning market dip.', 'Nhà môi giới chứng khoán được cấp phép đã khuyên cô ấy không nên bán tháo trong hoảng loạn giữa đợt giảm sáng nay.', ARRAY['Securities trader', 'Investment agent']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('fin-65', 'finance', 'Subsidy', '/ˈsʌb.sə.di/', 'Noun', 'B2', 'Khoản tiền trợ cấp của chính phủ', 'A sum of money granted by the government or a public body to assist an industry or business.', 'Agricultural subsidies help domestic dairy farmers remain competitive against imported goods.', 'Các khoản trợ cấp nông nghiệp giúp nông dân chăn nuôi bò sữa trong nước duy trì sức cạnh tranh với hàng nhập khẩu.', ARRAY['Grant', 'Financial aid', 'Allowance']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('fin-66', 'finance', 'Takeover', '/ˈteɪkˌoʊ.vɚ/', 'Noun', 'B2', 'Vụ thâu tóm nắm quyền kiểm soát công ty', 'An act of assuming control of something, especially the buying out of one company by another.', 'The hostile corporate takeover bid was narrowly defeated at the annual general meeting.', 'Nỗ lực thâu tóm thù địch doanh nghiệp đã bị đánh bại sít sao tại đại hội đồng cổ đông thường niên.', ARRAY['Buyout', 'Acquisition']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('fin-67', 'finance', 'Treasury', '/ˈtreʒ.ɚ.i/', 'Noun', 'B2', 'Kho bạc nhà nước hoặc ngân quỹ tài chính', 'The funds or revenue of a government, institution, or society; the department in charge of public money.', 'The national treasury issued thirty-year inflation-protected securities to institutional pension funds.', 'Kho bạc nhà nước đã phát hành chứng chỉ bảo hiểm lạm phát kỳ hạn 30 năm cho các quỹ hưu trí tổ chức.', ARRAY['National funds', 'Exchequer', 'Finances']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('fin-68', 'finance', 'Trust Fund', '/ˈtrʌst ˌfʌnd/', 'Noun', 'B2', 'Quỹ tín thác ủy thác cho người thừa kế', 'A fund consisting of assets that have been transferred to someone with stipulations that they be held on behalf of another.', 'Her grandparents established a generous college education trust fund when she was born.', 'Ông bà cô ấy đã lập một quỹ tín thác học đại học hậu hĩnh ngay từ khi cô ấy mới chào đời.', ARRAY['Settlement fund', 'Estate trust']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('fin-69', 'finance', 'Underwrite', '/ˈʌn.dɚ.raɪt/', 'Verb', 'C1', 'Bảo lãnh tài chính hoặc bảo hiểm rủi ro', 'Sign and accept liability under an insurance policy, thus guaranteeing payment in case of loss or damage.', 'Syndicates of global investment banks underwrite multi-billion-dollar sovereign bond issuances.', 'Các tổ hợp ngân hàng đầu tư toàn cầu đứng ra bảo lãnh các đợt phát hành trái phiếu chính phủ hàng tỷ USD.', ARRAY['Guarantee', 'Insure', 'Back']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('fin-70', 'finance', 'Venture', '/ˈven.tʃɚ/', 'Noun', 'B1', 'Dự án kinh doanh mạo hiểm nhiều rủi ro', 'A risky or daring journey or undertaking; a commercial enterprise involving risks.', 'The two aerospace companies launched a joint venture to develop reusable orbital rockets.', 'Hai công ty hàng không vũ trụ đã khởi động một dự án kinh doanh mạo hiểm chung nhằm phát triển tên lửa quỹ đạo tái sử dụng.', ARRAY['Enterprise', 'Endeavor', 'Project']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('fin-71', 'finance', 'Windfall', '/ˈwɪnd.fɑːl/', 'Noun', 'C1', 'Khoản lợi nhuận từ trên trời rơi xuống bất ngờ', 'An unexpected, unearned, or sudden gain or advantage, typically a sum of money.', 'Skyrocketing natural gas spot prices brought a multi-billion-dollar profit windfall to the energy firm.', 'Giá khí đốt tự nhiên giao ngay tăng vọt đã mang lại khoản lợi nhuận khổng lồ bất ngờ cho công ty năng lượng.', ARRAY['Bonanza', 'Jackpot', 'Sudden gain']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('fin-72', 'finance', 'Yield', '/jiːld/', 'Noun', 'B2', 'Lợi tức sinh lời từ khoản đầu tư', 'The income return on an investment, such as the interest or dividends received from holding a security.', 'High-yield savings accounts currently deliver competitive returns without market capital risks.', 'Các tài khoản tiết kiệm lợi suất cao hiện mang lại mức sinh lời hấp dẫn mà không phải chịu rủi ro vốn thị trường.', ARRAY['Return', 'Earnings', 'Payout']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('fin-73', 'finance', 'Zero-Sum', '/ˌzɪr.oʊ ˈsʌm/', 'Adj', 'C1', 'Trò chơi có tổng bằng không (người này được thì người khác mất)', 'Relating to a situation in which whatever is gained by one side is lost by the other.', 'Pure currency speculation is often categorized as a zero-sum financial game.', 'Đầu cơ tiền tệ thuần túy thường được xếp vào nhóm trò chơi tài chính có tổng bằng không.', ARRAY['Win-lose', 'Zero-sum game']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('fin-74', 'finance', 'Credit Line', '/ˈkred.ɪt ˌlaɪn/', 'Noun', 'B1', 'Hạn mức tín dụng ngân hàng cấp sẵn', 'An amount of credit extended to a borrower.', 'The manufacturing company tapped its revolving credit line to fund sudden raw material purchases.', 'Công ty sản xuất đã kích hoạt hạn mức tín dụng tuần hoàn để thanh toán các khoản mua nguyên liệu bất ngờ.', ARRAY['Credit facility', 'Borrowing limit']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('fin-75', 'finance', 'Annuity Plan', '/əˈnuː.ə.t̬i ˌplæn/', 'Noun', 'B2', 'Kế hoạch tích lũy niên kim hưu trí', 'A long-term investment that is issued by an insurance company and is designed to help protect you from the risk of outliving your income.', 'Choosing a lifetime annuity plan ensures steady monthly paychecks throughout retirement years.', 'Lựa chọn một kế hoạch niên kim trọn đời đảm bảo những tấm séc thu nhập hàng tháng ổn định suốt những năm hưu trí.', ARRAY['Retirement annuity', 'Pension plan']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('fin-76', 'finance', 'Bullish', '/ˈbʊl.ɪʃ/', 'Adj', 'B2', 'Lạc quan về xu hướng tăng giá thị trường', 'Characterized by optimism or certainty of price increases.', 'Institutional analysts remain strongly bullish on semiconductor chip manufacturers.', 'Các nhà phân tích tổ chức vẫn giữ quan điểm vô cùng lạc quan về xu hướng tăng giá của các nhà sản xuất chip bán dẫn.', ARRAY['Optimistic', 'Confident', 'Upbeat']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('fin-77', 'finance', 'Bearish', '/ˈber.ɪʃ/', 'Adj', 'B2', 'Bi quan dự báo thị trường sắp giảm giá', 'Characterized by pessimism, especially in the belief that stock prices will fall.', 'Mounting sovereign debt loads caused hedge fund managers to turn bearish on commercial banks.', 'Gánh nặng nợ quốc gia gia tăng đã khiến các nhà quản lý quỹ phòng hộ trở nên bi quan về nhóm ngân hàng thương mại.', ARRAY['Pessimistic', 'Negative', 'Downbeat']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('fin-78', 'finance', 'Capitalize', '/ˈkæp.ə.t̬əl.aɪz/', 'Verb', 'B2', 'Vốn hóa chi phí vào tài sản hoặc tận dụng cơ hội', 'Record an expenditure as an asset rather than an expense, or take advantage of an opportunity.', 'Companies can capitalize internal software development labor under strict accounting rules.', 'Các công ty có thể vốn hóa chi phí nhân công phát triển phần mềm nội bộ theo các quy tắc kế toán nghiêm ngặt.', ARRAY['Take advantage of', 'Fund']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('fin-79', 'finance', 'Compound Interest', '/ˌkɑːm.paʊnd ˈɪn.trɪst/', 'Noun', 'B2', 'Lãi kép, lãi mẹ đẻ lãi con kỳ diệu', 'Interest calculated on the initial principal, which also includes all of the accumulated interest from previous periods.', 'Albert Einstein famously described compound interest as the eighth wonder of the world.', 'Albert Einstein từng ví lãi kép một cách nổi tiếng như là kỳ quan thứ tám của thế giới.', ARRAY['Cumulative interest', 'Compounding']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('fin-80', 'finance', 'Credit Score', '/ˈkred.ɪt ˌskɔːr/', 'Noun', 'B1', 'Điểm số tín nhiệm tín dụng cá nhân', 'A number assigned to a person that indicates to lenders their capacity to repay a loan.', 'Maintaining a credit score above 750 qualifies borrowers for the lowest mortgage rates.', 'Duy trì điểm tín dụng trên 750 giúp người vay đủ điều kiện nhận các mức lãi suất thế chấp thấp nhất.', ARRAY['Credit rating', 'FICO score']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('fin-81', 'finance', 'Default Risk', '/dɪˈfɑːlt ˌrɪsk/', 'Noun', 'B2', 'Rủi ro vỡ nợ không trả được tiền vay', 'The risk that a lender takes on that the borrower will not be able to make required payments.', 'Credit default swaps allow institutional bondholders to insure against corporate default risk.', 'Các hợp đồng hoán đổi rủi ro tín dụng cho phép các trái chủ tổ chức mua bảo hiểm chống lại rủi ro vỡ nợ của doanh nghiệp.', ARRAY['Credit risk', 'Insolvency risk']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('fin-82', 'finance', 'Exchange Traded Fund', '/ɪksˈtʃeɪndʒ ˌtreɪ.dɪd ˈfʌnd/', 'Noun', 'B2', 'Quỹ hoán đổi danh mục giao dịch như cổ phiếu (ETF)', 'A type of pooled investment security that operates much like a mutual fund but trades on public stock exchanges.', 'Low-fee S&P 500 exchange traded funds are standard pillars in modern index investing.', 'Các quỹ ETF mô phỏng chỉ số S&P 500 với mức phí thấp là trụ cột tiêu chuẩn trong đầu tư chỉ số hiện đại.', ARRAY['ETF', 'Index fund']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('fin-83', 'finance', 'Hedge', '/hedʒ/', 'Verb', 'B2', 'Phòng ngừa và giảm thiểu tổn thất rủi ro', 'Protect oneself against loss on an investment or bet by making balancing or compensating other transactions.', 'Importers frequently buy forward contracts to hedge against sharp currency depreciations.', 'Các nhà nhập khẩu thường xuyên mua hợp đồng kỳ hạn để phòng ngừa rủi ro đồng tiền bị mất giá mạnh.', ARRAY['Protect', 'Safeguard', 'Counterbalance']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('fin-84', 'finance', 'Holdings', '/ˈhoʊl.dɪŋz/', 'Noun', 'B1', 'Toàn bộ tài sản hoặc cổ phần đang nắm giữ', 'Stocks, property, and other financial assets in someone''s possession.', 'The billionaire reduced his equity holdings across technology firms to increase cash reserves.', 'Tỷ phú đã giảm bớt số cổ phần đang nắm giữ tại các công ty công nghệ để tăng cường dự trữ tiền mặt.', ARRAY['Assets', 'Investments', 'Equities']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('fin-85', 'finance', 'Index', '/ˈɪn.deks/', 'Noun', 'B1', 'Chỉ số thị trường chứng khoán (VN-Index, S&P 500)', 'An indicator, sign, or measure of something; a benchmark tracking market movements.', 'The VN-Index surged thirty points driven by strong foreign institutional inflows.', 'Chỉ số VN-Index đã tăng vọt 30 điểm nhờ dòng vốn mua ròng mạnh mẽ từ các nhà đầu tư tổ chức nước ngoài.', ARRAY['Market gauge', 'Benchmark index']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('fin-86', 'finance', 'Junk Bond', '/ˈdʒʌŋk ˌbɑːnd/', 'Noun', 'C1', 'Trái phiếu rác lợi suất cao nhưng rủi ro vỡ nợ lớn', 'A high-yielding, high-risk security, typically issued by a company seeking to raise capital quickly in order to finance a takeover.', 'Pension funds are legally barred from holding high-risk junk bonds in their conservative portfolios.', 'Các quỹ hưu trí bị pháp luật nghiêm cấm nắm giữ các loại trái phiếu rác rủi ro cao trong danh mục thận trọng của họ.', ARRAY['High-yield bond', 'Speculative-grade bond']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('fin-87', 'finance', 'Leveraged Buyout', '/ˌlev.ɚ.ɪdʒd ˈbaɪ.aʊt/', 'Noun', 'C1', 'Thương vụ thâu tóm bằng vốn vay nợ (LBO)', 'The acquisition of another company using a significant amount of borrowed money to meet the cost of acquisition.', 'The Wall Street private equity firm financed the retail takeover through a massive leveraged buyout.', 'Công ty vốn tư nhân Phố Wall đã tài trợ cho thương vụ mua lại hãng bán lẻ thông qua một đòn bẩy tài chính khổng lồ.', ARRAY['LBO', 'Debt buyout']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('fin-88', 'finance', 'Market Capitalization', '/ˌmɑːr.kɪt ˌkæp.ə.t̬əl.əˈzeɪ.ʃən/', 'Noun', 'B2', 'Giá trị vốn hóa thị trường của doanh nghiệp', 'The value of a company that is traded on the stock market, calculated by multiplying total shares by current price.', 'The tech conglomerate''s market capitalization surpassed three trillion dollars.', 'Vốn hóa thị trường của tập đoàn công nghệ đã vượt qua mốc 3 nghìn tỷ USD.', ARRAY['Market cap', 'Equity valuation']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('fin-89', 'finance', 'Net Asset Value', '/ˌnet ˈæs.et ˌvæl.juː/', 'Noun', 'C1', 'Giá trị tài sản ròng trên mỗi chứng chỉ quỹ (NAV)', 'The value of a mutual fund that is reached by deducting the fund''s liabilities from the market value of all of its shares and dividing by the number of issued shares.', 'Fund managers calculate the net asset value of the portfolio at the close of every trading day.', 'Các nhà quản lý quỹ tính toán giá trị tài sản ròng của danh mục đầu tư vào cuối mỗi ngày giao dịch.', ARRAY['NAV', 'Net book value']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('fin-90', 'finance', 'Offshore Account', '/ˌɑːfˈʃɔːr əˈkaʊnt/', 'Noun', 'B2', 'Tài khoản ngân hàng nước ngoài tại các thiên đường thuế', 'A bank account located outside the country in which the depositor resides, often used for tax advantages.', 'Investigators audited multinational tax declarations to uncover hidden offshore accounts.', 'Các nhà điều tra đã kiểm toán các tờ khai thuế đa quốc gia để phát hiện những tài khoản nước ngoài bị che giấu.', ARRAY['Foreign account', 'Tax haven account']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('daily-1', 'daily', 'Acquaintance', '/əˈkweɪn.təns/', 'Noun', 'B1', 'Người quen biết sơ giao', 'A person one knows slightly, but who is not a close friend.', 'He greeted an old college acquaintance while waiting in line at the coffee shop.', 'Anh ấy đã chào một người quen thời đại học trong khi đứng xếp hàng tại quán cà phê.', ARRAY['Contact', 'Associate', 'Familiar']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('daily-2', 'daily', 'Spontaneous', '/spɑːnˈteɪ.ni.əs/', 'Adj', 'B2', 'Ngẫu hứng, tự phát không lên lịch trước', 'Performed or occurring as a result of a sudden inner impulse and without premeditation.', 'We took a spontaneous weekend road trip to the mountains without booking a hotel.', 'Chúng tôi đã có một chuyến phượt ngẫu hứng cuối tuần lên núi mà không hề đặt trước khách sạn.', ARRAY['Unplanned', 'Impulsive', 'Extemporaneous']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('daily-3', 'daily', 'Reluctant', '/rɪˈlʌk.tənt/', 'Adj', 'B1', 'Miễn cưỡng, ngập ngừng không muốn làm', 'Unwilling and hesitant; disinclined.', 'He was reluctant to attend the crowded party after an exhausting ten-hour workday.', 'Anh ấy rất miễn cưỡng khi phải tham dự bữa tiệc đông người sau một ngày làm việc 10 tiếng kiệt sức.', ARRAY['Hesitant', 'Unwilling', 'Averse']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('daily-4', 'daily', 'Ecstatic', '/ekˈstæt̬.ɪk/', 'Adj', 'B2', 'Vui mừng khôn xiết, ngập tràn hạnh phúc', 'Feeling or expressing overwhelming happiness or joyful excitement.', 'She was absolutely ecstatic when she opened the letter confirming her scholarship.', 'Cô ấy vô cùng mừng rỡ khi mở bức thư xác nhận cô được trao học bổng.', ARRAY['Elated', 'Thrilled', 'Euphoric']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('daily-5', 'daily', 'Mundane', '/mʌnˈdeɪn/', 'Adj', 'B2', 'Tầm thường, tẻ nhạt trong đời sống thường nhật', 'Lacking interest or excitement; dull; relating to the ordinary world.', 'Listening to entertaining podcasts makes mundane household chores much more enjoyable.', 'Nghe các tập podcast thú vị khiến những công việc nhà tẻ nhạt thường nhật trở nên thú vị hơn nhiều.', ARRAY['Ordinary', 'Everyday', 'Routine']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('daily-6', 'daily', 'Apprehensive', '/ˌæp.rəˈhen.sɪv/', 'Adj', 'B2', 'Lo âu, thấp thỏm về điều sắp xảy ra', 'Anxious or fearful that something bad or unpleasant will happen.', 'First-time home buyers often feel apprehensive before signing a thirty-year mortgage.', 'Những người mua nhà lần đầu thường cảm thấy thấp thỏm lo âu trước khi ký hợp đồng vay thế chấp 30 năm.', ARRAY['Anxious', 'Worried', 'Uneasy']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('daily-7', 'daily', 'Nostalgia', '/nɑːˈstæl.dʒə/', 'Noun', 'B2', 'Nỗi hoài niệm về ký ức tươi đẹp xưa cũ', 'A sentimental longing or wistful affection for the past, typically for a period with happy personal associations.', 'Looking at childhood photo albums filled him with sweet warmth and gentle nostalgia.', 'Ngắm nhìn những cuốn album ảnh thời thơ ấu khiến anh tràn ngập sự ấm áp ngọt ngào và nỗi hoài niệm êm dịu.', ARRAY['Reminiscence', 'Wistfulness', 'Homesickness']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('daily-8', 'daily', 'Exasperate', '/ɪɡˈzæs.pə.reɪt/', 'Verb', 'C1', 'Làm bực mình, khiến ai đó phát cáu', 'Irritate and frustrate someone intensely.', 'Endless unexpected traffic delays on the bridge completely exasperated the morning drivers.', 'Tình trạng kẹt xe chậm trễ bất tận trên cầu đã khiến những người lái xe buổi sáng hoàn toàn phát cáu.', ARRAY['Infuriate', 'Irritate', 'Annoy']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('daily-9', 'daily', 'Empathy', '/ˈem.pə.θi/', 'Noun', 'B2', 'Sự đồng cảm, thấu cảm với cảm xúc người khác', 'The ability to understand and share the feelings of another.', 'Active listening and deep empathy are the cornerstones of healthy personal relationships.', 'Lắng nghe tích cực và sự thấu cảm sâu sắc là nền tảng của các mối quan hệ cá nhân lành mạnh.', ARRAY['Compassion', 'Understanding', 'Sensitivity']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('daily-10', 'daily', 'Serenity', '/səˈren.ə.t̬i/', 'Noun', 'C1', 'Sự thanh bình, tĩnh lặng bình an trong tâm hồn', 'The state of being calm, peaceful, and untroubled.', 'Meditating near the tranquil mountain lake filled her with profound inner serenity.', 'Thiền định gần hồ nước trên núi tĩnh lặng đã mang lại cho cô sự bình an nội tâm sâu sắc.', ARRAY['Tranquility', 'Peacefulness', 'Calmness']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('daily-11', 'daily', 'Procrastinate', '/proʊˈkræs.tə.neɪt/', 'Verb', 'B2', 'Trì hoãn, chần chừ việc cần làm', 'Delay or postpone action; put off doing something.', 'It is easy to procrastinate on filing taxes until the final deadline approaches.', 'Rất dễ trì hoãn việc khai thuế cho đến khi thời hạn chót cận kề.', ARRAY['Delay', 'Put off', 'Dither']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('daily-12', 'daily', 'Punctual', '/ˈpʌŋk.tʃu.əl/', 'Adj', 'B1', 'Đúng giờ giấc, không bao giờ trễ', 'Happening or doing something at the agreed or proper time.', 'Being strictly punctual to doctor appointments demonstrates respect for the physician''s schedule.', 'Đúng giờ trong các buổi hẹn khám bác sĩ thể hiện sự tôn trọng đối với thời gian của bác sĩ.', ARRAY['On time', 'Prompt', 'Timely']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('daily-13', 'daily', 'Habitual', '/həˈbɪtʃ.u.əl/', 'Adj', 'B2', 'Quen thói, thành thói quen thường lệ', 'Done or doing constantly or as a habit.', 'His habitual morning routine consists of a twenty-minute jog followed by black coffee.', 'Thói quen buổi sáng quen thuộc của anh ấy gồm 20 phút chạy bộ và một ly cà phê đen.', ARRAY['Customary', 'Regular', 'Chronic']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('daily-14', 'daily', 'Insomnia', '/ɪnˈsɑːm.ni.ə/', 'Noun', 'B2', 'Chứng mất ngủ kinh niên', 'Habitual sleeplessness; inability to sleep.', 'Cutting down on late-night smartphone blue light is an effective remedy for mild insomnia.', 'Cắt giảm ánh sáng xanh từ điện thoại vào ban đêm là một liệu pháp hiệu quả cho chứng mất ngủ nhẹ.', ARRAY['Sleeplessness', 'Restlessness']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('daily-15', 'daily', 'Exhaustion', '/ɪɡˈzɑːs.tʃən/', 'Noun', 'B1', 'Sự kiệt sức hoàn toàn về thể xác lẫn tinh thần', 'A state of extreme physical or mental fatigue.', 'After studying through three nights for medical board finals, he collapsed from pure exhaustion.', 'Sau ba đêm thức trắng ôn thi tốt nghiệp y khoa, anh đã gục ngã vì hoàn toàn kiệt sức.', ARRAY['Fatigue', 'Weariness', 'Debility']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('daily-16', 'daily', 'Chores', '/tʃɔːrz/', 'Noun', 'A2', 'Việc vặt trong nhà (rửa bát, quét nhà, giặt đồ)', 'Routine tasks, especially household ones.', 'Doing weekly household chores together as a family fosters cooperation and responsibility.', 'Cùng nhau làm việc vặt gia đình hàng tuần nuôi dưỡng tinh thần hợp tác và trách nhiệm.', ARRAY['Housework', 'Daily tasks', 'Errands']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('daily-17', 'daily', 'Errand', '/ˈer.ənd/', 'Noun', 'B1', 'Chuyến đi làm việc vặt bên ngoài (mua sắm, gửi thư)', 'A short journey undertaken in order to deliver or collect something, especially on someone''s behalf.', 'I need to run a few quick errands this afternoon, including picking up my dry cleaning.', 'Chiều nay tôi cần chạy vài việc vặt, bao gồm cả việc lấy quần áo giặt là khô.', ARRAY['Task', 'Trip', 'Mission']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('daily-18', 'daily', 'Leisure', '/ˈliː.ʒɚ/', 'Noun', 'B1', 'Thời gian rảnh rỗi thư giãn', 'Use of free time for enjoyment.', 'Reading fiction novels and tending the garden are his favorite leisure activities.', 'Đọc tiểu thuyết hư cấu và chăm sóc khu vườn là những hoạt động giải trí lúc rảnh rỗi yêu thích của anh ấy.', ARRAY['Free time', 'Recreation', 'Spare time']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('daily-19', 'daily', 'Commute', '/kəˈmjuːt/', 'Noun', 'B1', 'Quãng đường và thời gian đi làm mỗi ngày', 'A regular journey of some distance to and from one''s place of work.', 'His daily forty-minute train commute gives him dedicated quiet time to read books.', 'Thời gian 40 phút đi tàu đi làm mỗi ngày mang lại cho anh ấy khoảng thời gian tĩnh lặng dành riêng để đọc sách.', ARRAY['Daily travel', 'Journey to work']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('daily-20', 'daily', 'Congestion', '/kənˈdʒes.tʃən/', 'Noun', 'B2', 'Sự tắc nghẽn giao thông đô thị', 'The state of being congested with traffic; crowding or clogging.', 'Heavy vehicular congestion during evening rush hour adds twenty minutes to the drive home.', 'Tình trạng tắc nghẽn giao thông nặng nề trong giờ cao điểm buổi tối làm chuyến lái xe về nhà lâu thêm 20 phút.', ARRAY['Gridlock', 'Traffic jam', 'Bottleneck']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('daily-21', 'daily', 'Grocery', '/ˈɡroʊ.sɚ.i/', 'Noun', 'A2', 'Thực phẩm và đồ dùng thiết yếu hàng ngày', 'Items of food in a grocery store or supermarket.', 'She ordered weekly household groceries online for same-day home delivery.', 'Cô ấy đã đặt mua thực phẩm thiết yếu hàng tuần qua mạng để được giao hàng tận nhà trong ngày.', ARRAY['Food items', 'Supermarket goods']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('daily-22', 'daily', 'Neighbourhood', '/ˈneɪ.bɚ.hʊd/', 'Noun', 'A2', 'Khu phố, xóm giềng nơi sinh sống', 'A district, especially one forming a community within a town or city.', 'The leafy green neighbourhood has safe bicycle lanes and several playground parks.', 'Khu phố rợp bóng cây xanh có các làn đường xe đạp an toàn và nhiều công viên sân chơi.', ARRAY['District', 'Locality', 'Community']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('daily-23', 'daily', 'Hospitality', '/ˌhɑː.spɪˈtæl.ə.t̬i/', 'Noun', 'B2', 'Sự đón tiếp niềm nở, lòng hiếu khách', 'The friendly reception and treatment of guests or strangers.', 'The newlyweds were touched by the warm hospitality shown by their new neighbors.', 'Cặp đôi mới cưới rất cảm động trước sự đón tiếp niềm nở, ấm áp của những người hàng xóm mới.', ARRAY['Warm welcome', 'Friendliness']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('daily-24', 'daily', 'Recreation', '/ˌrek.riˈeɪ.ʃən/', 'Noun', 'B1', 'Hoạt động giải trí, tái tạo năng lượng', 'Activity done for enjoyment when one is not working.', 'Playing badminton at the community center is an excellent form of evening recreation.', 'Chơi cầu lông tại nhà văn hóa cộng đồng là một hình thức giải trí buổi tối tuyệt vời.', ARRAY['Pastime', 'Leisure activity', 'Sport']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('daily-25', 'daily', 'Well-being', '/ˌwelˈbiː.ɪŋ/', 'Noun', 'B2', 'Sức khỏe thể chất và hạnh phúc tinh thần toàn diện', 'The state of being comfortable, healthy, or happy.', 'Maintaining regular physical exercise and balanced sleep is essential for overall well-being.', 'Duy trì tập thể dục đều đặn và giấc ngủ cân bằng là điều thiết yếu cho sức khỏe và hạnh phúc toàn diện.', ARRAY['Wellness', 'Health', 'Prosperity']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('daily-26', 'daily', 'Mindfulness', '/ˈmaɪnd.fəl.nəs/', 'Noun', 'B2', 'Sự chánh niệm, hiện diện trọn vẹn trong khoảnh khắc', 'The quality or state of being conscious or aware of something; a mental state achieved by focusing awareness on the present moment.', 'Practicing ten minutes of mindful breathing lowers cortisol stress hormone levels.', 'Thực hành 10 phút hít thở chánh niệm giúp làm giảm nồng độ hormone căng thẳng cortisol.', ARRAY['Present awareness', 'Consciousness']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('daily-27', 'daily', 'Resilience', '/rɪˈzɪl.jəns/', 'Noun', 'B2', 'Khả năng kiên cường phục hồi sau nghịch cảnh', 'The capacity to recover quickly from difficulties; toughness.', 'Emotional resilience enables individuals to bounce back stronger following career setbacks.', 'Khả năng phục hồi cảm xúc giúp con người đứng dậy mạnh mẽ hơn sau những thất bại trong sự nghiệp.', ARRAY['Hardiness', 'Fortitude', 'Tenacity']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('daily-28', 'daily', 'Gratitude', '/ˈɡræt̬.ə.tuːd/', 'Noun', 'B1', 'Lòng biết ơn trân trọng cuộc sống', 'The quality of being thankful; readiness to show appreciation for and to return kindness.', 'Keeping a nightly gratitude journal helps reframe daily stressors into positive perspectives.', 'Viết nhật ký biết ơn mỗi tối giúp chuyển đổi những căng thẳng hàng ngày thành góc nhìn tích cực.', ARRAY['Thankfulness', 'Appreciation', 'Gratefulness']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('daily-29', 'daily', 'Compassion', '/kəmˈpæʃ.ən/', 'Noun', 'B2', 'Lòng từ bi, trắc ẩn đối với nỗi đau người khác', 'Sympathetic pity and concern for the sufferings or misfortunes of others.', 'Showing genuine compassion towards struggling coworkers creates a supportive team culture.', 'Thể hiện lòng trắc ẩn chân thành đối với những đồng nghiệp đang gặp khó khăn sẽ tạo nên văn hóa đội ngũ hỗ trợ lẫn nhau.', ARRAY['Sympathy', 'Kindness', 'Benevolence']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('daily-30', 'daily', 'Self-Discipline', '/ˌselfˈdɪs.ə.plɪn/', 'Noun', 'B2', 'Kỷ luật bản thân, tự chủ thói quen', 'The ability to control one''s feelings and overcome one''s weaknesses; the ability to pursue what one thinks is right despite temptations.', 'Consistent self-discipline is far more reliable than fleeting temporary motivation.', 'Tính tự kỷ luật bền bỉ đáng tin cậy hơn rất nhiều so với những nguồn động lực ngắn ngủi nhất thời.', ARRAY['Willpower', 'Self-control', 'Restraint']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('daily-31', 'daily', 'Overwhelm', '/ˌoʊ.vɚˈwelm/', 'Verb', 'B2', 'Khiến ai đó quá tải ngợp lòng', 'Bury or drown beneath a huge mass of something, or defeat completely; have a strong emotional effect.', 'Juggling exams, a part-time job, and moving apartments threatened to overwhelm him.', 'Vừa lo thi cử, vừa làm việc bán thời gian lại phải chuyển nhà đe dọa sẽ khiến anh ấy quá tải.', ARRAY['Overburden', 'Inundate', 'Swamp']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('daily-32', 'daily', 'Catharsis', '/kəˈθɑːr.sɪs/', 'Noun', 'C1', 'Sự giải tỏa cảm xúc dồn nén nhẹ nhõm', 'The process of releasing, and thereby providing relief from, strong or repressed emotions.', 'Weeping openly during the poignant film provided a profound emotional catharsis.', 'Khóc nức nở khi xem bộ phim xúc động đã mang lại một sự giải tỏa cảm xúc sâu sắc và nhẹ nhõm.', ARRAY['Emotional release', 'Purging']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('daily-33', 'daily', 'Introvert', '/ˈɪn.trə.vɝːt/', 'Noun', 'B1', 'Người hướng nội thích không gian yên tĩnh', 'A shy, reticent person; someone who gets energy from solitary reflection.', 'As an introvert, she recharges her mental battery by spending a quiet evening reading.', 'Là một người hướng nội, cô ấy nạp lại năng lượng tinh thần bằng việc dành một buổi tối yên tĩnh để đọc sách.', ARRAY['Solitary person', 'Quiet thinker']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('daily-34', 'daily', 'Extrovert', '/ˈek.strə.vɝːt/', 'Noun', 'B1', 'Người hướng ngoại năng động thích giao lưu', 'An outgoing, overtly expressive person who thrives in social gatherings.', 'He is a natural extrovert who feels energized whenever surrounded by lively crowds.', 'Anh ấy là một người hướng ngoại bẩm sinh, luôn cảm thấy tràn đầy năng lượng khi được hòa mình trong đám đông sôi nổi.', ARRAY['Social butterfly', 'Outgoing person']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('daily-35', 'daily', 'Ambivert', '/ˈæm.bɪ.vɝːt/', 'Noun', 'B2', 'Người có cả nét tính cách hướng nội và hướng ngoại', 'A person who has a balance of extrovert and introvert features in their personality.', 'Most people are ambiverts, enjoying lively social events yet cherishing quiet downtime.', 'Phần lớn mọi người là người lưỡng hướng, vừa thích các sự kiện xã hội sôi động nhưng cũng trân trọng những khoảng lặng riêng tư.', ARRAY['Balanced personality']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('daily-36', 'daily', 'Overthink', '/ˌoʊ.vɚˈθɪŋk/', 'Verb', 'B1', 'Suy nghĩ quá nhiều, phức tạp hóa vấn đề', 'Think about something too much or for too long, causing needless worry.', 'Try not to overthink the interview; you prepared thoroughly and know your material.', 'Cố gắng đừng suy nghĩ quá nhiều về buổi phỏng vấn; bạn đã chuẩn bị rất kỹ lưỡng và nắm vững kiến thức.', ARRAY['Obsess over', 'Worry excessively']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('daily-37', 'daily', 'Contentment', '/kənˈtent.mənt/', 'Noun', 'B2', 'Sự mãn nguyện, hài lòng với thực tại', 'A state of happiness and satisfaction with one''s current circumstances.', 'True contentment comes from appreciating the present rather than relentlessly craving more.', 'Sự mãn nguyện thực sự đến từ việc trân trọng hiện tại thay vì không ngừng thèm muốn nhiều hơn.', ARRAY['Satisfaction', 'Fulfillment', 'Happiness']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('daily-38', 'daily', 'Bittersweet', '/ˌbɪt̬.ɚˈswiːt/', 'Adj', 'B2', 'Buồn vui lẫn lộn, ngọt ngào xen lẫn xót xa', 'Arousing pleasure tinged with sadness or regret.', 'Saying goodbye to their childhood hometown was a poignant, bittersweet experience.', 'Nói lời tạm biệt với thị trấn tuổi thơ là một trải nghiệm nghẹn ngào, buồn vui lẫn lộn.', ARRAY['Mixed feelings', 'Poignant']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('daily-39', 'daily', 'Heartwarming', '/ˈhɑːrtˌwɔːr.mɪŋ/', 'Adj', 'B1', 'Ấm áp cõi lòng, làm lay động tình cảm', 'Emotionally rewarding or uplifting, evoking feelings of happiness and kindness.', 'Watching the community unite to build an elderly widow''s house was truly heartwarming.', 'Chứng kiến cộng đồng chung tay xây dựng ngôi nhà cho bà cụ góa bụa thực sự làm ấm lòng mọi người.', ARRAY['Touching', 'Uplifting', 'Inspiring']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('daily-40', 'daily', 'Melancholy', '/ˈmel.əŋ.kɑːl.i/', 'Noun', 'C1', 'Nỗi buồn man mác, u hoài trầm lắng', 'A feeling of pensive sadness, typically with no obvious cause.', 'A gentle autumn rain always evokes a sense of contemplative melancholy in her heart.', 'Cơn mưa thu dịu nhẹ luôn gợi lên một nỗi buồn man mác trầm lắng trong lòng cô.', ARRAY['Sadness', 'Sorrow', 'Gloom']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('daily-41', 'daily', 'Jovial', '/ˈdʒoʊ.vi.əl/', 'Adj', 'C1', 'Vui vẻ hoạt bát, luôn tươi cười rạng rỡ', 'Cheerful and friendly; hearty and good-humored.', 'Our grandfather was a jovial host who greeted every guest with infectious laughter.', 'Ông của chúng tôi là một người chủ nhà vui vẻ, luôn chào đón từng vị khách bằng tràng cười lan tỏa.', ARRAY['Cheerful', 'Jolly', 'Genial']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('daily-42', 'daily', 'Compassionate', '/kəmˈpæʃ.ən.ət/', 'Adj', 'B2', 'Giàu lòng trắc ẩn và nhân ái', 'Feeling or showing sympathy and concern for others.', 'The nurse was exceptionally patient and compassionate with the elderly dementia patient.', 'Cô y tá đặc biệt kiên nhẫn và giàu lòng nhân ái với bệnh nhân cao tuổi mắc chứng sa sút trí tuệ.', ARRAY['Kind-hearted', 'Empathetic', 'Benevolent']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('daily-43', 'daily', 'Vulnerable', '/ˈvʌl.nɚ.ə.bəl/', 'Adj', 'B2', 'Dễ bị tổn thương tinh thần hoặc thể xác', 'Susceptible to physical or emotional attack or harm.', 'Opening up about past personal failures makes us feel emotionally vulnerable.', 'Bộc bạch về những thất bại cá nhân trong quá khứ khiến chúng ta cảm thấy dễ bị tổn thương cảm xúc.', ARRAY['Exposed', 'Defenseless', 'Sensitive']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('daily-44', 'daily', 'Appreciation', '/əˌpriː.ʃiˈeɪ.ʃən/', 'Noun', 'B1', 'Sự trân trọng và ghi nhận đóng góp', 'Recognition and enjoyment of the good qualities of someone or something.', 'A handwritten thank-you note is a sincere way to express appreciation to a mentor.', 'Một lá thư cảm ơn viết tay là cách chân thành để bày tỏ sự trân trọng tới người thầy hướng dẫn.', ARRAY['Gratitude', 'Recognition', 'Thanks']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('daily-45', 'daily', 'Optimistic', '/ˌɑːp.təˈmɪs.tɪk/', 'Adj', 'B1', 'Lạc quan, luôn nhìn về hướng tích cực', 'Hopeful and confident about the future.', 'Despite recent setbacks, the entrepreneur remained optimistic about the company''s prospects.', 'Bất chấp những trở ngại gần đây, doanh nhân vẫn lạc quan về triển vọng tương lai của công ty.', ARRAY['Hopeful', 'Positive', 'Upbeat']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('daily-46', 'daily', 'Pessimistic', '/ˌpes.əˈmɪs.tɪk/', 'Adj', 'B1', 'Bi quan, luôn nhìn vào mặt tiêu cực', 'Tending to see the worst aspect of things or believe that the worst will happen.', 'Constantly reading sensational doom-and-gloom news makes people overly pessimistic.', 'Liên tục đọc các tin tức giật gân u ám bi đát khiến con người trở nên quá đỗi bi quan.', ARRAY['Cynical', 'Negative', 'Gloomy']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('daily-47', 'daily', 'Introversion', '/ˌɪn.trəˈvɝː.ʒən/', 'Noun', 'B2', 'Khuynh hướng tính cách hướng nội', 'The quality of being shy and quiet, and preferring to spend time alone rather than with others.', 'Introversion should not be mistaken for social anxiety or lack of confidence.', 'Khuynh hướng hướng nội không nên bị nhầm lẫn với chứng lo âu xã hội hay sự thiếu tự tin.', ARRAY['Quietness', 'Reservedness']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('daily-48', 'daily', 'Extroversion', '/ˌek.strəˈvɝː.ʒən/', 'Noun', 'B2', 'Khuynh hướng tính cách hướng ngoại', 'The quality of being outgoing and socially confident.', 'Extroversion helps individuals comfortably strike up conversations with total strangers.', 'Tính hướng ngoại giúp mọi người thoải mái bắt chuyện với những người hoàn toàn xa lạ.', ARRAY['Outgoingness', 'Sociability']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('daily-49', 'daily', 'Assertive', '/əˈsɝː.t̬ɪv/', 'Adj', 'B2', 'Quyết đoán, biết bảo vệ quan điểm mà không thô lỗ', 'Having or showing a confident and forceful personality.', 'Learning to be politely assertive allows you to set firm healthy boundaries with coworkers.', 'Học cách quyết đoán một cách lịch thiệp cho phép bạn thiết lập những ranh giới lành mạnh và vững chắc với đồng nghiệp.', ARRAY['Confident', 'Decisive', 'Firm']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('daily-50', 'daily', 'Boundary', '/ˈbaʊn.dər.i/', 'Noun', 'B1', 'Ranh giới cá nhân cần tôn trọng', 'A line that marks the limits of an area; an emotional or psychological limit.', 'Setting clear personal boundaries is essential to protect your mental health from burnout.', 'Thiết lập các ranh giới cá nhân rõ ràng là điều thiết yếu để bảo vệ sức khỏe tâm thần của bạn khỏi kiệt sức.', ARRAY['Limit', 'Border', 'Threshold']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('daily-51', 'daily', 'Burnout', '/ˈbɝːn.aʊt/', 'Noun', 'B2', 'Tình trạng kiệt sức hoàn toàn do làm việc quá tải', 'Physical or mental collapse caused by overwork or stress.', 'Working eighty-hour weeks without a vacation inevitably leads to severe workplace burnout.', 'Làm việc 80 tiếng một tuần mà không nghỉ phép chắc chắn sẽ dẫn đến tình trạng kiệt quệ nghiêm trọng nơi công sở.', ARRAY['Exhaustion', 'Overwork fatigue', 'Collapse']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('daily-52', 'daily', 'Recharge', '/ˌriːˈtʃɑːrdʒ/', 'Verb', 'B1', 'Nạp lại năng lượng thể chất và tinh thần', 'Refill with electrical power; regain energy and enthusiasm.', 'A peaceful weekend walk through the forest helped him recharge after a grueling sprint.', 'Chuyến đi dạo cuối tuần thanh bình qua cánh rừng đã giúp anh nạp lại năng lượng sau một chu kỳ làm việc căng thẳng.', ARRAY['Refresh', 'Regenerate', 'Invigorate']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('daily-53', 'daily', 'Disconnect', '/ˌdɪs.kəˈnekt/', 'Verb', 'B1', 'Ngắt kết nối kỹ thuật số để thư giãn', 'Break the connection of something; unplug from electronic communications.', 'It is deeply therapeutic to disconnect from all social media notifications over the weekend.', 'Việc ngắt kết nối khỏi tất cả các thông báo mạng xã hội trong dịp cuối tuần mang lại cảm giác xoa dịu sâu sắc.', ARRAY['Unplug', 'Detach', 'Sever']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('daily-54', 'daily', 'Detox', '/ˈdiː.tɑːks/', 'Noun', 'B1', 'Thải độc cơ thể hoặc cai nghiện kỹ thuật số', 'A process or period of time in which one abstains from or rids the body of toxic substances; digital detox.', 'A seven-day digital detox helped her rediscover the serene joy of paper book reading.', 'Một đợt thanh lọc kỹ thuật số kéo dài 7 ngày đã giúp cô tìm lại niềm vui thanh bình khi đọc những cuốn sách giấy.', ARRAY['Purification', 'Cleansing']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('daily-55', 'daily', 'Simplicity', '/sɪmˈplɪs.ə.t̬i/', 'Noun', 'B2', 'Lối sống đơn giản, giản dị thanh tao', 'The quality or condition of being easy to understand or do; freedom from complexity.', 'Embracing voluntary simplicity allowed the family to live clutter-free and debt-free.', 'Áp dụng lối sống giản dị tự nguyện đã giúp gia đình sống một cuộc sống gọn gàng và không vướng bận nợ nần.', ARRAY['Clarity', 'Minimalism', 'Purity']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('daily-56', 'daily', 'Minimalism', '/ˈmɪn.ə.məl.ɪ.zəm/', 'Noun', 'B2', 'Chủ nghĩa tối giản, bớt đồ đạc hướng vào giá trị', 'A lifestyle philosophy that advocates living with fewer material possessions.', 'Practicing minimalism taught him to focus on enriching experiences rather than hoarding things.', 'Thực hành chủ nghĩa tối giản đã dạy anh tập trung vào những trải nghiệm phong phú thay vì tích trữ của cải đồ đạc.', ARRAY['Simple living', 'Essentialism']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('daily-57', 'daily', 'Routine', '/ruːˈtiːn/', 'Noun', 'A2', 'Lịch trình sinh hoạt cố định thường ngày', 'A sequence of actions regularly followed; a fixed program.', 'A consistent evening routine of warm chamomile tea and dim lights prepares the brain for restful sleep.', 'Lịch trình buổi tối quen thuộc với trà hoa cúc ấm và ánh đèn mờ giúp não bộ chuẩn bị cho giấc ngủ sâu.', ARRAY['Schedule', 'Habit', 'Pattern']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('daily-58', 'daily', 'Spontaneity', '/ˌspɑːn.təˈneɪ.ə.t̬i/', 'Noun', 'B2', 'Tính ngẫu hứng tự nhiên không gò bó', 'The condition of being spontaneous; spontaneous behavior or action.', 'Injecting a bit of spontaneity into long-term relationships keeps romance alive and playful.', 'Thêm một chút ngẫu hứng vào những mối quan hệ lâu năm sẽ giữ cho sự lãng mạn luôn tươi mới và tràn ngập niềm vui.', ARRAY['Impulsiveness', 'Naturalness', 'Whim']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('daily-59', 'daily', 'Perspective', '/pɚˈspek.tɪv/', 'Noun', 'B2', 'Góc nhìn, lăng kính nhân sinh quan', 'A particular attitude toward or way of regarding something; a point of view.', 'Traveling alone to distant foreign cultures broadens your perspective on what truly matters in life.', 'Đi du lịch một mình tới những nền văn hóa xa xôi giúp mở rộng góc nhìn của bạn về những điều thực sự quan trọng trong cuộc đời.', ARRAY['Point of view', 'Outlook', 'Stance']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('daily-60', 'daily', 'Humility', '/hjuːˈmɪl.ə.t̬i/', 'Noun', 'B2', 'Đức tính khiêm tốn nhún nhường', 'A modest or low view of one''s own importance; humbleness.', 'Great leaders balance supreme executive confidence with genuine intellectual humility.', 'Những nhà lãnh đạo vĩ đại luôn cân bằng giữa sự tự tin điều hành tối cao với đức tính khiêm tốn học hỏi chân thành.', ARRAY['Modesty', 'Humbleness', 'Meekness']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('daily-61', 'daily', 'Generosity', '/ˌdʒen.əˈrɑː.sə.t̬i/', 'Noun', 'B1', 'Lòng hào phóng rộng lượng', 'The quality of being kind and generous.', 'Her quiet generosity in sponsoring disadvantaged children''s tuition inspired the community.', 'Lòng hảo tâm thầm lặng của cô khi tài trợ học phí cho trẻ em có hoàn cảnh khó khăn đã truyền cảm hứng cho cả cộng đồng.', ARRAY['Magnanimity', 'Charity', 'Kindness']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('daily-62', 'daily', 'Integrity', '/ɪnˈteɡ.rə.t̬i/', 'Noun', 'B2', 'Sự chính trực, nhất quán đạo đức dù không ai nhìn', 'The quality of being honest and having strong moral principles.', 'True moral integrity means doing the right ethical thing even when nobody is watching.', 'Sự chính trực đạo đức đích thực nghĩa là luôn làm điều đúng đắn ngay cả khi không có ai nhìn thấy.', ARRAY['Honesty', 'Probity', 'Uprightness']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('daily-63', 'daily', 'Authenticity', '/ˌɑː.θenˈtɪs.ə.t̬i/', 'Noun', 'B2', 'Tính chân thật, sống thật với chính mình', 'The quality of being authentic; genuineness.', 'People are naturally drawn to leaders who exhibit vulnerability and emotional authenticity.', 'Mọi người tự nhiên bị thu hút bởi những nhà lãnh đạo dám thể hiện sự cởi mở và tính chân thực cảm xúc.', ARRAY['Genuineness', 'Originality', 'Realness']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('daily-64', 'daily', 'Courage', '/ˈkɝː.ɪdʒ/', 'Noun', 'B1', 'Lòng dũng cảm dám đối mặt nỗi sợ hãi', 'The ability to do something that frightens one; bravery.', 'It takes immense courage to walk away from a comfortable career to pursue your true passion.', 'Cần có một lòng dũng cảm to lớn để từ bỏ một sự nghiệp êm ấm nhằm theo đuổi đam mê đích thực của mình.', ARRAY['Bravery', 'Valor', 'Fearlessness']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('daily-65', 'daily', 'Perseverance', '/ˌpɝː.səˈvɪr.əns/', 'Noun', 'B2', 'Lòng kiên trì bền bỉ không bỏ cuộc', 'Persistence in doing something despite difficulty or delay in achieving success.', 'Through sheer stubborn perseverance, he mastered the complex violin concerto after two years of daily practice.', 'Nhờ lòng kiên trì bền bỉ phi thường, anh đã thành thạo bản hòa tấu vĩ cầm phức tạp sau hai năm khổ luyện mỗi ngày.', ARRAY['Persistence', 'Tenacity', 'Diligence']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('daily-66', 'daily', 'Patience', '/ˈpeɪ.ʃəns/', 'Noun', 'B1', 'Lòng kiên nhẫn nhẫn nại', 'The capacity to accept or tolerate delay, trouble, or suffering without getting angry or upset.', 'Gardening teaches the quiet virtue of patience as seeds slowly sprout over weeks.', 'Làm vườn dạy cho chúng ta đức tính kiên nhẫn lặng lẽ khi từng hạt giống từ từ nảy mầm qua nhiều tuần lễ.', ARRAY['Endurance', 'Tolerance', 'Forbearance']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('daily-67', 'daily', 'Curiosity', '/ˌkjʊr.iˈɑː.sə.t̬i/', 'Noun', 'B1', 'Tính hiếu kỳ, khát khao tò mò học hỏi', 'A strong desire to know or learn something.', 'Lifelong intellectual curiosity keeps our neural synapses sharp and active well into old age.', 'Khát khao học hỏi trí tuệ suốt đời giữ cho các khớp thần kinh của chúng ta luôn sắc bén và linh hoạt cho đến khi về già.', ARRAY['Inquisitiveness', 'Interest', 'Wonder']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('daily-68', 'daily', 'Adaptability', '/əˌdæp.təˈbɪl.ə.t̬i/', 'Noun', 'B2', 'Khả năng thích ứng linh hoạt trước thời cuộc', 'The quality of being able to adjust to new conditions or unexpected environments.', 'In a rapidly automating workplace, continuous learning and adaptability are prime survival skills.', 'Trong môi trường làm việc tự động hóa nhanh chóng, khả năng học tập liên tục và thích ứng linh hoạt là những kỹ năng sinh tồn hàng đầu.', ARRAY['Flexibility', 'Versatility', 'Agility']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('daily-69', 'daily', 'Creativity', '/ˌkriː.eɪˈtɪv.ə.t̬i/', 'Noun', 'B1', 'Tính sáng tạo tạo ra cái mới độc đáo', 'The use of imagination or original ideas to create something; inventiveness.', 'Playing with building blocks stimulates spatial imagination and boundless childhood creativity.', 'Chơi các khối xếp hình kích thích trí tưởng tượng không gian và sự sáng tạo vô biên của trẻ nhỏ.', ARRAY['Inventiveness', 'Imagination', 'Originality']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('daily-70', 'daily', 'Intuition', '/ˌɪn.tuːˈɪʃ.ən/', 'Noun', 'B2', 'Trực giác linh cảm mách bảo', 'The ability to understand something immediately, without the need for conscious reasoning.', 'Experienced chess grandmasters rely on sharp intuition to select winning moves in seconds.', 'Những đại kiện tướng cờ vua giàu kinh nghiệm dựa vào trực giác nhạy bén để chọn nước đi chiến thắng chỉ trong tích tắc.', ARRAY['Instinct', 'Gut feeling', 'Insight']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('daily-71', 'daily', 'Vibe', '/vaɪb/', 'Noun', 'B1', 'Bầu không khí hoặc cảm giác toát ra từ nơi chốn/người', 'A person''s emotional state or the atmosphere of a place as communicated to and felt by others.', 'The cozy neighborhood coffee shop has a wonderfully relaxing, creative vibe.', 'Quán cà phê ấm cúng trong khu phố mang lại một bầu không khí thư thái và sáng tạo tuyệt vời.', ARRAY['Atmosphere', 'Aura', 'Mood']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('daily-72', 'daily', 'Serendipity', '/ˌser.ənˈdɪp.ə.t̬i/', 'Noun', 'C1', 'Sự may mắn tình cờ bất ngờ thú vị', 'The occurrence and development of events by chance in a happy or beneficial way.', 'Finding her dream job while randomly chatting at an airport was a stroke of pure serendipity.', 'Tìm được công việc mơ ước khi đang trò chuyện ngẫu nhiên tại sân bay là một sự may mắn tình cờ kỳ diệu.', ARRAY['Chance', 'Happy accident', 'Fluke']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('daily-73', 'daily', 'Clutter', '/ˈklʌt̬.ɚ/', 'Noun', 'B1', 'Đồ đạc bừa bộn lộn xộn', 'A collection of things lying about in an untidy mass.', 'Clearing physical desk clutter instantly improves mental clarity and workplace productivity.', 'Dọn dẹp đồ đạc bừa bộn trên bàn làm việc giúp cải thiện ngay tức thì sự sáng suốt tinh thần và năng suất làm việc.', ARRAY['Disorder', 'Mess', 'Jumble']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('daily-74', 'daily', 'De-clutter', '/diːˈklʌt̬.ɚ/', 'Verb', 'B1', 'Dọn dẹp sắp xếp lại đồ đạc ngăn nắp', 'Remove unnecessary items from an untidy or overcrowded place.', 'Dedicate thirty minutes this Saturday to de-clutter your closet and donate unused garments.', 'Hãy dành 30 phút thứ Bảy này để dọn dẹp tủ quần áo và quyên góp những món đồ không dùng đến.', ARRAY['Tidy up', 'Organize', 'Purge']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('daily-75', 'daily', 'Sanctuary', '/ˈsæŋk.tʃu.er.i/', 'Noun', 'B2', 'Nơi chốn bình yên, chốn trú ẩn an toàn', 'A place of safety or refuge; a nature reserve.', 'Her quiet book-filled study serves as a serene sanctuary from the loud city streets.', 'Phòng đọc sách yên tĩnh ngập tràn sách của cô đóng vai trò như một chốn trú ẩn thanh bình tránh xa những đường phố ồn ào.', ARRAY['Haven', 'Refuge', 'Safe space']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('daily-76', 'daily', 'Solitude', '/ˈsɑː.lə.tuːd/', 'Noun', 'C1', 'Sự cô độc thanh tịnh tự nguyện để tái tạo', 'The state or situation of being alone, especially when pleasant and rejuvenating.', 'He cherishes the early morning solitude before the rest of the household awakens.', 'Anh ấy trân trọng sự tĩnh lặng thanh tịnh buổi sớm mai trước khi cả gia đình thức giấc.', ARRAY['Peaceful isolation', 'Aloneness', 'Quiet']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('daily-77', 'daily', 'Companionship', '/kəmˈpæn.jən.ʃɪp/', 'Noun', 'B2', 'Tình bạn bè đồng hành ấm áp', 'A feeling of fellowship or friendship.', 'Adopting a rescue golden retriever brought loyal companionship to the lonely pensioner.', 'Nhận nuôi một chú chó golden retriever đã mang lại tình bạn đồng hành trung thành cho người về hưu cô đơn.', ARRAY['Fellowship', 'Friendship', 'Camaraderie']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('daily-78', 'daily', 'Camaraderie', '/ˌkæm.əˈrɑː.dɚ.i/', 'Noun', 'C1', 'Tình đồng chí đồng đội gắn bó keo sơn', 'Mutual trust and friendship among people who spend a lot of time together.', 'The intense software bootcamp forged enduring camaraderie among the graduating engineers.', 'Khóa huấn luyện phần mềm cường độ cao đã tạo nên tình đồng đội gắn bó keo sơn giữa các kỹ sư tốt nghiệp.', ARRAY['Brotherhood', 'Comradeship', 'Solidarity']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('daily-79', 'daily', 'Nourish', '/ˈnɝː.ɪʃ/', 'Verb', 'B2', 'Nuôi dưỡng cơ thể hoặc tâm hồn', 'Provide with the food or other substances necessary for growth, health, and good condition.', 'Wholesome home-cooked soups nourish both the physical body and tired spirit.', 'Những bát súp nấu tại nhà bổ dưỡng nuôi dưỡng cả thể chất lẫn tinh thần mệt mỏi.', ARRAY['Feed', 'Nurture', 'Sustain']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('daily-80', 'daily', 'Nurture', '/ˈnɝː.tʃɚ/', 'Verb', 'B2', 'Chăm sóc ấp ủ nuôi lớn tài năng/mối quan hệ', 'Care for and encourage the growth or development of someone or something.', 'Parents should patiently nurture their children''s innate musical and artistic curiosities.', 'Cha mẹ nên kiên nhẫn nuôi dưỡng trí tò mò âm nhạc và nghệ thuật bẩm sinh của con cái.', ARRAY['Foster', 'Cultivate', 'Care for']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('daily-81', 'daily', 'Cherish', '/ˈtʃer.ɪʃ/', 'Verb', 'B2', 'Trân quý nâng niu yêu thương hết mực', 'Protect and care for someone lovingly; hold something dear in your heart.', 'Always cherish peaceful family dinners around the kitchen table after long days apart.', 'Hãy luôn trân quý những bữa cơm gia đình đầm ấm quanh bàn ăn sau những ngày dài xa cách.', ARRAY['Treasure', 'Prize', 'Hold dear']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('daily-82', 'daily', 'Reconcile', '/ˈrek.ən.saɪl/', 'Verb', 'B2', 'Hòa giải mâu thuẫn, làm lành sau bất đồng', 'Restore friendly relations between parties; make one belief compatible with another.', 'The two estranged siblings met over coffee to forgive past grievances and reconcile.', 'Hai anh em từng xa cách đã gặp nhau bên ly cà phê để tha thứ những khúc mắc xưa cũ và làm lành.', ARRAY['Make peace', 'Harmonize', 'Settle differences']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('daily-83', 'daily', 'Harmony', '/ˈhɑːr.mə.ni/', 'Noun', 'B1', 'Sự hòa thuận, hòa hợp êm ấm', 'The state of being in agreement or concord; pleasing arrangement of parts.', 'Living in harmony with nature inspires mindful consumption and reduced waste.', 'Sống chan hòa với thiên nhiên truyền cảm hứng cho việc tiêu dùng có ý thức và giảm thiểu rác thải.', ARRAY['Peace', 'Concord', 'Agreement']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('daily-84', 'daily', 'Fulfill', '/fʊlˈfɪl/', 'Verb', 'B1', 'Làm tròn bổn phận, hiện thực hóa ước mơ', 'Achieve or realize something desired, promised, or predicted; satisfy requirements.', 'Completing a marathon fulfilled her lifelong athletic aspiration.', 'Hoàn thành cự ly marathon đã hiện thực hóa khát vọng thể thao cả đời của cô.', ARRAY['Accomplish', 'Achieve', 'Realize']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('daily-85', 'daily', 'Fulfillment', '/fʊlˈfɪl.mənt/', 'Noun', 'B2', 'Cảm giác viên mãn tròn đầy hạnh phúc', 'Satisfaction or happiness as a result of fully developing one''s abilities or character.', 'Mentoring underprivileged teenagers brings him deep personal fulfillment and purpose.', 'Hướng dẫn các thanh thiếu niên có hoàn cảnh khó khăn mang lại cho anh cảm giác viên mãn và mục đích sống sâu sắc.', ARRAY['Satisfaction', 'Contentment', 'Attainment']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('daily-86', 'daily', 'Purpose', '/ˈpɝː.pəs/', 'Noun', 'B1', 'Mục đích, lẽ sống định hướng cuộc đời', 'The reason for which something is done or created or for which something exists.', 'Discovering your true life purpose gives you boundless drive to wake up excited every morning.', 'Khám phá ra lẽ sống đích thực của cuộc đời mang lại cho bạn động lực vô biên để thức dậy hào hứng mỗi sáng.', ARRAY['Meaning', 'Goal', 'Aim']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('daily-87', 'daily', 'Vibrant', '/ˈvaɪ.brənt/', 'Adj', 'B2', 'Sôi động rực rỡ tràn đầy nhựa sống', 'Full of energy and enthusiasm; bright and striking.', 'The evening street night market is filled with vibrant colors, live music, and sizzling street food.', 'Khu chợ đêm đường phố ngập tràn những sắc màu rực rỡ, âm nhạc sống động và những món ăn vỉa hè xèo xèo thơm phức.', ARRAY['Lively', 'Energetic', 'Spirited']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('daily-88', 'daily', 'Tranquil', '/ˈtræŋ.kwɪl/', 'Adj', 'B2', 'Thanh bình êm ả tĩnh mịch', 'Free from disturbance; calm and serene.', 'Rowing a wooden canoe on the tranquil morning lake washes away all worldly stress.', 'Chèo chiếc thuyền gỗ trên mặt hồ thanh bình buổi sớm mai gột rửa mọi căng thẳng hồng trần.', ARRAY['Serene', 'Peaceful', 'Placid']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('daily-89', 'daily', 'Bustling', '/ˈbʌs.lɪŋ/', 'Adj', 'B1', 'Nhộn nhịp tấp nập ngược xuôi', 'Full of energetic and noisy activity.', 'Ben Thanh Market is a bustling commercial center thronged with shoppers from dawn to dusk.', 'Chợ Bến Thành là trung tâm thương mại nhộn nhịp tấp nập người mua sắm từ sáng sớm tới đêm muộn.', ARRAY['Hectic', 'Lively', 'Crowded']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('daily-90', 'daily', 'Quaint', '/kweɪnt/', 'Adj', 'B2', 'Cổ kính mộc mạc duyên dáng', 'Attractively unusual or old-fashioned.', 'The riverside village is famous for its quaint wooden bridges and lantern-lit stone alleyways.', 'Ngôi làng ven sông nổi tiếng với những cây cầu gỗ mộc mạc cổ kính và những ngõ đá thắp đèn lồng duyên dáng.', ARRAY['Charming', 'Old-world', 'Picturesque']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('health-1', 'health', 'Diagnosis', '/ˌdaɪ.əɡˈnoʊ.sɪs/', 'Noun', 'B2', 'Sự chẩn đoán bệnh lý của bác sĩ', 'The identification of the nature of an illness or other problem by examination of the symptoms.', 'Early and accurate medical diagnosis significantly enhances cancer survival rates.', 'Chẩn đoán y khoa sớm và chính xác giúp tăng đáng kể tỷ lệ sống sót sau ung thư.', ARRAY['Identification', 'Detection', 'Assessment']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('health-2', 'health', 'Cardiovascular', '/ˌkɑːr.di.oʊˈvæs.kjə.lɚ/', 'Adj', 'B2', 'Thuộc về hệ tim mạch', 'Relating to the heart and blood vessels.', 'Aerobic swimming and brisk walking promote optimal cardiovascular health.', 'Bơi lội nhịp điệu và đi bộ nhanh thúc đẩy sức khỏe tim mạch tối ưu.', ARRAY['Cardiac', 'Heart-related', 'Circulatory']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('health-3', 'health', 'Prescription', '/prɪˈskrɪp.ʃən/', 'Noun', 'B1', 'Đơn thuốc do bác sĩ kê', 'An instruction written by a medical practitioner that authorizes a patient to be provided a medicine.', 'Take this written prescription to the licensed hospital pharmacy to collect your antibiotics.', 'Hãy mang đơn thuốc viết tay này tới nhà thuốc bệnh viện được cấp phép để lấy thuốc kháng sinh.', ARRAY['Rx', 'Doctor''s order', 'Medical order']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('health-4', 'health', 'Symptom', '/ˈsɪmp.təm/', 'Noun', 'B1', 'Triệu chứng dấu hiệu của bệnh', 'A physical or mental feature which is regarded as indicating a condition of disease.', 'Persistent dry coughing and high fever are hallmark symptoms of respiratory flu.', 'Ho khan dai dẳng và sốt cao là những triệu chứng tiêu biểu của bệnh cúm đường hô hấp.', ARRAY['Sign', 'Indication', 'Manifestation']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('health-5', 'health', 'Immunity', '/ɪˈmjuː.nə.t̬i/', 'Noun', 'B2', 'Khả năng miễn dịch chống lại bệnh tật', 'The ability of an organism to resist a particular infection or toxin by the action of specific antibodies.', 'Vaccination stimulates the production of antibodies, conferring lifelong protective immunity.', 'Tiêm chủng kích thích sản sinh kháng thể, mang lại khả năng miễn dịch bảo vệ suốt đời.', ARRAY['Resistance', 'Immunization', 'Protection']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('health-6', 'health', 'Nutritious', '/nuːˈtrɪʃ.əs/', 'Adj', 'B1', 'Bổ dưỡng, giàu giá trị dinh dưỡng', 'Nourishing, efficient as food; containing substances which your body needs to grow and be healthy.', 'A colorful bowl of fresh berries, nuts, and yogurt is a delightfully nutritious breakfast.', 'Một bát quả mọng tươi, hạt và sữa chua thơm ngon là một bữa sáng vô cùng bổ dưỡng.', ARRAY['Nourishing', 'Wholesome', 'Healthful']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('health-7', 'health', 'Sedentary', '/ˈsed.ən.ter.i/', 'Adj', 'B2', 'Thụ động, ít vận động ngồi một chỗ nhiều', 'Tending to spend much time seated; somewhat inactive.', 'A sedentary desk lifestyle elevates the long-term risk of developing chronic metabolic disorders.', 'Lối sống ngồi bàn làm việc thụ động làm tăng nguy cơ mắc các rối loạn chuyển hóa mãn tính lâu dài.', ARRAY['Inactive', 'Desk-bound', 'Stationary']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('health-8', 'health', 'Hypertension', '/ˌhaɪ.pɚˈten.ʃən/', 'Noun', 'B2', 'Chứng huyết áp cao', 'Abnormally high blood pressure.', 'Reducing dietary sodium salt intake is a vital lifestyle modification for managing hypertension.', 'Cắt giảm lượng muối natri trong chế độ ăn là thay đổi lối sống thiết yếu để kiểm soát huyết áp cao.', ARRAY['High blood pressure', 'Arterial pressure']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('health-9', 'health', 'Therapeutic', '/ˌθer.əˈpjuː.t̬ɪk/', 'Adj', 'B2', 'Có tính trị liệu, chữa lành', 'Relating to the healing of disease; having a good effect on body or mind.', 'Soaking in natural mineral hot springs has proven therapeutic benefits for aching joints.', 'Ngâm mình trong suối khoáng nóng tự nhiên đã được chứng minh mang lại lợi ích trị liệu cho các khớp đau nhức.', ARRAY['Healing', 'Curative', 'Restorative']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('health-10', 'health', 'Chronic', '/ˈkrɑː.nɪk/', 'Adj', 'B2', 'Mãn tính, kéo dài dai dẳng', 'Persisting for a long time or constantly recurring.', 'Physical rehabilitation exercises help patients manage chronic lower back pain without surgery.', 'Các bài tập phục hồi chức năng giúp bệnh nhân kiểm soát chứng đau thắt lưng mãn tính mà không cần phẫu thuật.', ARRAY['Persistent', 'Long-term', 'Protracted']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('health-11', 'health', 'Acute', '/əˈkjuːt/', 'Adj', 'B2', 'Cấp tính, bùng phát dữ dội tức thì', 'Present or experienced to a severe or intense degree; illness having a rapid onset.', 'The patient was rushed into the intensive care unit with acute appendicitis.', 'Bệnh nhân đã được đưa khẩn cấp vào phòng chăm sóc đặc biệt vì viêm ruột thừa cấp tính.', ARRAY['Severe', 'Critical', 'Sharp']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('health-12', 'health', 'Antibiotic', '/ˌæn.t̬i.baɪˈɑː.tɪk/', 'Noun', 'B1', 'Thuốc kháng sinh tiêu diệt vi khuẩn', 'A medicine that inhibits the growth of or destroys microorganisms.', 'Complete the full course of antibiotics prescribed by your doctor even if you feel better.', 'Hãy uống đủ liều lượng kháng sinh theo đơn của bác sĩ ngay cả khi bạn đã cảm thấy khỏe hơn.', ARRAY['Antimicrobial', 'Bactericide']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('health-13', 'health', 'Vaccine', '/vækˈsiːn/', 'Noun', 'B1', 'Vắc-xin phòng ngừa bệnh truyền nhiễm', 'A substance used to stimulate the production of antibodies and provide immunity against disease.', 'The discovery of the polio vaccine saved millions of children from lifelong paralysis.', 'Việc phát hiện ra vắc-xin bại liệt đã cứu hàng triệu trẻ em khỏi bị tàn tật suốt đời.', ARRAY['Immunization', 'Inoculation']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('health-14', 'health', 'Epidemic', '/ˌep.əˈdem.ɪk/', 'Noun', 'B2', 'Dịch bệnh bùng phát trên diện rộng', 'A widespread occurrence of an infectious disease in a community at a particular time.', 'Public health officials took swift measures to contain the local dengue fever epidemic.', 'Các quan chức y tế công cộng đã thực hiện các biện pháp nhanh chóng để kiềm chế dịch sốt xuất huyết tại địa phương.', ARRAY['Outbreak', 'Plague', 'Contagion']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('health-15', 'health', 'Pandemic', '/pænˈdem.ɪk/', 'Noun', 'B2', 'Đại dịch toàn cầu xuyên biên giới', 'An outbreak of a pandemic disease prevalent over a whole country or the world.', 'Global cooperation in vaccine manufacturing was critical during the recent respiratory pandemic.', 'Sự hợp tác toàn cầu trong việc sản xuất vắc-xin là điều tối quan trọng trong đợt đại dịch đường hô hấp vừa qua.', ARRAY['Global outbreak', 'Universal contagion']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('health-16', 'health', 'Metabolism', '/məˈtæb.əl.ɪ.zəm/', 'Noun', 'B2', 'Quá trình trao đổi chất của cơ thể', 'The chemical processes that occur within a living organism in order to maintain life.', 'High-intensity interval workouts temporarily boost your resting basal metabolism.', 'Các bài tập cường độ cao ngắt quãng tạm thời thúc đẩy quá trình trao đổi chất cơ bản lúc nghỉ ngơi của bạn.', ARRAY['Energy conversion', 'Metabolic rate']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('health-17', 'health', 'Pathogen', '/ˈpæθ.ə.dʒən/', 'Noun', 'C1', 'Mầm bệnh, tác nhân gây bệnh (vi khuẩn, virus)', 'A bacterium, virus, or other microorganism that can cause disease.', 'Handwashing with warm antibacterial soap removes harmful pathogens from skin surfaces.', 'Rửa tay bằng xà phòng kháng khuẩn ấm giúp loại bỏ các mầm bệnh có hại khỏi bề mặt da.', ARRAY['Infectious agent', 'Germ', 'Microbe']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('health-18', 'health', 'Allergy', '/ˈæl.ɚ.dʒi/', 'Noun', 'A2', 'Dị ứng với thực phẩm hoặc thời tiết', 'A damaging immune response by the body to a substance, especially a particular food, pollen, fur, or dust.', 'He carries an epinephrine injector due to a severe life-threatening peanut allergy.', 'Anh ấy luôn mang theo ống tiêm epinephrine do bị dị ứng đậu phộng nặng có thể đe dọa tính mạng.', ARRAY['Hypersensitivity', 'Allergic reaction']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('health-19', 'health', 'Rehabilitation', '/ˌriː.həˌbɪl.əˈteɪ.ʃən/', 'Noun', 'B2', 'Phục hồi chức năng sau chấn thương', 'The action of restoring someone to health or normal life through training and therapy.', 'Six months of physical rehabilitation restored full mobility to the athlete''s injured knee.', 'Sáu tháng phục hồi chức năng thể chất đã phục hồi hoàn toàn khả năng vận động cho khớp gối bị thương của vận động viên.', ARRAY['Rehab', 'Recovery therapy']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('health-20', 'health', 'Convalescence', '/ˌkɑːn.vəˈles.əns/', 'Noun', 'C1', 'Thời kỳ dưỡng bệnh hồi phục sức lực', 'Time spent recovering from an illness or medical treatment; recuperation.', 'A quiet seaside cottage provided the ideal restful setting for her post-surgery convalescence.', 'Ngôi nhà nhỏ yên tĩnh ven biển mang đến không gian nghỉ ngơi lý tưởng cho thời kỳ dưỡng bệnh sau phẫu thuật của bà.', ARRAY['Recuperation', 'Recovery period']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('health-21', 'health', 'Prognosis', '/prɑːɡˈnoʊ.sɪs/', 'Noun', 'C1', 'Tiên lượng diễn biến bệnh lý', 'The likely course of a medical condition; forecast.', 'Because the tumor was detected in stage one, the physician gave an overwhelmingly positive prognosis.', 'Vì khối u được phát hiện ở giai đoạn một, bác sĩ đã đưa ra tiên lượng vô cùng tích cực.', ARRAY['Forecast', 'Medical prediction']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('health-22', 'health', 'Incision', '/ɪnˈsɪʒ.ən/', 'Noun', 'B2', 'Vết rạch mổ phẫu thuật', 'A surgical cut made in skin or flesh.', 'Laparoscopic surgery requires only tiny puncture incisions, accelerating post-operative healing.', 'Phẫu thuật nội soi chỉ cần những vết rạch rạch siêu nhỏ, giúp đẩy nhanh quá trình hồi phục sau phẫu thuật.', ARRAY['Surgical cut', 'Slit']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('health-23', 'health', 'Anesthesia', '/ˌæn.əsˈθiː.ʒə/', 'Noun', 'B2', 'Thuốc gây mê hoặc gây tê phẫu thuật', 'Insensitivity to pain, especially as artificially induced by the administration of gases or the injection of drugs.', 'The anesthesiologist monitored heart rhythms closely throughout the entire general anesthesia procedure.', 'Bác sĩ gây mê đã theo dõi nhịp tim chặt chẽ trong suốt toàn bộ quá trình gây mê toàn thân.', ARRAY['Narcosis', 'Sedation']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('health-24', 'health', 'Cardiologist', '/ˌkɑːr.diˈɑː.lə.dʒɪst/', 'Noun', 'B2', 'Bác sĩ chuyên khoa tim mạch', 'A doctor who specializes in the study or treatment of heart diseases and heart abnormalities.', 'The cardiologist advised the patient to undergo a coronary angiography scan.', 'Bác sĩ tim mạch đã khuyên bệnh nhân nên thực hiện chụp mạch vành.', ARRAY['Heart specialist']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('health-25', 'health', 'Neurologist', '/nʊˈrɑː.lə.dʒɪst/', 'Noun', 'B2', 'Bác sĩ chuyên khoa thần kinh não bộ', 'A specialist in the anatomy, functions, and organic disorders of nerves and the nervous system.', 'The neurologist conducted an electroencephalogram to investigate the patient''s recurring migraines.', 'Bác sĩ thần kinh đã thực hiện điện não đồ để khảo sát các cơn đau nửa đầu tái phát của bệnh nhân.', ARRAY['Nerve specialist', 'Brain doctor']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('health-26', 'health', 'Orthopedics', '/ˌɔːr.θəˈpiː.dɪks/', 'Noun', 'B2', 'Khoa chấn thương chỉnh hình xương khớp', 'The branch of medicine dealing with the correction of deformities of bones or muscles.', 'The hospital''s department of orthopedics is internationally celebrated for hip replacement surgeries.', 'Khoa chấn thương chỉnh hình của bệnh viện nổi tiếng quốc tế về các ca phẫu thuật thay khớp háng.', ARRAY['Bone surgery', 'Musculoskeletal medicine']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('health-27', 'health', 'Pediatrician', '/ˌpiː.di.əˈtrɪʃ.ən/', 'Noun', 'B1', 'Bác sĩ chuyên khoa nhi', 'A medical practitioner specializing in children and their diseases.', 'The caring pediatrician weighed the newborn and administered the first scheduled childhood vaccine.', 'Bác sĩ nhi khoa chu đáo đã cân em bé sơ sinh và tiêm mũi vắc-xin theo lịch đầu tiên.', ARRAY['Child doctor', 'Baby specialist']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('health-28', 'health', 'Dermatologist', '/ˌdɝː.məˈtɑː.lə.dʒɪst/', 'Noun', 'B1', 'Bác sĩ chuyên khoa da liễu', 'A medical practitioner qualified to diagnose and treat skin disorders.', 'The dermatologist prescribed a gentle topical retinoid cream to clear stubborn acne.', 'Bác sĩ da liễu đã kê một loại kem bôi retinoid dịu nhẹ để làm sạch mụn trứng cá cứng đầu.', ARRAY['Skin specialist']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('health-29', 'health', 'Psychiatrist', '/səˈkaɪ.ə.trɪst/', 'Noun', 'B2', 'Bác sĩ chuyên khoa tâm thần điều trị thuốc', 'A medical practitioner specializing in the diagnosis and treatment of mental illness.', 'Unlike psychologists, licensed psychiatrists can prescribe clinical psychiatric medications.', 'Không giống như các nhà tâm lý học, các bác sĩ tâm thần được cấp phép có thể kê đơn các loại thuốc tâm thần lâm sàng.', ARRAY['Mental health doctor', 'Alienist']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('health-30', 'health', 'Hygiene', '/ˈhaɪ.dʒiːn/', 'Noun', 'B1', 'Vệ sinh phòng bệnh cá nhân', 'Conditions or practices conducive to maintaining health and preventing disease, especially through cleanliness.', 'Maintaining immaculate oral hygiene by flossing daily prevents periodontal gum disease.', 'Duy trì vệ sinh răng miệng sạch sẽ bằng cách dùng chỉ nha khoa hàng ngày giúp ngăn ngừa bệnh viêm nướu nha chu.', ARRAY['Cleanliness', 'Sanitation']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('health-31', 'health', 'Sanitation', '/ˌsæn.əˈteɪ.ʃən/', 'Noun', 'B2', 'Hệ thống vệ sinh xử lý nước thải công cộng', 'Conditions relating to public health, especially the provision of clean drinking water and adequate sewage disposal.', 'Improving urban sanitation infrastructure dramatically lowered infant mortality in cholera zones.', 'Cải thiện cơ sở hạ tầng vệ sinh đô thị đã làm giảm đáng kể tỷ lệ tử vong ở trẻ sơ sinh tại các vùng có dịch tả.', ARRAY['Public hygiene', 'Sewerage system']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('health-32', 'health', 'Deficiency', '/dɪˈfɪʃ.ən.si/', 'Noun', 'B2', 'Sự thiếu hụt dưỡng chất/vitamin', 'A lack or shortage of something, especially a vitamin or mineral in the body.', 'Iron deficiency is the leading clinical cause of fatigue and microcytic anemia in young women.', 'Thiếu hụt sắt là nguyên nhân lâm sàng hàng đầu gây mệt mỏi và thiếu máu hồng cầu nhỏ ở phụ nữ trẻ.', ARRAY['Shortage', 'Lack', 'Inadequacy']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('health-33', 'health', 'Supplements', '/ˈsʌp.lə.mənts/', 'Noun', 'B1', 'Thực phẩm chức năng bổ sung dinh dưỡng', 'A substance taken to remedy the deficiency or enhance the effect of diet.', 'Elderly individuals living in cloudy northern latitudes frequently take daily vitamin D supplements.', 'Người cao tuổi sống ở những vĩ độ phía bắc nhiều mây thường xuyên uống bổ sung vitamin D hàng ngày.', ARRAY['Nutritional additives', 'Dietary aids']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('health-34', 'health', 'Hydration', '/haɪˈdreɪ.ʃən/', 'Noun', 'B1', 'Cung cấp đủ nước cho cơ thể', 'The process of causing something to absorb water; maintaining fluid balance in the body.', 'Optimal bodily hydration improves skin elasticity, kidney filtration, and cognitive alertness.', 'Cung cấp đủ nước cho cơ thể giúp cải thiện độ đàn hồi của da, quá trình lọc của thận và sự tỉnh táo của nhận thức.', ARRAY['Fluid intake', 'Moisturization']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('health-35', 'health', 'Dehydration', '/ˌdiː.haɪˈdreɪ.ʃən/', 'Noun', 'B1', 'Tình trạng mất nước nguy hiểm', 'A dangerous lack of water in the body resulting from inadequate intake of fluids or excessive loss.', 'Severe dehydration during a marathon can precipitate heat exhaustion and kidney strain.', 'Mất nước nghiêm trọng trong một cuộc chạy marathon có thể dẫn đến kiệt sức vì nóng và căng thẳng cho thận.', ARRAY['Fluid deficit', 'Water loss']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('health-36', 'health', 'Obesity', '/oʊˈbiː.sə.t̬i/', 'Noun', 'B1', 'Bệnh béo phì quá mức', 'The state of being grossly fat or overweight, causing severe health risks.', 'Childhood obesity has surged due to the proliferation of hyper-processed fast foods.', 'Béo phì ở trẻ em đã tăng vọt do sự gia tăng của các loại thực phẩm chế biến sẵn quá mức.', ARRAY['Adiposity', 'Excess weight', 'Corpulence']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('health-37', 'health', 'Cholesterol', '/kəˈles.tə.rɑːl/', 'Noun', 'B1', 'Chất béo cholesterol trong máu', 'A compound of the sterol type found in most body tissues, important in cell membranes but harmful in excess.', 'High levels of LDL cholesterol can build up inside arterial walls, forming dangerous plaques.', 'Nồng độ cholesterol LDL cao có thể tích tụ bên trong thành động mạch, hình thành các mảng bám nguy hiểm.', ARRAY['Blood lipid', 'Sterol']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('health-38', 'health', 'Antioxidant', '/ˌæn.t̬iˈɑːk.sɪ.dənt/', 'Noun', 'B2', 'Chất chống oxy hóa ngăn ngừa lão hóa tế bào', 'A substance that inhibits oxidation, especially one used to counteract the deterioration of stored food products or remove potentially damaging oxidizing agents in a living organism.', 'Green tea and dark cocoa are celebrated sources of potent natural polyphenol antioxidants.', 'Trà xanh và ca cao đen là những nguồn cung cấp chất chống oxy hóa polyphenol tự nhiên mạnh mẽ được tôn vinh.', ARRAY['Free radical scavenger', 'Preservative']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('health-39', 'health', 'Calorie', '/ˈkæl.ɚ.i/', 'Noun', 'A2', 'Đơn vị đo năng lượng calo từ thức ăn', 'The energy needed to raise the temperature of 1 gram of water through 1 °C, now frequently used to measure food energy.', 'Tracking your daily caloric balance determines whether you gain, lose, or maintain body weight.', 'Theo dõi sự cân bằng lượng calo hàng ngày sẽ quyết định xem bạn tăng, giảm hay duy trì cân nặng của cơ thể.', ARRAY['Energy unit', 'Food energy']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('health-40', 'health', 'Endurance', '/ɪnˈdʊr.əns/', 'Noun', 'B2', 'Sức bền thể lực và độ dẻo dai', 'The fact or power of enduring an unpleasant or difficult process or situation without giving way.', 'Long-distance cycling develops exceptional cardiovascular stamina and muscular endurance.', 'Đạp xe đường dài giúp phát triển sức bền tim mạch vượt trội và độ dẻo dai của cơ bắp.', ARRAY['Stamina', 'Staying power', 'Fortitude']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('health-41', 'health', 'Stamina', '/ˈstæm.ə.nə/', 'Noun', 'B2', 'Thể lực dẻo dai bền bỉ', 'The ability to sustain prolonged physical or mental effort.', 'Elite marathon athletes possess extraordinary respiratory stamina and mental fortitude.', 'Các vận động viên marathon ưu tú sở hữu thể lực hô hấp phi thường và sự kiên cường về tinh thần.', ARRAY['Endurance', 'Toughness', 'Energy']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('health-42', 'health', 'Flexibility', '/ˌflek.səˈbɪl.ə.t̬i/', 'Noun', 'B1', 'Độ dẻo dai linh hoạt của cơ bắp', 'The quality of bending easily without breaking; the ability of joints to move through a full range of motion.', 'Practicing gentle Hatha yoga every morning enhances joint mobility and spine flexibility.', 'Thực hành Hatha yoga nhẹ nhàng mỗi sáng giúp tăng cường khả năng vận động của khớp và sự linh hoạt của cột sống.', ARRAY['Suppleness', 'Elasticity', 'Mobility']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('health-43', 'health', 'Strength Training', '/ˈstreŋθ ˌtreɪ.nɪŋ/', 'Noun', 'B1', 'Tập luyện sức mạnh kháng lực cơ bắp', 'A type of physical exercise specializing in the use of resistance to induce muscular contraction.', 'Regular strength training preserves vital bone density and lean skeletal muscle mass as we age.', 'Tập luyện sức kháng lực thường xuyên giúp bảo tồn mật độ xương thiết yếu và khối lượng cơ xương nạc khi chúng ta già đi.', ARRAY['Resistance training', 'Weightlifting']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('health-44', 'health', 'Aerobic', '/erˈoʊ.bɪk/', 'Adj', 'B1', 'Có oxy, bài tập hiếu khí tăng nhịp tim', 'Relating to, involving, or requiring free oxygen; exercise designed to improve the oxygen system.', 'Running, cycling, and rowing are classic examples of cardiovascular aerobic conditioning.', 'Chạy bộ, đạp xe và chèo thuyền là những ví dụ kinh điển về việc rèn luyện hiếu khí cho tim mạch.', ARRAY['Oxygen-using', 'Cardio']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('health-45', 'health', 'Anaerobic', '/ˌæn.erˈoʊ.bɪk/', 'Adj', 'B2', 'Yếm khí, bài tập bùng nổ ngắn không cần oxy', 'Relating to or requiring an absence of free oxygen; exercise consisting of brief, intense bursts.', 'Sprinting 100 meters relies entirely on rapid anaerobic energy pathways within muscle fibers.', 'Chạy nước rút 100 mét phụ thuộc hoàn toàn vào các con đường năng lượng yếm khí nhanh chóng bên trong các sợi cơ.', ARRAY['Oxygen-independent', 'High-intensity']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('health-46', 'health', 'Wellness', '/ˈwel.nəs/', 'Noun', 'B1', 'Lối sống khỏe mạnh toàn diện thân tâm trí', 'The state of being in good health, especially as an actively pursued goal.', 'The corporate wellness program offers employees free access to yoga and mental health therapy.', 'Chương trình chăm sóc sức khỏe toàn diện của công ty cung cấp cho nhân viên quyền truy cập miễn phí vào các buổi tập yoga và trị liệu tâm lý.', ARRAY['Holistic health', 'Well-being']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('health-47', 'health', 'Longevity', '/lɑːnˈdʒev.ə.t̬i/', 'Noun', 'C1', 'Tuổi thọ cao, sự sống lâu dài', 'Long life; the fact of having a long existence.', 'Mediterranean diets rich in cold-pressed extra virgin olive oil are strongly correlated with longevity.', 'Chế độ ăn Địa Trung Hải giàu dầu ô liu nguyên chất ép lạnh có mối tương quan chặt chẽ với tuổi thọ cao.', ARRAY['Long life', 'Durability']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('health-48', 'health', 'Addiction', '/əˈdɪk.ʃən/', 'Noun', 'B1', 'Sự nghiện ngập (thuốc lá, rượu, cờ bạc)', 'The fact or condition of being addicted to a particular substance, thing, or activity.', 'Nicotine addiction can develop within just a few weeks of habitual cigarette smoking.', 'Chứng nghiện nicotin có thể phát triển chỉ trong vài tuần hút thuốc lá theo thói quen.', ARRAY['Dependency', 'Habit', 'Obsession']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('health-49', 'health', 'Detoxification', '/diːˌtɑːk.sə.fəˈkeɪ.ʃən/', 'Noun', 'B2', 'Quá trình đào thải độc tố của gan và thận', 'The physiological or medicinal removal of toxic substances from a living organism.', 'The human liver performs intricate biochemical detoxification twenty-four hours a day.', 'Gan người thực hiện quá trình giải độc sinh hóa phức tạp suốt 24 giờ một ngày.', ARRAY['Detox', 'Purification', 'Cleansing']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('health-50', 'health', 'Remission', '/rɪˈmɪʃ.ən/', 'Noun', 'C1', 'Giai đoạn thuyên giảm tạm thời của bệnh ung thư', 'A temporary diminution of the severity of disease or pain.', 'After six grueling rounds of chemotherapy, the patient was overjoyed to hear she was in full remission.', 'Sau 6 đợt hóa trị mệt mỏi, bệnh nhân đã vỡ òa vui sướng khi biết tin bệnh của cô đã thuyên giảm hoàn toàn.', ARRAY['Abatement', 'Relief', 'Lull']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('health-51', 'health', 'Relapse', '/ˈriː.læps/', 'Noun', 'B2', 'Sự tái phát bệnh sau khi đã đỡ', 'A deterioration in someone''s state of health after a temporary improvement.', 'Patients must continue taking maintenance medications to prevent an unexpected clinical relapse.', 'Bệnh nhân phải tiếp tục dùng thuốc duy trì để ngăn ngừa sự tái phát lâm sàng bất ngờ.', ARRAY['Recurrence', 'Worsening', 'Regression']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('health-52', 'health', 'Palliative', '/ˈpæl.i.ə.t̬ɪv/', 'Adj', 'C1', 'Giảm nhẹ triệu chứng mà không trị dứt điểm', 'Relieving pain without dealing with the cause of the condition; palliative care.', 'Palliative hospice care focuses on providing compassionate comfort and pain relief to terminal patients.', 'Chăm sóc xoa dịu tại các viện chăm sóc cuối đời tập trung vào việc mang lại sự thoải mái đầy nhân ái và giảm đau cho bệnh nhân giai đoạn cuối.', ARRAY['Soothing', 'Alleviating', 'Comforting']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('health-53', 'health', 'Inoculate', '/ɪˈnɑː.kjə.leɪt/', 'Verb', 'C1', 'Tiêm chủng vắc-xin tạo miễn dịch', 'Treat a person or an animal with a vaccine to produce immunity against a disease.', 'Public health teams traveled to remote rural villages to inoculate children against measles.', 'Các đội y tế công cộng đã đến các làng quê hẻo lánh để tiêm chủng cho trẻ em phòng bệnh sởi.', ARRAY['Vaccinate', 'Immunize']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('health-54', 'health', 'Quarantine', '/ˈkwɔːr.ən.tiːn/', 'Noun', 'B2', 'Cách ly kiểm dịch y tế để ngăn lây lan', 'A state, period, or place of isolation in which people or animals that have been exposed to infectious disease are placed.', 'International cargo travelers exposed to yellow fever were placed in a fourteen-day medical quarantine.', 'Những người đi lại chở hàng quốc tế tiếp xúc với bệnh sốt vàng da đã được đưa vào cách ly y tế trong 14 ngày.', ARRAY['Isolation', 'Seclusion', 'Lockdown']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('health-55', 'health', 'Contagious', '/kənˈteɪ.dʒəs/', 'Adj', 'B2', 'Dễ lây nhiễm qua tiếp xúc thông thường', 'Spread from one person or organism to another by direct or indirect contact.', 'The common rhinovirus is exceptionally contagious in crowded air-conditioned offices.', 'Virus gây cảm lạnh thông thường đặc biệt dễ lây lan trong các văn phòng đông người có máy lạnh.', ARRAY['Infectious', 'Transmissible', 'Catching']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('health-56', 'health', 'Genetic', '/dʒəˈnet̬.ɪk/', 'Adj', 'B2', 'Thuộc về di truyền gen', 'Relating to genes or heredity.', 'Advances in molecular CRISPR tools allow scientists to repair rare genetic defects in human embryos.', 'Những tiến bộ trong các công cụ phân tử CRISPR cho phép các nhà khoa học sửa chữa các khiếm khuyết di truyền hiếm gặp trong phôi người.', ARRAY['Hereditary', 'Inborn', 'Biological']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('health-57', 'health', 'Hereditary', '/həˈred.ə.ter.i/', 'Adj', 'B2', 'Có tính di truyền từ đời cha mẹ', 'Conferred by or based on inheritance; determined by genetic factors and able to be passed on from parents.', 'Certain forms of early cardiac arrhythmia are strictly hereditary within specific family lineages.', 'Một số dạng loạn nhịp tim sớm hoàn toàn mang tính di truyền trong các dòng họ gia đình cụ thể.', ARRAY['Inherited', 'Familial', 'Inborn']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('health-58', 'health', 'Congenital', '/kənˈdʒen.ə.t̬əl/', 'Adj', 'C1', 'Bẩm sinh có từ khi chào đời', 'Present from birth, especially of a disease or physical abnormality.', 'The surgeon successfully repaired the infant''s congenital atrial heart defect.', 'Bác sĩ phẫu thuật đã sửa chữa thành công khiếm khuyết tim thông liên nhĩ bẩm sinh của trẻ sơ sinh.', ARRAY['Inborn', 'Innate', 'Native']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('health-59', 'health', 'Trauma', '/ˈtrɑː.mə/', 'Noun', 'B2', 'Chấn thương thể xác nặng hoặc sang chấn tâm lý', 'A deeply distressing or disturbing experience, or physical injury.', 'Emergency paramedics stabilized the patient''s blunt abdominal trauma before hospital transport.', 'Các nhân viên y tế khẩn cấp đã ổn định chấn thương bụng kín của bệnh nhân trước khi vận chuyển đến bệnh viện.', ARRAY['Injury', 'Damage', 'Shock']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('health-60', 'health', 'Concussion', '/kənˈkʌʃ.ən/', 'Noun', 'B2', 'Chấn động não sau cú va đập mạnh', 'Temporary unconsciousness or confusion caused by a blow on the head.', 'The football player was removed from the field to be medically evaluated for a suspected cerebral concussion.', 'Cầu thủ bóng đá đã được đưa ra khỏi sân để được đánh giá y tế về một chấn động não đáng ngờ.', ARRAY['Brain injury', 'Head trauma']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('health-61', 'health', 'Fracture', '/ˈfræk.tʃɚ/', 'Noun', 'B2', 'Vết nứt, rạn hoặc gãy xương', 'The cracking or breaking of a hard object or material, especially a bone.', 'An X-ray scan revealed a hairline bone fracture across the athlete''s right wrist.', 'Hình ảnh chụp X-quang cho thấy một vết rạn xương hình sợi tóc trên cổ tay phải của vận động viên.', ARRAY['Break', 'Crack', 'Rupture']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('health-62', 'health', 'Sprain', '/spreɪn/', 'Noun', 'B1', 'Bong gân mắt cá hoặc khớp', 'Wrench or twist the ligaments of an ankle, wrist, or other joint violently so as to cause pain and swelling.', 'Applying cold ice packs reduces painful swelling after an acute ankle sprain.', 'Chườm túi đá lạnh giúp giảm sưng đau sau một đợt bong gân mắt cá chân cấp tính.', ARRAY['Twist', 'Strain', 'Pull']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('health-63', 'health', 'Inflammation', '/ˌɪn.fləˈmeɪ.ʃən/', 'Noun', 'B2', 'Tình trạng viêm sưng tấy đau nhức', 'A localized physical condition in which part of the body becomes reddened, swollen, hot, and often painful.', 'Anti-inflammatory drugs were administered to decrease swelling and inflammation around the spinal cord.', 'Thuốc chống viêm đã được dùng để giảm sưng và viêm xung quanh tủy sống.', ARRAY['Swelling', 'Soreness', 'Infection']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('health-64', 'health', 'Bandage', '/ˈbæn.dɪdʒ/', 'Noun', 'A2', 'Băng gạc y tế quấn vết thương', 'A strip of material used to bind up a wound or to protect an injured part of the body.', 'The nurse wrapped a sterile cotton bandage firmly around the stitched wound.', 'Cô y tá đã quấn một dải băng bông vô trùng chắc chắn xung quanh vết thương đã được khâu.', ARRAY['Dressing', 'Gauze', 'Wrap']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('health-65', 'health', 'Sterile', '/ˈster.əl/', 'Adj', 'B2', 'Vô trùng tuyệt đối không có vi khuẩn', 'Free from bacteria or other living microorganisms; entirely clean.', 'Surgeons must scrub their hands thoroughly before entering the sterile operating theater.', 'Các bác sĩ phẫu thuật phải rửa tay kỹ lưỡng trước khi bước vào phòng mổ vô trùng.', ARRAY['Antiseptic', 'Disinfected', 'Aseptic']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('health-66', 'health', 'Disinfectant', '/ˌdɪs.ɪnˈfek.tənt/', 'Noun', 'B1', 'Dung dịch khử trùng sát khuẩn', 'A chemical liquid that destroys bacteria.', 'Hospital staff regularly wipe down intensive care bedrails with high-potency disinfectant.', 'Nhân viên bệnh viện thường xuyên lau các thanh chắn giường chăm sóc đặc biệt bằng chất khử trùng có hiệu lực cao.', ARRAY['Antiseptic', 'Sanitizer', 'Germicide']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('health-67', 'health', 'Syringe', '/səˈrɪndʒ/', 'Noun', 'B1', 'Ống tiêm tiêm thuốc hoặc lấy máu', 'A tube with a nozzle and piston for sucking in and ejecting liquid in a thin stream, used for injections.', 'The laboratory phlebotomist used a disposable sterile syringe to draw blood for the lipid panel.', 'Kỹ thuật viên phòng thí nghiệm đã dùng ống tiêm vô trùng dùng một lần để lấy máu làm xét nghiệm bộ mỡ.', ARRAY['Needle', 'Injector']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('health-68', 'health', 'Scalpel', '/ˈskæl.pəl/', 'Noun', 'B2', 'Dao mổ phẫu thuật sắc bén', 'A knife with a small, sharp, sometimes detachable blade, used by a surgeon.', 'The neurosurgeon guided the micro-scalpel with sub-millimeter precision under a high-powered microscope.', 'Bác sĩ phẫu thuật thần kinh đã điều khiển dao mổ vi phẫu với độ chính xác dưới một milimet dưới kính hiển vi công suất cao.', ARRAY['Surgical blade', 'Lancet']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('health-69', 'health', 'Stethoscope', '/ˈsteθ.ə.skoʊp/', 'Noun', 'B1', 'Ống nghe tim phổi của bác sĩ', 'A medical instrument for listening to the action of someone''s heart or breathing.', 'The physician placed the cold metal stethoscope against the child''s chest to listen to heart sounds.', 'Bác sĩ đặt ống nghe kim loại lạnh vào ngực đứa trẻ để lắng nghe tiếng tim.', ARRAY['Auscultator']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('health-70', 'health', 'Thermometer', '/θɚˈmɑː.mə.t̬ɚ/', 'Noun', 'A2', 'Nhiệt kế đo thân nhiệt', 'An instrument for measuring and indicating temperature, especially one consisting of a graduated glass tube.', 'The digital infrared thermometer registered a body temperature of 38.5 degrees Celsius.', 'Nhiệt kế hồng ngoại kỹ thuật số ghi nhận nhiệt độ cơ thể là 38,5 độ C.', ARRAY['Temperature gauge']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('health-71', 'health', 'Ointment', '/ˈɔɪnt.mənt/', 'Noun', 'B1', 'Thuốc mỡ bôi ngoài da', 'A smooth oily substance that is rubbed on the skin for medicinal purposes or as a cosmetic.', 'Gently apply the soothing herbal ointment to the sunburned skin three times a day.', 'Nhẹ nhàng thoa thuốc mỡ thảo dược làm dịu lên vùng da bị cháy nắng ba lần một ngày.', ARRAY['Salve', 'Balm', 'Cream']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('health-72', 'health', 'Capsule', '/ˈkæp.suːl/', 'Noun', 'B1', 'Viên thuốc con nhộng dễ nuốt', 'A small case or container, especially a round or cylindrical one, containing a dose of medicine.', 'Swallow two antibiotic capsules with a large glass of pure water after every meal.', 'Uống hai viên nang kháng sinh với một ly nước lọc lớn sau mỗi bữa ăn.', ARRAY['Pill', 'Tablet']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('health-73', 'health', 'Tablet', '/ˈtæb.lət/', 'Noun', 'A2', 'Viên thuốc nén', 'A small disc or cylinder of compressed solid matter, typically containing a dose of medicine.', 'Take one pain-relieving tablet every six hours as needed for dental discomfort.', 'Uống một viên thuốc giảm đau mỗi 6 giờ một lần khi cần nếu cảm thấy khó chịu ở răng.', ARRAY['Pill', 'Lozenge']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('health-74', 'health', 'Dosage', '/ˈdoʊ.sɪdʒ/', 'Noun', 'B1', 'Liều lượng thuốc dùng mỗi lần', 'The size or frequency of a dose of a medicine or drug.', 'Exceeding the recommended dosage of acetaminophen can cause irreversible liver damage.', 'Vượt quá liều lượng khuyến cáo của paracetamol có thể gây tổn thương gan không thể phục hồi.', ARRAY['Dose', 'Prescribed amount']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('health-75', 'health', 'Side Effect', '/ˈsaɪd ɪˌfekt/', 'Noun', 'B1', 'Tác dụng phụ không mong muốn của thuốc', 'A secondary, typically undesirable effect of a drug or medical treatment.', 'Drowsiness and dry mouth are common, harmless side effects of older antihistamine allergy pills.', 'Buồn ngủ và khô miệng là những tác dụng phụ phổ biến, vô hại của các loại thuốc chống dị ứng kháng histamin cũ.', ARRAY['Adverse reaction', 'Secondary effect']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('health-76', 'health', 'Overdose', '/ˈoʊ.vɚ.doʊs/', 'Noun', 'B1', 'Dùng thuốc quá liều nguy kịch', 'An excessive and dangerous dose of a drug.', 'Paramedics administered naloxone to reverse the critical respiratory depression from an accidental opioid overdose.', 'Các nhân viên y tế đã tiêm naloxone để đảo ngược tình trạng suy hô hấp nguy kịch do vô tình dùng quá liều opioid.', ARRAY['Excessive dose', 'Drug toxicity']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('health-77', 'health', 'Intravenous', '/ˌɪn.trəˈviː.nəs/', 'Adj', 'B2', 'Truyền trực tiếp vào tĩnh mạch (IV)', 'Existing or taking place within, or administered into, a vein or veins.', 'Dehydrated hospital patients received rapid intravenous saline rehydration infusions through a catheter.', 'Bệnh nhân bị mất nước tại bệnh viện đã được truyền bù nước bằng dung dịch muối trực tiếp vào tĩnh mạch nhanh chóng qua ống thông.', ARRAY['IV', 'Endovenous']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('health-78', 'health', 'Blood Transfusion', '/ˈblʌd trænsˌfjuː.ʒən/', 'Noun', 'B2', 'Truyền máu cấp cứu', 'An injection of a volume of blood, previously taken from a healthy person, into a patient.', 'The emergency trauma victim required an urgent four-unit whole blood transfusion.', 'Nạn nhân chấn thương khẩn cấp cần được truyền khẩn cấp 4 đơn vị máu toàn phần.', ARRAY['Blood infusion']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('health-79', 'health', 'Biopsy', '/ˈbaɪ.ɑːp.si/', 'Noun', 'B2', 'Sinh thiết mô bệnh học tìm tế bào lạ', 'An examination of tissue removed from a living body to discover the presence, cause, or extent of a disease.', 'The laboratory biopsy confirmed that the lymph node swelling was entirely benign, not cancerous.', 'Sinh thiết phòng thí nghiệm xác nhận rằng sự sưng hạch bạch huyết hoàn toàn lành tính, không phải ung thư.', ARRAY['Tissue test', 'Histology sample']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('health-80', 'health', 'Benign', '/bɪˈnaɪn/', 'Adj', 'B2', 'U lành tính, không gây nguy hiểm tính mạng', 'Of a disease: not harmful in effect, not malignant or cancerous.', 'Fortunately, the MRI confirmed the brain lesion was benign and required no radiation therapy.', 'May mắn thay, kết quả chụp MRI xác nhận tổn thương não là lành tính và không cần phải xạ trị.', ARRAY['Harmless', 'Non-cancerous', 'Non-malignant']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('health-81', 'health', 'Malignant', '/məˈlɪɡ.nənt/', 'Adj', 'C1', 'U ác tính, ung thư di căn nguy hiểm', 'Of a disease: very virulent or infectious; malevolent; cancerous.', 'Malignant tumors have the dangerous ability to invade surrounding healthy tissue and metastasize.', 'Các khối u ác tính có khả năng nguy hiểm là xâm lấn các mô khỏe mạnh xung quanh và di căn.', ARRAY['Cancerous', 'Deadly', 'Destructive']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('health-82', 'health', 'Metastasis', '/məˈtæs.tə.sɪs/', 'Noun', 'C1', 'Sự di căn của tế bào ung thư sang cơ quan khác', 'The development of secondary malignant growths at a distance from a primary site of cancer.', 'Targeted immunotherapy medications aim to halt tumor cell division and prevent distant metastasis.', 'Thuốc liệu pháp miễn dịch nhắm trúng đích nhằm mục đích ngăn chặn sự phân chia tế bào khối u và ngăn chặn sự di căn xa.', ARRAY['Cancer spread', 'Secondary growth']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('health-83', 'health', 'Chemotherapy', '/ˌkiː.moʊˈθer.ə.pi/', 'Noun', 'B2', 'Hóa trị liệu tiêu diệt tế bào ung thư', 'The treatment of disease by the use of chemical substances, especially the treatment of cancer by cytotoxic drugs.', 'Modern chemotherapy regimens use targeted infusions that minimize severe nausea.', 'Các phác đồ hóa trị hiện đại sử dụng các phương pháp truyền nhắm trúng đích giúp giảm thiểu tối đa cảm giác buồn nôn nghiêm trọng.', ARRAY['Chemo', 'Cytotoxic therapy']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('health-84', 'health', 'Radiotherapy', '/ˌreɪ.di.oʊˈθer.ə.pi/', 'Noun', 'B2', 'Xạ trị bằng tia bức xạ chiếu ngoài', 'The treatment of disease, especially cancer, using X-rays or similar forms of radiation.', 'Stereotactic radiotherapy directs high-dose radiation beams precisely at the spinal tumor while sparing nerves.', 'Xạ trị định vị hướng chùm bức xạ liều cao chính xác vào khối u cột sống mà không làm tổn thương các dây thần kinh.', ARRAY['Radiation therapy', 'Irradiation']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('health-85', 'health', 'Hospice', '/ˈhɑː.spɪs/', 'Noun', 'B2', 'Bệnh viện chăm sóc giảm nhẹ cuối đời', 'A home providing care for the sick or terminally ill.', 'The serene hospice provides peaceful comfort and emotional support for both patients and their families.', 'Bệnh viện chăm sóc cuối đời thanh tịnh cung cấp sự thoải mái yên bình và hỗ trợ tinh thần cho cả bệnh nhân và gia đình của họ.', ARRAY['Palliative facility', 'End-of-life care']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('env-1', 'environment', 'Sustainability', '/səˌsteɪ.nəˈbɪl.ə.t̬i/', 'Noun', 'B2', 'Sự phát triển bền vững không cạn kiệt tài nguyên', 'The ability to be maintained at a certain rate or level; avoidance of the depletion of natural resources in order to maintain an ecological balance.', 'Urban sustainability initiatives prioritize green public transit and zero-carbon building designs.', 'Các sáng kiến phát triển bền vững đô thị ưu tiên giao thông công cộng xanh và thiết kế tòa nhà không phát thải carbon.', ARRAY['Eco-balance', 'Endurance', 'Viability']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('env-2', 'environment', 'Renewable', '/rɪˈnuː.ə.bəl/', 'Adj', 'B1', 'Năng lượng tái tạo vô tận (gió, mặt trời, thủy triều)', 'Capable of being renewed, especially of a source of energy that is not depleted by use.', 'Investing in renewable wind and solar energy drastically cuts national fossil fuel reliance.', 'Đầu tư vào năng lượng gió và mặt trời tái tạo giúp cắt giảm đáng kể sự phụ thuộc của quốc gia vào nhiên liệu hóa thạch.', ARRAY['Sustainable', 'Inexhaustible', 'Green']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('env-3', 'environment', 'Emissions', '/iˈmɪʃ.ənz/', 'Noun', 'B2', 'Khí thải công nghiệp và phương tiện giao thông', 'The production and discharge of something, especially gas or radiation.', 'Strict industrial regulations mandate a fifty percent cut in factory sulfur emissions.', 'Các quy định công nghiệp nghiêm ngặt bắt buộc phải cắt giảm 50% lượng khí thải lưu huỳnh từ nhà máy.', ARRAY['Discharges', 'Effluents', 'Exhaust']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('env-4', 'environment', 'Ecosystem', '/ˈiː.koʊˌsɪs.təm/', 'Noun', 'B1', 'Hệ sinh thái tự nhiên quần tụ sinh vật', 'A biological community of interacting organisms and their physical environment.', 'Coral reefs form a fragile marine ecosystem supporting a quarter of all sea life.', 'Các rạn san hô hình thành một hệ sinh thái biển mỏng manh nuôi dưỡng một phần tư tổng số sinh vật biển.', ARRAY['Biosystem', 'Ecological community', 'Habitat']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('env-5', 'environment', 'Deforestation', '/diːˌfɔːr.əˈsteɪ.ʃən/', 'Noun', 'B2', 'Nạn phá rừng bừa bãi', 'The action of clearing a wide area of trees.', 'Tropical deforestation drives thousands of endangered indigenous species toward extinction.', 'Nạn phá rừng nhiệt đới đẩy hàng ngàn loài sinh vật bản địa có nguy cơ tuyệt chủng vào bờ vực diệt vong.', ARRAY['Forest clearance', 'Logging', 'Tree clearing']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('env-6', 'environment', 'Habitat', '/ˈhæb.ə.tæt/', 'Noun', 'B1', 'Môi trường sống tự nhiên của muôn loài', 'The natural home or environment of an animal, plant, or other organism.', 'The national park provides a protected wilderness habitat for rare Indochinese tigers.', 'Vườn quốc gia cung cấp một môi trường sống hoang dã được bảo vệ cho loài hổ Đông Dương quý hiếm.', ARRAY['Natural territory', 'Biotope', 'Home ground']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('env-7', 'environment', 'Biodiversity', '/ˌbaɪ.oʊ.daɪˈvɝː.sə.t̬i/', 'Noun', 'B2', 'Sự đa dạng sinh học các loài', 'The variety of plant and animal life in the world or in a particular habitat, a high level of which is usually considered to be important and desirable.', 'The Amazon rainforest harbors the most astounding biodiversity on planet Earth.', 'Rừng nhiệt đới Amazon lưu giữ sự đa dạng sinh học đáng kinh ngạc nhất trên hành tinh Trái Đất.', ARRAY['Ecological variety', 'Biological richness']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('env-8', 'environment', 'Carbon Footprint', '/ˌkɑːr.bən ˈfʊt.prɪnt/', 'Noun', 'B2', 'Dấu chân carbon phát thải từ hoạt động cá nhân/tổ chức', 'The amount of carbon dioxide and other carbon compounds emitted due to the consumption of fossil fuels by a particular person, group, etc.', 'Switching to plant-based diets significantly shrinks your personal carbon footprint.', 'Chuyển sang chế độ ăn thuần thực vật giúp thu nhỏ đáng kể dấu chân carbon cá nhân của bạn.', ARRAY['Emissions total', 'Environmental impact']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('env-9', 'environment', 'Conservation', '/ˌkɑːn.sɚˈveɪ.ʃən/', 'Noun', 'B2', 'Công tác bảo tồn tự nhiên và di sản', 'The prevention of wasteful use of a resource; preservation and protection of natural resources.', 'Wildlife conservation organizations work tirelessly to shield endangered black rhinos from poachers.', 'Các tổ chức bảo tồn động vật hoang dã làm việc không mệt mỏi để bảo vệ loài tê giác đen có nguy cơ tuyệt chủng khỏi những kẻ săn trộm.', ARRAY['Preservation', 'Protection', 'Safeguarding']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('env-10', 'environment', 'Pollution', '/pəˈluː.ʃən/', 'Noun', 'A2', 'Sự ô nhiễm nguồn nước, không khí và đất đai', 'The presence in or introduction into the environment of a substance or thing that has harmful or poisonous effects.', 'Industrial chemical runoff is the main cause of heavy river pollution downstream.', 'Nước thải hóa chất công nghiệp là nguyên nhân chính gây ô nhiễm sông ngòi nặng nề ở hạ lưu.', ARRAY['Contamination', 'Fouling', 'Degradation']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('env-11', 'environment', 'Afforestation', '/æfˌɔːr.əˈsteɪ.ʃən/', 'Noun', 'C1', 'Trồng rừng phủ xanh đất trống đồi trọc', 'The establishment of a forest or stand of trees in an area where there was no previous tree cover.', 'Government incentives funded massive afforestation initiatives across barren arid hillsides.', 'Các chính sách khuyến khích của chính phủ đã tài trợ cho các sáng kiến trồng rừng quy mô lớn trên các sườn đồi khô cằn trơ trọi.', ARRAY['Tree planting', 'Forest creation']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('env-12', 'environment', 'Reforestation', '/ˌriːˌfɔːr.əˈsteɪ.ʃən/', 'Noun', 'B2', 'Trồng lại rừng sau khai thác hoặc cháy rừng', 'The process of replanting an area with trees.', 'Volunteer groups organized the reforestation of coastal mangrove buffers damaged by storms.', 'Các nhóm tình nguyện đã tổ chức trồng lại rừng ngập mặn ven biển bị tàn phá bởi bão lũ.', ARRAY['Replanting', 'Regeneration']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('env-13', 'environment', 'Aquifer', '/ˈæk.wə.fɚ/', 'Noun', 'C1', 'Tầng ngậm nước ngầm dưới lòng đất', 'A body of permeable rock which can contain or transmit groundwater.', 'Over-pumping groundwater threatens to deplete the regional agricultural aquifer permanently.', 'Việc bơm hút nước ngầm quá mức đe dọa làm cạn kiệt vĩnh viễn tầng ngậm nước nông nghiệp của khu vực.', ARRAY['Groundwater reservoir', 'Water table']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('env-14', 'environment', 'Biodegradable', '/ˌbaɪ.oʊ.dɪˈɡreɪ.də.bəl/', 'Adj', 'B2', 'Tự phân hủy sinh học tự nhiên', 'Capable of being decomposed by bacteria or other living organisms.', 'Modern takeout packaging is made from biodegradable cornstarch instead of non-recyclable plastic.', 'Bao bì đồ ăn mang về hiện đại được làm từ tinh bột ngô có thể phân hủy sinh học thay vì nhựa không thể tái chế.', ARRAY['Decomposable', 'Eco-friendly']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('env-15', 'environment', 'Compost', '/ˈkɑːm.poʊst/', 'Noun', 'B1', 'Phân hữu cơ ủ từ rác thải thực vật', 'Decayed organic material used as a plant fertilizer.', 'Turning vegetable kitchen scraps into rich garden compost enriches soil microbes naturally.', 'Biến các mảnh vụn rau củ trong bếp thành phân hữu cơ giàu dinh dưỡng giúp làm giàu vi sinh vật đất một cách tự nhiên.', ARRAY['Organic fertilizer', 'Humus', 'Mulch']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('env-16', 'environment', 'Desalination', '/diːˌsæl.əˈneɪ.ʃən/', 'Noun', 'C1', 'Khử mặn nước biển thành nước ngọt uống được', 'The process of removing salt and other minerals from water, especially sea water.', 'Arid Gulf nations rely on reverse osmosis desalination plants for their entire municipal drinking supply.', 'Các quốc gia vùng Vịnh khô cằn dựa vào các nhà máy khử mặn thẩm thấu ngược cho toàn bộ nguồn nước uống đô thị.', ARRAY['Salt removal', 'Water purification']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('env-17', 'environment', 'Drought', '/draʊt/', 'Noun', 'B1', 'Hạn hán kéo dài khô cằn', 'A prolonged period of abnormally low rainfall, leading to a shortage of water.', 'A severe multi-year drought shriveled wheat crops and drove up global grain prices.', 'Một đợt hạn hán nghiêm trọng kéo dài nhiều năm đã làm teo tóp mùa màng lúa mì và đẩy giá ngũ cốc toàn cầu lên cao.', ARRAY['Dry spell', 'Water shortage', 'Aridity']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('env-18', 'environment', 'Effluent', '/ˈef.lu.ənt/', 'Noun', 'C1', 'Nước thải công nghiệp xả thẳng ra nguồn nước', 'Liquid waste or sewage discharged into a river or the sea.', 'The textile dying factory was shut down for discharging toxic untreated effluent into the river.', 'Nhà máy nhuộm dệt đã bị đóng cửa vì xả nước thải độc hại chưa qua xử lý ra sông.', ARRAY['Wastewater', 'Industrial discharge', 'Sewage']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('env-19', 'environment', 'Endangered', '/ɪnˈdeɪn.dʒɚd/', 'Adj', 'B1', 'Có nguy cơ tuyệt chủng trong tự nhiên', 'Seriously at risk of extinction.', 'The Javan rhinoceros is one of the most critically endangered large mammals on Earth.', 'Tê giác Java là một trong những loài động vật có vú lớn có nguy cơ tuyệt chủng nghiêm trọng nhất trên Trái Đất.', ARRAY['Threatened', 'At risk', 'Vulnerable']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('env-20', 'environment', 'Extinction', '/ɪkˈstɪŋk.ʃən/', 'Noun', 'B2', 'Sự tuyệt chủng biến mất vĩnh viễn', 'The state or process of a species, family, or larger group being or becoming extinct.', 'Meteor impact was the primary cause of dinosaur extinction sixty-six million years ago.', 'Cú va chạm của thiên thạch là nguyên nhân chính dẫn đến sự tuyệt chủng của loài khủng long cách đây 66 triệu năm.', ARRAY['Dying out', 'Eradication', 'Extermination']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('env-21', 'environment', 'Fossil Fuel', '/ˈfɑː.səl ˌfjuː.əl/', 'Noun', 'B1', 'Nhiên liệu hóa thạch (than đá, dầu mỏ, khí đốt)', 'A natural fuel such as coal or gas, formed in the geological past from the remains of living organisms.', 'Burning fossil fuels accounts for the vast majority of atmospheric greenhouse gas pollution.', 'Đốt nhiên liệu hóa thạch chiếm đại đa số lượng ô nhiễm khí nhà kính trong khí quyển.', ARRAY['Hydrocarbon fuel', 'Coal and oil']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('env-22', 'environment', 'Geothermal', '/ˌdʒiː.oʊˈθɝː.məl/', 'Adj', 'B2', 'Địa nhiệt từ lòng đất núi lửa', 'Relating to or produced by the internal heat of the earth.', 'Iceland generates nearly all of its electricity and district heating from clean geothermal vents.', 'Iceland tạo ra gần như toàn bộ điện năng và hệ thống sưởi ấm khu vực từ các lỗ phun địa nhiệt sạch.', ARRAY['Earth-heat', 'Subterranean energy']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('env-23', 'environment', 'Greenhouse Effect', '/ˈɡriːn.haʊs ɪˌfekt/', 'Noun', 'B1', 'Hiệu ứng nhà kính giữ nhiệt làm ấm trái đất', 'The trapping of the sun''s warmth in a planet''s lower atmosphere due to the greater transparency of the atmosphere to visible radiation from the sun than to infrared radiation emitted from the planet''s surface.', 'The anthropogenic greenhouse effect is driving unprecedented rises in global average temperatures.', 'Hiệu ứng nhà kính do con người gây ra đang dẫn đến sự gia tăng nhiệt độ trung bình toàn cầu chưa từng có.', ARRAY['Atmospheric warming', 'Heat trapping']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('env-24', 'environment', 'Hydroelectric', '/ˌhaɪ.droʊ.ɪˈlek.trɪk/', 'Adj', 'B1', 'Thủy điện khai thác sức nước', 'Relating to or denoting the generation of electricity using flowing water (typically from a reservoir).', 'The Son La hydroelectric dam is the largest renewable energy generating station in Southeast Asia.', 'Đập thủy điện Sơn La là trạm phát năng lượng tái tạo lớn nhất ở Đông Nam Á.', ARRAY['Water-powered', 'Hydropower']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('env-25', 'environment', 'Incineration', '/ɪnˌsɪn.əˈreɪ.ʃən/', 'Noun', 'B2', 'Thiêu hủy rác thải trong lò nhiệt độ cao', 'The destruction of something, especially waste material, by burning.', 'Modern waste-to-energy incineration facilities capture emissions and produce district steam heating.', 'Các cơ sở đốt rác phát điện hiện đại thu giữ khí thải và sản xuất hơi nước sưởi ấm cho khu vực.', ARRAY['Waste burning', 'Thermal disposal']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('env-26', 'environment', 'Landfill', '/ˈlænd.fɪl/', 'Noun', 'B1', 'Bãi chôn lấp rác thải đô thị', 'The disposal of waste material by burying it, especially as a method of filling in and reclaiming excavated pits.', 'Methane gas escaping from decomposing organic waste in municipal landfills must be actively captured.', 'Khí metan thoát ra từ chất thải hữu cơ đang phân hủy trong các bãi chôn lấp đô thị phải được tích cực thu giữ.', ARRAY['Dumping ground', 'Waste pit', 'Tip']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('env-27', 'environment', 'Mangrove', '/ˈmæŋ.ɡroʊv/', 'Noun', 'B2', 'Rừng ngập mặn chắn sóng ven biển', 'A tree or shrub that grows in chiefly tropical coastal swamps that are flooded at high tide.', 'Coastal mangrove forests act as natural shields that dissipate ferocious typhoon storm waves.', 'Rừng ngập mặn ven biển đóng vai trò như những lá chắn tự nhiên làm tiêu tán những đợt sóng bão dữ dội.', ARRAY['Coastal wetland forest', 'Tidal shrub']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('env-28', 'environment', 'Microplastics', '/ˈmaɪ.kroʊˌplæs.tɪks/', 'Noun', 'B2', 'Hạt vi nhựa siêu nhỏ gây độc hại chuỗi thức ăn', 'Extremely small pieces of plastic debris in the environment resulting from the disposal and breakdown of consumer products and industrial waste.', 'Scientists discovered toxic microplastics lodged inside the digestive tracts of deep-sea pelagic fish.', 'Các nhà khoa học phát hiện các hạt vi nhựa độc hại mắc kẹt bên trong đường tiêu hóa của các loài cá biển sâu.', ARRAY['Plastic particles', 'Micro-debris']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('env-29', 'environment', 'Monoculture', '/ˈmɑː.noʊˌkʌl.tʃɚ/', 'Noun', 'C1', 'Độc canh nông nghiệp một loại cây duy nhất', 'The cultivation of a single crop in a given area.', 'Vast agricultural monoculture deprives beneficial bees of varied pollen and degrades soil health.', 'Nền độc canh nông nghiệp rộng lớn tước đi lượng phấn hoa đa dạng của loài ong có ích và làm suy thoái sức khỏe đất đai.', ARRAY['Single cropping', 'Uniform farming']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('env-30', 'environment', 'Ozone Layer', '/ˈoʊ.zoʊn ˌleɪ.ɚ/', 'Noun', 'B1', 'Tầng ôzôn hấp thụ tia cực tím độc hại', 'A layer in the earth''s stratosphere at an altitude of about 10 km containing a high concentration of ozone, which absorbs most of the ultraviolet radiation reaching the earth from the sun.', 'The Montreal Protocol successfully banned CFC chemicals, allowing the protective ozone layer to heal.', 'Nghị định thư Montreal đã cấm thành công các hóa chất CFC, cho phép tầng ôzôn bảo vệ tự phục hồi.', ARRAY['Stratospheric shield', 'UV barrier']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('env-31', 'environment', 'Particulate Matter', '/pɑːrˈtɪk.jə.lət ˌmæt̬.ɚ/', 'Noun', 'C1', 'Bụi mịn lơ lửng trong không khí (PM2.5)', 'Microscopic solid or liquid matter suspended in the atmosphere of Earth.', 'Fine particulate matter smaller than 2.5 microns can penetrate deeply into human pulmonary alveoli.', 'Bụi mịn nhỏ hơn 2,5 micromet có thể xâm nhập sâu vào các phế nang phổi của con người.', ARRAY['PM2.5', 'Aerosol particles', 'Soot']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('env-32', 'environment', 'Permaculture', '/ˈpɝː.məˌkʌl.tʃɚ/', 'Noun', 'C1', 'Nông nghiệp sinh thái tự nuôi dưỡng lâu dài', 'The development of agricultural ecosystems intended to be sustainable and self-sufficient.', 'Designing food gardens based on permaculture principles creates self-regenerating resilient ecosystems.', 'Thiết kế các vườn thực phẩm dựa trên các nguyên tắc nông nghiệp sinh thái tạo ra các hệ sinh thái có khả năng tự tái tạo kiên cường.', ARRAY['Sustainable agriculture', 'Ecological farming']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('env-33', 'environment', 'Photovoltaic', '/ˌfoʊ.toʊ.vɑːlˈteɪ.ɪk/', 'Adj', 'B2', 'Quang điện biến ánh sáng mặt trời thành điện', 'Relating to the production of electric current at the junction of two substances exposed to light.', 'Photovoltaic rooftop solar arrays allow independent households to generate all their own green power.', 'Các giàn pin mặt trời quang điện trên mái nhà cho phép các hộ gia đình độc lập tự tạo ra toàn bộ nguồn điện xanh cho riêng mình.', ARRAY['Solar electric', 'PV']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('env-34', 'environment', 'Poaching', '/ˈpoʊ.tʃɪŋ/', 'Noun', 'B2', 'Nạn săn bắn trộm động vật hoang dã trái phép', 'The illegal practice of trespassing on another''s property to hunt or steal game without permission.', 'Armed rangers patrol the reserve day and night to eradicate organized pangolin poaching.', 'Các kiểm lâm viên có vũ trang tuần tra khu bảo tồn ngày đêm để xóa bỏ nạn săn trộm tê tê có tổ chức.', ARRAY['Illegal hunting', 'Game stealing']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('env-35', 'environment', 'Recycling', '/ˌriːˈsaɪ.klɪŋ/', 'Noun', 'A2', 'Tái chế rác thải thành vật liệu hữu ích', 'The action or process of converting waste into reusable material.', 'Aluminum can recycling requires ninety-five percent less energy than refining virgin bauxite ore.', 'Tái chế lon nhôm cần ít hơn 95% năng lượng so với việc tinh chế quặng bauxit nguyên chất.', ARRAY['Reclamation', 'Reprocessing', 'Upcycling']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('env-36', 'environment', 'Runoff', '/ˈrʌn.ɑːf/', 'Noun', 'B2', 'Nước chảy tràn bề mặt cuốn theo tạp chất', 'The draining away of water from the surface of an area of land, a building or structure, or other resource.', 'Agricultural chemical fertilizer runoff leads to severe toxic algae blooms in freshwater lakes.', 'Nước phân bón hóa học nông nghiệp chảy tràn bề mặt dẫn đến hiện tượng tảo độc nở hoa nghiêm trọng ở các hồ nước ngọt.', ARRAY['Surface drainage', 'Discharge']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('env-37', 'environment', 'Smog', '/smɑːɡ/', 'Noun', 'B1', 'Khói mù độc hại quang hóa kết hợp khói và sương', 'Fog or haze combined with smoke and other atmospheric pollutants.', 'Dense toxic industrial smog shrouded the capital, prompting health alerts and school closures.', 'Khói mù công nghiệp độc hại dày đặc bao phủ thủ đô, khiến cơ quan chức năng phải đưa ra cảnh báo sức khỏe và đóng cửa trường học.', ARRAY['Air haze', 'Pollution fog']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('env-38', 'environment', 'Solar Panel', '/ˈsoʊ.lɚ ˌpæn.əl/', 'Noun', 'A2', 'Tấm pin năng lượng mặt trời', 'A panel designed to absorb the sun''s rays as a source of energy for generating electricity or heating.', 'Modern monocrystalline solar panels achieve over twenty-two percent conversion efficiency.', 'Các tấm pin mặt trời đơn tinh thể hiện đại đạt hiệu suất chuyển đổi trên 22%.', ARRAY['Photovoltaic module', 'Solar collector']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('env-39', 'environment', 'Thermal Pollution', '/ˌθɝː.məl pəˈluː.ʃən/', 'Noun', 'C1', 'Ô nhiễm nhiệt độ nguồn nước từ các nhà máy', 'The degradation of water quality by any process that changes ambient water temperature.', 'Discharging scalding cooling water from nuclear reactors into rivers causes severe thermal pollution.', 'Xả nước làm mát bỏng rát từ các lò phản ứng hạt nhân ra sông ngòi gây ô nhiễm nhiệt độ nghiêm trọng.', ARRAY['Temperature pollution']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('env-40', 'environment', 'Upcycling', '/ˈʌpˌsaɪ.klɪŋ/', 'Noun', 'B2', 'Tái chế nâng cấp biến phế liệu thành tác phẩm giá trị cao', 'Reuse discarded objects or material in such a way as to create a product of higher quality or value than the original.', 'The artisan fashion workshop specializes in upcycling vintage denim jeans into luxury tote bags.', 'Xưởng thời trang thủ công chuyên tái chế nâng cấp quần jean denim cũ thành những chiếc túi tote sang trọng.', ARRAY['Creative reuse', 'Value recycling']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('env-41', 'environment', 'Waste Management', '/ˈweɪst ˌmæn.ədʒ.mənt/', 'Noun', 'B1', 'Quản lý và xử lý rác thải bài bản', 'The precise collection, transport, processing, recycling or disposal, and monitoring of waste materials.', 'Modern municipal waste management segregates organic, recyclable, and hazardous refuse at the source.', 'Quản lý chất thải đô thị hiện đại phân loại rác hữu cơ, rác tái chế và rác nguy hại ngay tại nguồn.', ARRAY['Refuse handling', 'Sanitation operations']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('env-42', 'environment', 'Wind Turbine', '/ˈwɪnd ˌtɝː.bɪn/', 'Noun', 'B1', 'Tua-bin gió khổng lồ phát điện', 'A turbine having a large vaned wheel rotated by the wind to generate electricity.', 'Massive offshore wind turbines harness relentless oceanic breezes with zero carbon footprint.', 'Các tua-bin gió khổng lồ ngoài khơi khai thác những làn gió đại dương không ngừng nghỉ mà không hề phát thải carbon.', ARRAY['Wind generator', 'Windmill generator']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('env-43', 'environment', 'Zero Waste', '/ˌzɪr.oʊ ˈweɪst/', 'Noun', 'B2', 'Lối sống không rác thải hướng đến bảo vệ môi trường', 'A philosophy that encourages the redesign of resource life cycles so that all products are reused.', 'Adopting a zero-waste grocery routine means carrying reusable cotton bags and glass jars.', 'Áp dụng thói quen mua sắm không rác thải nghĩa là luôn mang theo túi vải cotton và lọ thủy tinh có thể tái sử dụng.', ARRAY['No-waste lifestyle', 'Circular living']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('env-44', 'environment', 'Acid Rain', '/ˌæs.ɪd ˈreɪn/', 'Noun', 'B1', 'Mưa axit do khí thải lưu huỳnh hòa tan', 'Rainfall made sufficiently acidic by atmospheric pollution that it causes environmental harm, typically to forests and lakes.', 'Acid rain corroded ancient outdoor marble statues and acidified high-altitude alpine lakes.', 'Mưa axit làm ăn mòn các bức tượng cẩm thạch ngoài trời cổ xưa và làm chua các hồ nước trên núi cao.', ARRAY['Acid precipitation', 'Chemical rain']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('env-45', 'environment', 'Carbon Neutral', '/ˌkɑːr.bən ˈnuː.trəl/', 'Adj', 'B2', 'Trung hòa carbon (cân bằng lượng phát thải và hấp thụ)', 'Making or resulting in no net release of carbon dioxide into the atmosphere.', 'The enterprise pledged to make all its international data centers fully carbon neutral by 2030.', 'Doanh nghiệp cam kết sẽ đưa tất cả các trung tâm dữ liệu quốc tế của mình đạt trạng thái hoàn toàn trung hòa carbon vào năm 2030.', ARRAY['Net-zero carbon', 'Carbon-balanced']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('env-46', 'environment', 'Climate Change', '/ˈklaɪ.mət ˌtʃeɪndʒ/', 'Noun', 'B1', 'Biến đổi khí hậu toàn cầu', 'A change in global or regional climate patterns, in particular a change apparent from the mid to late 20th century onwards and attributed largely to the increased levels of atmospheric carbon dioxide produced by the use of fossil fuels.', 'Mitigating climate change requires rapid systemic decarbonization of global energy and transport.', 'Giảm nhẹ biến đổi khí hậu đòi hỏi phải khử carbon có hệ thống nhanh chóng trong ngành năng lượng và giao thông toàn cầu.', ARRAY['Global climate shift', 'Climatic disruption']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('env-47', 'environment', 'Ecological Footprint', '/ˌek.əˈlɑː.dʒɪ.kəl ˈfʊt.prɪnt/', 'Noun', 'B2', 'Dấu chân sinh thái đo lường diện tích đất tự nhiên cần để duy trì lối sống', 'The impact of a person or community on the environment, expressed as the amount of land required to sustain their use of natural resources.', 'If every human lived like Western suburban consumers, our ecological footprint would require four planet Earths.', 'Nếu mỗi con người đều sống như những người tiêu dùng ngoại ô phương Tây, dấu chân sinh thái của chúng ta sẽ cần đến 4 hành tinh Trái Đất.', ARRAY['Eco-impact', 'Nature demand']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('env-48', 'environment', 'Greenhouse Gas', '/ˈɡriːn.haʊs ˌɡæs/', 'Noun', 'B1', 'Khí nhà kính gây giữ nhiệt (CO2, CH4, N2O)', 'A gas that contributes to the greenhouse effect by absorbing infrared radiation, e.g., carbon dioxide and chlorofluorocarbons.', 'Curbing agricultural methane emissions is the fastest way to slow near-term greenhouse gas warming.', 'Hạn chế lượng khí thải metan trong nông nghiệp là cách nhanh nhất để làm chậm quá trình nóng lên do khí nhà kính trong thời gian tới.', ARRAY['GHG', 'Warming gas']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('env-49', 'environment', 'Reforest', '/ˌriːˈfɔːr.ɪst/', 'Verb', 'B2', 'Trồng lại rừng trên vùng đất đã mất cây', 'Replant an area with trees.', 'The conservation team plans to reforest fifty thousand hectares of denuded watershed basin.', 'Đội bảo tồn dự kiến sẽ trồng lại rừng trên 50.000 ha lưu vực đầu nguồn bị trơ trụi.', ARRAY['Replant', 'Regrow forest']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('env-50', 'environment', 'Renewable Energy', '/rɪˌnuː.ə.bəl ˈen.ɚ.dʒi/', 'Noun', 'B1', 'Năng lượng tái tạo sạch', 'Energy from a source that is not depleted when used, such as wind or solar power.', 'Massive battery storage arrays store surplus renewable energy for calm, cloudy days.', 'Các giàn pin lưu trữ khổng lồ tích trữ năng lượng tái tạo dư thừa cho những ngày lặng gió, nhiều mây.', ARRAY['Clean energy', 'Green power']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('env-51', 'environment', 'Solar Energy', '/ˌsoʊ.lɚ ˈen.ɚ.dʒi/', 'Noun', 'A2', 'Năng lượng mặt trời vô tận', 'Radiant energy emitted by the sun, harnessed using a range of technologies such as solar power to generate electricity.', 'Desert regions receive intense sunlight, making them prime global locations for utility-scale solar energy.', 'Các vùng sa mạc đón nhận ánh nắng gay gắt, biến chúng thành những địa điểm đắc địa trên toàn cầu cho năng lượng mặt trời quy mô lớn.', ARRAY['Sun power', 'Solar radiation']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('env-52', 'environment', 'Wind Energy', '/ˈwɪnd ˌen.ɚ.dʒi/', 'Noun', 'A2', 'Năng lượng gió tự nhiên', 'Power obtained by harnessing the energy of the wind of the atmosphere.', 'Coastal regions harness gusty offshore wind energy to drive giant power generators.', 'Các vùng ven biển khai thác năng lượng gió ngoài khơi giật mạnh để vận hành các máy phát điện khổng lồ.', ARRAY['Wind power', 'Aeolian energy']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('env-53', 'environment', 'Clean Energy', '/ˌkliːn ˈen.ɚ.dʒi/', 'Noun', 'B1', 'Năng lượng sạch không phát thải khí nhà kính', 'Energy that comes from renewable, zero emission sources that do not pollute the atmosphere when used.', 'Transitioning to clean energy creates millions of high-paying jobs in solar and grid engineering.', 'Chuyển đổi sang năng lượng sạch tạo ra hàng triệu việc làm thu nhập cao trong ngành kỹ thuật năng lượng mặt trời và lưới điện.', ARRAY['Green energy', 'Zero-emission power']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('env-54', 'environment', 'Fossil Energy', '/ˈfɑː.səl ˌen.ɚ.dʒi/', 'Noun', 'B1', 'Năng lượng từ nhiên liệu hóa thạch', 'Energy derived from burning ancient decayed organic matter such as coal and oil.', 'Phase-outs of coal-fired fossil energy plants are accelerating across developed continents.', 'Việc loại bỏ dần các nhà máy năng lượng hóa thạch đốt than đang tăng tốc trên khắp các lục địa phát triển.', ARRAY['Non-renewable energy', 'Carbon power']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('env-55', 'environment', 'Nuclear Energy', '/ˌnuː.kliː.ɚ ˈen.ɚ.dʒi/', 'Noun', 'B1', 'Năng lượng hạt nhân nguyên tử', 'The energy released during nuclear fission or fusion, especially when used to generate electricity.', 'Modern generation-four reactors provide safe, reliable zero-carbon nuclear energy around the clock.', 'Các lò phản ứng thế hệ thứ tư hiện đại cung cấp năng lượng hạt nhân không phát thải carbon an toàn, đáng tin cậy suốt ngày đêm.', ARRAY['Atomic power', 'Fission power']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('env-56', 'environment', 'Tidal Energy', '/ˈtaɪ.dəl ˌen.ɚ.dʒi/', 'Noun', 'B2', 'Năng lượng thủy triều từ lực hút mặt trăng', 'A form of power produced by the natural rise and fall of ocean tides and currents.', 'Submerged marine turbines generate predictable tidal energy regardless of surface weather.', 'Các tua-bin biển chìm dưới nước tạo ra năng lượng thủy triều có thể dự đoán được bất kể thời tiết trên bề mặt.', ARRAY['Tidal power', 'Marine energy']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('env-57', 'environment', 'Wave Energy', '/ˈweɪv ˌen.ɚ.dʒi/', 'Noun', 'B2', 'Năng lượng sóng biển dập dềnh', 'The capture of energy of wind waves to do useful work, including electricity generation.', 'Floating buoys bobbing on oceanic swells harvest mechanical wave energy smoothly.', 'Những chiếc phao nổi nhấp nhô trên các đợt sóng biển lớn thu hoạch năng lượng cơ học của sóng một cách êm ái.', ARRAY['Ocean wave power', 'Marine hydrokinetic']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('env-58', 'environment', 'Biofuel', '/ˈbaɪ.oʊˌfjuː.əl/', 'Noun', 'B2', 'Nhiên liệu sinh học từ nông sản và mỡ động vật', 'A fuel derived directly from living matter such as plants or agricultural waste.', 'Commercial airlines are testing sustainable aviation biofuel blends to lower flight emissions.', 'Các hãng hàng không thương mại đang thử nghiệm các hỗn hợp nhiên liệu sinh học hàng không bền vững để giảm lượng khí thải trong chuyến bay.', ARRAY['Biomass fuel', 'Agrofuel']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('env-59', 'environment', 'Carbon Sink', '/ˈkɑːr.bən ˌsɪŋk/', 'Noun', 'B2', 'Bể chứa hấp thụ carbon tự nhiên (rừng, đại dương)', 'A forest, ocean, or other natural environment viewed in terms of its ability to absorb carbon dioxide from the atmosphere.', 'The deep ocean abyss acts as the planetary biosphere''s most monumental carbon sink.', 'Vực thẳm đại dương sâu thẳm đóng vai trò là bể chứa carbon hoành tráng nhất của sinh quyển hành tinh.', ARRAY['Carbon reservoir', 'CO2 absorber']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('env-60', 'environment', 'Carbon Offset', '/ˈkɑːr.bən ˌɑːf.set/', 'Noun', 'B2', 'Tín chỉ bù đắp carbon thông qua dự án xanh', 'A reduction in emissions of carbon dioxide or other greenhouse gases made in order to compensate for emissions made elsewhere.', 'Travelers can purchase verified carbon offsets to neutralize the emissions of their transatlantic flights.', 'Hành khách đi máy bay có thể mua các khoản bù đắp carbon đã được xác thực để trung hòa lượng khí thải từ các chuyến bay qua Đại Tây Dương của họ.', ARRAY['Emission credit', 'Carbon compensation']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('env-61', 'environment', 'Carbon Tax', '/ˈkɑːr.bən ˌtæks/', 'Noun', 'B2', 'Thuế carbon đánh vào phát thải khí nhà kính', 'A tax on fossil fuels, especially those used by motor vehicles, intended to reduce the emission of carbon dioxide.', 'Instituting a progressive national carbon tax incentivizes heavy industries to innovate rapidly.', 'Việc thiết lập một mức thuế carbon quốc gia mang tính lũy tiến sẽ khuyến khích các ngành công nghiệp nặng đổi mới nhanh chóng.', ARRAY['Pollution levy', 'Emissions fee']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('env-62', 'environment', 'Cap-and-Trade', '/ˌkæp.ənˈtreɪd/', 'Noun', 'C1', 'Cơ chế giới hạn và mua bán hạn ngạch phát thải', 'A government-mandated, market-based approach to controlling pollution by providing economic incentives for achieving reductions in the emissions of pollutants.', 'Under cap-and-trade systems, efficient factories sell their surplus emission allowances for profit.', 'Theo hệ thống giới hạn và mua bán, các nhà máy hoạt động hiệu quả có thể bán hạn ngạch phát thải dư thừa của mình để kiếm lời.', ARRAY['Emissions trading', 'Carbon market']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('env-63', 'environment', 'Climate Crisis', '/ˈklaɪ.mət ˌkraɪ.sɪs/', 'Noun', 'B2', 'Khủng hoảng khí hậu nghiêm trọng đe dọa nhân loại', 'Intense difficulty or danger caused by changes to the Earth''s climate, typically resulting from human activity.', 'Youth activists organized worldwide peaceful strikes to demand urgent governmental action on the climate crisis.', 'Các nhà hoạt động trẻ tuổi đã tổ chức các cuộc đình công hòa bình trên toàn thế giới để yêu cầu chính phủ hành động khẩn cấp đối với cuộc khủng hoảng khí hậu.', ARRAY['Climate emergency', 'Ecological catastrophe']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('env-64', 'environment', 'Global Warming', '/ˌɡloʊ.bəl ˈwɔːr.mɪŋ/', 'Noun', 'B1', 'Hiện tượng ấm lên toàn cầu', 'A gradual increase in the overall temperature of the earth''s atmosphere generally attributed to the greenhouse effect caused by increased levels of carbon dioxide, chlorofluorocarbons, and other pollutants.', 'Global warming is causing Arctic polar sea ice to melt at an unprecedented, alarming rate.', 'Hiện tượng ấm lên toàn cầu đang khiến băng biển vùng cực Bắc tan chảy với tốc độ đáng báo động chưa từng có.', ARRAY['Planetary warming', 'Thermal rise']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('env-65', 'environment', 'Ocean Acidification', '/ˌoʊ.ʃən əˌsɪd.ə.fəˈkeɪ.ʃən/', 'Noun', 'C1', 'Hiện tượng axit hóa đại dương do hấp thụ nhiều CO2', 'The ongoing decrease in the pH of the Earth''s oceans, caused by the uptake of carbon dioxide from the atmosphere.', 'Ocean acidification dissolves the delicate calcium carbonate shells of microscopic plankton and young mollusks.', 'Axit hóa đại dương làm hòa tan lớp vỏ canxi cacbonat mỏng manh của các sinh vật phù du siêu nhỏ và động vật thân mềm non.', ARRAY['Marine acidification', 'pH decline']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('env-66', 'environment', 'Sea Level Rise', '/ˈsiː ˌlev.əl ˌraɪz/', 'Noun', 'B1', 'Mực nước biển dâng cao đe dọa các vùng ven biển', 'An increase in the level of the world''s oceans due to the effects of global warming.', 'Low-lying river delta regions are severely vulnerable to chronic saltwater intrusion caused by sea level rise.', 'Các vùng đồng bằng châu thổ sông trũng thấp đặc biệt dễ bị tổn thương trước hiện tượng xâm nhập mặn mãn tính do nước biển dâng.', ARRAY['Ocean rise', 'Coastal inundation']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('env-67', 'environment', 'Extreme Weather', '/ɪkˌstriːm ˈweð.ɚ/', 'Noun', 'B1', 'Thời tiết cực đoan (bão dữ, sóng nhiệt, lũ quét)', 'Severe or unseasonal weather, which can include prolonged heatwaves, intense hurricanes, or unprecedented cold snaps.', 'Frequency of extreme weather disasters has quadrupled over the past four decades.', 'Tần suất xảy ra các thảm họa thời tiết cực đoan đã tăng gấp bốn lần trong suốt bốn thập kỷ qua.', ARRAY['Severe weather', 'Climatic anomalies']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('env-68', 'environment', 'Heatwave', '/ˈhiːt.weɪv/', 'Noun', 'B1', 'Đợt sóng nhiệt gay gắt kéo dài', 'A prolonged period of abnormally hot weather, often accompanied by high humidity.', 'The record European summer heatwave buckled railway tracks and caused thousands of excess hospitalizations.', 'Đợt sóng nhiệt mùa hè kỷ lục ở châu Âu đã làm cong các đường ray xe lửa và khiến hàng ngàn người phải nhập viện ngoài dự kiến.', ARRAY['Thermal spike', 'Hot spell']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('env-69', 'environment', 'Wildfire', '/ˈwaɪld.faɪr/', 'Noun', 'B1', 'Cháy rừng hoang dã lan nhanh không kiểm soát', 'A large, destructive fire that spreads quickly over woodland or brush.', 'Dry tinder timber and howling gale winds fueled an uncontrollable Australian bush wildfire.', 'Gỗ khô dễ bắt lửa và những cơn gió rít gào đã thổi bùng lên một trận cháy rừng dữ dội không thể kiểm soát tại Úc.', ARRAY['Forest fire', 'Bushfire', 'Conflagration']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('env-70', 'environment', 'Flood', '/flʌd/', 'Noun', 'A2', 'Trận lũ lụt dâng ngập nhà cửa', 'An overflowing of a large amount of water beyond its normal confines, especially over what is normally dry land.', 'Heavy monsoon downpours triggered catastrophic river flash floods that submerged provincial towns.', 'Những trận mưa rào gió mùa trút nước xối xả đã kích hoạt các trận lũ quét kinh hoàng trên sông làm ngập chìm các thị trấn của tỉnh.', ARRAY['Deluge', 'Inundation', 'Overflow']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('env-71', 'environment', 'Typhoon', '/taɪˈfuːn/', 'Noun', 'B1', 'Cơn bão nhiệt đới dữ dội ở vùng biển châu Á', 'A tropical storm in the region of the western Pacific Oceans.', 'The coastal fishing fleet sought safe harbor before the category-five super typhoon made landfall.', 'Đội tàu đánh cá ven biển đã tìm nơi trú ẩn an toàn trước khi siêu bão cấp 5 đổ bộ vào đất liền.', ARRAY['Hurricane', 'Tropical cyclone', 'Tempest']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('env-72', 'environment', 'Glacier', '/ˈɡleɪ.ʃɚ/', 'Noun', 'B1', 'Sông băng tuyết vĩnh cửu trên núi cao', 'A slowly moving mass or river of ice formed by the accumulation and compaction of snow on mountains or near the poles.', 'Tourists hiked to the edge of the ancient Icelandic glacier to witness massive ice shelves calving into the bay.', 'Du khách đã đi bộ đến rìa của dòng sông băng cổ xưa ở Iceland để chứng kiến những thềm băng khổng lồ tách ra và rơi xuống vịnh.', ARRAY['Ice sheet', 'Ice field', 'Ice river']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('env-73', 'environment', 'Permafrost', '/ˈpɝː.mə.frɑːst/', 'Noun', 'C1', 'Tầng đất đóng băng vĩnh cửu ở vùng cực', 'A thick subsurface layer of soil that remains frozen throughout the year, occurring chiefly in polar regions.', 'Thawing Siberian permafrost releases ancient trapped reservoirs of explosive methane gas into the atmosphere.', 'Tầng đất đóng băng vĩnh cửu ở Siberia đang tan chảy giải phóng các túi khí metan dễ nổ từng bị giữ lại từ thời cổ đại vào khí quyển.', ARRAY['Frozen ground', 'Arctic soil']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('env-74', 'environment', 'Ice Cap', '/ˈaɪs ˌkæp/', 'Noun', 'B2', 'Mũ băng bao phủ các vùng cực', 'A covering of ice over a large area, especially on the polar region of a planet.', 'The Greenland ice cap contains sufficient freshwater to raise worldwide sea levels by seven meters if completely melted.', 'Mũ băng Greenland chứa đủ lượng nước ngọt để làm dâng mực nước biển trên toàn thế giới thêm 7 mét nếu bị tan chảy hoàn toàn.', ARRAY['Polar cap', 'Glacial dome']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('env-75', 'environment', 'Ecology', '/iˈkɑː.lə.dʒi/', 'Noun', 'B2', 'Khoa học sinh thái học nghiên cứu môi trường', 'The branch of biology that deals with the relations of organisms to one another and to their physical surroundings.', 'Studying marine ecology reveals how microscopic changes in phytoplankton populations ripple through entire food webs.', 'Nghiên cứu sinh thái học biển tiết lộ những thay đổi vi mô trong quần thể thực vật phù du có thể tạo ra làn sóng gợn như thế nào trên toàn bộ mạng lưới thức ăn.', ARRAY['Bionomics', 'Environmental biology']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('env-76', 'environment', 'Rainforest', '/ˈreɪn.fɔːr.ɪst/', 'Noun', 'A2', 'Rừng mưa nhiệt đới rậm rạp', 'A luxuriant, dense forest rich in biodiversity, found typically in tropical areas with consistently heavy rainfall.', 'The Amazon rainforest produces substantial oxygen and shelters millions of species.', 'Rừng mưa nhiệt đới Amazon sản xuất lượng oxy dồi dào và che chở cho hàng triệu loài sinh vật.', ARRAY['Jungle', 'Tropical forest']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('env-77', 'environment', 'Tundra', '/ˈtʌn.drə/', 'Noun', 'B2', 'Thảo nguyên đài nguyên băng giá vùng cực', 'A vast, flat, treeless Arctic region of Europe, Asia, and North America in which the subsoil is permanently frozen.', 'Reindeer herds migrate across the frozen Arctic tundra during brief polar summers.', 'Các đàn tuần lộc di cư qua vùng đài nguyên Bắc Cực băng giá trong những mùa hè vùng cực ngắn ngủi.', ARRAY['Arctic plain', 'Frozen steppe']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('env-78', 'environment', 'Canopy', '/ˈkæn.ə.pi/', 'Noun', 'B2', 'Tầng tán lá rậm rạp trên ngọn cây rừng', 'The uppermost branchy layer in a forest, formed by the crowns of the trees.', 'Many colorful tropical birds live exclusively high up in the dense jungle canopy.', 'Nhiều loài chim nhiệt đới rực rỡ sắc màu chỉ sinh sống độc quyền trên tầng tán lá rừng rậm rạp.', ARRAY['Treetop layer', 'Forest roof']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('env-79', 'environment', 'Understory', '/ˈʌn.dɚˌstɔːr.i/', 'Noun', 'C1', 'Tầng dưới tán cây của rừng nhiệt đới', 'A layer of vegetation beneath the main canopy of a forest.', 'Shade-tolerant ferns and mosses flourish in the dim, humid forest understory.', 'Các loài dương xỉ và rêu ưa bóng râm phát triển tươi tốt ở tầng dưới tán rừng ẩm ướt và mờ tối.', ARRAY['Lower vegetative layer']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('env-80', 'environment', 'Decarbonization', '/diːˌkɑːr.bən.əˈzeɪ.ʃən/', 'Noun', 'C1', 'Khử carbon, loại bỏ khí thải carbon trong công nghiệp', 'The reduction or removal of carbon dioxide emissions from energy systems and economies.', 'National decarbonization roadmaps require replacing heavy fossil fuels with green electricity.', 'Lộ trình khử carbon quốc gia đòi hỏi phải thay thế các nhiên liệu hóa thạch nặng bằng điện xanh.', ARRAY['Carbon reduction', 'Zero-emission shift']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('env-81', 'environment', 'Affluence', '/ˈæf.lu.əns/', 'Noun', 'B2', 'Sự giàu sang phồn vinh làm gia tăng tiêu thụ tài nguyên', 'The state of having a great deal of money; wealth that drives consumer energy use.', 'Rising global affluence drives higher per capita meat consumption and carbon emissions.', 'Sự giàu sang gia tăng trên toàn cầu thúc đẩy mức tiêu thụ thịt bình quân đầu người và lượng phát thải carbon cao hơn.', ARRAY['Wealth', 'Prosperity', 'Abundance']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('env-82', 'environment', 'Contaminant', '/kənˈtæm.ə.nənt/', 'Noun', 'B2', 'Chất gây ô nhiễm độc hại', 'A polluting or poisonous substance that makes something impure.', 'Heavy metal industrial contaminants were filtered from drinking water using activated charcoal.', 'Các chất ô nhiễm công nghiệp kim loại nặng đã được lọc khỏi nước uống bằng than hoạt tính.', ARRAY['Pollutant', 'Toxin', 'Impurity']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('env-83', 'environment', 'Ecocide', '/ˈiː.koʊ.saɪd/', 'Noun', 'C1', 'Tội ác tàn sát hủy hoại môi trường sinh thái', 'Destruction of the natural environment, especially when caused deliberately by human activity.', 'International legal scholars advocate recognizing massive industrial chemical dumping as ecocide.', 'Các học giả pháp lý quốc tế ủng hộ việc công nhận hành vi xả hóa chất công nghiệp quy mô lớn là tội ác hủy hoại sinh thái.', ARRAY['Environmental destruction']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('env-84', 'environment', 'Biosphere', '/ˈbaɪ.oʊ.sfɪr/', 'Noun', 'B2', 'Sinh quyển bao trùm sự sống trên Trái Đất', 'The regions of the surface, atmosphere, and hydrosphere of the earth occupied by living organisms.', 'Human greenhouse emissions are placing unprecedented stress on the planetary biosphere.', 'Lượng phát thải nhà kính của con người đang đặt áp lực chưa từng có lên sinh quyển toàn cầu.', ARRAY['Living world', 'Ecosphere']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('env-85', 'environment', 'Defoliant', '/diːˈfoʊ.li.ənt/', 'Noun', 'C1', 'Chất khai hoang làm rụng lá cây', 'A chemical that removes the leaves from trees and plants, often used in warfare.', 'Toxic chemical defoliants stripped pristine rainforest canopies, leaving lingering ecological scars.', 'Chất làm rụng lá hóa học độc hại đã tước đi những tán rừng nhiệt đới nguyên sơ, để lại những vết sẹo sinh thái dai dẳng.', ARRAY['Chemical herbicide', 'Plant stripper']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('edu-1', 'education', 'Curriculum', '/kəˈrɪk.jə.ləm/', 'Noun', 'B2', 'Khung chương trình học tập toàn khóa', 'The subjects comprising a course of study in a school or college.', 'The national curriculum incorporates hands-on computer programming from primary school onwards.', 'Chương trình học quốc gia đưa việc lập trình máy tính thực hành vào giảng dạy ngay từ cấp tiểu học trở đi.', ARRAY['Syllabus', 'Course of study', 'Program']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('edu-2', 'education', 'Prerequisite', '/ˌpriːˈrek.wə.zɪt/', 'Noun', 'B2', 'Điều kiện tiên quyết phải hoàn thành trước', 'A thing that is required as a prior condition for something else to happen or exist.', 'Passing introductory calculus is an absolute prerequisite for enrolling in advanced quantum mechanics.', 'Vượt qua môn giải tích đại cương là điều kiện tiên quyết bắt buộc để đăng ký học cơ học lượng tử nâng cao.', ARRAY['Requirement', 'Precondition', 'Must-have']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('edu-3', 'education', 'Dissertation', '/ˌdɪs.ɚˈteɪ.ʃən/', 'Noun', 'C1', 'Luận án tiến sĩ / luận văn thạc sĩ', 'A long essay on a particular subject, especially one written for a university degree or diploma.', 'Her doctoral dissertation on generative neural architecture search was published in a prestigious peer-reviewed journal.', 'Luận án tiến sĩ của cô về tìm kiếm kiến trúc mạng nơ-ron tạo sinh đã được xuất bản trên một tạp chí bình duyệt danh tiếng.', ARRAY['Thesis', 'Treatise', 'Academic paper']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('edu-4', 'education', 'Tuition', '/tuːˈɪʃ.ən/', 'Noun', 'B1', 'Học phí học đại học hoặc khóa học', 'A sum of money charged for teaching by a college or university.', 'The university awarded merit scholarships to cover international tuition fees for high-achieving applicants.', 'Trường đại học đã trao các suất học bổng tài năng để chi trả toàn bộ học phí quốc tế cho các ứng viên đạt thành tích xuất sắc.', ARRAY['Tuition fee', 'School fee', 'Instruction cost']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('edu-5', 'education', 'Pedagogical', '/ˌped.əˈɡɑː.dʒɪ.kəl/', 'Adj', 'C1', 'Thuộc về phương pháp sư phạm giảng dạy', 'Relating to teaching methods and the practice of educating.', 'Introducing interactive gamified quizzes reflects a modern pedagogical shift toward student engagement.', 'Đưa vào các câu đố trò chơi hóa mang tính tương tác phản ánh sự chuyển dịch sư phạm hiện đại hướng tới sự hào hứng của học sinh.', ARRAY['Instructional', 'Educational', 'Teaching-related']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('edu-6', 'education', 'Syllabus', '/ˈsɪl.ə.bəs/', 'Noun', 'B1', 'Đề cương chi tiết từng buổi học của môn học', 'An outline of the subjects in a course of study or teaching.', 'The professor handed out the semester course syllabus during the introductory orientation lecture.', 'Giáo sư đã phát đề cương môn học của học kỳ trong bài giảng định hướng nhập môn đầu tiên.', ARRAY['Course outline', 'Curriculum summary']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('edu-7', 'education', 'Plagiarism', '/ˈpleɪ.dʒɚ.ɪ.zəm/', 'Noun', 'B2', 'Hành vi đạo văn, sao chép trái phép', 'The practice of taking someone else''s work or ideas and passing them off as one''s own.', 'Academic institutions employ automated scanning algorithms to detect and penalize deliberate plagiarism.', 'Các tổ chức học thuật sử dụng các thuật toán quét tự động để phát hiện và xử phạt nghiêm khắc hành vi cố ý đạo văn.', ARRAY['Copying', 'Infringement', 'Appropriation']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('edu-8', 'education', 'Extracurricular', '/ˌek.strə.kəˈrɪk.jə.lɚ/', 'Adj', 'B1', 'Hoạt động ngoại khóa ngoài giờ học chính', 'Pursued in addition to the normal course of study.', 'Participation in extracurricular debate clubs sharpens public speaking and spontaneous rhetoric skills.', 'Tham gia vào các câu lạc bộ tranh biện ngoại khóa giúp mài giũa khả năng nói trước đám đông và kỹ năng hùng biện ngẫu hứng.', ARRAY['After-school', 'Co-curricular']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('edu-9', 'education', 'Alumni', '/əˈlʌm.naɪ/', 'Noun', 'B2', 'Cựu sinh viên từng tốt nghiệp', 'Graduates or former students of a particular school, college, or university.', 'Prominent university alumni donated fifty million dollars to fund cutting-edge artificial intelligence laboratories.', 'Các cựu sinh viên ưu tú của trường đại học đã quyên góp 50 triệu USD để tài trợ cho các phòng thí nghiệm trí tuệ nhân tạo tối tân.', ARRAY['Graduates', 'Past students', 'Old scholars']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('edu-10', 'education', 'Scholarship', '/ˈskɑː.lɚ.ʃɪp/', 'Noun', 'A2', 'Học bổng tài trợ cho học sinh giỏi', 'A grant or payment made to support a student''s education, awarded on the basis of academic or other achievement.', 'Winning a full scholarship to Cambridge University transformed the ambitious rural student''s trajectory.', 'Giành được học bổng toàn phần đến Đại học Cambridge đã làm thay đổi hoàn toàn quỹ đạo cuộc đời của cậu học sinh nông thôn giàu khát vọng.', ARRAY['Grant', 'Fellowship', 'Endowment']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('edu-11', 'education', 'Valedictorian', '/ˌvæl.ə.dɪkˈtɔːr.i.ən/', 'Noun', 'C1', 'Thủ khoa tốt nghiệp có điểm số cao nhất khóa', 'A student having the highest rank in a graduating class who delivers the valedictory address.', 'As class valedictorian, she delivered an inspirational commencement address to three thousand graduating peers.', 'Với tư cách là thủ khoa của khóa, cô đã có bài phát biểu bế giảng đầy cảm hứng trước 3.000 bạn học tốt nghiệp.', ARRAY['Top graduate', 'Class leader']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('edu-12', 'education', 'Salutatorian', '/səˌluː.t̬əˈtɔːr.i.ən/', 'Noun', 'C1', 'Á khoa tốt nghiệp xếp hạng nhì toàn khóa', 'The student who ranks second highest in a graduating class and delivers the salutatory address.', 'The salutatorian was awarded a full engineering scholarship at the prestigious polytechnic institute.', 'Á khoa tốt nghiệp đã được trao học bổng kỹ thuật toàn phần tại viện bách khoa danh tiếng.', ARRAY['Second graduate', 'Runner-up']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('edu-13', 'education', 'Commencement', '/kəˈmens.mənt/', 'Noun', 'B2', 'Lễ tốt nghiệp đại học trang trọng', 'A ceremony in which degrees or diplomas are conferred on graduating students.', 'Families gathered in the grand auditorium to celebrate the annual university commencement ceremony.', 'Các gia đình tụ họp trong đại giảng đường để chúc mừng lễ tốt nghiệp đại học thường niên.', ARRAY['Graduation ceremony', 'Convocation']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('edu-14', 'education', 'Convocation', '/ˌkɑːn.vəˈkeɪ.ʃən/', 'Noun', 'C1', 'Lễ triệu tập trao bằng tốt nghiệp trang trọng', 'A large formal assembly of people, especially for the conferring of university academic degrees.', 'The chancellor presided over the formal doctoral convocation ceremony in traditional academic regalia.', 'Hiệu trưởng đã chủ trì buổi lễ triệu tập trao bằng tiến sĩ trang trọng trong trang phục học thuật truyền thống.', ARRAY['Academic assembly', 'Degree ceremony']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('edu-15', 'education', 'Accreditation', '/əˌkred.əˈteɪ.ʃən/', 'Noun', 'B2', 'Sự kiểm định chất lượng giáo dục chính thức', 'The action or process of officially recognizing someone as having a particular status or being qualified to perform a particular activity.', 'The medical university achieved prestigious international accreditation from the World Federation for Medical Education.', 'Trường đại học y khoa đã đạt được sự kiểm định chất lượng quốc tế danh giá từ Liên đoàn Giáo dục Y khoa Thế giới.', ARRAY['Certification', 'Validation', 'Endorsement']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('edu-16', 'education', 'Faculty', '/ˈfæk.əl.t̬i/', 'Noun', 'B1', 'Đội ngũ giảng viên hoặc khoa chuyên ngành', 'The teaching staff of a university or college, or of one of its departments.', 'The computer science faculty includes world-renowned pioneers in deep learning and robotics.', 'Khoa khoa học máy tính quy tụ những người tiên phong nổi tiếng thế giới trong lĩnh vực học sâu và robot.', ARRAY['Academic staff', 'Department professors']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('edu-17', 'education', 'Tenure', '/ˈten.jɚ/', 'Noun', 'C1', 'Quyền giữ vị trí giáo sư biên chế trọn đời', 'A status granted to an employee, usually after a probationary period, indicating that the position or employment is permanent.', 'After six years of groundbreaking empirical publications, the assistant professor was granted coveted academic tenure.', 'Sau sáu năm có những công bố thực nghiệm mang tính đột phá, vị phó giáo sư đã được cấp biên chế học thuật trọn đời mà ai cũng khao khát.', ARRAY['Permanent post', 'Job security']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('edu-18', 'education', 'Sabbatical', '/səˈbæt̬.ɪ.kəl/', 'Noun', 'C1', 'Kỳ nghỉ phép nghiên cứu khoa học của giáo sư', 'A period of paid leave granted to a university teacher or other worker for study or travel, traditionally one year for every seven years worked.', 'During his year-long sabbatical, the physics professor conducted quantum computing research at CERN.', 'Trong kỳ nghỉ nghiên cứu kéo dài một năm, giáo sư vật lý đã thực hiện nghiên cứu điện toán lượng tử tại CERN.', ARRAY['Study leave', 'Research break']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('edu-19', 'education', 'Fellowship', '/ˈfel.oʊ.ʃɪp/', 'Noun', 'B2', 'Khoản tài trợ nghiên cứu sau tiến sĩ', 'A financial grant in aid, fellowship, or scholarship granted to a scholar or student.', 'She was awarded a competitive two-year postdoctoral fellowship in renewable energy systems.', 'Cô ấy đã được trao một suất tài trợ nghiên cứu sau tiến sĩ kéo dài hai năm đầy cạnh tranh về các hệ sinh thái năng lượng tái tạo.', ARRAY['Research grant', 'Endowment']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('edu-20', 'education', 'Mentorship', '/ˈmen.tɔːr.ʃɪp/', 'Noun', 'B1', 'Mối quan hệ cố vấn hướng dẫn học tập', 'The guidance provided by a mentor, especially an experienced person in a company or educational institution.', 'Close one-on-one mentorship from a senior scientist dramatically accelerates a graduate student''s laboratory mastery.', 'Sự cố vấn kèm cặp một - một chặt chẽ từ một nhà khoa học cấp cao giúp đẩy nhanh đáng kể khả năng làm chủ phòng thí nghiệm của một sinh viên sau đại học.', ARRAY['Guidance', 'Tutoring', 'Coaching']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('edu-21', 'education', 'Pedagogy', '/ˈped.ə.ɡɑː.dʒi/', 'Noun', 'C1', 'Khoa học và nghệ thuật giảng dạy sư phạm', 'The method and practice of teaching, especially as an academic subject or theoretical concept.', 'Constructivist pedagogy emphasizes that students construct knowledge through collaborative hands-on projects.', 'Phương pháp sư phạm kiến tạo nhấn mạnh rằng học sinh tự xây dựng kiến thức thông qua các dự án thực hành có tính hợp tác.', ARRAY['Teaching theory', 'Educational science']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('edu-22', 'education', 'Didactic', '/daɪˈdæk.tɪk/', 'Adj', 'C1', 'Mang tính giáo huấn, truyền thụ kiến thức trực tiếp', 'Intended to teach, particularly in having moral instruction as an ulterior motive.', 'Modern educational games balance didactic instruction with open-ended creative exploration.', 'Các trò chơi giáo dục hiện đại cân bằng giữa việc hướng dẫn mang tính giáo huấn trực tiếp với việc khám phá sáng tạo mở.', ARRAY['Instructive', 'Educational', 'Informative']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('edu-23', 'education', 'Assessment', '/əˈses.mənt/', 'Noun', 'B1', 'Đánh giá kết quả học tập', 'The evaluation or estimation of the nature, quality, or ability of someone or something.', 'Continuous classroom assessment through weekly project deliverables provides deeper insights than a single final exam.', 'Đánh giá thường xuyên trên lớp thông qua các sản phẩm dự án hàng tuần mang lại cái nhìn sâu sắc hơn là một bài thi cuối kỳ duy nhất.', ARRAY['Evaluation', 'Appraisal', 'Testing']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('edu-24', 'education', 'Formative', '/ˈfɔːr.mə.t̬ɪv/', 'Adj', 'B2', 'Đánh giá quá trình để cải thiện (formative assessment)', 'Serving to form something, especially having a profound and lasting influence on development; diagnostic assessment during learning.', 'Formative quizzes provide immediate actionable feedback to help students correct misconceptions before finals.', 'Các bài kiểm tra ngắn trong quá trình học cung cấp phản hồi tức thì để giúp học sinh sửa chữa những hiểu lầm trước khi bước vào kỳ thi cuối kỳ.', ARRAY['Developmental', 'Diagnostic']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('edu-25', 'education', 'Summative', '/ˈsʌm.ə.t̬ɪv/', 'Adj', 'B2', 'Đánh giá tổng kết cuối kỳ (summative evaluation)', 'Gathering together; in education, assessment administered at the end of an instructional unit to measure learning.', 'The final three-hour written examination represents the summative assessment for the entire semester.', 'Bài thi viết kéo dài ba giờ cuối kỳ đại diện cho bài đánh giá tổng kết cho toàn bộ học kỳ.', ARRAY['Cumulative', 'Final evaluation']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('edu-26', 'education', 'Matriculate', '/məˈtrɪk.jə.leɪt/', 'Verb', 'C1', 'Trúng tuyển và chính thức nhập học đại học', 'Enroll as a student at a college or university.', 'Over four thousand talented freshmen matriculated into the engineering academy this autumn.', 'Hơn bốn ngàn tân sinh viên tài năng đã chính thức trúng tuyển nhập học vào học viện kỹ thuật vào mùa thu này.', ARRAY['Enroll', 'Register', 'Enter college']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('edu-27', 'education', 'Auditing', '/ˈɑː.dɪ.tɪŋ/', 'Noun', 'B2', 'Dự thính môn học lấy kiến thức không lấy điểm', 'Attending a university course informally without working for academic credit.', 'Auditing the world history lecture allowed the working professional to explore history without exam stress.', 'Dự thính bài giảng lịch sử thế giới cho phép người đi làm có thể khám phá lịch sử mà không phải chịu áp lực thi cử.', ARRAY['Unofficial listening', 'Sitting in']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('edu-28', 'education', 'Elective', '/iˈlek.tɪv/', 'Noun', 'B1', 'Môn học tự chọn theo sở thích', 'An optional course of study in a university or school curriculum.', 'Students can select two humanistic electives such as philosophy or creative writing to round out their technical degrees.', 'Sinh viên có thể chọn hai môn học tự chọn mang tính nhân văn như triết học hoặc viết sáng tạo để hoàn thiện tấm bằng kỹ thuật của mình.', ARRAY['Optional subject', 'Selective course']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('edu-29', 'education', 'Core Subject', '/kɔːr ˈsʌb.dʒɪkt/', 'Noun', 'B1', 'Môn học bắt buộc cốt lõi', 'A course of study that is compulsory for all students in a particular educational track.', 'Linear algebra and discrete mathematics are compulsory core subjects for computer software majors.', 'Đại số tuyến tính và toán rời rạc là các môn học cốt lõi bắt buộc đối với sinh viên chuyên ngành phần mềm máy tính.', ARRAY['Compulsory course', 'Mandatory study']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('edu-30', 'education', 'Transcript', '/ˈtræn.skrɪpt/', 'Noun', 'B1', 'Bảng điểm học tập chính thức', 'An official record of a student''s work, showing courses taken and grades achieved.', 'Submit an official certified transcript alongside your graduate school application dossier.', 'Hãy nộp bảng điểm chính thức có công chứng đính kèm hồ sơ xin học sau đại học của bạn.', ARRAY['Grade report', 'Academic record']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('edu-31', 'education', 'Grade Point Average', '/ˌɡreɪd ˌpɔɪnt ˈæv.ɚ.ɪdʒ/', 'Noun', 'B1', 'Điểm trung bình tích lũy toàn khóa (GPA)', 'A number representing the average value of the accumulated final grades earned in courses over time.', 'Maintaining a cumulative grade point average above 3.8 qualifies students for dean''s list honors.', 'Duy trì điểm trung bình tích lũy GPA trên 3.8 giúp sinh viên đủ điều kiện nhận vinh danh trong danh sách sinh viên xuất sắc của khoa.', ARRAY['GPA', 'Cumulative mark']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('edu-32', 'education', 'Honors', '/ˈɑː.nɚz/', 'Noun', 'B1', 'Chương trình đào tạo danh dự cho sinh viên giỏi', 'A degree or award that recognizes outstanding achievement.', 'She graduated with highest honors in molecular biochemistry after discovering a new enzyme pathway.', 'Cô đã tốt nghiệp với tấm bằng danh dự loại xuất sắc ngành hóa sinh phân tử sau khi phát hiện ra một con đường enzyme mới.', ARRAY['Distinction', 'Laudable degree']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('edu-33', 'education', 'Cum Laude', '/ˌkʊm ˈlaʊ.deɪ/', 'Phrase', 'C1', 'Tốt nghiệp loại giỏi danh dự (tiếng Latin)', 'With honor; with distinction, typically used on university academic degrees.', 'He earned his bachelor''s degree cum laude from Stanford University.', 'Anh đã nhận bằng cử nhân loại giỏi cum laude từ Đại học Stanford.', ARRAY['With honors', 'With praise']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('edu-34', 'education', 'Magna Cum Laude', '/ˌmæɡ.nə kʊm ˈlaʊ.deɪ/', 'Phrase', 'C1', 'Tốt nghiệp loại xuất sắc ưu tú (tiếng Latin)', 'With great honor; with high distinction.', 'She graduated magna cum laude, ranking within the top five percent of her medical class.', 'Cô đã tốt nghiệp loại xuất sắc magna cum laude, nằm trong top 5% sinh viên lớp y của mình.', ARRAY['With great distinction']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('edu-35', 'education', 'Summa Cum Laude', '/ˌsuː.mə kʊm ˈlaʊ.deɪ/', 'Phrase', 'C1', 'Tốt nghiệp thủ khoa loại xuất sắc tối cao (tiếng Latin)', 'With highest honor; with the highest distinction.', 'Finishing summa cum laude earned him an immediate prestigious faculty fellowship.', 'Tốt nghiệp loại xuất sắc tối cao summa cum laude đã mang lại cho anh một suất học bổng nghiên cứu giảng viên danh giá ngay lập tức.', ARRAY['With highest distinction', 'Top honor']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('edu-36', 'education', 'Dormitory', '/ˈdɔːr.mə.tɔːr.i/', 'Noun', 'A2', 'Ký túc xá sinh viên trong khuôn viên trường', 'A large bedroom for a number of people in a school or institution; a university hall of residence.', 'Living in the university dormitory fosters lifelong friendships among diverse international students.', 'Sống trong ký túc xá đại học nuôi dưỡng những tình bạn trọn đời giữa các sinh viên quốc tế đa dạng.', ARRAY['Dorm', 'Hall of residence', 'Student housing']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('edu-37', 'education', 'Campus', '/ˈkæm.pəs/', 'Noun', 'A2', 'Khuôn viên trường đại học', 'The grounds and buildings of a university or college.', 'The sprawling university campus features ancient Gothic libraries, tranquil botanical gardens, and modern laboratories.', 'Khuôn viên trường đại học rộng lớn nổi bật với những thư viện phong cách Gothic cổ kính, vườn bách thảo thanh bình và các phòng thí nghiệm hiện đại.', ARRAY['University grounds', 'College precinct']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('edu-38', 'education', 'Lecturer', '/ˈlek.tʃɚ.ɚ/', 'Noun', 'B1', 'Giảng viên đại học đứng lớp', 'A person who gives lectures, especially as an occupation at a university or college of higher education.', 'The guest lecturer shared practical insights from twenty years of building enterprise cloud systems.', 'Vị giảng viên thỉnh giảng đã chia sẻ những bài học thực tế từ hai mươi năm xây dựng các hệ sinh thái đám mây cho doanh nghiệp.', ARRAY['Instructor', 'Teacher', 'Academic']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('edu-39', 'education', 'Professor', '/prəˈfes.ɚ/', 'Noun', 'A2', 'Giáo sư giảng dạy và nghiên cứu học thuật', 'A university academic of the highest rank; a holder of an endowed or designated university chair.', 'The physics professor was honored with the international medal for her research on gravitational waves.', 'Vị giáo sư vật lý đã được vinh danh bằng huy chương quốc tế cho công trình nghiên cứu về sóng hấp dẫn.', ARRAY['Don', 'Academic chair', 'Scholar']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('edu-40', 'education', 'Dean', '/diːn/', 'Noun', 'B2', 'Trưởng khoa chuyên ngành', 'The head of a division, faculty, or school in a college or university.', 'The dean of the business school introduced a groundbreaking program combining finance with data science.', 'Trưởng khoa kinh doanh đã giới thiệu một chương trình đào tạo mang tính đột phá kết hợp giữa tài chính với khoa học dữ liệu.', ARRAY['Faculty head', 'Division director']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('edu-41', 'education', 'Chancellor', '/ˈtʃæn.səl.ɚ/', 'Noun', 'C1', 'Giám đốc / viện trưởng điều hành trường đại học', 'The head of the government in some European countries, or the titular head of a university.', 'The university chancellor delivered the welcoming keynote address to incoming international freshmen.', 'Giám đốc trường đại học đã có bài phát biểu quan trọng chào đón các tân sinh viên quốc tế nhập trường.', ARRAY['University head', 'President', 'Provost']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('edu-42', 'education', 'Provost', '/ˈproʊ.voʊst/', 'Noun', 'C1', 'Phó giám đốc phụ trách học thuật đại học', 'A senior administrative officer in certain universities.', 'The university provost oversees all academic appointments, research grants, and curriculum standards.', 'Phó viện trưởng phụ trách học thuật giám sát toàn bộ việc bổ nhiệm giảng viên, các khoản tài trợ nghiên cứu và các tiêu chuẩn chương trình học.', ARRAY['Chief academic officer', 'Vice-chancellor']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('edu-43', 'education', 'Registrar', '/ˈredʒ.ə.strɑːr/', 'Noun', 'B2', 'Phòng đào tạo quản lý hồ sơ sinh viên', 'An official responsible for keeping a register or official records at a university.', 'Visit the university registrar office to order official sealed transcripts for overseas study.', 'Hãy đến văn phòng đào tạo của trường đại học để xin cấp bảng điểm chính thức có dán tem niêm phong phục vụ du học.', ARRAY['Records officer', 'Academic clerk']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('edu-44', 'education', 'Bursar', '/ˈbɝː.sɚ/', 'Noun', 'C1', 'Trưởng phòng tài chính quản lý học phí trường học', 'A person who manages the financial affairs of a college or school.', 'The bursar sent a friendly payment reminder regarding second-semester accommodation fees.', 'Trưởng phòng tài chính đã gửi một lá thư nhắc nhở thanh toán ân cần về phí chỗ ở ký túc xá học kỳ hai.', ARRAY['Treasurer', 'Financial manager']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('edu-45', 'education', 'Peer Review', '/ˌpɪr rɪˈvjuː/', 'Noun', 'B2', 'Quy trình bình duyệt khoa học độc lập của đồng nghiệp', 'Evaluation of scientific, academic, or professional work by others working in the same field.', 'Manuscripts undergo rigorous anonymous peer review prior to acceptance in prestigious medical journals.', 'Các bản thảo phải trải qua quá trình bình duyệt kín nghiêm ngặt từ các đồng nghiệp trước khi được chấp nhận đăng trên các tạp chí y khoa danh tiếng.', ARRAY['Scholarly review', 'Expert vetting']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('edu-46', 'education', 'Citation', '/saɪˈteɪ.ʃən/', 'Noun', 'B2', 'Trích dẫn tài liệu học thuật theo chuẩn', 'A quotation from or reference to a book, paper, or author, especially in a scholarly work.', 'His groundbreaking 2017 paper on deep attention mechanisms garnered over fifty thousand citations.', 'Bài báo mang tính đột phá năm 2017 của ông về cơ chế chú ý sâu đã thu hút được hơn 50.000 lượt trích dẫn.', ARRAY['Reference', 'Bibliographical note']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('edu-47', 'education', 'Bibliography', '/ˌbɪb.liˈɑː.ɡrə.fi/', 'Noun', 'B2', 'Danh mục tài liệu tham khảo cuối luận văn', 'A list of the books of a particular author or printer, or on a particular subject, appended to a scholarly article.', 'Ensure your thesis bibliography is meticulously formatted according to standard APA 7th edition guidelines.', 'Hãy đảm bảo danh mục tài liệu tham khảo trong luận văn của bạn được định dạng tỉ mỉ theo đúng chuẩn hướng dẫn APA xuất bản lần thứ 7.', ARRAY['References', 'Reading list']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('edu-48', 'education', 'Plagiarize', '/ˈpleɪ.dʒɚ.aɪz/', 'Verb', 'B2', 'Đạo văn, chép bài của người khác', 'Take the work or an idea of someone else and pass it off as one''s own.', 'Never plagiarize paragraphs from online encyclopedias; always paraphrase and cite original sources correctly.', 'Tuyệt đối không bao giờ được đạo văn các đoạn văn từ bách khoa toàn thư trực tuyến; hãy luôn diễn đạt lại theo cách của mình và trích dẫn nguồn gốc chính xác.', ARRAY['Copy', 'Steal ideas', 'Appropriate']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('edu-49', 'education', 'Paraphrase', '/ˈper.ə.freɪz/', 'Verb', 'B1', 'Diễn giải lại bằng lời văn của mình mà không đổi nghĩa', 'Express the meaning of the writer or speaker or something written or spoken using different words, especially to achieve greater clarity.', 'Skilled academic essayists learn how to paraphrase complex philosophical arguments concisely.', 'Những người viết luận học thuật thành thạo biết cách diễn giải lại các lập luận triết học phức tạp một cách súc tích.', ARRAY['Reword', 'Restate', 'Rephrase']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('edu-50', 'education', 'Quotation', '/kwoʊˈteɪ.ʃən/', 'Noun', 'B1', 'Đoạn trích dẫn nguyên văn đặt trong ngoặc kép', 'A group of words taken from a text or speech and repeated by someone other than the original author or speaker.', 'The essay opens with a poignant quotation from Nelson Mandela on the transformative power of education.', 'Bài luận mở đầu bằng một câu trích dẫn đầy cảm xúc từ Nelson Mandela về sức mạnh biến đổi to lớn của giáo dục.', ARRAY['Citation', 'Excerpt', 'Quote']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('edu-51', 'education', 'Doctorate', '/ˈdɑːk.tɚ.ət/', 'Noun', 'B2', 'Học vị tiến sĩ cao nhất', 'The highest degree awarded by a graduate school or other approved educational organization.', 'She completed her doctorate in computational linguistics in just three and a half years.', 'Cô đã hoàn thành học vị tiến sĩ ngành ngôn ngữ học tính toán chỉ trong ba năm rưỡi.', ARRAY['PhD', 'Doctor''s degree']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('edu-52', 'education', 'Master''s Degree', '/ˈmæs.tɚz dɪˌɡriː/', 'Noun', 'B1', 'Bằng thạc sĩ sau đại học', 'A degree awarded by a graduate school and usually requiring at least one year of full-time study after a bachelor''s degree.', 'He pursued an online Master''s degree in software engineering while continuing his full-time job.', 'Anh đã theo học một chương trình lấy bằng thạc sĩ trực tuyến về kỹ thuật phần mềm trong khi vẫn tiếp tục công việc toàn thời gian của mình.', ARRAY['Postgraduate degree', 'Master''s']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('edu-53', 'education', 'Bachelor''s Degree', '/ˈbætʃ.əl.ɚz dɪˌɡriː/', 'Noun', 'A2', 'Bằng cử nhân đại học 4 năm', 'An undergraduate academic degree awarded by colleges and universities upon completion of a course of study lasting three to six years.', 'A bachelor''s degree in computer science or electrical engineering provides a solid foundational launchpad.', 'Bằng cử nhân khoa học máy tính hoặc kỹ thuật điện mang lại một bệ phóng nền tảng vô cùng vững chắc.', ARRAY['Undergraduate degree', 'Bachelor''s']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('edu-54', 'education', 'Associate Degree', '/əˈsoʊ.ʃi.ət dɪˌɡriː/', 'Noun', 'B1', 'Bằng cao đẳng 2 năm', 'A degree granted after a two-year course of study, especially by a community or junior college.', 'Earning an associate degree in cybersecurity enabled him to transition quickly into entry-level network defense.', 'Đạt được tấm bằng cao đẳng về an ninh mạng đã cho phép anh nhanh chóng chuyển mình sang công việc phòng thủ mạng cấp độ đầu vào.', ARRAY['Junior degree', 'Community college diploma']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('edu-55', 'education', 'Diploma', '/dɪˈploʊ.mə/', 'Noun', 'A2', 'Chứng chỉ hoặc văn bằng tốt nghiệp', 'A certificate awarded by an educational establishment to show that someone has successfully completed a course of study.', 'Students who pass the rigorous vocational electrical course receive an accredited technical diploma.', 'Học sinh vượt qua khóa học nghề điện nghiêm ngặt sẽ nhận được một tấm văn bằng kỹ thuật được kiểm định.', ARRAY['Certificate', 'Graduation award']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('edu-56', 'education', 'Vocational', '/voʊˈkeɪ.ʃən.əl/', 'Adj', 'B1', 'Thuộc về đào tạo học nghề thực hành', 'Relating to an occupation or employment; directed toward preparing someone for a trade or trade skill.', 'Vocational institutes provide intensive practical training in precision machining, welding, and carpentry.', 'Các viện đào tạo nghề cung cấp quá trình đào tạo thực hành chuyên sâu về gia công chính xác, hàn và nghề mộc.', ARRAY['Career-oriented', 'Trade-based', 'Occupational']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('edu-57', 'education', 'Apprenticeship', '/əˈpren.tɪs.ʃɪp/', 'Noun', 'B2', 'Thời gian học việc thực tế dưới sự hướng dẫn của thợ lành nghề', 'The position of an apprentice; a period of training under a skilled employer.', 'Completing a four-year electrical apprenticeship combines paid on-the-job training with classroom theory.', 'Hoàn thành kỳ học việc ngành điện kéo dài bốn năm là sự kết hợp giữa đào tạo thực tế tại chỗ có lương với lý thuyết trên lớp.', ARRAY['Internship', 'Traineeship', 'Practicum']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('edu-58', 'education', 'Practicum', '/ˈpræk.tə.kəm/', 'Noun', 'B2', 'Học phần thực hành thực địa áp dụng lý thuyết', 'A practical section of a course of study in medicine, nursing, or education.', 'Student teachers spend ten weeks in public school classrooms completing their mandatory clinical practicum.', 'Các giáo viên sinh viên thực tập dành mười tuần trong các lớp học trường công lập để hoàn thành học phần thực hành lâm sàng bắt buộc.', ARRAY['Practical training', 'Fieldwork']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('edu-59', 'education', 'Internship', '/ˈɪn.tɝːn.ʃɪp/', 'Noun', 'B1', 'Kỳ thực tập sinh viên tại doanh nghiệp', 'The position of a student or trainee who works in an organization, sometimes without pay, in order to gain work experience.', 'Securing a summer software engineering internship at a tech giant provides invaluable real-world experience.', 'Giành được một suất thực tập kỹ thuật phần mềm mùa hè tại một tập đoàn công nghệ lớn mang lại kinh nghiệm thực tế vô giá.', ARRAY['Work placement', 'Traineeship']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('edu-60', 'education', 'Co-op', '/ˈkoʊ.ɑːp/', 'Noun', 'B2', 'Chương trình thực tập vừa học vừa làm xen kẽ của đại học', 'A cooperative education program balancing classroom learning with full-time paid professional employment.', 'University co-op programs allow students to graduate with eighteen months of verified professional engineering experience.', 'Các chương trình đại học hợp tác vừa học vừa làm cho phép sinh viên tốt nghiệp với 18 tháng kinh nghiệm kỹ thuật chuyên nghiệp đã được xác thực.', ARRAY['Cooperative education', 'Work-study']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('edu-61', 'education', 'Pedagogue', '/ˈped.ə.ɡɑːɡ/', 'Noun', 'C1', 'Nhà sư phạm, thầy giáo nghiêm cẩn', 'A teacher, especially a strict or pedantic one.', 'The legendary pedagogue inspired generations of young mathematicians with his infectious enthusiasm.', 'Vị nhà sư phạm huyền thoại đã truyền cảm hứng cho nhiều thế hệ các nhà toán học trẻ bằng sự nhiệt tình lan tỏa của mình.', ARRAY['Teacher', 'Educator', 'Instructor']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('edu-62', 'education', 'Polymath', '/ˈpɑː.li.mæθ/', 'Noun', 'C1', 'Học giả uyên bác thông tuệ nhiều lĩnh vực', 'A person of wide-ranging knowledge or learning across multiple distinct disciplines.', 'Leonardo da Vinci stands as the supreme historical embodiment of the Renaissance polymath.', 'Leonardo da Vinci sừng sững như hiện thân lịch sử tối cao của một học giả uyên bác thời Phục hưng thông thạo nhiều lĩnh vực.', ARRAY['Renaissance person', 'Universal genius']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('edu-63', 'education', 'Autodidact', '/ˌɑː.toʊˈdaɪ.dækt/', 'Noun', 'C1', 'Người tự học thành tài không qua trường lớp', 'A self-taught person.', 'As an inquisitive autodidact, he mastered computer programming and Japanese entirely through online resources.', 'Là một người tự học ham học hỏi, anh đã thành thạo lập trình máy tính và tiếng Nhật hoàn toàn thông qua các tài nguyên trực tuyến.', ARRAY['Self-taught scholar', 'Independent learner']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('edu-64', 'education', 'Illiteracy', '/ɪˈlɪt̬.ɚ.ə.si/', 'Noun', 'B2', 'Nạn mù chữ không biết đọc viết', 'The inability to read or write.', 'Targeted village literacy initiatives helped eradicate adult illiteracy in remote mountainous districts.', 'Các sáng kiến xóa mù chữ tại các bản làng mục tiêu đã giúp xóa bỏ nạn mù chữ ở người lớn tại các huyện miền núi vùng sâu vùng xa.', ARRAY['Inability to read', 'Unlettered state']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('edu-65', 'education', 'Literacy', '/ˈlɪt̬.ɚ.ə.si/', 'Noun', 'B1', 'Khả năng biết đọc biết viết thành thạo', 'The ability to read and write.', 'Universal youth literacy is a primary foundation for sustainable national economic development.', 'Xóa mù chữ toàn diện cho thanh thiếu niên là nền tảng hàng đầu cho sự phát triển kinh tế quốc gia bền vững.', ARRAY['Reading ability', 'Education level']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('edu-66', 'education', 'Numeracy', '/ˈnuː.mɚ.ə.si/', 'Noun', 'B2', 'Năng lực tính toán toán học cơ bản', 'The ability to understand and work with numbers.', 'Early childhood educational games foster intuitive basic numeracy and spatial reasoning.', 'Các trò chơi giáo dục đầu đời nuôi dưỡng năng lực tính toán cơ bản và tư duy không gian một cách trực quan.', ARRAY['Mathematical skill', 'Number literacy']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('edu-67', 'education', 'Pedantry', '/ˈped.ən.tri/', 'Noun', 'C1', 'Thói câu nệ tiểu tiết sách vở máy móc', 'Excessive concern with minor details and rules in learning or teaching.', 'Avoid sterile academic pedantry; focus instead on applying core concepts to solve real human problems.', 'Hãy tránh thói câu nệ sách vở tiểu tiết máy móc vô bổ; thay vào đó hãy tập trung vào việc áp dụng các khái niệm cốt lõi để giải quyết các vấn đề thực tế của con người.', ARRAY['Dogmatism', 'Over-punctiliousness']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('edu-68', 'education', 'Erudite', '/ˈer.jʊ.daɪt/', 'Adj', 'C1', 'Uyên bác, học rộng tài cao', 'Having or showing great knowledge or learning.', 'The distinguished professor delivered an erudite lecture examining ancient Roman legal systems.', 'Vị giáo sư lỗi lạc đã có một bài giảng uyên bác khảo cứu các hệ thống pháp luật La Mã cổ đại.', ARRAY['Scholarly', 'Learned', 'Intellectual']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('edu-69', 'education', 'Intellectual', '/ˌɪn.t̬əlˈek.tʃu.əl/', 'Adj', 'B2', 'Thuộc về trí tuệ và học thuật thông thái', 'Relating to the intellect; appealing to or engaging the intellect.', 'Engaging in spirited intellectual discussions with colleagues broadens your scientific horizons.', 'Tham gia vào các cuộc thảo luận học thuật sôi nổi với các đồng nghiệp giúp mở rộng chân trời khoa học của bạn.', ARRAY['Scholarly', 'Cerebral', 'Mental']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('edu-70', 'education', 'Enlightenment', '/ɪnˈlaɪ.tən.mənt/', 'Noun', 'B2', 'Sự khai sáng trí tuệ, giác ngộ tri thức', 'The state of being enlightened; a European intellectual movement of the 17th and 18th centuries emphasizing reason and individualism rather than tradition.', 'The 18th-century European Enlightenment championed empirical scientific inquiry and universal human rights.', 'Thời kỳ Khai sáng châu Âu thế kỷ 18 đã cổ vũ mạnh mẽ cho cuộc điều tra khoa học thực nghiệm và các quyền con người phổ quát.', ARRAY['Illumination', 'Awakening', 'Understanding']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('edu-71', 'education', 'Scholar', '/ˈskɑː.lɚ/', 'Noun', 'B1', 'Học giả nghiên cứu chuyên sâu một lĩnh vực', 'A specialist in a particular branch of study, especially the humanities; a distinguished academic.', 'The visiting Sanskrit scholar decrypted ancient palm-leaf manuscripts preserved in the monastery.', 'Vị học giả tiếng Phạn thỉnh giảng đã giải mã những bản thảo cổ trên lá cọ được bảo tồn trong tu viện.', ARRAY['Academic', 'Researcher', 'Intellectual']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('edu-72', 'education', 'Classroom', '/ˈklæs.ruːm/', 'Noun', 'A1', 'Phòng học nơi học sinh tiếp thu kiến thức', 'A room, typically in a school, in which a class of students is taught.', 'Modern smart classrooms are outfitted with interactive digital touchscreens and ergonomic desks.', 'Các phòng học thông minh hiện đại được trang bị màn hình cảm ứng kỹ thuật số tương tác và bàn ghế công thái học.', ARRAY['Schoolroom', 'Lecture hall']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('edu-73', 'education', 'Laboratory', '/ˈlæb.rə.tɔːr.i/', 'Noun', 'A2', 'Phòng thí nghiệm khoa học', 'A room or building equipped for scientific experiments, research, or teaching.', 'Students must wear protective goggles and lab coats inside the organic chemistry laboratory.', 'Sinh viên phải đeo kính bảo hộ và áo choàng phòng thí nghiệm khi ở bên trong phòng thí nghiệm hóa học hữu cơ.', ARRAY['Lab', 'Research facility']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('edu-74', 'education', 'Library', '/ˈlaɪ.brer.i/', 'Noun', 'A1', 'Thư viện lưu trữ sách và tài liệu học tập', 'A building or room containing collections of books, periodicals, and sometimes films and recorded music for use or borrowing by the public or the members of an institution.', 'The university library provides quiet study cubicles and access to millions of digital academic journals.', 'Thư viện đại học cung cấp các khoang học tập yên tĩnh và quyền truy cập vào hàng triệu tạp chí học thuật kỹ thuật số.', ARRAY['Athenaeum', 'Book depository']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('edu-75', 'education', 'Seminar', '/ˈsem.ə.nɑːr/', 'Noun', 'B1', 'Buổi hội thảo chuyên đề thảo luận sâu', 'A conference or other meeting for discussion or training; a class at a university or college in which a topic is discussed by a teacher and a small group of students.', 'Graduate students presented their ongoing research papers during the weekly departmental seminar.', 'Các học viên cao học đã trình bày các bài báo nghiên cứu đang thực hiện của họ trong buổi hội thảo chuyên đề hàng tuần của khoa.', ARRAY['Colloquium', 'Workshop', 'Discussion group']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('edu-76', 'education', 'Workshop', '/ˈwɝːk.ʃɑːp/', 'Noun', 'B1', 'Buổi học thực hành rèn luyện kỹ năng thực tế', 'A meeting at which a group of people engage in intensive discussion and activity on a particular subject or project.', 'The three-day interactive writing workshop taught aspiring authors how to plot compelling novels.', 'Hội thảo viết thực hành kéo dài ba ngày đã dạy cho các tác giả đầy khát vọng cách xây dựng cốt truyện cho những cuốn tiểu thuyết hấp dẫn.', ARRAY['Masterclass', 'Training session', 'Clinic']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('edu-77', 'education', 'Symposium', '/sɪmˈpoʊ.zi.əm/', 'Noun', 'C1', 'Hội nghị khoa học chuyên đề tầm cỡ', 'A conference or meeting to discuss a particular subject; a collection of essays or papers on a subject by a number of contributors.', 'International climatologists convened at the annual polar symposium to discuss ice sheet melting rates.', 'Các nhà khí hậu học quốc tế đã triệu tập tại hội nghị chuyên đề vùng cực thường niên để thảo luận về tốc độ tan chảy của các tảng băng.', ARRAY['Conference', 'Convention', 'Colloquium']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('edu-78', 'education', 'Colloquium', '/kəˈloʊ.kwi.əm/', 'Noun', 'C1', 'Hội đàm học thuật trao đổi quan điểm', 'An academic conference or seminar.', 'The philosophy department hosts a monthly colloquium inviting distinguished external scholars.', 'Khoa triết học tổ chức một buổi hội đàm học thuật hàng tháng mời các học giả lỗi lạc từ bên ngoài đến chia sẻ.', ARRAY['Symposium', 'Academic gathering']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('edu-79', 'education', 'Thesis', '/ˈθiː.sɪs/', 'Noun', 'B2', 'Luận điểm nghiên cứu hoặc bài luận văn tốt nghiệp', 'A long piece of writing on a particular subject, especially one that is done for a higher college or university degree.', 'Her master''s thesis analyzed the socioeconomic impacts of rural microfinance in Southeast Asia.', 'Luận văn thạc sĩ của cô đã phân tích các tác động kinh tế xã hội của tài chính vi mô nông thôn ở Đông Nam Á.', ARRAY['Dissertation', 'Research monograph']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('edu-80', 'education', 'Hypothesis', '/haɪˈpɑː.θə.sɪs/', 'Noun', 'B2', 'Giả thuyết khoa học cần kiểm chứng', 'A supposition or proposed explanation made on the basis of limited evidence as a starting point for further investigation.', 'Experiments were meticulously designed to test the initial scientific hypothesis.', 'Các thí nghiệm đã được thiết kế tỉ mỉ để kiểm chứng giả thuyết khoa học ban đầu.', ARRAY['Theory', 'Premise', 'Proposition']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('edu-81', 'education', 'Methodology', '/ˌmeθ.əˈdɑː.lə.dʒi/', 'Noun', 'B2', 'Phương pháp luận nghiên cứu khoa học', 'A system of methods used in a particular area of study or activity.', 'The dissertation devotes an entire comprehensive chapter to quantitative survey methodology.', 'Luận án dành hẳn một chương toàn diện cho phương pháp luận điều tra khảo sát định lượng.', ARRAY['Method', 'Research approach', 'Technique']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('edu-82', 'education', 'Qualitative', '/ˈkwɑː.lə.teɪ.t̬ɪv/', 'Adj', 'B2', 'Nghiên cứu định tính dựa trên phỏng vấn và quan sát', 'Relating to, measuring, or measured by the quality of something rather than its quantity.', 'Qualitative interviews provided deep nuanced insights into the psychological motives of consumers.', 'Các cuộc phỏng vấn định tính đã mang lại những hiểu biết sâu sắc và tinh tế về các động cơ tâm lý của người tiêu dùng.', ARRAY['Descriptive', 'Non-numerical']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('edu-83', 'education', 'Quantitative', '/ˈkwɑːn.t̬ə.teɪ.t̬ɪv/', 'Adj', 'B2', 'Nghiên cứu định lượng dựa trên số liệu và thống kê', 'Relating to, measuring, or measured by the quantity of something rather than its quality.', 'Rigorous quantitative statistical analysis verified that the correlation was statistically significant.', 'Phân tích thống kê định lượng nghiêm ngặt đã xác minh rằng mối tương quan có ý nghĩa thống kê.', ARRAY['Numerical', 'Data-driven', 'Statistical']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('edu-84', 'education', 'Empirical', '/emˈpɪr.ɪ.kəl/', 'Adj', 'C1', 'Thực nghiệm dựa trên dữ liệu thu thập thực tế', 'Based on, concerned with, or verifiable by observation or experience rather than theory or pure logic.', 'The paper presented solid empirical evidence disproving the classical economic theory.', 'Bài báo đã trình bày các bằng chứng thực nghiệm vững chắc bác bỏ lý thuyết kinh tế cổ điển.', ARRAY['Evidence-based', 'Observed', 'Practical']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('edu-85', 'education', 'Theoretical', '/ˌθiː.əˈret̬.kəl/', 'Adj', 'B2', 'Mang tính lý thuyết học thuật trừu tượng', 'Concerned with or involving the theory of a subject or area of study rather than its practical application.', 'Theoretical physicists formulate mathematical models describing the origins of cosmic spacetime.', 'Các nhà vật lý lý thuyết xây dựng các mô hình toán học mô tả nguồn gốc của không-thời gian vũ trụ.', ARRAY['Abstract', 'Conceptual', 'Hypothetical']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('food-1', 'food', 'Delicacy', '/ˈdel.ə.kə.si/', 'Noun', 'B2', 'Món ăn cao lương mỹ vị quý hiếm', 'Something delightful or pleasing, especially a choice food considered rare or expensive.', 'Smoked sturgeon caviar and white truffles are celebrated worldwide as rare luxury delicacies.', 'Trứng cá tầm muối hun khói và nấm truffle trắng được tôn vinh trên toàn thế giới như những món cao lương mỹ vị quý hiếm xa xỉ.', ARRAY['Gourmet food', 'Treat', 'Dainty']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('food-2', 'food', 'Artisan', '/ˈɑːr.t̬ə.zən/', 'Adj', 'B2', 'Nghệ nhân thủ công truyền thống chất lượng cao', 'Made in a traditional or non-mechanized way using high-quality ingredients.', 'The rustic countryside bakery is famous for its crusty artisan sourdough bread.', 'Tiệm bánh mì mộc mạc ở vùng nông thôn nổi tiếng với món bánh mì men chua thủ công giòn rụm được làm theo phương pháp truyền thống.', ARRAY['Handcrafted', 'Craftsman-made', 'Traditional']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('food-3', 'food', 'Culinary', '/ˈkʌl.ə.ner.i/', 'Adj', 'B2', 'Thuộc về nghệ thuật ẩm thực và nấu nướng', 'Of or for cooking or the kitchen; relating to food preparation.', 'Studying at the historic French culinary institute honed his master chef techniques.', 'Học tập tại viện ẩm thực lịch sử của Pháp đã giúp mài giũa những kỹ thuật đỉnh cao của một đầu bếp bậc thầy.', ARRAY['Gastronomic', 'Cooking', 'Kitchen']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('food-4', 'food', 'Gourmet', '/ɡʊrˈmeɪ/', 'Adj', 'B2', 'Ẩm thực sành điệu tinh tế chuẩn sao', 'Relating to or being high quality, sophisticated, or exotic food and drink.', 'The downtown five-star hotel features an award-winning gourmet seafood restaurant.', 'Khách sạn 5 sao ở trung tâm thành phố có một nhà hàng hải sản cao cấp sành điệu từng đoạt nhiều giải thưởng danh giá.', ARRAY['Epicurean', 'Fine-dining', 'High-class']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('food-5', 'food', 'Savor', '/ˈseɪ.vɚ/', 'Verb', 'B2', 'Thưởng thức từ tốn, nhâm nhi từng hương vị', 'Taste good food or drink and enjoy it completely; appreciate fully.', 'Take your time to savor the complex notes of roasted hazelnut and dark berry in the single-origin coffee.', 'Hãy dành thời gian để thưởng thức từ tốn những nốt hương phức hợp của hạt phỉ nướng và quả mọng đen trong tách cà phê nguyên bản.', ARRAY['Relish', 'Enjoy slowly', 'Appreciate']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('food-6', 'food', 'Appetizing', '/ˈæp.ə.taɪ.zɪŋ/', 'Adj', 'B1', 'Ngon mắt, khơi gợi cảm giác thèm ăn', 'Appealing to the appetite; looking, sounding, or smelling delicious.', 'The golden roasted chicken was served with an exceptionally appetizing honey-rosemary glaze.', 'Món gà nướng vàng rộm được phục vụ với lớp nước sốt mật ong hương thảo vô cùng ngon mắt và kích thích vị giác.', ARRAY['Mouth-watering', 'Tempting', 'Delicious']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('food-7', 'food', 'Fermentation', '/ˌfɝː.menˈteɪ.ʃən/', 'Noun', 'B2', 'Quá trình lên men vi sinh tạo hương vị độc đáo', 'The chemical breakdown of a substance by bacteria, yeasts, or other microorganisms, typically involving effervescence and the giving off of heat.', 'Traditional lactic acid fermentation transforms plain cabbage into tangy, probiotic-rich kimchi.', 'Quá trình lên men axit lactic truyền thống biến bắp cải thông thường thành món kim chi chua thanh và giàu lợi khuẩn sinh học.', ARRAY['Brewing', 'Culturing', 'Microbial breakdown']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('food-8', 'food', 'Palatable', '/ˈpæl.ə.t̬ə.bəl/', 'Adj', 'C1', 'Hợp khẩu vị, vừa miệng dễ ăn', 'Pleasant to taste; acceptable or satisfactory.', 'Adding a dash of sweet coconut milk made the spicy Thai curry wonderfully palatable.', 'Thêm một chút nước cốt dừa ngọt béo đã khiến món cà ri cay kiểu Thái trở nên vô cùng vừa miệng và thơm ngon.', ARRAY['Tasty', 'Flavorful', 'Appetizing']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('food-9', 'food', 'Condiment', '/ˈkɑːn.də.mənt/', 'Noun', 'B1', 'Gia vị chấm hoặc nêm ăn kèm (tương, ớt, giấm)', 'A substance such as salt, mustard, or pickle that is used to add flavor to food.', 'Vietnamese fish sauce seasoned with lime and chili is an indispensable dipping condiment.', 'Nước mắm Việt Nam pha chanh ớt là một loại gia vị chấm ăn kèm không thể thiếu trong mỗi bữa ăn.', ARRAY['Seasoning', 'Sauce', 'Dressing']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('food-10', 'food', 'Aroma', '/əˈroʊ.mə/', 'Noun', 'B1', 'Hương thơm ngào ngạt của đồ ăn thức uống', 'A distinctive, typically pleasant smell of food, wine, or coffee.', 'The enticing aroma of fresh garlic sizzling in olive oil filled the bustling kitchen.', 'Hương thơm quyến rũ của tỏi tươi xèo xèo trong dầu ô liu lan tỏa khắp căn bếp nhộn nhịp.', ARRAY['Fragrance', 'Scent', 'Bouquet']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('food-11', 'food', 'Marinade', '/ˌmer.əˈneɪd/', 'Noun', 'B1', 'Nước sốt ướp thịt cá cho thấm gia vị', 'A sauce, typically made of oil, vinegar, spices, and herbs, in which meat, fish, or other food is soaked before cooking.', 'Soaking beef ribs overnight in a sweet soy marinade guarantees tender, juicy barbecue.', 'Ngâm sườn bò qua đêm trong nước sốt ướp tương ngọt đảm bảo món nướng sẽ mềm ngọt và mọng nước.', ARRAY['Seasoning sauce', 'Soak', 'Brine']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('food-12', 'food', 'Marinate', '/ˈmer.ə.neɪt/', 'Verb', 'B1', 'Ướp gia vị cho thực phẩm ngấm đều', 'Undergo soaking in a marinade.', 'Marinate the salmon fillets for at least thirty minutes before placing them on the hot grill.', 'Hãy ướp các miếng phi lê cá hồi trong ít nhất ba mươi phút trước khi đặt chúng lên vỉ nướng nóng.', ARRAY['Soak', 'Season', 'Steep']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('food-13', 'food', 'Simmer', '/ˈsɪm.ɚ/', 'Verb', 'B1', 'Đun sôi liu riu nhỏ lửa', 'Stay just below the boiling point while bubbling gently.', 'Let the bone broth simmer on low heat for ten hours to extract maximum collagen richness.', 'Hãy để nồi nước dùng xương đun sôi liu riu trên lửa nhỏ trong mười tiếng để chiết xuất tối đa lượng collagen đậm đà.', ARRAY['Stew', 'Bubble gently', 'Poach']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('food-14', 'food', 'Sauté', '/soʊˈteɪ/', 'Verb', 'B2', 'Xào lăn nhanh trên chảo nóng với ít dầu', 'Fried quickly in a little hot fat or oil.', 'Sauté the chopped shallots and wild mushrooms until they turn tender and golden brown.', 'Xào nhanh hành tím băm nhỏ và nấm rừng cho đến khi chúng mềm và chuyển sang màu nâu vàng đẹp mắt.', ARRAY['Pan-fry', 'Stir-fry', 'Sear']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('food-15', 'food', 'Caramelize', '/ˈker.ə.məl.aɪz/', 'Verb', 'B2', 'Thắng đường, làm đường chuyển màu nâu caramen', 'Convert or be converted into caramel, typically through the application of heat to sugars.', 'Slowly cooking sliced onions caramelizes their natural sugars into a rich, sweet relish.', 'Nấu hành tây thái lát từ từ trên lửa nhỏ sẽ thắng đường tự nhiên của chúng thành một món sốt ngọt ngào đậm đà.', ARRAY['Brown', 'Sugar-cook']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('food-16', 'food', 'Blanch', '/blæntʃ/', 'Verb', 'B2', 'Trần sơ qua nước sôi rồi ngâm nước đá giữ màu', 'Make white or pale by extracting color; in cooking, plunge into boiling water briefly.', 'Blanch the fresh green asparagus for two minutes to preserve its vibrant emerald hue and crisp snap.', 'Trần măng tây xanh tươi qua nước sôi trong hai phút để giữ lại sắc xanh ngọc bích rực rỡ và độ giòn ngọt.', ARRAY['Parboil', 'Scald']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('food-17', 'food', 'Broil', '/brɔɪl/', 'Verb', 'B1', 'Nướng bằng nhiệt trực tiếp từ phía trên', 'Cook by exposure to direct, intense radiant heat, typically from above.', 'Broil the cheese-topped oysters under high oven heat until bubbly and melted.', 'Nướng hàu phủ phô mai dưới nhiệt độ lò nướng cao từ phía trên cho đến khi sủi bọt và tan chảy thơm lừng.', ARRAY['Grill', 'Roast under direct heat']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('food-18', 'food', 'Braise', '/breɪz/', 'Verb', 'B2', 'Om, hầm trong nồi đậy kín với một ít nước sốt', 'Fry food lightly and then stew it slowly in a closed container.', 'Braise the pork belly chunks in caramel fish sauce until melt-in-your-mouth succulent.', 'Om những miếng thịt ba chỉ trong nước hàng mắm cho đến khi mềm tan mọng nước trong miệng.', ARRAY['Slow-cook', 'Pot-roast', 'Stew']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('food-19', 'food', 'Sear', '/sɪr/', 'Verb', 'B2', 'Áp chảo lửa lớn cho cháy cạnh bên ngoài', 'Burn or scorch the surface of something with a sudden, intense heat.', 'Sear the prime ribeye steak for two minutes on each side to lock in flavorful natural juices.', 'Áp chảo miếng thịt thăn bò hảo hạng trong hai phút mỗi mặt trên lửa lớn để khóa chặt vị ngọt tự nhiên thơm lừng bên trong.', ARRAY['Brown quickly', 'Scorch', 'Char']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('food-20', 'food', 'Garnish', '/ˈɡɑːr.nɪʃ/', 'Verb', 'B1', 'Trang trí món ăn bằng rau mùi hoặc hoa lát mỏng', 'Decorate or embellish something, especially food.', 'Garnish the velvety pumpkin soup with toasted pumpkin seeds and a swirl of cream.', 'Trang trí bát súp bí đỏ mịn màng bằng hạt bí nướng giòn và một đường kem tươi xoáy nghệ thuật.', ARRAY['Decorate', 'Adorn', 'Embellish']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('food-21', 'food', 'Appetizer', '/ˈæp.ə.taɪ.zɚ/', 'Noun', 'A2', 'Món khai vị đầu bữa ăn kích thích vị giác', 'A small dish of food or a drink taken before a meal or the main course of a meal to stimulate one''s appetite.', 'Crispy vegetarian spring rolls served with sweet chili dip made a delightful light appetizer.', 'Những chiếc nem chay giòn rụm ăn kèm nước chấm ớt ngọt tạo nên một món khai vị nhẹ nhàng đầy thú vị.', ARRAY['Starter', 'Hors d''oeuvre', 'First course']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('food-22', 'food', 'Entrée', '/ˈɑːn.treɪ/', 'Noun', 'B1', 'Món ăn chính trong thực đơn phương Tây', 'The main course of a meal in modern North American culinary terminology.', 'For the main dinner entrée, guests had a choice between grilled Chilean sea bass and duck confit.', 'Đối với món chính của bữa tối, các thực khách có sự lựa chọn giữa cá vược Chile nướng và đùi vịt confit.', ARRAY['Main dish', 'Main course', 'Plat principal']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('food-23', 'food', 'Dessert', '/dɪˈzɝːt/', 'Noun', 'A2', 'Món tráng miệng ngọt ngào kết thúc bữa tiệc', 'The sweet course eaten at the end of a meal.', 'A warm dark chocolate lava cake served with Tahitian vanilla bean gelato was the perfect sweet dessert.', 'Chiếc bánh sô-cô-la đen tan chảy ấm nóng phục vụ cùng kem gelato vani Tahiti là món tráng miệng ngọt ngào hoàn hảo.', ARRAY['Sweet course', 'Pudding']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('food-24', 'food', 'Sommelier', '/sɑːm.əlˈjeɪ/', 'Noun', 'C1', 'Chuyên gia thử nếm và tư vấn kết hợp rượu vang', 'A wine waiter; a trained and knowledgeable wine professional, normally working in fine dining restaurants.', 'The certified sommelier recommended a crisp, mineral Chablis to pair with the raw oyster platter.', 'Chuyên gia rượu vang được chứng nhận đã gợi ý một chai Chablis thanh mát, đậm khoáng chất để kết hợp cùng đĩa hàu sống.', ARRAY['Wine steward', 'Wine expert']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('food-25', 'food', 'Degustation', '/ˌdiː.ɡʌsˈteɪ.ʃən/', 'Noun', 'C1', 'Tiệc thưởng thức nhiều món nhỏ nếm thử', 'The action or an instance of tasting or savoring something, especially food or drink; a tasting menu.', 'The Michelin-starred restaurant offers a memorable twelve-course degustation menu showcasing local micro-seasons.', 'Nhà hàng gắn sao Michelin cung cấp thực đơn nếm thử 12 món đáng nhớ thể hiện rõ các tiểu mùa khí hậu của địa phương.', ARRAY['Tasting menu', 'Sampling dinner']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('food-26', 'food', 'Confectionery', '/kənˈfek.ʃən.er.i/', 'Noun', 'B2', 'Bánh kẹo đồ ngọt thủ công tinh xảo', 'Sweets and chocolates considered collectively; the candy-making craft.', 'Belgian confectionery is internationally celebrated for exquisite pralines and delicate fruit jellies.', 'Bánh kẹo Bỉ nổi tiếng trên toàn thế giới với những viên kẹo praline tinh xảo và kẹo thạch trái cây thanh tao.', ARRAY['Sweets', 'Candies', 'Pastries']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('food-27', 'food', 'Pastry', '/ˈpeɪ.stri/', 'Noun', 'A2', 'Bánh ngọt nướng bằng bột mì nhiều lớp bơ', 'A dough of flour, fat, and water, used as a base and covering in baked dishes such as pies.', 'Flaky French butter croissants require meticulous pastry laminating techniques to achieve fifty layers.', 'Bánh sừng bò bơ Pháp giòn rụm nhiều lớp đòi hỏi kỹ thuật cán bột bánh ngọt tỉ mỉ để đạt tới 50 lớp bơ mỏng.', ARRAY['Baked good', 'Tart', 'Croissant']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('food-28', 'food', 'Dough', '/doʊ/', 'Noun', 'B1', 'Khối bột nhào đã lên men để nướng bánh', 'A thick, malleable mixture of flour and liquid, used for baking into bread or pastry.', 'Knead the elastic pizza dough thoroughly on a floured marble counter for ten minutes.', 'Nhào kỹ khối bột bánh pizza đàn hồi trên mặt bàn đá cẩm thạch rắc bột trong mười phút.', ARRAY['Batter', 'Bread paste']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('food-29', 'food', 'Batter', '/ˈbæt̬.ɚ/', 'Noun', 'B1', 'Bột lỏng pha trứng sữa để rán hoặc nhúng bột', 'A semi-liquid mixture of one or more flours made with liquids such as water, milk, or eggs.', 'Dip the jumbo prawns into the airy tempura batter before dropping them into boiling hot oil.', 'Nhúng những con tôm sú lớn vào lớp bột lỏng tempura xốp nhẹ trước khi thả chúng vào chảo dầu nóng sôi.', ARRAY['Liquid dough', 'Pancake mix']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('food-30', 'food', 'Knead', '/niːd/', 'Verb', 'B2', 'Nhào bột bằng tay cho dẻo quánh', 'Work moistened flour or clay into dough or paste with the hands.', 'Knead the bread dough until it passes the windowpane stretch test and feels satin smooth.', 'Nhào bột bánh mì cho đến khi nó vượt qua bài kiểm tra kéo màng mỏng và cho cảm giác mịn như lụa satin.', ARRAY['Massage dough', 'Work paste']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('food-31', 'food', 'Whisk', '/wɪsk/', 'Verb', 'B1', 'Đánh bông trứng hoặc kem bằng cây đánh trứng', 'Beat or stir a substance, especially cream or eggs, with a light, rapid movement.', 'Whisk the cold heavy whipping cream until stiff, glossy peaks form in the copper bowl.', 'Đánh bông kem tươi lạnh cho đến khi hình thành các chóp nhọn bóng bẩy và cứng cáp trong chiếc âu đồng.', ARRAY['Beat', 'Whip', 'Blend']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('food-32', 'food', 'Infusion', '/ɪnˈfjuː.ʒən/', 'Noun', 'B2', 'Nước hãm trà thảo mộc hoặc chiết xuất hương vị', 'A drink, remedy, or extract prepared by soaking tea leaves or herbs in liquid.', 'A soothing warm chamomile and lavender herbal infusion calms racing minds before bedtime.', 'Một tách nước hãm thảo mộc hoa cúc và hoa oải hương ấm áp giúp xoa dịu những tâm trí đang căng thẳng trước giờ đi ngủ.', ARRAY['Steeped tea', 'Herbal brew', 'Extract']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('food-33', 'food', 'Steep', '/stiːp/', 'Verb', 'B2', 'Hãm, ngâm lá trà trong nước nóng lấy tinh chất', 'Soak in water or other liquid, as to soften, cleanse, or extract an essential principle.', 'Steep the organic high-mountain oolong tea leaves for three minutes to release floral notes.', 'Hãm những búp trà ô long hữu cơ vùng núi cao trong ba phút để giải phóng trọn vẹn những nốt hương hoa thanh khiết.', ARRAY['Infuse', 'Soak', 'Brew']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('food-34', 'food', 'Zest', '/zest/', 'Noun', 'B2', 'Vỏ cam chanh bào lấy tinh dầu thơm nồng', 'Scrape off the outer colored part of the peel of a citrus fruit for use as flavoring.', 'A teaspoon of freshly grated lemon zest adds vibrant brightness to the creamy pasta sauce.', 'Một thìa cà phê vỏ chanh vàng mới bào tươi mang lại sự tươi sáng sống động cho món sốt mì ống béo ngậy.', ARRAY['Citrus peel', 'Flavoring skin']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('food-35', 'food', 'Coriander', '/ˈkɔːr.i.æn.dɚ/', 'Noun', 'B1', 'Rau mùi, ngò rí tươi', 'An aromatic Mediterranean plant of the parsley family, the leaves and seeds of which are used as culinary herbs.', 'Fresh coriander leaves are scattered over steaming bowls of beef pho just before serving.', 'Những lá rau mùi tươi xanh được rắc lên những bát phở bò bốc khói nghi ngút ngay trước khi bưng ra phục vụ.', ARRAY['Cilantro', 'Chinese parsley']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('food-36', 'food', 'Seasoning', '/ˈsiː.zən.ɪŋ/', 'Noun', 'A2', 'Gia vị nêm nếm mặn ngọt cho vừa miệng', 'Salt, herbs, or spices added to food to enhance the flavor.', 'Taste the simmered tomato stew frequently to adjust the salt and pepper seasoning.', 'Hãy nếm thử món hầm cà chua đang đun sôi thường xuyên để điều chỉnh gia vị muối và hạt tiêu cho vừa vặn.', ARRAY['Flavoring', 'Condiment', 'Spice']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('food-37', 'food', 'Piquant', '/ˈpiː.kənt/', 'Adj', 'C1', 'Vị cay the kích thích đầu lưỡi, đậm đà', 'Having a pleasantly sharp taste or appetizing flavor.', 'The piquant homemade salsa combined fiery jalapeño peppers with zesty fresh lime juice.', 'Món sốt salsa tự làm có vị cay the kích thích kết hợp giữa ớt jalapeño cay nồng với nước cốt chanh tươi chua thanh.', ARRAY['Spicy', 'Sharp', 'Zesty']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('food-38', 'food', 'Zesty', '/ˈzes.ti/', 'Adj', 'B2', 'Chua thanh the mát, tràn đầy sức sống', 'Having a strong, pleasant, and somewhat spicy flavor.', 'The lime-coriander salad dressing lends a wonderfully zesty kick to the grilled chicken.', 'Nước sốt salad chanh ngò rí mang lại một cú hích chua thanh the mát tuyệt vời cho món gà nướng.', ARRAY['Tangy', 'Invigorating', 'Spirited']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('food-39', 'food', 'Tangy', '/ˈtæŋ.i/', 'Adj', 'B1', 'Chua ngọt sắc sảo đượm vị', 'Having a pleasantly sharp and strong taste, like lemons or ripe tamarind.', 'Key lime pie is famous for its smooth custard filling that is simultaneously sweet and tangy.', 'Bánh tart chanh Key nổi tiếng với lớp nhân kem trứng mịn màng vừa ngọt ngào lại vừa chua thanh sắc sảo.', ARRAY['Tart', 'Sharp-tasting', 'Acidic']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('food-40', 'food', 'Crispy', '/ˈkrɪs.pi/', 'Adj', 'A2', 'Giòn rụm bên ngoài khi chiên nướng', 'Pleasantly thin, dry, and easily broken, having a firm dry texture.', 'These golden french fries are irresistibly crispy on the outside yet fluffy inside.', 'Những cọng khoai tây chiên vàng ruộm này giòn rụm khó cưỡng ở bên ngoài nhưng lại mềm xốp bên trong.', ARRAY['Crunchy', 'Brittle', 'Crusty']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('food-41', 'food', 'Succulent', '/ˈsʌk.jə.lənt/', 'Adj', 'B2', 'Mọng nước ngọt mềm thịt cá', 'Tender, juicy, and tasty of food, especially meat.', 'The roast turkey breast was surprisingly succulent and flavorful, never drying out in the oven.', 'Phần ức gà tây nướng mềm mọng nước và đậm đà đến kinh ngạc, không hề bị khô cứng trong lò nướng.', ARRAY['Juicy', 'Moist', 'Luscious']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('food-42', 'food', 'Melt-in-your-mouth', '/ˌmelt.ɪn.jɔːrˈmaʊθ/', 'Adj', 'B1', 'Mềm tan biến ngay trong miệng', 'Extremely tender, soft, and delicious food.', 'Slow-cooked Japanese wagyu beef possesses a melt-in-your-mouth buttery marbling texture.', 'Thịt bò wagyu Nhật Bản nấu chậm sở hữu kết cấu vân mỡ cẩm thạch béo ngậy mềm tan ngay trên đầu lưỡi.', ARRAY['Super tender', 'Dissolving']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('food-43', 'food', 'Savory', '/ˈseɪ.vɚ.i/', 'Adj', 'B1', 'Đậm đà vị mặn ngọt hài hòa, không ngọt tráng miệng', 'Belonging to the category that is salty or spicy rather than sweet in food classification.', 'She prefers hearty savory breakfast dishes like omelets and sausage over sweet sugary pancakes.', 'Cô ấy thích những món ăn sáng đậm đà như trứng tráng và xúc xích hơn là những chiếc bánh kếp ngọt nhiều đường.', ARRAY['Salty-sweet', 'Umami', 'Flavorful']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('food-44', 'food', 'Umami', '/uːˈmɑː.mi/', 'Noun', 'B2', 'Vị ngọt thịt tự nhiên từ glutamate (vị thứ 5)', 'A category of taste in food (besides sweet, sour, salt, and bitter), corresponding to the flavor of glutamates, especially monosodium glutamate.', 'Aged Parmesan cheese, ripe tomatoes, and dried shiitake mushrooms are packed with rich natural umami.', 'Phô mai Parmesan ủ lâu năm, cà chua chín mọng và nấm hương khô chứa đầy vị ngọt thịt umami tự nhiên phong phú.', ARRAY['Savory taste', 'Meatiness']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('food-45', 'food', 'Glaze', '/ɡleɪz/', 'Noun', 'B2', 'Lớp nước sốt bóng bẩy phủ mặt ngoài món nướng', 'A shiny coating brushed onto food, such as a sugar syrup on pastry or a reduction on meat.', 'Brush the roast duck with a shiny hoisin-honey glaze during the final fifteen minutes of baking.', 'Hãy quét lên mình vịt quay một lớp nước sốt bóng bẩy mật ong tương đen trong 15 phút nướng cuối cùng.', ARRAY['Glossy coat', 'Icing', 'Lacquer']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('food-46', 'food', 'Carbohydrate', '/ˌkɑːr.boʊˈhaɪ.dreɪt/', 'Noun', 'B1', 'Chất bột đường tinh bột cung cấp năng lượng', 'Any of a large group of organic compounds occurring in foods and living tissues and including sugars, starch, and cellulose.', 'Complex carbohydrates found in whole grain oats release sustained physical energy throughout the morning.', 'Các loại carbohydrate phức hợp có trong yến mạch nguyên cám giải phóng năng lượng thể chất bền bỉ suốt cả buổi sáng.', ARRAY['Carb', 'Starch', 'Sugar']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('food-47', 'food', 'Protein', '/ˈproʊ.tiːn/', 'Noun', 'A2', 'Chất đạm xây dựng cơ bắp và tế bào', 'Any of a class of nitrogenous organic compounds that consist of large molecules composed of one or more long chains of amino acids and are an essential part of all living organisms.', 'Eggs, Greek yogurt, and chicken breasts provide clean, bioavailable protein for muscle recovery.', 'Trứng gà, sữa chua Hy Lạp và ức gà cung cấp nguồn chất đạm sạch, dễ hấp thu cho sự phục hồi cơ bắp.', ARRAY['Amino source', 'Nutritional protein']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('food-48', 'food', 'Fiber', '/ˈfaɪ.bɚ/', 'Noun', 'B1', 'Chất xơ tiêu hóa tốt cho đường ruột', 'Dietary material containing substances such as cellulose, lignin, and pectin, which are resistant to the action of digestive enzymes.', 'Eating abundant dietary fiber promotes healthy gut flora biodiversity and stabilizes blood sugar.', 'Ăn nhiều chất xơ hòa tan thúc đẩy sự đa dạng sinh học của hệ vi sinh đường ruột và ổn định đường huyết.', ARRAY['Roughage', 'Dietary bulk']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('food-49', 'food', 'Cholesterol', '/kəˈles.tə.rɑːl/', 'Noun', 'B1', 'Chất mỡ máu cholesterol cần kiểm soát', 'A compound of the sterol type found in animal tissues and blood, related to heart disease when elevated.', 'Avocados contain healthy monounsaturated fats that help reduce bad LDL cholesterol in the bloodstream.', 'Quả bơ chứa các chất béo không bão hòa đơn lành mạnh giúp làm giảm cholesterol xấu LDL trong máu.', ARRAY['Blood fat']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('food-50', 'food', 'Gluten', '/ˈɡluː.tən/', 'Noun', 'B1', 'Protein tạo độ dai dính trong lúa mì', 'A substance present in cereal grains, especially wheat, that is responsible for the elastic texture of dough.', 'People diagnosed with celiac disease must strictly consume certified gluten-free alternative grains.', 'Những người được chẩn đoán mắc bệnh celiac phải tiêu thụ nghiêm ngặt các loại ngũ cốc thay thế không chứa gluten đã được chứng nhận.', ARRAY['Wheat protein']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('food-51', 'food', 'Beverage', '/ˈbev.ɚ.ɪdʒ/', 'Noun', 'B1', 'Đồ uống giải khát các loại', 'A drink, especially one other than water.', 'The flight attendant wheeled a trolley stocked with sparkling beverages, juices, and hot tea.', 'Tiếp viên hàng không đẩy một chiếc xe đẩy chứa đầy các loại đồ uống có ga, nước trái cây và trà nóng.', ARRAY['Drink', 'Refreshment', 'Liquid']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('food-52', 'food', 'Gastronomy', '/ɡæsˈtrɑː.nə.mi/', 'Noun', 'C1', 'Nghệ thuật ẩm thực và văn hóa thưởng thức món ngon', 'The practice or art of choosing, cooking, and eating good food.', 'Molecular gastronomy merges laboratory science with culinary art to create unexpected textures.', 'Ẩm thực phân tử kết hợp khoa học phòng thí nghiệm với nghệ thuật nấu ăn để tạo ra những kết cấu bất ngờ.', ARRAY['Culinary art', 'Food culture']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('food-53', 'food', 'Barista', '/bəˈrɪs.tə/', 'Noun', 'B1', 'Chuyên gia pha chế cà phê điêu luyện', 'A person who prepares and serves espresso-based coffee drinks.', 'The skilled barista crafted an intricate leafy fern design in the velvety latte micro-foam.', 'Người thợ pha chế cà phê lành nghề đã tạo nên hình chiếc lá dương xỉ tinh xảo trên lớp bọt sữa vi mô mịn màng của tách latte.', ARRAY['Coffee specialist', 'Espresso maker']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('food-54', 'food', 'Bartender', '/ˈbɑːrˌten.dɚ/', 'Noun', 'A2', 'Người pha chế đồ uống tại quầy bar', 'A person who mixes and serves drinks at a bar.', 'The charismatic bartender mixed a smoky Mezcal cocktail with fresh grapefruit juice.', 'Chàng bartender quyến rũ đã pha chế một ly cocktail Mezcal thơm mùi khói với nước bưởi hồng tươi.', ARRAY['Mixologist', 'Barkeep']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('food-55', 'food', 'Sommelier', '/sɑːm.əlˈjeɪ/', 'Noun', 'C1', 'Chuyên gia nếm và phục vụ rượu vang cao cấp', 'A wine expert who advises restaurant guests on wine choices and food pairings.', 'Ask the sommelier to recommend a robust red vintage that complements the grilled lamb chops.', 'Hãy nhờ chuyên gia rượu vang gợi ý một chai rượu vang đỏ đậm đà niên vụ tốt để kết hợp cùng sườn cừu nướng.', ARRAY['Wine waiter', 'Wine professional']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('food-56', 'food', 'Appetite', '/ˈæp.ə.taɪt/', 'Noun', 'B1', 'Cảm giác ngon miệng, sự thèm ăn', 'A natural desire to satisfy a bodily need, especially for food.', 'A brisk morning hike in the crisp mountain air worked up a tremendous appetite for breakfast.', 'Một chuyến đi bộ nhanh buổi sáng trong bầu không khí miền núi trong lành đã khơi dậy cảm giác thèm ăn bữa sáng vô cùng to lớn.', ARRAY['Hunger', 'Desire for food', 'Craving']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('food-57', 'food', 'Ravenous', '/ˈræv.ən.əs/', 'Adj', 'C1', 'Đói cồn cào ruột gan', 'Extremely hungry.', 'After skipping lunch during the intense twelve-hour workshop, all attendees were utterly ravenous.', 'Sau khi bỏ bữa trưa trong buổi hội thảo kéo dài 12 tiếng căng thẳng, tất cả những người tham dự đều đói cồn cào.', ARRAY['Famished', 'Starving', 'Voracious']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('food-58', 'food', 'Famished', '/ˈfæm.ɪʃt/', 'Adj', 'B2', 'Đói lả người kiệt sức', 'Extremely hungry; starved.', 'Let''s find a cozy local noodle stall immediately; I am completely famished.', 'Hãy tìm ngay một quán mì địa phương ấm cúng nào; tôi đang đói lả cả người rồi.', ARRAY['Ravenous', 'Starving']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('food-59', 'food', 'Binge', '/bɪndʒ/', 'Verb', 'B2', 'Ăn uống vô độ, chè chén thả phanh', 'Indulge in an activity, especially eating or drinking, to excess.', 'Avoid emotional stress that tempts you to binge on sugary junk food late at night.', 'Hãy tránh những căng thẳng cảm xúc thôi thúc bạn ăn uống vô độ các món đồ ăn vặt nhiều đường vào đêm khuya.', ARRAY['Overindulge', 'Gorge', 'Pig out']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('food-60', 'food', 'Dietitian', '/ˌdaɪ.əˈtɪʃ.ən/', 'Noun', 'B2', 'Chuyên gia tư vấn dinh dưỡng y khoa', 'An expert on diet and nutrition, certified to treat medical conditions through dietary changes.', 'The clinical dietitian designed a customized diabetic meal plan to keep blood glucose stable.', 'Chuyên gia dinh dưỡng lâm sàng đã thiết kế một thực đơn riêng cho người tiểu đường nhằm giữ lượng đường huyết ổn định.', ARRAY['Nutritionist', 'Diet consultant']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('food-61', 'food', 'Nutritionist', '/nuːˈtrɪʃ.ən.ɪst/', 'Noun', 'B1', 'Chuyên gia dinh dưỡng thể hình và sức khỏe', 'A person who studies or is a specialist in nutrition.', 'The sports nutritionist recommended consuming thirty grams of protein immediately after heavy workouts.', 'Chuyên gia dinh dưỡng thể thao khuyến nghị nên nạp 30 gram chất đạm ngay sau những buổi tập tạ nặng.', ARRAY['Diet expert', 'Food specialist']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('food-62', 'food', 'Locavore', '/ˈloʊ.kə.vɔːr/', 'Noun', 'C1', 'Người chuộng tiêu thụ thực phẩm địa phương', 'A person whose diet consists only or principally of locally grown or produced food.', 'As a committed locavore, she buys ninety percent of her seasonal vegetables from nearby farm stands.', 'Là một người cam kết ủng hộ thực phẩm địa phương, cô mua 90% lượng rau củ theo mùa từ các sạp nông trại gần nhà.', ARRAY['Local food consumer']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('food-63', 'food', 'Organic', '/ɔːrˈɡæn.ɪk/', 'Adj', 'B1', 'Hữu cơ tự nhiên không phân thuốc hóa học', 'Produced or involving production without the use of chemical fertilizers, pesticides, or other artificial agents.', 'Organic pasture-raised chicken eggs have vibrant deep orange yolks rich in omega-3 fats.', 'Trứng gà hữu cơ nuôi thả vườn có lòng đỏ màu cam đậm rực rỡ và giàu chất béo omega-3.', ARRAY['Chemical-free', 'Natural', 'Bio']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('food-64', 'food', 'Pesticide', '/ˈpes.tə.saɪd/', 'Noun', 'B1', 'Thuốc trừ sâu bảo vệ thực vật hóa học', 'A substance used for destroying insects or other organisms harmful to cultivated plants or to animals.', 'Rinse all fruits and vegetables under running tap water to remove trace agricultural pesticides.', 'Hãy rửa sạch tất cả các loại trái cây và rau củ dưới vòi nước chảy để loại bỏ tàn dư thuốc trừ sâu nông nghiệp.', ARRAY['Insecticide', 'Pest killer']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('food-65', 'food', 'Preservative', '/prɪˈzɝː.və.t̬ɪv/', 'Noun', 'B2', 'Chất bảo quản thực phẩm chống ôi thiu', 'A substance used to preserve foodstuffs, wood, or other materials against decay.', 'This artisanal jam is made solely of whole berries and cane sugar, containing zero artificial preservatives.', 'Món mứt thủ công này chỉ được làm từ quả mọng nguyên trái và đường mía, hoàn toàn không chứa chất bảo quản nhân tạo.', ARRAY['Chemical stabilizer', 'Additive']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('food-66', 'food', 'Additive', '/ˈæd.ə.t̬ɪv/', 'Noun', 'B2', 'Phụ gia thực phẩm tạo màu và mùi', 'A substance added to something in small quantities to improve or preserve it.', 'Parents often check labels to steer clear of artificial food coloring additives in children''s cereals.', 'Cha mẹ thường kiểm tra nhãn mác để tránh các chất phụ gia tạo màu nhân tạo trong ngũ cốc của trẻ nhỏ.', ARRAY['Supplement', 'Chemical additive']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('food-67', 'food', 'Satiety', '/səˈtaɪ.ə.t̬i/', 'Noun', 'C1', 'Cảm giác no nê thỏa mãn sau bữa ăn', 'The feeling or state of being sated, full, and satisfied.', 'High-fiber whole foods stimulate sustained hormonal satiety, preventing between-meal snacking cravings.', 'Thực phẩm toàn phần giàu chất xơ kích thích cảm giác no nê lâu dài từ hormone, ngăn ngừa cơn thèm ăn vặt giữa các bữa.', ARRAY['Fullness', 'Satisfaction', 'Repletion']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('food-68', 'food', 'Guzzle', '/ˈɡʌz.əl/', 'Verb', 'C1', 'Tu ừng ực, uống một hơi hết sạch vì khát', 'Eat or drink something greedily, noisily, or quickly.', 'After running ten hot kilometers under the blazing sun, he guzzled down a liter of cold coconut water.', 'Sau khi chạy 10 km nóng nực dưới cái nắng gay gắt, anh đã tu ừng ực một hơi hết sạch cả lít nước dừa lạnh.', ARRAY['Gulp', 'Swill', 'Quaff']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('food-69', 'food', 'Nibble', '/ˈnɪb.əl/', 'Verb', 'B1', 'Gặm nhấm từng miếng nhỏ xíu', 'Take small bites out of.', 'She sat peacefully reading her novel, nibbling on a single square of rich dark chocolate.', 'Cô ngồi thanh bình đọc cuốn tiểu thuyết của mình, chậm rãi nhấm nháp từng mẩu nhỏ thanh sô-cô-la đen đậm đà.', ARRAY['Munch', 'Peck at', 'Nibble on']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('food-70', 'food', 'Feast', '/fiːst/', 'Noun', 'B1', 'Bữa đại tiệc thịnh soạn ê hề món ngon', 'A large meal, typically one in celebration of something.', 'The Lunar New Year family gathering was a magnificent culinary feast featuring twenty traditional festive dishes.', 'Buổi sum họp gia đình dịp Tết Nguyên Đán là một bữa đại tiệc ẩm thực hoành tráng với 20 món ăn truyền thống ngày lễ.', ARRAY['Banquet', 'Spread', 'Gala dinner']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('food-71', 'food', 'Banquet', '/ˈbæŋ.kwɪt/', 'Noun', 'B1', 'Yến tiệc trang trọng đông người', 'An elaborate and formal evening meal for many people, often followed by speeches.', 'The university held an official banquet to honor the Nobel laureate visiting the research campus.', 'Trường đại học đã tổ chức một buổi yến tiệc trang trọng để vinh danh nhà khoa học đoạt giải Nobel đang đến thăm khuôn viên nghiên cứu.', ARRAY['Formal dinner', 'Feast', 'Dinner gala']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('food-72', 'food', 'Potluck', '/ˈpɑːt.lʌk/', 'Noun', 'B1', 'Bữa tiệc liên hoan mỗi người tự mang một món góp vui', 'A meal or party to which each guest contributes a dish of food.', 'Our neighborhood organized an informal Sunday potluck where everyone brought homemade regional specialties.', 'Khu phố của chúng tôi đã tổ chức một bữa tiệc potluck thân mật vào Chủ nhật, nơi mỗi người đều mang đến những món đặc sản vùng miền tự nấu.', ARRAY['Shared meal', 'Bring-a-dish party']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('food-73', 'food', 'Leftovers', '/ˈleftˌoʊ.vɚz/', 'Noun', 'A2', 'Thức ăn thừa còn lại từ bữa trước', 'Food remaining from a meal and kept for later consumption.', 'Stored in an airtight glass container, yesterday''s leftover chicken curry tastes even richer reheated today.', 'Được bảo quản trong hộp thủy tinh đậy kín, món cà ri gà còn thừa hôm qua thậm chí còn đậm đà hơn khi hâm nóng lại hôm nay.', ARRAY['Surplus food', 'Remaining meal']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('food-74', 'food', 'Recipe', '/ˈres.ə.pi/', 'Noun', 'A2', 'Công thức hướng dẫn cách nấu nướng', 'A set of instructions for preparing a particular dish, including a list of the ingredients required.', 'Grandmother passed down her secret handwritten recipe for velvety caramel egg flan.', 'Bà đã truyền lại công thức viết tay bí truyền của mình cho món bánh flan trứng caramen mịn màng.', ARRAY['Formula', 'Cooking instructions', 'Preparation method']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('food-75', 'food', 'Ingredient', '/ɪnˈɡriː.di.ənt/', 'Noun', 'A2', 'Nguyên liệu thành phần món ăn', 'Any of the foods or substances that are combined to make a particular dish.', 'Fresh sweet shallots, fragrant lemongrass, and dark soy are essential ingredients for Vietnamese barbecue.', 'Hành tím tươi ngọt, sả thơm nức và nước tương đen là những nguyên liệu thiết yếu cho món thịt nướng Việt Nam.', ARRAY['Component', 'Constituent', 'Element']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('food-76', 'food', 'Portion', '/ˈpɔːr.ʃən/', 'Noun', 'B1', 'Khẩu phần ăn của một người', 'An amount of food suitable for or served to one person.', 'The generous portion of seafood fried rice was easily large enough for two people to share.', 'Khẩu phần cơm chiên hải sản hào phóng này dễ dàng đủ lớn cho hai người cùng thưởng thức.', ARRAY['Serving', 'Helping', 'Share']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('food-77', 'food', 'Bite-sized', '/ˈbaɪt.saɪzd/', 'Adj', 'B1', 'Kích cỡ vừa miệng cắn một miếng', 'Small enough to be eaten in one single mouthful.', 'Caterers served elegant bite-sized savory canapés during the cocktail reception.', 'Đơn vị cung cấp tiệc đã phục vụ những chiếc bánh canapé mặn thanh lịch có kích cỡ vừa vặn một miếng cắn trong buổi tiệc cocktail.', ARRAY['Mouthful', 'Miniature', 'Tiny']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('food-78', 'food', 'Grate', '/ɡreɪt/', 'Verb', 'B1', 'Bào nhỏ phô mai, củ quả bằng bàn mài', 'Reduce food to small shreds by rubbing it on a grater.', 'Grate two tablespoons of aged Parmesan directly over the steaming bowl of pasta.', 'Hãy bào hai thìa phô mai Parmesan ủ lâu năm trực tiếp lên trên bát mì ống bốc khói nghi ngút.', ARRAY['Shred', 'Scrape', 'Grind']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('food-79', 'food', 'Peel', '/piːl/', 'Verb', 'A2', 'Gọt vỏ hoa quả hoặc củ', 'Remove the outer covering or skin from a fruit or vegetable.', 'Peel and dice the ripe sweet mangoes into bite-sized cubes for the dessert salad.', 'Gọt vỏ và cắt hạt lựu những quả xoài chín ngọt thành những khối vừa ăn cho món salad tráng miệng.', ARRAY['Skin', 'Pare', 'Strip']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('food-80', 'food', 'Dice', '/daɪs/', 'Verb', 'B1', 'Cắt hạt lựu thành các khối vuông nhỏ', 'Cut food into small cubes.', 'Dice the red bell peppers and crisp celery into uniform half-centimeter squares.', 'Cắt hạt lựu ớt chuông đỏ và cần tây giòn thành những hình vuông đều nhau nửa centimet.', ARRAY['Cube', 'Chop small']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('food-81', 'food', 'Chop', '/tʃɑːp/', 'Verb', 'A2', 'Băm chặt, thái khúc thực phẩm', 'Cut something into pieces with repeated sharp blows of an axe or knife.', 'Chop the fresh cilantro and scallions finely before stirring them into the simmering soup.', 'Băm nhỏ ngò rí và hành lá tươi trước khi khuấy chúng vào nồi súp đang sôi liu riu.', ARRAY['Cut', 'Mince', 'Slice']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('food-82', 'food', 'Mince', '/mɪns/', 'Verb', 'B1', 'Băm nhuyễn tỏi, ớt hoặc thịt', 'Cut up or grind food, especially meat, into very small pieces.', 'Mince three cloves of fragrant purple garlic before tossing them into the sizzling pan.', 'Băm nhuyễn ba tép tỏi tím thơm phức trước khi thả chúng vào chiếc chảo đang xèo xèo nóng bỏng.', ARRAY['Finely chop', 'Grind', 'Hash']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('food-83', 'food', 'Slice', '/slaɪs/', 'Verb', 'A2', 'Thái lát mỏng đều tay', 'Cut something into slices with a sharp knife.', 'Slice the crusty whole grain sourdough loaf thinly to make gourmet avocado toast.', 'Thái mỏng ổ bánh mì men chua nguyên cám giòn rụm để làm món bánh mì nướng bơ thượng hạng.', ARRAY['Carve', 'Shave', 'Cut into pieces']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('food-84', 'food', 'Simmering', '/ˈsɪm.ɚ.ɪŋ/', 'Adj', 'B1', 'Đang sôi lăn tăn sủi bọt nhẹ', 'Staying just below the boiling point while gently bubbling.', 'The fragrant aroma wafting from the simmering pot of beef pho made everyone''s mouth water.', 'Hương thơm ngào ngạt bốc lên từ nồi phở bò đang sôi lăn tăn khiến ai nấy đều ứa nước miếng.', ARRAY['Gentle boiling', 'Stewing']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('food-85', 'food', 'Boil', '/bɔɪl/', 'Verb', 'A1', 'Đun sôi sùng sục ở 100 độ C', 'Reach or cause to reach the temperature at which it bubbles and turns to vapor.', 'Bring two liters of salted water to a rolling boil before adding the dried spaghetti.', 'Đun hai lít nước muối cho sôi sùng sục trước khi thả những sợi mì spaghetti khô vào.', ARRAY['Bubble vigorously', 'Heat to 100°C']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('idiom-1', 'idioms', 'Hit the nail on the head', '/hɪt ðə neɪl ɑːn ðə hed/', 'Phrase', 'B2', 'Nói trúng phóc tim đen, cực kỳ chính xác', 'Describe exactly what is causing a situation or problem.', 'Her incisive analysis of our product bottleneck completely hit the nail on the head.', 'Phân tích sắc sảo của cô về nút thắt cổ chai sản phẩm của chúng tôi đã nói trúng phóc tim đen hoàn toàn.', ARRAY['Be dead right', 'Accurate', 'Spot on']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('idiom-2', 'idioms', 'Bite the bullet', '/baɪt ðə ˈbʊl.ɪt/', 'Phrase', 'B2', 'Cắn răng chịu đựng đối mặt với việc khó', 'Decide to do something difficult or unpleasant that one has been putting off or hesitating over.', 'I finally decided to bite the bullet and pay the expensive repair bill for my car transmission.', 'Cuối cùng tôi quyết định cắn răng chịu đựng chi trả hóa đơn sửa chữa đắt đỏ cho hộp số xe ô tô của mình.', ARRAY['Face the music', 'Endure hardships', 'Take the plunge']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('idiom-3', 'idioms', 'Blessing in disguise', '/ˌbles.ɪŋ ɪn dɪsˈɡaɪz/', 'Phrase', 'B2', 'Trong cái rủi lại có cái may', 'An apparent misfortune that eventually has good results.', 'Getting laid off from the bank turned out to be a blessing in disguise as he launched his dream tech firm.', 'Bị sa thải khỏi ngân hàng hóa ra lại là trong cái rủi có cái may vì anh đã khởi nghiệp thành công công ty công nghệ mơ ước.', ARRAY['Hidden benefit', 'Fortunate misfortune']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('idiom-4', 'idioms', 'Burn the midnight oil', '/bɝːn ðə ˈmɪd.naɪt ɔɪl/', 'Phrase', 'B1', 'Thức khuya cày cuốc học tập hoặc làm việc', 'Read or work late into the night.', 'Medical residents frequently burn the midnight oil preparing for their specialized board exams.', 'Các bác sĩ nội trú thường xuyên phải thức khuya cày cuốc để chuẩn bị cho kỳ thi cấp chứng chỉ hành nghề chuyên khoa.', ARRAY['Work late', 'Pull an all-nighter', 'Study late']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('idiom-5', 'idioms', 'Break the ice', '/breɪk ðiː aɪs/', 'Phrase', 'B1', 'Phá vỡ bầu không khí ngượng ngùng ban đầu', 'Do or say something to relieve tension or get conversation going at the start of a meeting or party.', 'The facilitator introduced a fun trivia quiz to break the ice among the new corporate hires.', 'Người điều phối đã giới thiệu một câu đố vui nhộn để phá vỡ sự ngượng ngùng ban đầu giữa các nhân sự mới của tập đoàn.', ARRAY['Ease tension', 'Warm up', 'Make comfortable']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('idiom-6', 'idioms', 'Piece of cake', '/piːs əv keɪk/', 'Phrase', 'A2', 'Dễ như ăn kẹo, không tốn chút sức lực', 'Something that is very easy to do.', 'With months of diligent preparation, the final driving test was an absolute piece of cake.', 'Với nhiều tháng chuẩn bị chăm chỉ, bài thi sát hạch lái xe cuối cùng dễ như ăn kẹo.', ARRAY['Child''s play', 'Breeze', 'Walk in the park']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('idiom-7', 'idioms', 'Under the weather', '/ˌʌn.dɚ ðə ˈweð.ɚ/', 'Phrase', 'B1', 'Cảm thấy hơi mệt mỏi trong người, uể oải', 'Slightly unwell or in low spirits.', 'She decided to stay home from work today because she was feeling a bit under the weather.', 'Cô ấy quyết định ở nhà nghỉ làm hôm nay vì cảm thấy trong người hơi mệt mỏi uể oải.', ARRAY['Indisposed', 'Ailing', 'Unwell']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('idiom-8', 'idioms', 'Cost an arm and a leg', '/kɑːst ən ɑːrm ənd ə leɡ/', 'Phrase', 'B1', 'Đắt đỏ cắt cổ, tốn một gia tài', 'Be extremely expensive.', 'Repairing European luxury sports cars can cost an arm and a leg if genuine parts are required.', 'Sửa chữa xe thể thao hạng sang của châu Âu có thể đắt đỏ cắt cổ nếu đòi hỏi phụ tùng chính hãng.', ARRAY['Exorbitant', 'Astronomical', 'Pricy']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('idiom-9', 'idioms', 'See eye to eye', '/siː aɪ tuː aɪ/', 'Phrase', 'B1', 'Hoàn toàn đồng lòng nhất trí quan điểm', 'Agree with someone completely.', 'Although they are brothers, they rarely see eye to eye when discussing political economics.', 'Mặc dù là anh em ruột, họ hiếm khi hoàn toàn đồng lòng nhất trí khi thảo luận về kinh tế chính trị.', ARRAY['Agree', 'Be in accord', 'Concur']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('idiom-10', 'idioms', 'Once in a blue moon', '/wʌns ɪn ə bluː muːn/', 'Phrase', 'B1', 'Năm thì mười họa, hiếm hoi lắm mới có', 'Very rarely; on rare occasions.', 'Living across different continents, the old friends meet up only once in a blue moon.', 'Sống ở hai lục địa khác nhau, những người bạn cũ năm thì mười họa hiếm hoi lắm mới có dịp gặp nhau.', ARRAY['Seldom', 'Rarely', 'Infrequently']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('idiom-11', 'idioms', 'Barking up the wrong tree', '/ˌbɑːr.kɪŋ ʌp ðə rɑːŋ ˈtriː/', 'Phrase', 'B2', 'Hiểu lầm hướng đi, trách nhầm đối tượng', 'Pursuing a mistaken line of thought or course of action.', 'If you think accusing the front-desk clerk will solve system bugs, you''re barking up the wrong tree.', 'Nếu bạn nghĩ việc đổ lỗi cho nhân viên lễ tân sẽ giải quyết được lỗi hệ thống thì bạn đang hiểu lầm hướng đi hoàn toàn rồi.', ARRAY['Misguided', 'On the wrong track']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('idiom-12', 'idioms', 'Add insult to injury', '/æd ˈɪn.sʌlt tuː ˈɪn.dʒɚ.i/', 'Phrase', 'B2', 'Xát muối vào vết thương, làm tình hình tệ hơn', 'Act in a way that makes a bad situation even worse.', 'First our flight was delayed by four hours, and then, to add insult to injury, they lost our luggage.', 'Đầu tiên là chuyến bay bị hoãn bốn tiếng, và sau đó, như xát thêm muối vào vết thương, họ làm thất lạc luôn hành lý của chúng tôi.', ARRAY['Worsen things', 'Make matters worse']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('idiom-13', 'idioms', 'At the drop of a hat', '/æt ðə drɑːp əv ə hæt/', 'Phrase', 'B2', 'Ngay tắp lự, không ngần ngại chút nào', 'Without hesitation or good reason; instantly.', 'He is so adventurous that he will pack a backpack and travel to distant countries at the drop of a hat.', 'Anh ấy thích phiêu lưu đến mức sẵn sàng xách ba lô lên và đi du lịch tới những vùng đất xa xôi ngay tắp lự không một chút đắn đo.', ARRAY['Instantly', 'Without delay', 'Promptly']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('idiom-14', 'idioms', 'Ball is in your court', '/bɑːl ɪz ɪn jɔːr kɔːrt/', 'Phrase', 'B1', 'Quyền quyết định hành động tiếp theo thuộc về bạn', 'It is up to you to take the next decision or step.', 'We have submitted our best commercial price offer; the ball is now in the client''s court.', 'Chúng tôi đã gửi mức giá thương mại tốt nhất có thể; quyền quyết định bước tiếp theo giờ thuộc về phía khách hàng.', ARRAY['Your move', 'Up to you']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('idiom-15', 'idioms', 'Beat around the bush', '/biːt əˈraʊnd ðə bʊʃ/', 'Phrase', 'B1', 'Nói vòng vo tam quốc, tránh né chuyện chính', 'Discuss a matter without coming to the point.', 'Stop beating around the bush and tell us directly whether you accept the job offer.', 'Đừng nói vòng vo tam quốc nữa và hãy nói thẳng cho chúng tôi biết liệu bạn có nhận lời mời làm việc hay không.', ARRAY['Equivocate', 'Prevaricate', 'Dither']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('idiom-16', 'idioms', 'Best of both worlds', '/ˌbest əv boʊθ ˈwɝːldz/', 'Phrase', 'B2', 'Vẹn cả đôi đường, được cả hai mặt tốt', 'A situation in which you can enjoy the advantages of two very different things at the same time.', 'Living in the tranquil green countryside while working remotely for a Silicon Valley firm gives her the best of both worlds.', 'Sống ở vùng quê xanh mát thanh bình trong khi làm việc từ xa cho một công ty Thung lũng Silicon mang lại cho cô sự vẹn toàn cả đôi đường.', ARRAY['Win-win', 'Ideal situation']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('idiom-17', 'idioms', 'Burn bridges', '/bɝːn ˈbrɪdʒ.ɪz/', 'Phrase', 'B2', 'Đốt cầu rút ván, tự cắt đứt đường lui của mình', 'Destroy all possible ways of going back to an earlier situation.', 'Never insult your previous employer when resigning; you should never burn your professional bridges.', 'Đừng bao giờ xúc phạm người sử dụng lao động cũ khi nộp đơn từ chức; bạn tuyệt đối không nên tự cắt đứt các mối quan hệ chuyên môn của mình.', ARRAY['Cut ties permanently', 'Ruin relations']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('idiom-18', 'idioms', 'By the skin of one''s teeth', '/baɪ ðə skɪn əv wʌnz tiːθ/', 'Phrase', 'B2', 'Trong gang tấc, suýt soát sát nút', 'Only just; by a very narrow margin.', 'He sprinted frantically across the terminal and caught the final train by the skin of his teeth.', 'Anh đã chạy thục mạng qua nhà ga và bắt kịp chuyến tàu cuối cùng chỉ trong đường tơ kẽ tóc.', ARRAY['Barely', 'Narrowly', 'Just in time']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('idiom-19', 'idioms', 'Cry over spilt milk', '/kraɪ ˈoʊ.vɚ spɪlt mɪlk/', 'Phrase', 'B1', 'Tiếc rẻ chuyện đã rồi không thể cứu vãn', 'Worry or lament about past events that cannot be changed.', 'The server already crashed and was restored; there is zero point crying over spilt milk.', 'Máy chủ đằng nào cũng đã sập và đã được khôi phục; chẳng ích gì khi cứ ngồi tiếc rẻ chuyện đã qua.', ARRAY['Useless regret', 'Lamenting the past']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('idiom-20', 'idioms', 'Curiosity killed the cat', '/ˌkjʊr.iˈɑː.sə.t̬i kɪld ðə kæt/', 'Phrase', 'B2', 'Tò mò quá hại thân, chớ chõ mũi vào chuyện người', 'Being too curious can get you into trouble.', 'Don''t snoop through confidential executive memos; remember that curiosity killed the cat.', 'Đừng có lén lút đọc các bản ghi nhớ tuyệt mật của ban giám đốc; hãy nhớ rằng tò mò quá có ngày hại thân.', ARRAY['Warning against prying']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('idiom-21', 'idioms', 'Devil''s advocate', '/ˌdev.əlz ˈæd.və.kət/', 'Noun', 'B2', 'Người cố tình phản biện để tìm ra kẽ hở', 'A person who expresses a contentious opinion in order to provoke debate or test the strength of the opposing arguments.', 'Let me play devil''s advocate for a moment: what if our chief competitor slashes their subscription prices by half?', 'Hãy để tôi đóng vai người phản biện một lát: điều gì sẽ xảy ra nếu đối thủ cạnh tranh lớn nhất của chúng ta giảm một nửa giá thuê bao?', ARRAY['Contrarian', 'Counter-arguer']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('idiom-22', 'idioms', 'Don''t count your chickens before they hatch', '/doʊnt kaʊnt jɔːr ˈtʃɪk.ɪnz/', 'Phrase', 'B2', 'Đừng đếm cua trong lỗ, nói trước bước không qua', 'Don''t make plans based on events that may not happen.', 'Wait until the enterprise contract is signed before celebrating; don''t count your chickens before they hatch.', 'Hãy đợi cho đến khi hợp đồng doanh nghiệp được ký kết chính thức rồi hãy ăn mừng; đừng đếm cua trong lỗ.', ARRAY['Don''t anticipate victory']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('idiom-23', 'idioms', 'Elephant in the room', '/ˈel.ə.fənt ɪn ðə ruːm/', 'Noun', 'B2', 'Vấn đề hiển nhiên to lù lù nhưng ai cũng né tránh', 'A major problem or controversial issue that is obviously present but which everyone avoids discussing.', 'The company''s declining cash reserves was the obvious elephant in the room that nobody dared mention during the board meeting.', 'Lượng dự trữ tiền mặt ngày càng cạn kiệt của công ty là vấn đề to lù lù hiển nhiên nhưng không ai dám nhắc tới trong cuộc họp hội đồng quản trị.', ARRAY['Unaddressed problem', 'Taboo topic']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('idiom-24', 'idioms', 'Fit as a fiddle', '/fɪt əz ə ˈfɪd.əl/', 'Phrase', 'B2', 'Khỏe như vâm, dồi dào sinh lực', 'In very good health and physical condition.', 'After completing his cardiac rehabilitation program, our seventy-year-old grandfather is as fit as a fiddle.', 'Sau khi hoàn thành chương trình phục hồi chức năng tim mạch, người ông bảy mươi tuổi của chúng tôi lại khỏe như vâm.', ARRAY['In peak health', 'Robust', 'Vigorous']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('idiom-25', 'idioms', 'Go the extra mile', '/ɡoʊ ðiː ˈek.strə maɪl/', 'Phrase', 'B1', 'Nỗ lực vượt bậc làm nhiều hơn mong đợi', 'Make a special effort to achieve something or help someone.', 'Our dedicated customer service team is always willing to go the extra mile to delight clients.', 'Đội ngũ chăm sóc khách hàng tận tâm của chúng tôi luôn sẵn sàng nỗ lực vượt bậc để làm hài lòng khách hàng.', ARRAY['Exceed expectations', 'Make extra effort']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('idiom-26', 'idioms', 'Good things come to those who wait', '/ɡʊd θɪŋz kʌm tuː ðoʊz huː weɪt/', 'Phrase', 'B1', 'Kiên nhẫn ắt gặt hái quả ngọt', 'Patience is a virtue that will ultimately be rewarded.', 'Don''t get discouraged by early setbacks in your business venture; good things come to those who wait.', 'Đừng nản lòng trước những trở ngại ban đầu trong dự án kinh doanh của bạn; kiên nhẫn ắt sẽ gặt hái được quả ngọt.', ARRAY['Patience pays off']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('idiom-27', 'idioms', 'Hear it on the grapevine', '/hɪr ɪt ɑːn ðə ˈɡreɪp.vaɪn/', 'Phrase', 'B2', 'Nghe phong phanh tin đồn hành lang', 'Hear rumors or unverified information circulated informally.', 'I heard on the corporate grapevine that the finance director is planning to step down next month.', 'Tôi nghe phong phanh tin đồn hành lang rằng giám đốc tài chính đang có kế hoạch từ chức vào tháng tới.', ARRAY['Hear rumors', 'Word of mouth']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('idiom-28', 'idioms', 'Hit the sack', '/hɪt ðə sæk/', 'Phrase', 'B1', 'Đi ngủ sau một ngày dài mệt mỏi', 'Go to bed to sleep.', 'It''s past midnight and we have an early morning flight; I''m going to hit the sack right now.', 'Đã qua nửa đêm rồi và chúng ta có một chuyến bay vào sáng sớm mai; tôi sẽ đi ngủ ngay bây giờ đây.', ARRAY['Go to sleep', 'Turn in']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('idiom-29', 'idioms', 'In the heat of the moment', '/ɪn ðə hiːt əv ðə ˈmoʊ.mənt/', 'Phrase', 'B2', 'Trong lúc nóng giận nhất thời mất kiểm soát', 'While temporarily angry, excited, or engrossed, without thinking about consequences.', 'He apologized sincerely for shouting, admitting he said those hurtful words in the heat of the moment.', 'Anh đã chân thành xin lỗi vì đã quát tháo, thừa nhận rằng mình đã buột miệng nói ra những lời gây tổn thương đó trong lúc nóng giận nhất thời.', ARRAY['Impetuously', 'Angrily']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('idiom-30', 'idioms', 'It takes two to tango', '/ɪt teɪks tuː tuː ˈtæŋ.ɡoʊ/', 'Phrase', 'B2', 'Cả hai bên đều có lỗi, một bàn tay không vỗ nên tiếng', 'Both people involved in a difficult situation or argument must share the blame.', 'Don''t put all the blame on your coworker for the project collapse; remember it takes two to tango.', 'Đừng đổ hết mọi lỗi lầm lên đầu người đồng nghiệp về sự đổ bể của dự án; hãy nhớ rằng một bàn tay không vỗ nên tiếng.', ARRAY['Mutual responsibility', 'Shared blame']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('idiom-31', 'idioms', 'Jump on the bandwagon', '/dʒʌmp ɑːn ðə ˈbændˌwæɡ.ən/', 'Phrase', 'B2', 'Đua đòi theo trào lưu số đông', 'Join others in doing or supporting something fashionable or likely to be successful.', 'Every consumer brand is rushing to jump on the artificial intelligence bandwagon this year.', 'Mọi thương hiệu tiêu dùng đều đang vội vã chạy theo trào lưu trí tuệ nhân tạo trong năm nay.', ARRAY['Follow the trend', 'Conform']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('idiom-32', 'idioms', 'Keep an eye on', '/kiːp ən aɪ ɑːn/', 'Phrase', 'A2', 'Để mắt trông chừng, giám sát cẩn thận', 'Watch someone or something carefully; supervise.', 'Could you please keep an eye on my laptop backpack while I step away to order a coffee?', 'Bạn có thể vui lòng để mắt trông chừng chiếc ba lô đựng laptop của tôi trong khi tôi đi gọi cà phê được không?', ARRAY['Watch over', 'Guard', 'Monitor']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('idiom-33', 'idioms', 'Kill two birds with one stone', '/kɪl tuː bɝːdz wɪð wʌn stoʊn/', 'Phrase', 'B1', 'Một mũi tên trúng hai đích, nhất cử lưỡng tiện', 'Achieve two objectives with one single action.', 'Walking to the downtown office kills two birds with one stone: you get daily cardio exercise and save commute money.', 'Đi bộ đến văn phòng ở trung tâm thành phố là một mũi tên trúng hai đích: bạn vừa được tập thể dục tim mạch mỗi ngày vừa tiết kiệm tiền đi lại.', ARRAY['Dual achievement', 'Efficient action']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('idiom-34', 'idioms', 'Leave no stone unturned', '/liːv noʊ stoʊn ʌnˈtɝːnd/', 'Phrase', 'B2', 'Dốc toàn lực tìm mọi cách, không bỏ sót điều gì', 'Try every possible course of action in order to achieve something.', 'Investigators promised the grieving family they would leave no stone unturned in finding the missing hiker.', 'Các nhà điều tra hứa với gia đình đau buồn rằng họ sẽ dốc toàn lực tìm kiếm mọi ngóc ngách và không bỏ sót manh mối nào để tìm ra người đi bộ mất tích.', ARRAY['Exhaust all options', 'Search thoroughly']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('idiom-35', 'idioms', 'Let the cat out of the bag', '/let ðə kæt aʊt əv ðə bæɡ/', 'Phrase', 'B1', 'Vô tình làm lộ bí mật', 'Reveal a secret carelessly or by mistake.', 'We were planning a surprise birthday party for him, but his sister let the cat out of the bag.', 'Chúng tôi đang lên kế hoạch tổ chức một bữa tiệc sinh nhật bất ngờ cho anh ấy, nhưng em gái anh đã vô tình làm lộ bí mật mất rồi.', ARRAY['Spill the beans', 'Divulge a secret']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('idiom-36', 'idioms', 'Miss the boat', '/mɪs ðə boʊt/', 'Phrase', 'B1', 'Bỏ lỡ cơ hội vàng ngàn năm có một', 'Be too slow to take advantage of an opportunity.', 'Investors who hesitated to buy shares during the market dip completely missed the boat.', 'Những nhà đầu tư ngập ngừng không dám mua cổ phiếu trong đợt sụt giảm của thị trường đã hoàn toàn bỏ lỡ cơ hội vàng.', ARRAY['Lose the opportunity', 'Be too late']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('idiom-37', 'idioms', 'No pain, no gain', '/noʊ peɪn noʊ ɡeɪn/', 'Phrase', 'B1', 'Có công mài sắt có ngày nên kim, không gian nan sao có thành công', 'Suffering or effort is needed to achieve something worthwhile.', 'The rigorous conditioning drills were grueling, but the athletes lived by the mantra: no pain, no gain.', 'Những bài tập thể lực nghiêm ngặt vô cùng mệt mỏi, nhưng các vận động viên luôn sống theo tôn chỉ: không có gian nan thì làm sao có được thành công.', ARRAY['Effort brings reward']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('idiom-38', 'idioms', 'Off the hook', '/ˌɑːf ðə ˈhʊk/', 'Phrase', 'B1', 'Thoát khỏi rắc rối hoặc trách nhiệm', 'No longer in trouble or difficulty; freed from an obligation.', 'Since the client canceled the presentation, the design team is off the hook for this weekend.', 'Vì khách hàng đã hủy buổi thuyết trình, đội ngũ thiết kế đã thoát khỏi gánh nặng phải làm thêm vào cuối tuần này.', ARRAY['Exonerated', 'Relieved of duty']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('idiom-39', 'idioms', 'On cloud nine', '/ɑːn klaʊd naɪn/', 'Phrase', 'B2', 'Lâng lâng trên chín tầng mây, hạnh phúc tột cùng', 'Extremely happy; in a state of blissful euphoria.', 'She was on cloud nine the entire week after receiving an offer letter from her dream university.', 'Cô ấy như đang lâng lâng trên chín tầng mây suốt cả tuần sau khi nhận được thư mời nhập học từ trường đại học mơ ước.', ARRAY['Elated', 'Overjoyed', 'Ecstatic']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('idiom-40', 'idioms', 'On the fence', '/ɑːn ðə fens/', 'Phrase', 'B1', 'Lưỡng lự ba phải chưa thể đưa ra quyết định', 'Undecided between two choices or opinions.', 'I am still on the fence about whether to buy the electric hybrid vehicle or wait for solid-state batteries.', 'Tôi vẫn còn đang lưỡng lự chưa biết nên mua chiếc xe lai điện hay chờ đợi công nghệ pin thể rắn ra đời.', ARRAY['Undecided', 'Wavering', 'Hesitant']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('idiom-41', 'idioms', 'Play by ear', '/pleɪ baɪ ɪr/', 'Phrase', 'B1', 'Tùy cơ ứng biến theo tình hình thực tế', 'Proceed intuitively without a pre-formulated plan; improvise.', 'We don''t have a rigid itinerary for tomorrow''s city tour; let''s just play it by ear depending on the weather.', 'Chúng ta không có một lịch trình cứng nhắc nào cho chuyến tham quan thành phố ngày mai; hãy cứ tùy cơ ứng biến tùy theo thời tiết ra sao.', ARRAY['Improvise', 'Adapt as you go']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('idiom-42', 'idioms', 'Rain on someone''s parade', '/reɪn ɑːn ˈsʌm.wʌnz pəˈreɪd/', 'Phrase', 'B2', 'Dội gáo nước lạnh làm mất hứng người khác', 'Spoil someone''s pleasure or plans.', 'I hate to rain on your parade, but the outdoor festival has been canceled due to the torrential storm.', 'Tôi rất ghét phải dội một gáo nước lạnh làm mất hứng của bạn, nhưng lễ hội ngoài trời đã bị hủy do cơn bão lớn trút nước.', ARRAY['Dampen enthusiasm', 'Spoil fun']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('idiom-43', 'idioms', 'Raining cats and dogs', '/ˈreɪ.nɪŋ kæts ənd dɑːɡz/', 'Phrase', 'A2', 'Mưa tầm tã, mưa như trút nước', 'Raining extremely heavily.', 'Don''t step outside without an umbrella; it''s raining cats and dogs out there.', 'Đừng bước ra ngoài mà không có ô; ngoài trời đang mưa như trút nước đấy.', ARRAY['Pouring down', 'Torrential rain']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('idiom-44', 'idioms', 'Spill the beans', '/spɪl ðə biːnz/', 'Phrase', 'B1', 'Bật mí, tiết lộ bí mật cho mọi người biết', 'Disclose a secret or reveal confidential information.', 'Come on, spill the beans! What did the hiring manager tell you in the private meeting?', 'Nào, mau bật mí đi! Người quản lý tuyển dụng đã nói gì với bạn trong cuộc họp riêng vậy?', ARRAY['Reveal the secret', 'Disclose']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('idiom-45', 'idioms', 'Take with a grain of salt', '/teɪk wɪð ə ɡreɪn əv sɑːlt/', 'Phrase', 'B2', 'Bán tín bán nghi, nghe để tham khảo thôi', 'View something with skepticism or not to take it literally.', 'Take online celebrity gossip with a grain of salt; sensational blogs frequently exaggerate rumors.', 'Hãy bán tín bán nghi với những tin đồn của người nổi tiếng trên mạng; các trang blog giật gân thường phóng đại tin đồn.', ARRAY['Be skeptical of', 'Don''t swallow whole']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('idiom-46', 'idioms', 'Taste of one''s own medicine', '/teɪst əv wʌnz oʊn ˈmed.ə.sɪn/', 'Phrase', 'B2', 'Gậy ông đập lưng ông, nếm mùi vị mình từng làm với người khác', 'A harsh treatment that is identical or similar to one that one has oneself administered to others.', 'The chronic bully got a taste of his own medicine when a bolder classmate publicly challenged his insults.', 'Kẻ chuyên đi bắt nạt kinh niên đã phải nếm mùi gậy ông đập lưng ông khi một người bạn cùng lớp dũng cảm hơn đã công khai thách thức những lời lăng mạ của hắn.', ARRAY['Retribution', 'Poetic justice']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('idiom-47', 'idioms', 'Through thick and thin', '/θruː θɪk ənd θɪn/', 'Phrase', 'B2', 'Cùng nhau vượt qua mọi hoạn nạn thăng trầm', 'Under all circumstances, no matter how difficult or unpleasant.', 'True childhood friends stick together through thick and thin for decades.', 'Những người bạn thời thơ ấu đích thực luôn gắn bó bên nhau cùng vượt qua mọi hoạn nạn thăng trầm trong suốt nhiều thập kỷ.', ARRAY['In good and bad times', 'Steadfastly']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('idiom-48', 'idioms', 'Throw in the towel', '/θroʊ ɪn ðə ˈtaʊ.əl/', 'Phrase', 'B2', 'Tung khăn trắng đầu hàng, bỏ cuộc', 'Abandon a struggle; admit defeat.', 'After years of fighting declining retail sales, the boutique owner finally decided to throw in the towel.', 'Sau nhiều năm vật lộn với doanh số bán lẻ sụt giảm, người chủ cửa hàng thời trang cuối cùng đã quyết định tung khăn trắng đầu hàng.', ARRAY['Give up', 'Admit defeat', 'Surrender']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('idiom-49', 'idioms', 'Time flies', '/taɪm flaɪz/', 'Phrase', 'A2', 'Thời gian thấm thoát thoi đưa vút bay', 'Time passes surprisingly quickly.', 'It feels like we only began university yesterday; how time flies when you''re deeply engrossed in learning!', 'Cảm giác như chúng ta mới chỉ bước chân vào đại học ngày hôm qua; thời gian mới thấm thoát thoi đưa làm sao khi bạn say mê học tập!', ARRAY['Time passes swiftly']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('idiom-50', 'idioms', 'Under the table', '/ˌʌn.dɚ ðə ˈteɪ.bəl/', 'Phrase', 'B2', 'Lén lút dưới gầm bàn, hối lộ phi pháp', 'Secretly and illegally, especially of financial transactions.', 'The dishonest contractor paid shady inspectors under the table to bypass mandatory fire regulations.', 'Nhà thầu bất chính đã đút lót lén lút dưới gầm bàn cho các thanh tra mờ ám để né tránh các quy định phòng cháy bắt buộc.', ARRAY['Illicitly', 'Bribed', 'Covertly']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('idiom-51', 'idioms', 'Up in the air', '/ʌp ɪn ðiː er/', 'Phrase', 'B2', 'Còn lơ lửng chưa ngã ngũ, chưa chắc chắn', 'Unresolved or undecided.', 'Our international vacation plans are still up in the air until my annual leave is officially approved.', 'Kế hoạch đi nghỉ dưỡng quốc tế của chúng tôi vẫn còn lơ lửng chưa ngã ngũ cho đến khi đơn xin nghỉ phép năm của tôi được phê duyệt chính thức.', ARRAY['Uncertain', 'Pending', 'Undecided']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('idiom-52', 'idioms', 'Water under the bridge', '/ˈwɑː.t̬ɚ ˌʌn.dɚ ðə brɪdʒ/', 'Phrase', 'B2', 'Chuyện cũ bỏ qua, nước chảy qua cầu không nhắc lại nữa', 'Past events that are no longer important or that have been forgiven.', 'We had bitter disagreements years ago, but that''s all water under the bridge now; we are close allies.', 'Chúng tôi từng có những bất đồng gay gắt nhiều năm trước, nhưng tất cả giờ chỉ là chuyện cũ bỏ qua như nước chảy qua cầu; hiện chúng tôi là những đồng minh thân thiết.', ARRAY['Past history', 'Forgiven past']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('idiom-53', 'idioms', 'Wrap one''s head around', '/ræp wʌnz hed əˈraʊnd/', 'Phrase', 'B2', 'Hiểu thấu được một vấn đề hóc búa', 'Find a way to understand or accept something complex or surprising.', 'It took weeks for the physics students to wrap their heads around the mind-bending principles of quantum entanglement.', 'Phải mất nhiều tuần các sinh viên vật lý mới có thể hiểu thấu được những nguyên lý đầy hóc búa của hiện tượng rối lượng tử.', ARRAY['Fathom', 'Comprehend', 'Grasp']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('idiom-54', 'idioms', 'You can''t judge a book by its cover', '/juː kænt dʒʌdʒ ə bʊk/', 'Phrase', 'B1', 'Đừng trông mặt mà bắt hình dong', 'One should not judge the worth or value of something by its outward appearance alone.', 'The restaurant looked modest and rustic from the outside, but you can''t judge a book by its cover: the food was Michelin-star level.', 'Nhà hàng trông có vẻ khiêm tốn và mộc mạc nhìn từ bên ngoài, nhưng đừng trông mặt mà bắt hình dong: đồ ăn ở đây đạt đẳng cấp sao Michelin.', ARRAY['Appearances can deceive']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('idiom-55', 'idioms', 'Back to the drawing board', '/bæk tuː ðə ˈdrɑː.ɪŋ ˌbɔːrd/', 'Phrase', 'B2', 'Làm lại từ đầu khi kế hoạch thất bại', 'Start again from the beginning because a previous attempt failed completely.', 'The initial aerodynamic prototype failed wind-tunnel simulations, forcing engineers back to the drawing board.', 'Mẫu thử nghiệm khí động học ban đầu đã thất bại trong các mô phỏng đường hầm gió, buộc các kỹ sư phải làm lại từ đầu.', ARRAY['Start over', 'Re-plan']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('idiom-56', 'idioms', 'Burn the candle at both ends', '/bɝːn ðə ˈkæn.dəl æt boʊθ endz/', 'Phrase', 'C1', 'Làm việc quá sức cả ngày lẫn đêm kiệt quệ', 'Exhaust someone''s physical or mental resources by working or doing other things from early in the morning until late at night.', 'Holding two demanding jobs while studying for the bar exam is burning the candle at both ends.', 'Vừa ôm hai công việc đòi hỏi khắt khe lại vừa ôn thi chứng chỉ luật sư là đang vắt kiệt sức mình cả ngày lẫn đêm.', ARRAY['Overwork', 'Exhaust oneself']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('idiom-57', 'idioms', 'Call it a day', '/kɑːl ɪt ə deɪ/', 'Phrase', 'B1', 'Nghỉ tay dừng việc hôm nay tại đây', 'Stop working on something, especially because you''ve done enough or you''re tired.', 'We''ve fixed the critical database migration bugs; let''s call it a day and resume tomorrow morning.', 'Chúng ta đã sửa xong các lỗi di chuyển cơ sở dữ liệu nguy cấp rồi; hãy nghỉ tay dừng việc hôm nay tại đây và tiếp tục vào sáng mai.', ARRAY['Pack up', 'Finish work']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('idiom-58', 'idioms', 'Cut corners', '/kʌt ˈkɔːr.nɚz/', 'Phrase', 'B2', 'Làm ẩu bớt xén quy trình để tiết kiệm', 'Do something perfunctorily so as to save time or money.', 'Never cut corners on structural concrete foundations when building high-rise skyscrapers.', 'Tuyệt đối không bao giờ được làm ẩu bớt xén quy trình móng bê tông kết cấu khi xây dựng các tòa nhà chọc trời.', ARRAY['Skimp', 'Scrimp', 'Take shortcuts']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('idiom-59', 'idioms', 'Down to the wire', '/daʊn tuː ðə waɪr/', 'Phrase', 'B2', 'Sát nút tới tận phút chót nghẹt thở', 'Until the very last minute or final moment.', 'The fierce bidding contest went right down to the wire before the winner was announced.', 'Cuộc so găng đấu thầu quyết liệt diễn ra sát nút tới tận phút chót nghẹt thở trước khi người chiến thắng được công bố.', ARRAY['Until the last second', 'Nail-biting']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('idiom-60', 'idioms', 'Easier said than done', '/ˌiː.zi.ɚ ˈsed ðæn ˈdʌn/', 'Phrase', 'B1', 'Nói thì dễ làm mới khó', 'More difficult to do than to talk about.', 'Adopting a strict zero-sugar diet is much easier said than done when surrounded by dessert bakeries.', 'Áp dụng chế độ ăn kiêng hoàn toàn không đường nói thì dễ làm mới khó khi xung quanh toàn là các tiệm bánh ngọt.', ARRAY['Easier talked about', 'Challenging in reality']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('idiom-61', 'idioms', 'Every cloud has a silver lining', '/ˈev.ri klaʊd hæz ə ˈsɪl.vɚ ˈlaɪ.nɪŋ/', 'Phrase', 'B2', 'Trong cái rủi có cái may, sau cơn mưa trời lại sáng', 'Every difficult or unpleasant situation has some advantage or hopeful aspect.', 'Losing that client gave our engineering team time to overhaul our core platform; every cloud has a silver lining.', 'Việc mất đi khách hàng đó đã cho đội ngũ kỹ thuật của chúng tôi thời gian để đại tu lại nền tảng cốt lõi; sau cơn mưa trời lại sáng.', ARRAY['Hope in adversity', 'Optimistic view']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('idiom-62', 'idioms', 'Get out of hand', '/ɡet aʊt əv hænd/', 'Phrase', 'B1', 'Vượt ra ngoài tầm kiểm soát, mất trật tự', 'Become chaotic, unruly, or uncontrollable.', 'The celebration street party began to get out of hand when loud fireworks were lit inside the crowd.', 'Bữa tiệc ăn mừng trên đường phố bắt đầu vượt ra ngoài tầm kiểm soát khi pháo hoa phát nổ ầm ĩ ngay giữa đám đông.', ARRAY['Spirals out of control', 'Become unruly']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('idiom-63', 'idioms', 'Give the benefit of the doubt', '/ɡɪv ðə ˈben.ə.fɪt əv ðə daʊt/', 'Phrase', 'B2', 'Tin tưởng thiện chí của người khác dù chưa rõ bằng chứng', 'Accept what someone tells you even though you think that they may be wrong or lying.', 'She was thirty minutes late, but we gave her the benefit of the doubt given the sudden heavy snowstorm.', 'Cô ấy đến muộn ba mươi phút, nhưng chúng tôi vẫn tin tưởng vào thiện chí của cô ấy trước cơn bão tuyết lớn bất ngờ.', ARRAY['Trust someone', 'Show leniency']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('idiom-64', 'idioms', 'Go down in flames', '/ɡoʊ daʊn ɪn fleɪmz/', 'Phrase', 'B2', 'Thất bại thảm hại ê chề ngoạn mục', 'Fail spectacularly or disastrously.', 'The overhyped luxury gadget went down in flames after catastrophic safety recalls.', 'Thiết bị xa xỉ được thổi phồng quá mức đã thất bại thảm hại ê chề sau các đợt triệu hồi an toàn thảm khốc.', ARRAY['Fail miserably', 'Collapse disastrously']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('idiom-65', 'idioms', 'Ignorance is bliss', '/ˈɪɡ.nɚ.əns ɪz blɪs/', 'Phrase', 'B2', 'Không biết lại hay, không biết thì đỡ khổ', 'Not knowing something is often more comfortable than knowing the harsh truth.', 'Sometimes when eating street food in exotic alleys, ignorance is bliss regarding the exact ingredients.', 'Đôi khi khi ăn đồ ăn đường phố trong những con ngõ lạ, không biết rõ nguyên liệu chính xác lại là một điều thanh thản hơn.', ARRAY['Better not knowing']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('idiom-66', 'idioms', 'In a nutshell', '/ɪn ə ˈnʌt.ʃel/', 'Phrase', 'B1', 'Nói một cách ngắn gọn súc tích nhất', 'In the fewest possible words; concisely.', 'In a nutshell, our software reduces database cloud hosting expenses by sixty percent.', 'Nói một cách ngắn gọn súc tích nhất, phần mềm của chúng tôi giúp giảm 60% chi phí lưu trữ cơ sở dữ liệu trên đám mây.', ARRAY['Briefly', 'Concisely', 'In short']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('idiom-67', 'idioms', 'Keep someone at arm''s length', '/kiːp ˈsʌm.wʌn æt ɑːrmz leŋθ/', 'Phrase', 'C1', 'Giữ khoảng cách xa giao, không để quá thân thiết', 'Avoid becoming too friendly with someone.', 'The prudent manager keeps overly ambitious office politicians at arm''s length.', 'Người quản lý thận trọng luôn giữ khoảng cách vừa phải với những kẻ nhiều mưu mô nơi công sở.', ARRAY['Maintain distance', 'Stay aloof']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('idiom-68', 'idioms', 'Let sleeping dogs lie', '/let ˈsliː.pɪŋ dɑːɡz laɪ/', 'Phrase', 'B2', 'Chuyện đã qua hãy để nó ngủ yên, chớ bới lông tìm vết', 'Avoid interfering in a situation that is currently causing no problems but might cause problems if you interfere.', 'Don''t bring up that old dispute between the co-founders; let sleeping dogs lie.', 'Đừng gợi lại mối bất hòa cũ giữa các đồng sáng lập nữa; chuyện đã qua hãy để cho nó ngủ yên.', ARRAY['Avoid stirring trouble', 'Leave well enough alone']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('idiom-69', 'idioms', 'Look before you leap', '/lʊk bɪˈfɔːr juː liːp/', 'Phrase', 'B1', 'Cẩn tắc vô áy náy, suy tính kỹ trước khi hành động', 'Think carefully about the possible results of something before doing it.', 'Investing all your life savings into speculative cryptocurrencies is reckless; always look before you leap.', 'Dốc toàn bộ số tiền tiết kiệm cả đời vào các loại tiền mã hóa đầu cơ là liều lĩnh; hãy luôn cẩn tắc vô áy náy suy tính kỹ trước khi hành động.', ARRAY['Exercise caution', 'Think first']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('idiom-70', 'idioms', 'Make ends meet', '/meɪk endz miːt/', 'Phrase', 'B1', 'Kiếm đủ tiền trang trải cuộc sống qua ngày', 'Earn just enough money to live on.', 'Working overtime on weekends enabled the humble student to make ends meet in the expensive capital.', 'Làm thêm giờ vào dịp cuối tuần đã giúp người sinh viên nghèo kiếm đủ tiền trang trải cuộc sống tại thủ đô đắt đỏ.', ARRAY['Survive financially', 'Get by']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('idiom-71', 'idioms', 'No-brainer', '/ˈnoʊˌbreɪ.nɚ/', 'Noun', 'B1', 'Quyết định hiển nhiên không cần phải đắn đo suy nghĩ', 'Something that requires very little thought; an obvious decision.', 'Accepting a fully-funded PhD fellowship at MIT was a complete no-brainer for the young researcher.', 'Nhận suất học bổng tiến sĩ toàn phần tại MIT là một quyết định hiển nhiên không cần phải đắn đo đối với nhà nghiên cứu trẻ.', ARRAY['Obvious choice', 'Easy decision']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('idiom-72', 'idioms', 'On the same page', '/ɑːn ðə seɪm peɪdʒ/', 'Phrase', 'B1', 'Cùng chung cách hiểu và chí hướng', 'In complete agreement about a plan or goal.', 'Let''s hold a quick alignment standup to ensure the whole engineering team is on the same page.', 'Hãy tổ chức một cuộc họp ngắn để đảm bảo toàn bộ đội ngũ kỹ thuật đều cùng chung cách hiểu và chí hướng.', ARRAY['In accord', 'Unified']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('idiom-73', 'idioms', 'Out of the blue', '/ˌaʊt əv ðə ˈbluː/', 'Phrase', 'B1', 'Bất thình lình, hoàn toàn bất ngờ không báo trước', 'Completely unexpectedly; without warning.', 'Out of the blue, my childhood best friend called me after fifteen years of zero contact.', 'Hoàn toàn bất thình lình, người bạn thân nhất thời thơ ấu đã gọi điện cho tôi sau 15 năm bặt vô âm tín.', ARRAY['Unexpectedly', 'Suddenly', 'Unannounced']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('idiom-74', 'idioms', 'Pull someone''s leg', '/pʊl ˈsʌm.wʌnz leɡ/', 'Phrase', 'B1', 'Trêu chọc, đùa cợt ai đó cho vui', 'Deceive someone playfully as a joke.', 'Don''t panic! He wasn''t serious about the company canceling all bonuses; he was just pulling your leg.', 'Đừng hoảng sợ! Anh ấy không có ý nghiêm túc về việc công ty hủy toàn bộ tiền thưởng đâu; anh ấy chỉ đang trêu đùa bạn thôi.', ARRAY['Tease', 'Joke with']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('idiom-75', 'idioms', 'Put all one''s eggs in one basket', '/pʊt ɔːl wʌnz eɡz/', 'Phrase', 'B2', 'Bỏ tất cả trứng vào một giỏ (quá mạo hiểm)', 'Risk everything on the success of one venture or asset.', 'Diversify your retirement portfolio; never put all your financial eggs in one volatile stock basket.', 'Hãy đa dạng hóa danh mục hưu trí của bạn; đừng bao giờ bỏ tất cả số trứng tài chính vào một giỏ cổ phiếu đầy biến động.', ARRAY['Over-concentrate risk']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('idiom-76', 'idioms', 'Rule of thumb', '/ˌruːl əv ˈθʌm/', 'Noun', 'B2', 'Kinh nghiệm thực tế bỏ túi mang tính ước chừng', 'A broadly accurate guide or principle, based on practice rather than theory.', 'As a general rule of thumb, save at least twenty percent of your net take-home salary every month.', 'Như một kinh nghiệm bỏ túi thông thường, hãy tiết kiệm ít nhất 20% mức lương thực nhận hàng tháng của bạn.', ARRAY['Heuristic', 'Practical guideline']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('idiom-77', 'idioms', 'Second to none', '/ˈsek.ənd tuː ˈnʌn/', 'Phrase', 'B2', 'Đỉnh cao số một, không ai sánh bằng', 'Better than all others; unmatched.', 'The hospital''s intensive pediatric care unit is truly second to none in the country.', 'Khoa chăm sóc tích cực nhi của bệnh viện thực sự là đỉnh cao số một không nơi nào trong cả nước sánh bằng.', ARRAY['Peerless', 'Incomparable', 'Unrivaled']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('idiom-78', 'idioms', 'Shoot oneself in the foot', '/ʃuːt wʌn.self ɪn ðə fʊt/', 'Phrase', 'B2', 'Gậy ông đập lưng ông, tự hại chính mình vì sơ suất', 'Inadvertently cause damage to one''s own cause or prospects.', 'Posting rude comments about your interviewers online is completely shooting yourself in the foot.', 'Đăng những bình luận khiếm nhã về người phỏng vấn lên mạng là bạn đang tự hại chính mình một cách ngớ ngẩn.', ARRAY['Self-sabotage', 'Hurt oneself']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('idiom-79', 'idioms', 'Steal someone''s thunder', '/stiːl ˈsʌm.wʌnz ˈθʌn.dɚ/', 'Phrase', 'C1', 'Cướp công cướp sự chú ý của người khác trước khi họ kịp tỏa sáng', 'Win praise for an achievement before someone else can, or steal someone''s limelight.', 'He announced his startup''s product launch early, effectively stealing his rival''s conference thunder.', 'Anh đã công bố việc ra mắt sản phẩm của công ty khởi nghiệp sớm hơn, cướp trọn sự chú ý của đối thủ tại hội nghị.', ARRAY['Steal limelight', 'Upstage']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('idiom-80', 'idioms', 'Straight from the horse''s mouth', '/streɪt frəm ðə ˈhɔːr.sɪz maʊθ/', 'Phrase', 'B2', 'Nguồn tin trực tiếp từ người trong cuộc xác thực', 'From the highest or most direct authority; first-hand.', 'I didn''t believe the merger rumors until I heard it straight from the horse''s mouth from our CEO.', 'Tôi đã không tin những lời đồn về vụ sáp nhập cho đến khi nghe trực tiếp từ chính miệng vị Tổng giám đốc điều hành của chúng tôi.', ARRAY['From the primary source', 'First-hand']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('idiom-81', 'idioms', 'Take the bull by the horns', '/teɪk ðə bʊl baɪ ðə hɔːrnz/', 'Phrase', 'B2', 'Dũng cảm nắm lấy sừng bò, trực diện đương đầu khó khăn', 'Directly confront a difficult situation with courage.', 'Instead of dreading the complex software migration, the team took the bull by the horns and finished it in two weeks.', 'Thay vì sợ hãi cuộc di chuyển phần mềm phức tạp, toàn đội đã dũng cảm trực diện đương đầu và hoàn thành nó chỉ trong hai tuần.', ARRAY['Confront boldly', 'Tackle head-on']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('idiom-82', 'idioms', 'The tip of the iceberg', '/ðə tɪp əv ðiː ˈaɪs.bɝːɡ/', 'Phrase', 'B1', 'Chỉ là phần nổi của tảng băng chìm', 'The small, perceptible part of a much larger situation or problem that remains unstated or unseen.', 'Reported customer payment failures are merely the tip of the iceberg of our underlying database latency.', 'Các báo cáo về lỗi thanh toán của khách hàng chỉ là phần nổi của tảng băng chìm về độ trễ cơ sở dữ liệu bên dưới của chúng tôi.', ARRAY['Small part', 'Surface symptom']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('idiom-83', 'idioms', 'Throw caution to the wind', '/θroʊ ˈkɑː.ʃən tuː ðə wɪnd/', 'Phrase', 'B2', 'Liều mình hành động, phó mặc cho số phận', 'Take a reckless risk; disregard warnings.', 'He threw caution to the wind, resigned from his stable job, and booked a one-way flight to Tokyo to pursue game design.', 'Anh đã liều mình gạt bỏ mọi e ngại, từ chức công việc ổn định và đặt vé một chiều đến Tokyo để theo đuổi ngành thiết kế trò chơi.', ARRAY['Take big risks', 'Be daring']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('idiom-84', 'idioms', 'Turn over a new leaf', '/tɝːn ˈoʊ.vɚ ə nuː liːf/', 'Phrase', 'B1', 'Bước sang trang mới cuộc đời, làm lại từ đầu hướng thiện', 'Start to act or behave in a better or more responsible way.', 'After realizing how unhealthy his habits were, he decided to turn over a new leaf and exercise daily.', 'Sau khi nhận ra thói quen của mình có hại cho sức khỏe như thế nào, anh quyết định bước sang một trang mới và tập thể dục mỗi ngày.', ARRAY['Reform', 'Start afresh']::text[]) ON CONFLICT ("Id") DO NOTHING;
INSERT INTO public."VocabularyWords" ("Id", "TopicId", "Word", "Phonetic", "PartOfSpeech", "DifficultyLevel", "MeaningVi", "DefinitionEn", "ExampleEn", "ExampleVi", "Synonyms") VALUES ('idiom-85', 'idioms', 'Weather the storm', '/ˈweð.ɚ ðə stɔːrm/', 'Phrase', 'B2', 'Vượt qua giông bão gian khó an toàn', 'Successfully deal with a very difficult problem or period.', 'With disciplined fiscal management and strong cash reserves, the tech firm weathered the severe recession storm safely.', 'Với việc quản lý tài chính kỷ luật và lượng dự trữ tiền mặt dồi dào, công ty công nghệ đã vượt qua cơn bão suy thoái nghiêm trọng một cách an toàn.', ARRAY['Survive', 'Endure', 'Come through safely']::text[]) ON CONFLICT ("Id") DO NOTHING;