-- seed_1000_vocabulary.sql
-- Lingora Platform 1,000+ Categorized Vocabulary Bank Seed

CREATE TABLE IF NOT EXISTS public."VocabularyTopics" (
    "Id" text PRIMARY KEY,
    "Title" text NOT NULL,
    "Slug" text NOT NULL,
    "Icon" text NOT NULL,
    "Description" text NOT NULL,
    "WordCount" integer NOT NULL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS public."VocabularyWords" (
    "Id" text PRIMARY KEY,
    "TopicId" text NOT NULL REFERENCES public."VocabularyTopics"("Id") ON DELETE CASCADE,
    "Word" text NOT NULL,
    "Phonetic" text NOT NULL,
    "PartOfSpeech" text NOT NULL,
    "DifficultyLevel" text NOT NULL,
    "MeaningVi" text NOT NULL,
    "DefinitionEn" text NOT NULL,
    "ExampleEn" text NOT NULL,
    "ExampleVi" text NOT NULL,
    "Synonyms" text[] NOT NULL DEFAULT '{}'
);

